# V29 · snapshot-context live AI Coach chat (retained; V30 adds mobile-only overrides below)
BASE_CSS += r"""
.v29-coach-chat{position:relative;margin:18px 0;border:1px solid rgba(69,215,232,.26);border-radius:21px;background:linear-gradient(145deg,rgba(69,215,232,.055),rgba(155,124,255,.045) 48%,rgba(255,255,255,.014));box-shadow:0 18px 48px rgba(0,0,0,.22),inset 0 1px 0 rgba(255,255,255,.025);overflow:hidden}
.v29-coach-chat::before{content:'';position:absolute;inset:-90px auto auto -60px;width:220px;height:180px;border-radius:50%;background:rgba(69,215,232,.09);filter:blur(38px);pointer-events:none}.v29-coach-chat::after{content:'';position:absolute;right:-70px;top:-95px;width:210px;height:180px;border-radius:50%;background:rgba(155,124,255,.08);filter:blur(42px);pointer-events:none}
.v29-coach-chat>.lab-accordion-trigger{position:relative;z-index:1;min-height:76px;padding:16px 18px;gap:12px}.v29-coach-chat>.lab-accordion-trigger .lab-accordion-sign{order:0;margin-left:auto}.v29-chat-orb{flex:0 0 45px;width:45px;height:45px;display:grid;place-items:center;border:1px solid rgba(69,215,232,.34);border-radius:15px;background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.18),transparent 26%),linear-gradient(145deg,rgba(69,215,232,.15),rgba(155,124,255,.13));box-shadow:0 0 0 5px rgba(69,215,232,.035),0 10px 26px rgba(0,0,0,.22);font-size:21px}.v29-chat-heading{min-width:0;flex:1 1 auto}.v29-chat-heading strong{display:block;font-size:17px;letter-spacing:.025em}.v29-chat-heading small{display:block;margin-top:3px;color:#b9c4cd;font-size:13px;line-height:1.4}.v29-chat-context{flex:0 0 auto;display:flex;align-items:center;gap:7px;min-height:31px;padding:0 10px;border:1px solid rgba(69,215,232,.25);border-radius:999px;background:rgba(69,215,232,.045);color:#c8f8fc;font-size:11px;font-weight:850;letter-spacing:.055em;white-space:nowrap}.v29-chat-context i{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 10px rgba(37,212,122,.42)}
.v29-chat-panel{position:relative;z-index:1;padding:0 18px 18px}.v29-chat-stage{border:1px solid rgba(116,128,143,.27);border-radius:18px;background:rgba(5,7,10,.55);overflow:hidden}.v29-chat-messages{display:flex;flex-direction:column;gap:12px;min-height:130px;max-height:520px;overflow:auto;padding:16px;scroll-behavior:smooth}.v29-msg{display:flex;gap:9px;align-items:flex-end}.v29-msg.user{justify-content:flex-end}.v29-msg-avatar{flex:0 0 30px;width:30px;height:30px;display:grid;place-items:center;border:1px solid rgba(69,215,232,.25);border-radius:10px;background:rgba(69,215,232,.07);font-size:14px}.v29-msg.user .v29-msg-avatar{order:2;border-color:rgba(155,124,255,.28);background:rgba(155,124,255,.08)}.v29-bubble{max-width:min(78%,820px);padding:11px 13px;border:1px solid rgba(69,215,232,.18);border-radius:15px 15px 15px 5px;background:rgba(69,215,232,.055);color:#e7edf2;font-size:14px;line-height:1.58;white-space:pre-wrap;overflow-wrap:anywhere}.v29-msg.user .v29-bubble{border-color:rgba(155,124,255,.24);border-radius:15px 15px 5px 15px;background:rgba(155,124,255,.075)}.v29-msg.welcome .v29-bubble{max-width:900px;color:#c9d4dc;background:rgba(255,255,255,.025);border-color:rgba(255,255,255,.075)}
.v29-msg-tools{display:flex;gap:6px;margin-top:8px}.v29-save-memory{min-height:30px;padding:0 9px;border:1px solid rgba(69,215,232,.22);border-radius:999px;background:rgba(69,215,232,.035);color:#c9f8fc;font-family:var(--font);font-size:10px;font-weight:850;letter-spacing:.045em;cursor:pointer}.v29-save-memory:hover{border-color:rgba(69,215,232,.52);background:rgba(69,215,232,.075)}.v29-save-memory.is-saved{color:#80eab2;border-color:rgba(37,212,122,.28);background:rgba(37,212,122,.055)}
.v29-typing{display:inline-flex;align-items:center;gap:5px;height:18px}.v29-typing i{width:6px;height:6px;border-radius:50%;background:#b9c7cf;animation:v29Typing 1.1s infinite ease-in-out}.v29-typing i:nth-child(2){animation-delay:.14s}.v29-typing i:nth-child(3){animation-delay:.28s}@keyframes v29Typing{0%,70%,100%{transform:translateY(0);opacity:.45}35%{transform:translateY(-4px);opacity:1}}
.v29-quick-row{display:flex;flex-wrap:wrap;gap:7px;padding:0 16px 13px}.v29-quick{min-height:34px;padding:0 11px;border:1px solid rgba(116,128,143,.3);border-radius:999px;background:rgba(255,255,255,.022);color:#c6d0d7;font-family:var(--font);font-size:11px;font-weight:750;cursor:pointer}.v29-quick:hover{border-color:rgba(69,215,232,.42);color:#e9fbfd;background:rgba(69,215,232,.055)}
.v29-chat-compose{display:grid;grid-template-columns:1fr auto;gap:9px;padding:12px;border-top:1px solid rgba(116,128,143,.22);background:rgba(0,0,0,.18)}.v29-chat-input{width:100%;min-height:52px;max-height:150px;resize:none;border:1px solid rgba(116,128,143,.35);border-radius:14px;background:#080a0d;color:#f3f5f7;padding:14px 14px;font-family:var(--font);font-size:15px;line-height:1.45;outline:none}.v29-chat-input:focus{border-color:rgba(69,215,232,.55);box-shadow:0 0 0 4px rgba(69,215,232,.065)}.v29-chat-send{min-width:120px;align-self:stretch;display:inline-flex;align-items:center;justify-content:center;gap:7px}.v29-chat-send span{font-size:16px}.v29-chat-send:disabled{opacity:.55;cursor:not-allowed;transform:none!important}
.v29-chat-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 3px 0;color:#9ca8b3;font-size:12px;line-height:1.45}.v29-chat-foot strong{color:#c8f8fc}.v29-chat-clear{flex:0 0 auto;border:0;background:transparent;color:#aab5be;font-family:var(--font);font-size:11px;font-weight:800;text-decoration:underline;text-underline-offset:3px;cursor:pointer}.v29-chat-clear:hover{color:#fff}.v29-chat-disabled{padding:16px;border:1px dashed rgba(116,128,143,.32);border-radius:15px;color:#aeb8c1;font-size:13px;line-height:1.55;text-align:center}.v29-chat-disabled strong{display:block;margin-bottom:4px;color:#d9e0e6;font-size:14px}
.v29-chat-error{margin:0 16px 13px;padding:10px 12px;border:1px solid rgba(255,66,84,.27);border-radius:12px;background:rgba(255,66,84,.055);color:#ffa1aa;font-size:13px;line-height:1.5}
@media(max-width:760px){.v29-coach-chat>.lab-accordion-trigger{align-items:flex-start;flex-wrap:wrap;padding:14px}.v29-chat-orb{flex-basis:42px;width:42px;height:42px}.v29-chat-context{order:3;margin-left:54px;max-width:calc(100% - 54px);white-space:normal}.v29-coach-chat>.lab-accordion-trigger .lab-accordion-sign{position:absolute;right:14px;top:14px}.v29-chat-heading{padding-right:42px}.v29-chat-panel{padding:0 12px 13px}.v29-chat-messages{padding:13px;max-height:460px}.v29-bubble{max-width:88%;font-size:14px}.v29-chat-compose{grid-template-columns:1fr;padding:10px}.v29-chat-input{font-size:16px}.v29-chat-send{min-height:48px}.v29-chat-foot{align-items:flex-start;flex-direction:column;padding:9px 2px 0}.v29-quick-row{padding:0 13px 11px}.v29-quick{min-height:38px;font-size:12px}}
@media(max-width:430px){.v29-chat-heading strong{font-size:16px}.v29-chat-heading small{font-size:12px}.v29-chat-context{margin-left:0;max-width:calc(100% - 42px)}.v29-msg-avatar{display:none}.v29-bubble{max-width:94%}.v29-chat-messages{min-height:115px}.v29-quick{flex:1 1 calc(50% - 5px)}}
"""

# V31 · intrinsic chat layout + site-wide typography contract.
# No training/recovery/nutrition/AI decision logic is changed here.
BASE_CSS += r"""
/* ------------------------------------------------------------------
   V31 TYPOGRAPHY CONTRACT
   Keep the same hierarchy everywhere and prevent Android text autosizing
   from inflating isolated cards differently from the rest of the page.
   ------------------------------------------------------------------ */
:root{
  --font:'Nunito',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;
  --display:'Nunito',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;
  --lab-body:14px;
  --lab-support:13px;
  --lab-label:12px;
  --lab-card-title:16px;
}
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
body,button,input,textarea,select{font-family:var(--font)}
.v4-section-title,.v4-control-title,.v4-session h3,.v25-blocks-head h3,.v25-block h4,.v19-event-builder h3{font-family:var(--display)}

/* Body copy: equivalent explanatory text has one readable size. */
.v4-copy,.v4-session-main,.v4-session-why,.v4-readiness-copy p,.v4-energy-card>p,
.v8-nutrition-intro,.v8-nutrition-row p,.v8-legend-item p,
.v10-override-banner p,.v10-memory-list p,.v13-recent-note p,.v19-journal-entry p,.v19-event-builder>p,
.v22-context-box p,.v22-session-row>p,.v23-fuel-copy,.v23-recovery-card p,
.v25-consideration,.v26-replenishment p,.v4-details>.lab-accordion-panel>p,
.v29-bubble,.v29-chat-disabled,.v29-chat-error{
  font-size:var(--lab-body)!important;
  line-height:1.58!important;
}

/* Supporting copy/subtitles: same role, same size. */
.v4-section-note,.v4-subtitle,.v20-zone-title p,.v20-zone-note,
.v25-blocks-head p,.v25-current,.v26-first-feed-note,.v26-strategy-note,
.v27-report-banner span,.v29-chat-heading small,.v29-chat-foot,
.v14-storage-note,.v14-cleanup-note,.v12-planning-hint,.v12-retro-help{
  font-size:var(--lab-support)!important;
  line-height:1.48!important;
}

/* Metadata / labels / compact status text. This is the smallest normal
   dashboard type. Tiny calendar numerals remain intentionally separate. */
.v4-session-slot,.v4-session-pill,.v4-stat-label,.v4-stat-sub,.v4-health-cell span,.v4-power-label,
.v4-metric-label,.v4-metric-status,.v4-ring-sub,.v4-week-label,.v4-week-chip,.v4-week-note,
.v7-energy-live,.v7-night-strip span,.v7-baseline-table span,.v7-baseline-table small,
.v8-nutrition-slot,.v8-nutrition-label,.v8-legend-head small,
.v10-field-label,.v10-rule-row label>span,.v11-date-field>span,.v13-note-label,
.v13-memory-toggle span,.v13-memory-toggle small,.v13-recent-note-head span,
.v14-storage-counts span,.v14-cleanup-head span,.v14-cleanup-head small,
.v19-field-title,.v19-journal-date,.v19-journal-meta,.v19-daily-context,.v19-tag,
.v20-count-badge,.v24-training-head small,
.v25-block-top span,.v25-block-metrics b,.v25-zone-lines span,.v25-pattern-title small,.v25-pattern-stats span,.v25-pattern-foot,
.v22-context-head strong,.v22-context-head b,.v22-context-box small,.v22-context-box em,
.v22-demand span,.v22-demand strong,.v22-demand small,.v22-fuel-grid span,.v22-fuel-grid small,
.v23-fuel-head>b,.v23-fuel-meta,.v23-recovery-slot,.v23-recovery-demand span,.v23-recovery-demand b,.v23-recovery-label,.v23-science,
.v26-fuel-total,.v26-replenishment-head span,.v26-replenishment-head b,
.v29-chat-context,.v29-quick,.v29-save-memory,.v29-chat-clear{
  font-size:var(--lab-label)!important;
}

/* Section/card headings use a stable hierarchy instead of inheriting
   incidental sizes from older versioned components. */
.v8-legend-head strong,.v23-recovery-head strong,.v23-fuel-head>strong,.v24-training-head strong,
.v22-context-head strong,.v25-pattern-title strong{font-size:var(--lab-card-title)!important}

/* Training Metrics legend: literal separator in markup, no gap/pseudo-element
   dependency. This also fixes CTLFitness / ATLFatigue / TSBForm. */
.v31-legend-label{
  display:grid!important;
  grid-template-columns:auto auto minmax(0,1fr);
  align-items:baseline;
  column-gap:9px;
  min-width:0;
}
.v31-legend-label strong{color:var(--cyan);font-family:var(--display);font-size:16px!important;line-height:1.25}
.v31-legend-divider{color:#707a86;font-size:14px!important;font-weight:700}
.v31-legend-name{color:#d8dde4;font-size:14px!important;font-weight:700;line-height:1.35;min-width:0}
.v8-legend-item p{margin-top:9px!important}

/* ------------------------------------------------------------------
   AI COACH HEADER
   Mobile-first by structure, not by a max-width rescue rule. The context
   can never steal width from the title because it lives on its own row.
   ------------------------------------------------------------------ */
.v29-coach-chat>.lab-accordion-trigger{
  position:relative;z-index:1;
  display:block!important;
  min-height:0!important;
  padding:16px 18px!important;
}
.v31-chat-head-row{
  display:grid;
  grid-template-columns:46px minmax(0,1fr) 34px;
  grid-template-areas:'orb heading sign';
  align-items:center;
  column-gap:12px;
  min-width:0;
}
.v29-chat-orb{
  grid-area:orb!important;
  flex:none!important;
  width:45px;height:45px;
}
.v29-chat-heading{
  grid-area:heading!important;
  min-width:0!important;
  padding:0!important;
  flex:none!important;
}
.v29-chat-heading strong{
  display:block;
  font-size:17px!important;
  line-height:1.25!important;
  letter-spacing:.02em;
  white-space:normal!important;
  word-break:normal!important;
  overflow-wrap:normal!important;
}
.v29-chat-heading small{
  display:block;
  margin-top:3px;
  white-space:normal!important;
  word-break:normal!important;
  overflow-wrap:normal!important;
}
.v29-coach-chat>.lab-accordion-trigger .lab-accordion-sign{
  grid-area:sign!important;
  position:static!important;
  inset:auto!important;
  order:initial!important;
  margin:0!important;
  justify-self:end;
  align-self:center;
}
.v29-chat-context{
  display:inline-flex!important;
  width:fit-content!important;
  max-width:100%!important;
  min-width:0!important;
  margin:12px 0 0 58px!important;
  padding:7px 10px!important;
  min-height:32px;
  order:initial!important;
  white-space:normal!important;
  overflow-wrap:anywhere!important;
  line-height:1.35!important;
}

/* V33.1 desktop safety: keep the same proven stacked header structure used
   on mobile. Context stays on its own row, so it can never compete with the
   title/orb/sign for horizontal space. */
@media(min-width:1100px){
  .v29-coach-chat>.lab-accordion-trigger{display:block!important}
  .v31-chat-head-row{
    display:grid!important;
    grid-template-columns:46px minmax(0,1fr) 34px!important;
    grid-template-areas:'orb heading sign'!important;
    align-items:center!important;
    column-gap:12px!important;
    width:100%!important;
    min-width:0!important;
  }
  .v29-chat-orb{grid-area:orb!important}
  .v29-chat-heading{grid-area:heading!important}
  .v29-coach-chat>.lab-accordion-trigger .lab-accordion-sign{grid-area:sign!important}
  .v29-chat-context{
    display:inline-flex!important;
    margin:10px 0 0 58px!important;
    width:fit-content!important;
    max-width:calc(100% - 58px)!important;
    white-space:nowrap!important;
    justify-self:auto!important;
  }
}

@media(max-width:720px){
  :root{--lab-body:15px;--lab-support:13.5px;--lab-label:12px;--lab-card-title:16px}
  .v29-coach-chat>.lab-accordion-trigger{padding:15px!important}
  .v31-chat-head-row{grid-template-columns:44px minmax(0,1fr) 32px;column-gap:10px}
  .v29-chat-orb{width:42px;height:42px}
  .v29-chat-heading strong{font-size:17px!important}
  .v29-chat-context{margin-left:54px!important;width:auto!important}
  .v29-chat-panel{padding:0 12px 13px}
  .v29-chat-messages{padding:13px;max-height:460px}
  .v29-bubble{max-width:92%}
  .v29-chat-compose{grid-template-columns:1fr;padding:10px}
  .v29-chat-input{font-size:16px!important}
  .v29-chat-send{min-height:48px}
  .v29-chat-foot{align-items:flex-start;flex-direction:column;padding:9px 2px 0}
  .v29-quick-row{padding:0 13px 11px}
  .v29-quick{min-height:40px}
  .v4-build{display:none!important}
}
@media(max-width:430px){
  .v29-chat-context{margin-left:0!important;width:100%!important;justify-content:flex-start}
  .v29-msg-avatar{display:none}
  .v29-bubble{max-width:96%}
  .v29-quick{flex:1 1 calc(50% - 5px)}
}


/* ------------------------------------------------------------------
   V34 · AI COACH RESPONSIVE LAYOUT CONTRACT
   The trigger itself is the grid. No nested flex/grid wrapper, no inherited
   accordion ordering. Desktop, tablet and mobile therefore share one source
   of truth and cannot push the +/- control or title to opposite edges.
   ------------------------------------------------------------------ */
.v29-coach-chat>.lab-accordion-trigger.v34-chat-trigger{
  display:grid!important;
  grid-template-columns:46px minmax(0,1fr) auto 34px!important;
  grid-template-areas:'orb heading context sign'!important;
  align-items:center!important;
  column-gap:12px!important;
  row-gap:0!important;
  width:100%!important;
  min-width:0!important;
  min-height:76px!important;
  padding:16px 18px!important;
  text-align:left!important;
}
.v34-chat-trigger>.v29-chat-orb{
  grid-area:orb!important;
  width:45px!important;
  height:45px!important;
  margin:0!important;
  justify-self:start!important;
  align-self:center!important;
}
.v34-chat-trigger>.v29-chat-heading{
  grid-area:heading!important;
  min-width:0!important;
  width:auto!important;
  margin:0!important;
  padding:0!important;
  text-align:left!important;
  justify-self:stretch!important;
}
.v34-chat-trigger>.v29-chat-heading strong,
.v34-chat-trigger>.v29-chat-heading small{
  text-align:left!important;
}
.v34-chat-trigger>.v29-chat-context{
  grid-area:context!important;
  display:inline-flex!important;
  align-items:center!important;
  justify-self:end!important;
  align-self:center!important;
  width:auto!important;
  max-width:360px!important;
  min-width:0!important;
  margin:0!important;
  padding:7px 10px!important;
  white-space:nowrap!important;
  overflow-wrap:normal!important;
}
.v34-chat-trigger>.lab-accordion-sign{
  grid-area:sign!important;
  order:0!important;
  position:static!important;
  inset:auto!important;
  width:32px!important;
  height:32px!important;
  margin:0!important;
  justify-self:end!important;
  align-self:center!important;
}
@media(max-width:980px){
  .v29-coach-chat>.lab-accordion-trigger.v34-chat-trigger{
    grid-template-columns:46px minmax(0,1fr) 34px!important;
    grid-template-areas:'orb heading sign' '. context .'!important;
    row-gap:9px!important;
  }
  .v34-chat-trigger>.v29-chat-context{
    justify-self:start!important;
    width:auto!important;
    max-width:100%!important;
    white-space:normal!important;
  }
}
@media(max-width:720px){
  .v29-coach-chat>.lab-accordion-trigger.v34-chat-trigger{
    grid-template-columns:44px minmax(0,1fr) 32px!important;
    grid-template-areas:'orb heading sign' 'context context context'!important;
    column-gap:10px!important;
    row-gap:10px!important;
    padding:15px!important;
  }
  .v34-chat-trigger>.v29-chat-orb{width:42px!important;height:42px!important}
  .v34-chat-trigger>.v29-chat-context{
    width:100%!important;
    justify-self:stretch!important;
    justify-content:flex-start!important;
    white-space:normal!important;
  }
}

/* ------------------------------------------------------------------
   V36 · SNAPSHOT UI HIERARCHY / STATUS EXPLANATIONS
   Logic remains V35-stable; this release only refines presentation.
   Existing v35-* class names are intentionally retained to avoid broad
   template/JS churn and keep the patch surgical.
   ------------------------------------------------------------------ */
.v35-intelligence-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,.65fr);gap:14px;margin:14px 0 18px}
.v35-phys-card,.v35-sleep-card,.v35-aero-card,.v35-power-model{min-width:0;padding:17px 18px}
.v35-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:13px;min-width:0}
.v35-head-main{display:flex;align-items:flex-start;gap:11px;min-width:0}
.v35-head-icon{font-size:24px;line-height:1.2;flex:0 0 auto}
.v35-head h3,.v35-head h2{margin:0;font-family:var(--display);font-size:var(--lab-card-title)!important;line-height:1.25;letter-spacing:.025em}
.v35-head p{margin:3px 0 0;color:var(--muted);font-size:var(--lab-support)!important;line-height:1.45}
.v35-status{display:inline-flex;align-items:center;justify-content:center;min-height:31px;padding:0 10px;border:1px solid var(--line);border-radius:999px;font-size:var(--lab-label)!important;font-weight:900;letter-spacing:.055em;white-space:nowrap;background:rgba(255,255,255,.025)}
.v4-metric-status.orange{color:var(--orange)}
.v35-status.green{color:#8cf0b5;border-color:rgba(37,212,122,.42);background:rgba(37,212,122,.08)}
.v35-status.cyan{color:#c9fbff;border-color:rgba(69,215,232,.40);background:rgba(69,215,232,.08)}
.v35-status.orange{color:#ffd18a;border-color:rgba(255,173,51,.42);background:rgba(255,173,51,.08)}
.v35-status.red{color:#ff9c9c;border-color:rgba(255,87,87,.44);background:rgba(255,87,87,.08)}
.v35-status.purple{color:#dacfff;border-color:rgba(155,124,255,.46);background:rgba(155,124,255,.09)}
.v35-status.grey{color:#c5ccd3;border-color:rgba(255,255,255,.14);background:rgba(255,255,255,.035)}

.v35-phys-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}
.v35-phys-item{min-width:0;padding:13px 12px 14px;border:1px solid rgba(255,255,255,.075);border-radius:14px;background:rgba(255,255,255,.018)}
.v35-phys-top{display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;gap:6px;margin-bottom:10px}
.v35-phys-label{display:block;font-size:var(--lab-label)!important;font-weight:900;letter-spacing:.055em;color:#dfe5ea;line-height:1.35}
.v35-phys-state{display:block;font-size:var(--lab-label)!important;font-weight:900;line-height:1.25}
.v35-phys-state.green{color:var(--green)}.v35-phys-state.cyan{color:var(--cyan)}.v35-phys-state.orange{color:var(--orange)}.v35-phys-state.red{color:var(--red)}.v35-phys-state.grey{color:var(--grey)}
.v35-phys-item p{margin:0;color:#b9c2cb;font-size:var(--lab-support)!important;line-height:1.48}
.v36-status-guide{margin-top:11px;padding:10px 12px;border:1px solid rgba(69,215,232,.13);border-radius:12px;background:rgba(69,215,232,.025);color:#b9c5ce;font-size:var(--lab-support)!important;line-height:1.48}
.v36-status-guide strong{color:#dffcff;font-size:var(--lab-label)!important;letter-spacing:.045em}
.v36-status-guide span{color:#e6edf3;font-weight:850}
.v35-disclaimer{margin:9px 0 0;color:var(--muted);font-size:var(--lab-support)!important;line-height:1.45}

.v35-sleep-primary{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;padding:12px 13px;border:1px solid rgba(69,215,232,.18);border-radius:14px;background:rgba(69,215,232,.035)}
.v35-sleep-primary span,.v35-sleep-box span{display:block;color:var(--muted);font-size:var(--lab-label)!important;font-weight:850;letter-spacing:.045em}
.v35-sleep-primary strong{display:block;margin-top:3px;font-family:var(--display);font-size:27px;line-height:1.1}
.v35-sleep-delta{font-size:var(--lab-body)!important;font-weight:900;white-space:nowrap}.v35-sleep-delta.green{color:var(--green)}.v35-sleep-delta.grey{color:var(--grey)}.v35-sleep-delta.orange{color:var(--orange)}.v35-sleep-delta.red{color:var(--red)}
.v35-sleep-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:9px}
.v35-sleep-box{padding:11px 12px;border:1px solid rgba(255,255,255,.075);border-radius:13px;background:rgba(255,255,255,.018);min-width:0}
.v35-sleep-box strong{display:block;margin-top:4px;font-size:var(--lab-body)!important;line-height:1.3}
.v35-sleep-box small{display:block;margin-top:4px;color:var(--muted);font-size:var(--lab-support)!important;line-height:1.4}
.v35-sleep-reference{margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,.07);color:#c3ccd4;font-size:var(--lab-support)!important;line-height:1.48}
.v35-sleep-reference strong{color:#fff}

.v35-upcoming-head{align-items:flex-start;gap:14px}
.v35-phase-wrap{flex:0 0 auto;max-width:380px;min-width:250px}
.v35-phase-button{width:100%;display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-areas:'icon body';align-items:flex-start;gap:10px;padding:11px 12px;border:1px solid rgba(69,215,232,.24);border-radius:14px;background:rgba(69,215,232,.035);color:var(--text);font-family:var(--font);cursor:pointer;text-align:left}
.v35-phase-button:hover{border-color:rgba(69,215,232,.48);background:rgba(69,215,232,.065)}
.v35-phase-button .icon{grid-area:icon;font-size:20px;line-height:1.25}.v36-phase-body{grid-area:body;min-width:0}.v35-phase-button span{display:block;font-size:var(--lab-label)!important;color:var(--muted);font-weight:850;letter-spacing:.05em}.v35-phase-button strong{display:block;margin-top:3px;font-family:var(--display);font-size:var(--lab-card-title)!important;line-height:1.2}.v36-phase-confidence-label{display:block!important;margin-top:8px;color:var(--muted-2)!important;font-size:calc(var(--lab-label) - 1px)!important;letter-spacing:.06em!important}.v35-phase-button em{display:block;margin-top:1px;font-style:normal;font-size:var(--lab-label)!important;font-weight:900;color:#c9fbff;white-space:normal}
.v35-phase-button.red{border-color:rgba(255,87,87,.35);background:rgba(255,87,87,.055)}.v35-phase-button.orange{border-color:rgba(255,173,51,.35);background:rgba(255,173,51,.055)}.v35-phase-button.purple{border-color:rgba(155,124,255,.38);background:rgba(155,124,255,.065)}.v35-phase-button.green{border-color:rgba(37,212,122,.34);background:rgba(37,212,122,.05)}
.v35-phase-explain{margin:12px 0 14px;padding:13px 14px;border:1px solid rgba(155,124,255,.19);border-radius:14px;background:linear-gradient(135deg,rgba(155,124,255,.06),rgba(69,215,232,.03));font-size:var(--lab-body)!important;line-height:1.52}
.v35-phase-explain strong{font-family:var(--display);font-size:var(--lab-card-title)!important}.v35-phase-explain p{margin:6px 0 0}.v35-phase-signals{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.v35-phase-signals span{padding:5px 8px;border:1px solid var(--line);border-radius:999px;color:#c8d0d7;font-size:var(--lab-label)!important}

.v35-aero-card{margin:14px 0 18px;border:1px solid rgba(69,215,232,.22);border-radius:17px;background:linear-gradient(135deg,rgba(69,215,232,.045),rgba(37,212,122,.025))}
.v35-aero-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}
.v35-aero-metric{padding:11px 12px;border:1px solid rgba(255,255,255,.075);border-radius:13px;background:rgba(0,0,0,.12);min-width:0}
.v35-aero-metric span{display:block;color:var(--muted);font-size:var(--lab-label)!important;font-weight:850;letter-spacing:.045em}.v35-aero-metric strong{display:block;margin-top:4px;font-size:var(--lab-body)!important;line-height:1.3}.v35-aero-copy{margin:11px 0 0;font-size:var(--lab-body)!important;line-height:1.52}.v35-aero-note{margin:7px 0 0;color:var(--muted);font-size:var(--lab-support)!important;line-height:1.46}
.v35-aero-sessions{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.v35-aero-session{padding:6px 8px;border:1px solid var(--line);border-radius:999px;font-size:var(--lab-label)!important;color:#cbd4db;white-space:nowrap}

.v35-power-grid{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:14px;align-items:start}
.v35-power-core{display:grid;grid-template-columns:1fr 1fr;gap:9px}.v35-power-stat{padding:13px;border:1px solid rgba(255,255,255,.08);border-radius:14px;background:rgba(255,255,255,.018)}.v35-power-stat span{display:block;color:var(--muted);font-size:var(--lab-label)!important;font-weight:850;letter-spacing:.05em}.v35-power-stat strong{display:block;margin-top:4px;font-family:var(--display);font-size:26px;line-height:1.1}.v35-power-stat small{display:block;margin-top:4px;color:#bbc5cd;font-size:var(--lab-support)!important;line-height:1.4}
.v35-power-copy{font-size:var(--lab-body)!important;line-height:1.52}.v35-power-copy p{margin:0 0 10px}.v35-curve-compare{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.v35-curve-point{padding:10px;border:1px solid var(--line);border-radius:12px}.v35-curve-point span{display:block;color:var(--muted);font-size:var(--lab-label)!important;font-weight:850}.v35-curve-point strong{display:block;margin-top:4px;font-size:var(--lab-body)!important}.v35-power-formula{margin-top:10px;padding:9px 11px;border:1px solid rgba(155,124,255,.18);border-radius:12px;background:rgba(155,124,255,.035);font-size:var(--lab-support)!important;color:#d9d2ff}.v35-power-model .v35-disclaimer{padding-top:10px;border-top:1px solid rgba(255,255,255,.07)}

@media(max-width:1100px){.v35-phys-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.v35-intelligence-grid{grid-template-columns:1fr}.v35-power-grid{grid-template-columns:1fr}.v35-aero-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:800px){.v35-upcoming-head{display:block}.v35-phase-wrap{max-width:none;min-width:0;margin-top:12px}.v35-phys-grid{grid-template-columns:1fr 1fr}.v35-power-core{grid-template-columns:1fr 1fr}}
@media(max-width:560px){
  .v35-phys-grid,.v35-sleep-grid,.v35-aero-metrics,.v35-power-core,.v35-curve-compare{grid-template-columns:1fr}
  .v35-head{align-items:flex-start;flex-direction:column}
  .v35-status{white-space:normal}
  .v35-sleep-primary{align-items:flex-start;flex-direction:column}
  .v35-sleep-delta{white-space:normal}
  .v35-phase-wrap{width:100%}
  .v35-phase-button{display:block;position:relative;width:100%;padding:16px 16px 14px;text-align:center}
  .v35-phase-button .icon{position:absolute;left:14px;top:14px;width:22px;text-align:center;font-size:19px;line-height:1.25}
  .v36-phase-body{width:100%;min-width:0;padding:0 28px;text-align:center}
  .v35-phase-button strong,.v35-phase-button em{text-align:center}
  .v36-phase-confidence-label{margin-top:10px!important;font-size:11px!important;letter-spacing:.045em!important;overflow-wrap:anywhere}
  .v35-aero-session{white-space:normal}
}

/* VO2MAX layout intentionally untouched: its wide chart/table remains
   horizontally scrollable on mobile exactly as in V30. */
"""

# PRODUCT V4.7 · Owner mode selector. It deliberately reuses the Snapshot visual
# language instead of the product-security setup skin.
BASE_CSS += r"""
.v47-owner-page{min-height:100vh;background:radial-gradient(circle at 12% 8%,rgba(69,215,232,.075),transparent 34%),radial-gradient(circle at 88% 86%,rgba(155,124,255,.075),transparent 32%),#070b10}
.v47-owner-shell{padding-bottom:42px}
.v47-owner-hero{padding:30px 26px 28px;text-align:center;overflow:hidden}
.v47-owner-hero .v4-logo{margin-bottom:14px}.v47-owner-hero .v4-title{font-size:clamp(42px,7vw,70px)}
.v47-owner-sub{max-width:760px;margin:10px auto 0;color:#a9b4c0;font-size:14px;line-height:1.7;overflow-wrap:anywhere}
.v47-owner-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:18px}
.v47-owner-choice{position:relative;min-width:0;padding:24px;text-decoration:none;color:inherit;overflow:hidden;transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease}
.v47-owner-choice:hover{transform:translateY(-2px);border-color:rgba(69,215,232,.42);box-shadow:0 22px 54px rgba(0,0,0,.34),0 0 0 3px rgba(69,215,232,.035)}
.v47-owner-choice.admin:hover{border-color:rgba(155,124,255,.46);box-shadow:0 22px 54px rgba(0,0,0,.34),0 0 0 3px rgba(155,124,255,.045)}
.v47-owner-choice.is-disabled{pointer-events:none;opacity:.72}
.v47-owner-choice-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;min-width:0}
.v47-owner-choice-icon{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border:1px solid rgba(69,215,232,.28);border-radius:15px;background:rgba(69,215,232,.055);font-size:23px}
.v47-owner-choice.admin .v47-owner-choice-icon{border-color:rgba(155,124,255,.30);background:rgba(155,124,255,.065)}
.v47-owner-status{display:inline-flex;align-items:center;min-height:28px;max-width:100%;padding:0 9px;border:1px solid rgba(37,212,122,.28);border-radius:999px;background:rgba(37,212,122,.045);color:#9cf4c6;font-size:9.5px;font-weight:900;letter-spacing:.065em;white-space:normal;text-align:center;line-height:1.25}
.v47-owner-status.warn{border-color:rgba(255,176,32,.30);background:rgba(255,176,32,.055);color:#ffd18a}
.v47-owner-copy{min-width:0;margin-top:18px}.v47-owner-copy span{display:block;color:#83eaf5;font-size:10px;font-weight:900;letter-spacing:.11em;text-transform:uppercase}
.v47-owner-choice.admin .v47-owner-copy span{color:#c7b7ff}.v47-owner-copy h2{margin:7px 0 9px;font-family:var(--display);font-size:30px;line-height:1.06;overflow-wrap:anywhere}
.v47-owner-copy p{margin:0;color:#aab5c1;font-size:13px;line-height:1.65;overflow-wrap:anywhere;word-break:normal}
.v47-owner-meta{display:flex;flex-wrap:wrap;gap:7px;margin-top:18px}.v47-owner-meta b{display:inline-flex;align-items:center;min-height:29px;padding:0 9px;border:1px solid rgba(116,128,143,.25);border-radius:999px;color:#aab8c7;background:rgba(255,255,255,.018);font-size:9.5px;letter-spacing:.035em;white-space:normal;line-height:1.25}
.v47-owner-arrow{margin-top:20px;padding-top:15px;border-top:1px solid rgba(255,255,255,.055);color:#dffbff;font-size:12px;font-weight:900;letter-spacing:.055em}.v47-owner-choice.admin .v47-owner-arrow{color:#dfd6ff}
.v47-owner-note{margin-top:16px;padding:13px 15px;border:1px solid rgba(116,128,143,.20);border-radius:14px;background:rgba(255,255,255,.018);color:#8fa0b1;font-size:11px;line-height:1.6;overflow-wrap:anywhere}
.v47-owner-note.error{border-color:rgba(255,176,32,.28);color:#eac68a;background:rgba(255,176,32,.035)}
@media(max-width:760px){.v47-owner-grid{grid-template-columns:1fr}.v47-owner-hero{padding:24px 18px}.v47-owner-choice{padding:20px}.v47-owner-copy h2{font-size:27px}.v47-owner-sub{font-size:13px}.v47-owner-choice-head{gap:9px}}
@media(max-width:390px){.v47-owner-choice{padding:17px}.v47-owner-choice-icon{width:43px;height:43px;flex-basis:43px;font-size:20px}.v47-owner-status{font-size:8.8px}.v47-owner-copy h2{font-size:25px}.v47-owner-copy p{font-size:12.5px;line-height:1.62}.v47-owner-meta b{font-size:9px}}
"""

# PRODUCT V4.8.4 keeps V4.8.2 Training Direction presentation + preflight UX + historical journey. One responsive block is
# shared by Live Snapshot, public Preview and Stored Last Report.
BASE_CSS += r"""
.v48-direction{border-color:rgba(69,215,232,.27);background:radial-gradient(circle at 6% 0,rgba(69,215,232,.075),transparent 30%),radial-gradient(circle at 96% 0,rgba(155,124,255,.06),transparent 28%),var(--panel)}
.v48-direction .v7-analysis-body{padding-top:2px}
.v48-strategy-grid{display:grid;grid-template-columns:minmax(0,1.04fr) minmax(0,.96fr);gap:14px;margin-bottom:14px}
.v48-plan-card,.v48-adherence-card,.v48-cycle-card,.v48-season-context{min-width:0;border:1px solid rgba(116,128,143,.20);border-radius:17px;background:linear-gradient(145deg,rgba(12,24,38,.80),rgba(7,14,23,.94));overflow:hidden}
.v48-plan-card{padding:17px}.v48-card-kicker{display:flex;align-items:center;gap:8px;color:#9beef7;font-size:10px;font-weight:900;letter-spacing:.09em;text-transform:uppercase}.v48-card-kicker span{font-size:18px;line-height:1}
.v48-plan-summary{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:13px}.v48-plan-stat{min-width:0;padding:12px;border:1px solid rgba(255,255,255,.065);border-radius:13px;background:rgba(255,255,255,.018)}.v48-plan-stat span{display:block;color:var(--muted);font-size:10px;font-weight:850;letter-spacing:.05em}.v48-plan-stat strong{display:block;margin-top:5px;font-family:var(--display);font-size:19px;line-height:1.18;overflow-wrap:anywhere}.v48-plan-stat small{display:block;margin-top:4px;color:#8497aa;font-size:10.5px;line-height:1.45;overflow-wrap:anywhere}
.v48-strategy-form{margin-top:15px;padding-top:14px;border-top:1px solid rgba(255,255,255,.065)}.v48-form-label{display:block;margin:0 0 8px;color:#91a5b9;font-size:10px;font-weight:900;letter-spacing:.075em;text-transform:uppercase}.v48-choice-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.v48-choice{position:relative;min-width:0}.v48-choice input{position:absolute;opacity:0;pointer-events:none}.v48-choice span{display:flex;align-items:center;justify-content:center;min-height:42px;padding:7px 8px;border:1px solid rgba(116,128,143,.24);border-radius:12px;background:rgba(255,255,255,.015);color:#aebdcb;font-size:10.5px;font-weight:900;letter-spacing:.03em;text-align:center;cursor:pointer;transition:.16s ease;overflow-wrap:anywhere}.v48-choice input:checked+span{border-color:rgba(69,215,232,.62);background:rgba(69,215,232,.075);color:#dcfbff;box-shadow:0 0 0 3px rgba(69,215,232,.055)}
.v48-goal-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-top:2px}.v48-goal{position:relative;min-width:0}.v48-goal input{position:absolute;opacity:0;pointer-events:none}.v48-goal span{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:7px;min-height:50px;padding:8px 9px;border:1px solid rgba(116,128,143,.24);border-radius:12px;background:rgba(255,255,255,.015);color:#aebdcb;font-size:10px;font-weight:850;line-height:1.25;cursor:pointer;transition:.16s ease;overflow-wrap:anywhere}.v48-goal b{font-size:17px;font-weight:400}.v48-goal input:checked+span{border-color:rgba(155,124,255,.58);background:rgba(155,124,255,.075);color:#eee8ff;box-shadow:0 0 0 3px rgba(155,124,255,.05)}
.v48-save{width:100%;margin-top:10px}.v48-form-note{display:block;margin-top:7px;color:#74889d;font-size:9.8px;line-height:1.45}
.v48-adherence-card{padding:17px;display:flex;flex-direction:column;justify-content:center}.v48-adherence-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.v48-adherence-title{min-width:0}.v48-adherence-title span{display:block;color:#91a5b9;font-size:10px;font-weight:900;letter-spacing:.08em}.v48-adherence-title strong{display:block;margin-top:5px;font-family:var(--display);font-size:23px;line-height:1.08;overflow-wrap:anywhere}.v48-adherence-number{flex:0 0 auto;font-family:var(--display);font-size:43px;line-height:.95;letter-spacing:-.035em}.v48-adherence-number small{font-family:var(--font);font-size:13px;color:var(--muted);letter-spacing:0}.v48-adherence-track{position:relative;height:15px;margin-top:17px;border:1px solid rgba(116,128,143,.22);border-radius:999px;background:#111a24;overflow:hidden;box-shadow:inset 0 2px 7px rgba(0,0,0,.35)}.v48-adherence-fill{height:100%;border-radius:999px;box-shadow:0 0 18px rgba(69,215,232,.26);transition:width .7s ease}.v48-adherence-fill.strong{background:linear-gradient(90deg,#16b984,#51e7ae)}.v48-adherence-fill.good{background:linear-gradient(90deg,#17b8cc,#54ddec)}.v48-adherence-fill.partial{background:linear-gradient(90deg,#d6902a,#f2bc52)}.v48-adherence-fill.low{background:linear-gradient(90deg,#be4d5b,#ef6a72)}.v48-adherence-fill.learning{background:linear-gradient(90deg,#687789,#8998aa)}
.v48-adherence-label{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:8px;color:#aab8c6;font-size:10.5px;font-weight:850}.v48-adherence-label strong{color:#e7f4f7}.v48-score-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}.v48-score{padding:10px 11px;border:1px solid rgba(255,255,255,.06);border-radius:12px;background:rgba(255,255,255,.015)}.v48-score span{display:block;color:#8295a8;font-size:9.5px;font-weight:850;letter-spacing:.04em}.v48-score strong{display:block;margin-top:4px;font-size:16px}.v48-direction-headline{margin:13px 0 0;padding-top:12px;border-top:1px solid rgba(255,255,255,.065);color:#cbd5de;font-size:12.5px;line-height:1.6;overflow-wrap:anywhere}
.v482-journey{margin:0 0 14px;padding:15px;border:1px solid rgba(69,215,232,.18);border-radius:17px;background:linear-gradient(145deg,rgba(69,215,232,.028),rgba(155,124,255,.025));overflow:hidden}.v482-journey-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:12px}.v482-journey-head>div{min-width:0}.v482-journey-head strong{display:block;font-family:var(--display);font-size:18px;line-height:1.2}.v482-journey-head small{display:block;margin-top:4px;color:#8497aa;font-size:10.5px;line-height:1.45}.v482-journey-head>b{flex:0 0 auto;display:inline-flex;align-items:center;min-height:28px;padding:0 9px;border:1px solid rgba(69,215,232,.20);border-radius:999px;color:#b8eff6;font-size:9px;letter-spacing:.05em}.v482-journey-grid{display:grid;grid-template-columns:minmax(0,1fr) 34px minmax(0,1fr) 34px minmax(0,1fr);align-items:stretch;gap:7px}.v482-journey-step{min-width:0;padding:12px;border:1px solid rgba(255,255,255,.065);border-radius:13px;background:rgba(255,255,255,.018)}.v482-journey-step.decision{border-color:rgba(155,124,255,.24);background:rgba(155,124,255,.035)}.v482-journey-step.now{border-color:rgba(69,215,232,.24);background:rgba(69,215,232,.035)}.v482-journey-step span{display:block;color:#8295a8;font-size:9.3px;font-weight:900;letter-spacing:.065em}.v482-journey-step strong{display:block;margin-top:6px;font-family:var(--display);font-size:19px;line-height:1.15;overflow-wrap:anywhere}.v482-journey-step small{display:block;margin-top:5px;color:#95a5b5;font-size:10px;line-height:1.45;overflow-wrap:anywhere}.v482-zone-mini{display:flex;gap:7px;flex-wrap:wrap;margin-top:8px}.v482-zone-mini b{font-size:9.2px;font-weight:850;letter-spacing:.02em}.v482-zone-mini .low{color:#74e9ad}.v482-zone-mini .mod{color:#ffc66e}.v482-zone-mini .high{color:#ff8d94}.v482-journey-arrow{display:grid;place-items:center;color:#668296;font-size:22px;font-weight:300}.v482-journey-summary{margin:11px 0 0;padding-top:10px;border-top:1px solid rgba(255,255,255,.055);color:#b8c5d1;font-size:11.5px;line-height:1.55;overflow-wrap:anywhere}
.v48-cycle-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px}.v48-cycle-card{padding:15px}.v48-cycle-head{display:flex;align-items:center;gap:8px}.v48-cycle-head span{font-size:18px}.v48-cycle-head strong{font-size:10px;letter-spacing:.08em;color:#a9ecf5}.v48-cycle-card h3{margin:8px 0 6px;font-family:var(--display);font-size:20px;line-height:1.16}.v48-cycle-card p{margin:0;color:#b8c5d1;font-size:12px;line-height:1.62;overflow-wrap:anywhere}.v48-cycle-card.micro{border-color:rgba(155,124,255,.22)}.v48-cycle-card.micro .v48-cycle-head strong{color:#d4c7ff}
.v48-season-context{padding:15px;margin-top:2px}.v48-season-context-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:12px}.v48-season-context-head>div{min-width:0}.v48-season-context-head strong{display:block;font-family:var(--display);font-size:20px}.v48-season-context-head small{display:block;margin-top:4px;color:#8497aa;font-size:10.5px;line-height:1.45}.v48-season-context-head b{flex:0 0 auto;display:inline-flex;align-items:center;min-height:29px;padding:0 9px;border:1px solid rgba(69,215,232,.20);border-radius:999px;color:#b9eff6;font-size:9px;letter-spacing:.05em}.v48-method{margin:12px 0 0;color:#73879b;font-size:9.8px;line-height:1.48;overflow-wrap:anywhere}
body.v27-report-mode .v48-strategy-form,.v10-preview-mode .v48-strategy-form{display:none!important}
@media(max-width:980px){.v48-strategy-grid{grid-template-columns:1fr}.v48-goal-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:700px){.v48-plan-card,.v48-adherence-card,.v48-cycle-card,.v48-season-context{padding:14px}.v482-journey{padding:14px}.v482-journey-grid{grid-template-columns:1fr}.v482-journey-arrow{height:18px;transform:rotate(90deg);font-size:18px}.v48-plan-summary,.v48-cycle-grid{grid-template-columns:1fr}.v48-choice-row{grid-template-columns:repeat(2,minmax(0,1fr))}.v48-goal-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.v48-adherence-number{font-size:38px}.v48-adherence-title strong{font-size:21px}.v48-score-grid{grid-template-columns:1fr 1fr}}
@media(max-width:430px){.v482-journey-head{flex-direction:column}.v482-journey-head>b{align-self:flex-start}.v482-journey-step{padding:11px}.v48-adherence-top{gap:8px}.v48-adherence-number{font-size:34px}.v48-adherence-title strong{font-size:19px}.v48-goal span{min-height:52px;padding:8px;font-size:9.8px}.v48-goal b{font-size:16px}.v48-score-grid{grid-template-columns:1fr}.v48-season-context-head{flex-direction:column}.v48-season-context-head b{align-self:flex-start}}
@media(max-width:360px){.v48-choice-row,.v48-goal-grid{grid-template-columns:1fr}.v48-plan-card,.v48-adherence-card,.v48-cycle-card,.v48-season-context{padding:12px}.v48-adherence-top{flex-direction:column}.v48-adherence-number{font-size:36px}}
@media print{.v48-direction{break-inside:auto}.v48-strategy-grid,.v48-cycle-grid{grid-template-columns:1fr 1fr}.v48-strategy-form{display:none!important}.v48-plan-card,.v48-adherence-card,.v48-cycle-card,.v48-season-context{break-inside:avoid;page-break-inside:avoid}}

/* PRODUCT V4.8.4 · Snapshot preflight + adaptive rhythm + compact unavailable metrics. */
.v481-preflight{min-width:0;margin:4px 0 12px;padding:12px;border:1px solid rgba(69,215,232,.18);border-radius:14px;background:rgba(69,215,232,.035);text-align:left}
.v481-preflight-head{display:flex;align-items:flex-start;gap:9px;margin-bottom:10px;min-width:0}.v481-preflight-head>span{font-size:17px;line-height:1}.v481-preflight-head>div{min-width:0}.v481-preflight-head strong{display:block;color:#d6f9fd;font-size:11px;font-weight:900;letter-spacing:.075em}.v481-preflight-head small{display:block;margin-top:3px;color:#8396a9;font-size:10px;line-height:1.45;overflow-wrap:anywhere}
.v481-preflight-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.v481-preflight-field{display:block;min-width:0}.v481-preflight-field>span{display:block;margin-bottom:5px;color:#8da1b5;font-size:9px;font-weight:900;letter-spacing:.065em}.v481-preflight-field select{width:100%;height:42px;min-width:0;border:1px solid rgba(116,128,143,.30);border-radius:11px;background:#090d12;color:#e5edf5;padding:0 9px;font-family:var(--font);font-size:10.5px;font-weight:800;outline:none}.v481-preflight-field select:focus{border-color:rgba(69,215,232,.58);box-shadow:0 0 0 3px rgba(69,215,232,.055)}
.v481-preflight-note{display:block;margin-top:8px;color:#74889b;font-size:9.5px;line-height:1.45;overflow-wrap:anywhere}.v481-preflight.is-preview{opacity:.76}
.v481-unavailable-panel{min-width:0}.v481-unavailable-trigger{display:grid!important;grid-template-columns:minmax(0,1fr) auto auto!important;align-items:center!important;gap:10px!important;padding:12px 14px!important;min-width:0}.v481-unavailable-label{display:flex;align-items:center;gap:8px;min-width:0;color:#c4ced8;font-size:12px;line-height:1.35}.v481-unavailable-label strong{font-family:var(--display);font-size:15px;line-height:1.22;white-space:normal;word-break:normal;overflow-wrap:normal}.v481-unavailable-count{display:grid;place-items:center;min-width:28px;height:28px;padding:0 7px;border:1px solid rgba(144,158,177,.22);border-radius:999px;color:#aab9c9;background:rgba(255,255,255,.025);font-size:10px;font-weight:900}.v481-unavailable-plus{width:28px!important;height:28px!important;display:grid!important;place-items:center!important;margin:0!important;flex:0 0 28px!important}.v481-unavailable-panel .v43-gap-body{padding-top:0}
@media(max-width:560px){.v481-unavailable-trigger{grid-template-columns:minmax(0,1fr) auto!important;grid-template-areas:"label plus" "count count"!important;align-items:start!important;padding:12px!important;gap:9px 10px!important}.v481-unavailable-label{grid-area:label;display:block;min-width:0;padding-right:6px}.v481-unavailable-label strong{display:inline;white-space:normal;word-break:normal;overflow-wrap:break-word}.v481-unavailable-count{grid-area:count;justify-self:start;margin-top:1px}.v481-unavailable-plus{grid-area:plus;justify-self:end;align-self:start}}
@media(max-width:430px){.v481-preflight-grid{grid-template-columns:1fr}.v481-unavailable-trigger{padding:11px 12px!important;gap:8px 9px!important}.v481-unavailable-label{font-size:11.5px}.v481-unavailable-label strong{font-size:14.5px;line-height:1.24}.v481-unavailable-count{min-width:27px;height:27px;padding:0 6px}}
@media(max-width:360px){.v481-unavailable-trigger{padding:11px 10px!important}.v481-unavailable-label strong{font-size:14px}}
"""

OWNER_PORTAL_PAGE = """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0a0d0f"><title>THE LAB · Owner Workspace</title><link rel="icon" type="image/png" sizes="192x192" href="{{ url_for('pwa_icon_192') }}"><style>{{ css }}</style></head>
<body class="v47-owner-page"><main class="v4-shell v47-owner-shell">
<header class="v4-topbar"><div class="v4-brand"><img class="v4-brand-logo" src="data:image/png;base64,{{ brand_wordmark }}" alt="The Gluten Free Cyclist"></div><div class="v4-top-actions"><span class="v4-pill">OWNER</span><a class="v4-logout" href="{{ url_for('logout') }}">Log out</a></div></header>
<section class="v4-card v4-hero v47-owner-hero"><img class="v4-logo" src="data:image/png;base64,{{ logo }}" alt="The Gluten Free Cyclist Lab"><h1 class="v4-title">Choose your workspace</h1><div class="v4-kicker">ONE LOGIN · TWO SEPARATE ROLES</div><p class="v47-owner-sub">Your personal Snapshot stays on its existing private data path. Product administration stays on the Product database. Choose what you want to do now.</p></section>
<section class="v47-owner-grid">
{% if owner_storage.ready %}<a class="v4-card v47-owner-choice snapshot" href="{{ url_for('owner_snapshot') }}">{% else %}<div class="v4-card v47-owner-choice snapshot is-disabled">{% endif %}
<div class="v47-owner-choice-head"><span class="v47-owner-choice-icon" aria-hidden="true">🧬</span><span class="v47-owner-status {{ '' if owner_storage.ready else 'warn' }}">{{ 'PERSONAL NEON READY' if owner_storage.ready else 'PERSONAL NEON SETUP REQUIRED' }}</span></div>
<div class="v47-owner-copy"><span>ATHLETE MODE</span><h2>My Health Snapshot</h2><p>Your normal THE LAB workspace: your existing personal Neon Memory, Planning, Daily Logs and Last Full Report, together with your owner Intervals and AI credentials. No beta-athlete data is mixed into this workspace.</p></div>
<div class="v47-owner-meta"><b>{{ 'INTERVALS READY' if intervals_ready else 'INTERVALS ENV REQUIRED' }}</b><b>{{ 'OWNER AI READY' if ai_ready else 'OWNER AI ENV REQUIRED' }}</b><b>PERSONAL MEMORY</b></div><div class="v47-owner-arrow">OPEN MY SNAPSHOT →</div>
{% if owner_storage.ready %}</a>{% else %}</div>{% endif %}
<a class="v4-card v47-owner-choice admin" href="{{ url_for('admin_control_center') }}"><div class="v47-owner-choice-head"><span class="v47-owner-choice-icon" aria-hidden="true">⚙️</span><span class="v47-owner-status">PRODUCT CONTROL</span></div><div class="v47-owner-copy"><span>ADMIN MODE</span><h2>Control Center</h2><p>Manage invitations, licenses, password resets, athlete AI access, sessions, usage metering and security audit. This stays isolated on Product Neon.</p></div><div class="v47-owner-meta"><b>USERS</b><b>LICENSES</b><b>AI USAGE</b><b>SECURITY</b></div><div class="v47-owner-arrow">OPEN ADMIN →</div></a>
</section>
{% if owner_storage.configured and not owner_storage.ready %}<div class="v47-owner-note error"><strong>Personal Neon connection check failed.</strong> {{ owner_storage.error or 'Check THE_LAB_OWNER_DATABASE_URL on Render.' }}</div>{% elif not owner_storage.configured %}<div class="v47-owner-note error"><strong>One Render variable is still needed.</strong> Add the existing personal Neon connection string as <code>THE_LAB_OWNER_DATABASE_URL</code>. Product <code>DATABASE_URL</code> must remain pointed at Product Neon.</div>{% else %}<div class="v47-owner-note">The owner bridge performs no schema migration on personal Neon. The personal database remains compatible with the existing standalone THE LAB service while Product users remain isolated on Product Neon.</div>{% endif %}
</main></body></html>
"""

LOGIN_PAGE = """
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="theme-color" content="#06101d">
  <meta name="application-name" content="The Lab">
  <meta name="mobile-web-app-capable" content="yes">
  <meta name="apple-mobile-web-app-capable" content="yes">
  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
  <meta name="apple-mobile-web-app-title" content="The Lab">
  <link rel="manifest" href="{{ url_for('pwa_manifest') }}">
  <link rel="apple-touch-icon" sizes="192x192" href="{{ url_for('pwa_icon_192') }}">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Amatic+SC:wght@400;700&family=Nunito:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <title>The Gluten Free Cyclist · The Lab</title>
  <link rel="icon" type="image/png" sizes="192x192" href="{{ url_for('pwa_icon_192') }}">
  <style>{{ css }}</style>
  <style>.v3-admin-console{display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:0 13px;border-radius:10px;background:linear-gradient(135deg,#7b4dff,#b05cff);border:1px solid rgba(225,207,255,.72);color:#fff!important;text-decoration:none;font-weight:900;letter-spacing:.055em;box-shadow:0 0 0 1px rgba(123,77,255,.12),0 8px 24px rgba(123,77,255,.28)}.v3-admin-console:hover{filter:brightness(1.08)}@media(max-width:720px){.v3-admin-console{order:-3;min-height:42px;padding:0 15px}}</style>
</head>
<body class="v46-login-page" data-auth-error="{{ '1' if error else '0' }}">
  <main class="v46-login-shell">
    <section class="v4-card v46-login-stage">
      <div class="v46-brand-lockup">
        <img class="v46-login-logo" src="data:image/png;base64,{{ logo }}" alt="The Gluten Free Cyclist · The Lab">
        <div class="v46-login-kicker">ATHLETE-SPECIFIC TRAINING DECISION SYSTEM</div>
        <h1>Your physiology. Your baseline. Your next move.</h1>
        <p class="v46-login-copy">THE LAB is a personal training intelligence platform that combines recovery, training load, sleep, physiology, planning and fueling into one evolving daily snapshot. Deterministic Python engines establish the athlete state; AI Coach explains the why, the trade-offs and the next move.</p>
      </div>

      <div class="v46-feature-grid" aria-label="THE LAB features">
        <article><span class="v46-feature-icon" aria-hidden="true">🧬</span><div><strong>Personal Baselines</strong><small>HRV, resting HR, sleep and longitudinal athlete-specific references.</small></div></article>
        <article><span class="v46-feature-icon" aria-hidden="true">❤️</span><div><strong>Recovery Signals</strong><small>Autonomic, sleep and subjective context interpreted together.</small></div></article>
        <article><span class="v46-feature-icon" aria-hidden="true">⚡</span><div><strong>Training State</strong><small>Load, phase, Coach Clock, restrictions and the next-session decision.</small></div></article>
        <article><span class="v46-feature-icon" aria-hidden="true">🥤</span><div><strong>Fueling Engine</strong><small>Duration- and intensity-aware carbohydrate strategy built around the athlete.</small></div></article>
        <article><span class="v46-feature-icon" aria-hidden="true">🔬</span><div><strong>Learning Lab</strong><small>Advanced physiology, dynamic references and research context that improve with data.</small></div></article>
        <article><span class="v46-feature-icon" aria-hidden="true">💬</span><div><strong>AI Coach</strong><small>Ask the current Snapshot questions without replacing deterministic safety rules.</small></div></article>
      </div>

      {% if request.args.get('security') %}<div style="margin:18px 0 0;padding:12px 14px;border:1px solid rgba(69,215,232,.28);border-radius:14px;background:rgba(69,215,232,.06);color:#d8f9fc"><strong style="display:block;font-size:12px;letter-spacing:.06em">{{ request.args.get('security') }}</strong><span style="display:block;margin-top:4px;color:#a9bdca;font-size:12px;line-height:1.5">{{ request.args.get('security_detail','Please log in again.') }}</span></div>{% endif %}

      <div class="v46-login-actions">
        <button class="v46-login-primary" type="button" id="v46-open-login"><span>🔐</span> Log in to THE LAB</button>
        <a class="v46-login-secondary" href="{{ url_for('preview') }}"><span>✨</span> Explore demo preview</a>
        <a class="v46-login-secondary" href="{{ url_for('activate') }}"><span>🎟️</span> Activate invitation</a>
      </div>
      <div class="v46-login-trust"><span>🔒 Authenticated athlete access</span><span>🧠 Persistent memory</span><span>📊 Intervals.icu data</span><span>🤖 AI only where explicitly activated</span></div>
    </section>

    <footer class="v46-legal" aria-label="Privacy and copyright information">
      <p><strong>Privacy.</strong> Private athlete data, credentials, persistent memory and connected-service data remain behind authentication. The public demo uses sample data and does not expose the authenticated athlete's private records.</p>
      <p><strong>Copyright &amp; intellectual property.</strong> © 2026 The Gluten Free Cyclist. All rights reserved. The original branding, visual identity, interface, copy, code and content published under <em>“The Gluten Free Cyclist”</em> and <em>“The Gluten Free Cyclist: The Lab”</em> are protected by applicable copyright and intellectual-property laws and may not be copied, reproduced, distributed, republished or adapted without prior written permission.</p>
    </footer>
  </main>

  <div class="v46-login-modal" id="v46-login-modal" hidden>
    <button class="v46-modal-backdrop" type="button" data-v46-close aria-label="Close login"></button>
    <section class="v46-modal-card" role="dialog" aria-modal="true" aria-labelledby="v46-modal-title">
      <button class="v46-modal-close" type="button" data-v46-close aria-label="Close login">×</button>
      <div class="v46-modal-mark" aria-hidden="true">🔐</div>
      <span class="v46-modal-kicker">SECURE ATHLETE ACCESS</span>
      <h2 id="v46-modal-title">Log in to THE LAB</h2>
      <p>Enter your personal THE LAB credentials. Access is verified and revocable server-side.</p>
      <form method="post" class="v46-login-form"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
        <label><span>USERNAME</span><input id="v46-username" type="text" name="username" placeholder="Username" autocomplete="username" autocapitalize="none" spellcheck="false" required></label>
        <label><span>PASSWORD</span><input type="password" name="password" placeholder="Password" autocomplete="current-password" required></label>
        <button type="submit">Enter THE LAB</button>
      </form>
      {% if error %}<div class="v4-error v46-login-error">{{ error }}</div>{% endif %}
      <small class="v46-modal-foot">Credentials are verified server-side. The public demo remains isolated from private athlete records.</small>
    </section>
  </div>

  <script>
    (function(){
      var modal=document.getElementById('v46-login-modal'), openBtn=document.getElementById('v46-open-login'), user=document.getElementById('v46-username');
      function openLogin(){ if(!modal)return; modal.hidden=false; document.body.classList.add('v46-modal-open'); setTimeout(function(){if(user)user.focus();},40); }
      function closeLogin(){ if(!modal)return; modal.hidden=true; document.body.classList.remove('v46-modal-open'); if(openBtn)openBtn.focus(); }
      if(openBtn)openBtn.addEventListener('click',openLogin);
      document.querySelectorAll('[data-v46-close]').forEach(function(el){el.addEventListener('click',closeLogin);});
      document.addEventListener('keydown',function(e){if(e.key==='Escape'&&modal&&!modal.hidden)closeLogin();});
      if(document.body.getAttribute('data-auth-error')==='1')openLogin();
      if ('serviceWorker' in navigator) { window.addEventListener('load', function () { navigator.serviceWorker.register('/service-worker.js'); }); }
    })();
  </script>
</body>
</html>
"""

