def get_active_training_strategy_plan(user_id=None):
    owner_id = _data_owner_user_id(user_id)
    rows = _db_execute(
        "SELECT * FROM training_strategy_plans WHERE user_id=? AND status='active' ORDER BY created_at_utc DESC LIMIT 1",
        (owner_id,), fetch=True,
    )
    return dict(rows[0]) if rows else None


def get_training_strategy_history(user_id=None, limit=12):
    owner_id = _data_owner_user_id(user_id)
    rows = _db_execute(
        "SELECT * FROM training_strategy_plans WHERE user_id=? ORDER BY created_at_utc DESC LIMIT ?",
        (owner_id, max(1, min(int(limit or 12), 50))), fetch=True,
    )
    return [dict(x) for x in rows]


def training_strategy_form_state(user_id=None, preview=False):
    """Small pre-Snapshot form state. No external API call.

    The declared direction is chosen before /analyze starts any Intervals or AI
    work. Existing plans are preselected; new athletes explicitly choose a goal.
    """
    if preview:
        plan = {"distribution_target": "PYRAMIDAL", "primary_goal": "POWER_20", "started_on": None}
    else:
        try:
            plan = get_active_training_strategy_plan(user_id)
        except Exception:
            plan = None
    plan = plan or {}
    return {
        "active": bool(plan),
        "distribution_target": str(plan.get("distribution_target") or "AUTO").upper(),
        "primary_goal": str(plan.get("primary_goal") or "").upper(),
        "started_on": plan.get("started_on"),
        "distribution_options": [
            {"key": key, "label": label, "description": description}
            for key, label, description in TRAINING_DISTRIBUTION_OPTIONS
        ],
        "goal_options": [
            {"key": key, "emoji": emoji, "label": label}
            for key, emoji, label in TRAINING_GOAL_OPTIONS
        ],
    }


def save_training_strategy_plan(distribution_target, primary_goal, user_id=None):
    """Version the athlete's declared training direction on Product Neon.

    This intentionally never uses _data_execute: even the OWNER keeps strategy
    metadata on Product Neon while personal logs/memory/reports remain on the
    dedicated Personal Neon bridge. No API key or health datum is stored here.
    """
    owner_id = _data_owner_user_id(user_id)
    distribution_target = str(distribution_target or '').strip().upper()
    primary_goal = str(primary_goal or '').strip().upper()
    if distribution_target not in TRAINING_DISTRIBUTION_KEYS:
        raise ValueError("Choose a valid training distribution.")
    if primary_goal not in TRAINING_GOAL_KEYS:
        raise ValueError("Choose a valid primary goal.")

    now_utc = _now_utc_text()
    try:
        local_today = datetime.now(_runtime_timezone(owner_id)).date().isoformat()
    except Exception:
        local_today = datetime.utcnow().date().isoformat()
    current = get_active_training_strategy_plan(owner_id)
    if current and current.get('distribution_target') == distribution_target and current.get('primary_goal') == primary_goal:
        _db_execute("UPDATE training_strategy_plans SET updated_at_utc=? WHERE id=? AND user_id=?", (now_utc, current['id'], owner_id))
        return get_active_training_strategy_plan(owner_id), False

    if current:
        _db_execute(
            "UPDATE training_strategy_plans SET status='completed', ended_on=?, updated_at_utc=? WHERE id=? AND user_id=?",
            (local_today, now_utc, current['id'], owner_id),
        )
    plan_id = str(uuid.uuid4())
    _db_execute(
        "INSERT INTO training_strategy_plans (id, user_id, distribution_target, primary_goal, status, started_on, ended_on, created_at_utc, updated_at_utc) VALUES (?, ?, ?, ?, 'active', ?, NULL, ?, ?)",
        (plan_id, owner_id, distribution_target, primary_goal, local_today, now_utc, now_utc),
    )
    return get_active_training_strategy_plan(owner_id), True



