def _runtime_identity(user_id=None):
    """Return (owner_id, user) without ever choosing another athlete implicitly."""
    try:
        owner_id = _data_owner_user_id(user_id)
    except RuntimeError:
        return None, None
    return owner_id, (_get_user_by_id(owner_id) or {})


def _runtime_is_athlete(user_id=None):
    _owner_id, user = _runtime_identity(user_id)
    return bool(user and user.get("role") != "admin")


def _runtime_profile(user_id=None):
    owner_id, user = _runtime_identity(user_id)
    if owner_id and user and user.get("role") != "admin":
        return get_athlete_profile(owner_id)
    return None


def _runtime_timezone(user_id=None):
    profile = _runtime_profile(user_id)
    if profile:
        try:
            return ZoneInfo(str(profile.get("timezone_name") or ""))
        except Exception:
            # Invalid timezone cannot leak owner configuration; UTC is neutral.
            return ZoneInfo("UTC")
    return ROME_TZ


def _runtime_athlete_context(user_id=None):
    profile = _runtime_profile(user_id)
    if profile:
        explicit = str(profile.get("athlete_context") or "").strip()
        if explicit:
            return explicit
        display = profile.get("display_name") or "The athlete"
        sport = str(profile.get("sport") or "cycling").lower()
        environment = str(profile.get("training_environment") or "mixed").lower()
        return f"{display} is a {sport} athlete. Usual training environment: {environment}. No additional athlete context was supplied."
    return ATHLETE_CONTEXT


def _runtime_fueling_profile(user_id=None):
    profile = _runtime_profile(user_id)
    if not profile:
        return dict(OWNER_FUELING_PROFILE)
    values = {**_GENERIC_FUELING_STARTER, **dict(profile.get("fueling") or {})}
    environment = str(profile.get("training_environment") or "MIXED").upper()
    values["default_training_environment"] = environment if environment in ("INDOOR", "OUTDOOR", "MIXED") else "MIXED"
    return values


def _runtime_baseline_values(user_id=None):
    profile = _runtime_profile(user_id)
    if not profile:
        return dict(OWNER_GARMIN_BASELINES)
    values = dict(profile.get("baselines") or {})
    # Missing athlete references remain None so the deterministic engine learns
    # from longitudinal data instead of inheriting the owner's Garmin ranges.
    return {key: values.get(key) for key in _BASELINE_FIELDS}


class _RuntimeProfileMapping:
    def __init__(self, resolver):
        self._resolver = resolver
    def __getitem__(self, key):
        return self._resolver().get(key)
    def get(self, key, default=None):
        value = self._resolver().get(key)
        return default if value is None else value
    def copy(self):
        return dict(self._resolver())


# Preserve the old symbol names as request-scoped proxies so the mature engine
# stays surgical while every authenticated athlete receives only their own data.
GARMIN_BASELINES = _RuntimeProfileMapping(_runtime_baseline_values)
ATHLETE_FUELING_PROFILE = _RuntimeProfileMapping(_runtime_fueling_profile)


def _resolve_intervals_runtime(user_id=None):
    """Return the authenticated athlete's Intervals ID/key.

    Athlete accounts are strictly isolated and never fall back to OWNER Render
    environment variables. The admin keeps legacy env fallback for compatibility.
    """
    owner_id = _data_owner_user_id(user_id)
    user = _get_user_by_id(owner_id) or {}
    integration = get_intervals_integration(owner_id, include_secret=True)
    if integration and integration.get("status") == "connected" and integration.get("api_key") and integration.get("external_athlete_id"):
        return {
            "athlete_id": str(integration.get("external_athlete_id")),
            "api_key": integration.get("api_key"),
            "source": "athlete_encrypted_integration" if user.get("role") != "admin" else "owner_saved_integration",
        }
    if user.get("role") == "admin" and ICU_API_KEY and ICU_ATHLETE_ID:
        return {"athlete_id": ICU_ATHLETE_ID, "api_key": ICU_API_KEY, "source": "owner_server_fallback"}
    raise RuntimeError("Intervals.icu is not configured for this athlete. Complete Athlete Settings first.")


_AI_PROVIDER_LABELS = {"ANTHROPIC": "Claude / Anthropic", "OPENAI": "OpenAI / GPT", "GEMINI": "Google Gemini"}
_AI_DEFAULT_MODELS = {"ANTHROPIC": "claude-sonnet-5", "OPENAI": "gpt-5.6-terra", "GEMINI": "gemini-3.5-flash"}


def get_ai_integration(user_id=None, include_secret=False):
    owner_id = _data_owner_user_id(user_id)
    rows = _db_execute("SELECT * FROM athlete_ai_integrations WHERE user_id=? LIMIT 1", (owner_id,), fetch=True)
    if not rows:
        return None
    row = dict(rows[0])
    row["provider_label"] = _AI_PROVIDER_LABELS.get(str(row.get("provider") or "").upper(), row.get("provider") or "AI")
    row["has_credential"] = bool(row.get("credential_ciphertext"))
    if include_secret:
        row["api_key"] = _decrypt_credential(row.get("credential_ciphertext"))
    row.pop("credential_ciphertext", None)
    return row


def _openai_output_text(payload):
    if isinstance(payload, dict) and isinstance(payload.get("output_text"), str):
        return payload.get("output_text", "").strip()
    chunks = []
    for item in (payload.get("output") or []) if isinstance(payload, dict) else []:
        if not isinstance(item, dict):
            continue
        for part in item.get("content") or []:
            if not isinstance(part, dict):
                continue
            text = part.get("text")
            if isinstance(text, str) and text:
                chunks.append(text)
    return "".join(chunks).strip()


def _gemini_output_text(payload):
    """Extract text from Gemini GenerateContent without depending on an SDK."""
    chunks = []
    for candidate in (payload.get("candidates") or []) if isinstance(payload, dict) else []:
        if not isinstance(candidate, dict):
            continue
        content = candidate.get("content") or {}
        if not isinstance(content, dict):
            continue
        for part in content.get("parts") or []:
            if not isinstance(part, dict):
                continue
            value = part.get("text")
            if isinstance(value, str) and value:
                chunks.append(value)
    return "".join(chunks).strip()


class AIUsageLimitError(RuntimeError):
    """Raised before an outbound AI request when the active THE LAB lane is exhausted."""


class AIManagedFallbackRequired(RuntimeError):
    """Internal signal: Managed premium allowance is exhausted; try Standard Gemini."""


def _standard_ai_runtime_config():
    """THE LAB Standard lane: server-side Gemini credential, never exposed to athletes.

    V4.8.33 deliberately resolves the legacy Standard-only 2.5 Flash setting to
    Gemini 3.5 Flash.  This does not rewrite Render ENV and never changes an
    athlete's BYOK model selection.
    """
    requested = str(STANDARD_AI_MODEL_REQUESTED or "").strip()
    model = str(STANDARD_AI_MODEL or "gemini-3.5-flash").strip() or "gemini-3.5-flash"
    key = str(STANDARD_AI_API_KEY or "").strip()
    return {
        "provider": "GEMINI", "model": model, "api_key": key,
        "configured": bool(model and key),
        "requested_model": requested or None,
        "legacy_model_migrated": bool(requested == "gemini-2.5-flash" and model != requested),
    }


def _platform_ai_runtime_config():
    provider = str(PLATFORM_AI_PROVIDER or "OPENAI").strip().upper()
    model = str(PLATFORM_AI_MODEL or "").strip() or _AI_DEFAULT_MODELS.get(provider, "")
    key = str(PLATFORM_AI_API_KEY or "").strip()
    return {"provider": provider, "model": model, "api_key": key, "configured": bool(provider in _AI_PROVIDER_LABELS and model and key)}


def _global_ai_access_mode():
    """Return the safe global default used when an athlete has no explicit override."""
    return AI_ACCESS_MODE if AI_ACCESS_MODE in {"BYOK", "STANDARD", "PLATFORM"} else "BYOK"


def _effective_ai_access_mode(user_id=None):
    """Resolve AI access per athlete without ever storing server-side secrets in Neon."""
    owner_id = _data_owner_user_id(user_id)
    rows = _db_execute("SELECT role, ai_access_mode_override FROM users WHERE id=? LIMIT 1", (owner_id,), fetch=True)
    if not rows:
        return _global_ai_access_mode()
    user = rows[0]
    if str(user.get("role") or "").lower() == "admin":
        return _global_ai_access_mode()
    override = str(user.get("ai_access_mode_override") or "").strip().upper()
    return override if override in {"BYOK", "STANDARD", "PLATFORM"} else _global_ai_access_mode()


def set_user_ai_access_mode(user_id, requested_mode, actor_user_id):
    """Set/clear an athlete-specific AI access override from the owner dashboard."""
    target = _get_user_by_id(user_id)
    if not target or target.get("role") == "admin":
        raise ValueError("AI access mode can only be changed for athlete accounts.")
    requested = str(requested_mode or "DEFAULT").strip().upper()
    if requested not in {"DEFAULT", "BYOK", "STANDARD", "PLATFORM"}:
        raise ValueError("Unknown AI access mode.")
    if requested == "STANDARD" and not _standard_ai_runtime_config().get("configured"):
        raise ValueError("THE LAB Standard AI is not configured yet. Add THE_LAB_STANDARD_AI_API_KEY on Render, then retry.")
    if requested == "PLATFORM" and not _platform_ai_runtime_config().get("configured"):
        raise ValueError("THE LAB Managed AI is not configured yet. Add the platform provider, model and API key on Render once, then retry.")

    old_override = str(target.get("ai_access_mode_override") or "").strip().upper() or None
    new_override = None if requested == "DEFAULT" else requested
    _db_execute("UPDATE users SET ai_access_mode_override=?, updated_at_utc=? WHERE id=?", (new_override, _now_utc_text(), user_id))
    effective = _effective_ai_access_mode(user_id)
    _refresh_setup_completed(user_id)
    audit_event(
        "AI_ACCESS_MODE_UPDATED", actor_user_id=actor_user_id, target_user_id=user_id,
        details={
            "old_override": old_override, "new_override": new_override,
            "global_default": _global_ai_access_mode(), "effective_mode": effective,
        },
    )
    return {"override": new_override, "effective_mode": effective}


def _ai_usage_local_date(user_id):
    return datetime.now(_runtime_timezone(user_id)).date().isoformat()


def _ai_usage_token_counts(provider, payload):
    provider = str(provider or "").upper()
    if provider == "GEMINI":
        usage = payload.get("usageMetadata") if isinstance(payload, dict) else None
        if not isinstance(usage, dict):
            return None, None, None
        input_tokens = usage.get("promptTokenCount")
        output_tokens = usage.get("candidatesTokenCount")
        total_tokens = usage.get("totalTokenCount")
    else:
        usage = payload.get("usage") if isinstance(payload, dict) else None
        if not isinstance(usage, dict):
            return None, None, None
    if provider == "ANTHROPIC":
        input_tokens = usage.get("input_tokens")
        output_tokens = usage.get("output_tokens")
        total_tokens = None
        try:
            if input_tokens is not None or output_tokens is not None:
                total_tokens = int(input_tokens or 0) + int(output_tokens or 0)
        except (TypeError, ValueError):
            total_tokens = None
    elif provider != "GEMINI":
        input_tokens = usage.get("input_tokens")
        output_tokens = usage.get("output_tokens")
        total_tokens = usage.get("total_tokens")
        if total_tokens is None:
            try:
                if input_tokens is not None or output_tokens is not None:
                    total_tokens = int(input_tokens or 0) + int(output_tokens or 0)
            except (TypeError, ValueError):
                total_tokens = None
    def _safe_int(value):
        try:
            return int(value) if value is not None else None
        except (TypeError, ValueError):
            return None
    return _safe_int(input_tokens), _safe_int(output_tokens), _safe_int(total_tokens)


def _ai_quota_policy(credential_source):
    """Return quota lane for one outbound request.

    BYOK is intentionally unlimited by THE LAB.  The Standard quota is shared by
    direct Standard use and Managed fallback so an athlete can never consume more
    than three server-side Gemini calls in one local day regardless of how they
    reached that lane.
    """
    source = str(credential_source or "").strip().lower()
    if source == "platform_managed":
        return {
            "lane": "MANAGED", "limit": MANAGED_AI_DAILY_CALL_LIMIT,
            "sources": ("platform_managed",), "fallback": True,
        }
    if source in {"the_lab_standard", "managed_fallback_standard"}:
        return {
            "lane": "STANDARD", "limit": STANDARD_AI_DAILY_CALL_LIMIT,
            "sources": ("the_lab_standard", "managed_fallback_standard"), "fallback": False,
        }
    return {"lane": "UNLIMITED", "limit": None, "sources": (), "fallback": False}


def _reserve_ai_usage(user_id, call_type, provider, model, credential_source, counts_toward_limit=True, enforce_limit=True):
    """Atomically reserve one outbound AI request under the lane-specific policy.

    Counted requests are reserved before the provider call, so failed/time-out calls
    still count as real owner-funded requests. Connection tests never consume quota.
    BYOK calls remain visible in usage history but are never capped by THE LAB.
    """
    owner_id = _data_owner_user_id(user_id)
    user = _get_user_by_id(owner_id) or {}
    local_date = _ai_usage_local_date(owner_id)
    is_athlete = user.get("role") != "admin"
    policy = _ai_quota_policy(credential_source)
    limited_lane = bool(policy.get("limit") is not None and policy.get("sources"))
    should_enforce = bool(enforce_limit and counts_toward_limit and is_athlete and limited_lane)
    effective_counts = bool(counts_toward_limit and is_athlete and limited_lane)
    event_id = str(uuid.uuid4())
    conn = _db_connect()
    try:
        cur = conn.cursor()
        if _db_is_postgres():
            # Serialize quota decisions per athlete so simultaneous requests cannot
            # step around the three-call lane limits or the Managed→Standard switch.
            cur.execute(_db_sql("SELECT id FROM users WHERE id=? FOR UPDATE"), (owner_id,))
        else:
            cur.execute("BEGIN IMMEDIATE")

        used = 0
        if should_enforce:
            sources = tuple(policy["sources"])
            placeholders = ",".join("?" for _ in sources)
            sql = (
                "SELECT COUNT(*) FROM ai_usage_events WHERE user_id=? AND local_date=? "
                "AND counts_toward_limit=1 AND credential_source IN (" + placeholders + ")"
            )
            cur.execute(_db_sql(sql), (owner_id, local_date, *sources))
            used = int(cur.fetchone()[0])
            if used >= int(policy["limit"]):
                conn.rollback()
                if policy.get("fallback"):
                    raise AIManagedFallbackRequired()
                audit_event(
                    "AI_DAILY_LIMIT_BLOCKED", actor_user_id=owner_id, target_user_id=owner_id,
                    details={"local_date": local_date, "lane": policy["lane"], "limit": policy["limit"], "call_type": str(call_type or "AI")[:40]},
                )
                if str(credential_source or "") == "managed_fallback_standard":
                    raise AIUsageLimitError(
                        f"Daily THE LAB allowance reached: {MANAGED_AI_DAILY_CALL_LIMIT} Managed + "
                        f"{STANDARD_AI_DAILY_CALL_LIMIT} Standard Gemini calls. Try again tomorrow; saved data and your latest Snapshot remain available."
                    )
                raise AIUsageLimitError(
                    f"Daily THE LAB Standard limit reached ({STANDARD_AI_DAILY_CALL_LIMIT} calls). "
                    "Try again tomorrow; saved data and your latest Snapshot remain available."
                )

        cur.execute(
            _db_sql("INSERT INTO ai_usage_events (id, user_id, created_at_utc, local_date, call_type, provider, model, credential_source, counts_toward_limit, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'started')"),
            (event_id, owner_id, _now_utc_text(), local_date, str(call_type or "AI")[:40], str(provider or "")[:40], str(model or "")[:120], str(credential_source or "")[:80], 1 if effective_counts else 0),
        )
        conn.commit()
        return event_id
    finally:
        conn.close()


def _finish_ai_usage(event_id, provider, payload=None, status="success", http_status=None, error_type=None):
    if not event_id:
        return
    input_tokens, output_tokens, total_tokens = _ai_usage_token_counts(provider, payload or {})
    _db_execute(
        "UPDATE ai_usage_events SET status=?, input_tokens=?, output_tokens=?, total_tokens=?, http_status=?, error_type=? WHERE id=?",
        (str(status or "unknown")[:30], input_tokens, output_tokens, total_tokens, http_status, str(error_type or "")[:100] or None, event_id),
    )


def get_ai_usage_today(user_id=None):
    owner_id = _data_owner_user_id(user_id)
    local_date = _ai_usage_local_date(owner_id)
    rows = _db_execute(
        "SELECT COUNT(*) AS api_calls, "
        "COALESCE(SUM(CASE WHEN counts_toward_limit=1 THEN 1 ELSE 0 END),0) AS quota_calls, "
        "COALESCE(SUM(CASE WHEN counts_toward_limit=1 AND credential_source='platform_managed' THEN 1 ELSE 0 END),0) AS managed_calls, "
        "COALESCE(SUM(CASE WHEN counts_toward_limit=1 AND credential_source IN ('the_lab_standard','managed_fallback_standard') THEN 1 ELSE 0 END),0) AS standard_calls, "
        "COALESCE(SUM(CASE WHEN credential_source IN ('athlete_byok','athlete_byok_test') THEN 1 ELSE 0 END),0) AS byok_calls, "
        "COALESCE(SUM(input_tokens),0) AS input_tokens, COALESCE(SUM(output_tokens),0) AS output_tokens, COALESCE(SUM(total_tokens),0) AS total_tokens "
        "FROM ai_usage_events WHERE user_id=? AND local_date=?",
        (owner_id, local_date), fetch=True,
    )
    row = rows[0] if rows else {}
    managed_calls = int(row.get("managed_calls") or 0)
    standard_calls = int(row.get("standard_calls") or 0)
    mode = _effective_ai_access_mode(owner_id)
    standard_ready = bool(_standard_ai_runtime_config().get("configured"))

    if mode == "BYOK":
        limit = None
        remaining = None
        quota_calls = 0
        quota_label = "UNLIMITED · BYOK"
        remaining_label = "UNLIMITED"
        remaining_class = "ps-quota-ok"
    elif mode == "STANDARD":
        limit = STANDARD_AI_DAILY_CALL_LIMIT
        quota_calls = standard_calls
        remaining = max(0, limit - standard_calls)
        quota_label = f"{standard_calls} / {limit} · Standard"
        remaining_label = str(remaining)
        remaining_class = "ps-quota-zero" if remaining == 0 else ("ps-quota-low" if remaining <= 1 else "ps-quota-ok")
    else:  # PLATFORM / THE LAB Managed
        managed_remaining = max(0, MANAGED_AI_DAILY_CALL_LIMIT - managed_calls)
        standard_remaining = max(0, STANDARD_AI_DAILY_CALL_LIMIT - standard_calls) if standard_ready else 0
        limit = MANAGED_AI_DAILY_CALL_LIMIT + (STANDARD_AI_DAILY_CALL_LIMIT if standard_ready else 0)
        quota_calls = managed_calls + standard_calls
        remaining = managed_remaining + standard_remaining
        quota_label = f"{managed_calls}/{MANAGED_AI_DAILY_CALL_LIMIT} Managed · {standard_calls}/{STANDARD_AI_DAILY_CALL_LIMIT} Gemini"
        remaining_label = str(remaining)
        remaining_class = "ps-quota-zero" if remaining == 0 else ("ps-quota-low" if remaining <= 2 else "ps-quota-ok")

    return {
        "local_date": local_date,
        "access_mode": mode,
        "api_calls": int(row.get("api_calls") or 0),
        "quota_calls": quota_calls,
        "managed_calls": managed_calls,
        "standard_calls": standard_calls,
        "byok_calls": int(row.get("byok_calls") or 0),
        "remaining": remaining,
        "limit": limit,
        "quota_label": quota_label,
        "remaining_label": remaining_label,
        "remaining_class": remaining_class,
        "input_tokens": int(row.get("input_tokens") or 0),
        "output_tokens": int(row.get("output_tokens") or 0),
        "total_tokens": int(row.get("total_tokens") or 0),
    }


def admin_ai_usage_data():
    """Owner-only aggregate for the Control Center; stores metadata/tokens, never prompts or AI replies."""
    athlete_rows = _db_execute("SELECT id, username, admin_hidden FROM users WHERE role!='admin' ORDER BY created_at_utc DESC", fetch=True)
    per_user = []
    total_api_calls = total_quota_calls = total_tokens = 0
    for row in athlete_rows:
        usage = get_ai_usage_today(row["id"])
        total_api_calls += usage["api_calls"]
        total_quota_calls += usage["quota_calls"]
        total_tokens += usage["total_tokens"]
        per_user.append({**row, **usage})
    recent = _db_execute(
        "SELECT e.created_at_utc, e.local_date, e.call_type, e.provider, e.model, e.credential_source, e.counts_toward_limit, e.status, e.input_tokens, e.output_tokens, e.total_tokens, e.http_status, e.error_type, u.username "
        "FROM ai_usage_events e LEFT JOIN users u ON u.id=e.user_id ORDER BY e.created_at_utc DESC LIMIT 80",
        fetch=True,
    )
    standard = _standard_ai_runtime_config()
    platform = _platform_ai_runtime_config()
    return {
        "mode": AI_ACCESS_MODE,
        "managed_daily_limit": MANAGED_AI_DAILY_CALL_LIMIT,
        "standard_daily_limit": STANDARD_AI_DAILY_CALL_LIMIT,
        "standard_provider": standard.get("provider"),
        "standard_model": standard.get("model"),
        "standard_configured": bool(standard.get("configured")),
        "platform_provider": platform.get("provider"),
        "platform_model": platform.get("model"),
        "platform_configured": bool(platform.get("configured")),
        "today_api_calls": total_api_calls,
        "today_quota_calls": total_quota_calls,
        "today_tokens": total_tokens,
        "athletes": per_user,
        "recent": recent,
    }


def _call_ai_provider(provider, api_key, model, prompt, max_tokens=1200, *, usage_kind="AI", user_id=None, credential_source=None, counts_toward_limit=True, enforce_limit=True):
    provider = str(provider or "").strip().upper()
    api_key = (api_key or "").strip()
    model = (model or "").strip()
    credential_source = str(credential_source or "").strip()
    if provider not in _AI_PROVIDER_LABELS:
        raise ValueError("Unsupported AI provider")
    if not api_key:
        raise ValueError("AI API key is required")
    if not model:
        model = _AI_DEFAULT_MODELS[provider]

    try:
        event_id = _reserve_ai_usage(
            user_id, usage_kind, provider, model, credential_source,
            counts_toward_limit=counts_toward_limit, enforce_limit=enforce_limit,
        )
    except AIManagedFallbackRequired:
        standard = _standard_ai_runtime_config()
        if not standard.get("configured"):
            owner_id = _data_owner_user_id(user_id)
            local_date = _ai_usage_local_date(owner_id)
            audit_event(
                "AI_MANAGED_FALLBACK_UNAVAILABLE", actor_user_id=owner_id, target_user_id=owner_id,
                details={"local_date": local_date, "managed_limit": MANAGED_AI_DAILY_CALL_LIMIT, "call_type": str(usage_kind or "AI")[:40]},
            )
            raise AIUsageLimitError(
                f"THE LAB Managed has used its {MANAGED_AI_DAILY_CALL_LIMIT} premium calls today and the Standard Gemini fallback is not configured. "
                "Try again tomorrow; saved data and your latest Snapshot remain available."
            )
        provider = standard["provider"]
        model = standard["model"]
        api_key = standard["api_key"]
        credential_source = "managed_fallback_standard"
        event_id = _reserve_ai_usage(
            user_id, usage_kind, provider, model, credential_source,
            counts_toward_limit=counts_toward_limit, enforce_limit=enforce_limit,
        )

    resp = None
    payload = None
    try:
        if provider == "ANTHROPIC":
            resp = requests.post(
                "https://api.anthropic.com/v1/messages",
                headers={"x-api-key": api_key, "anthropic-version": "2023-06-01", "content-type": "application/json"},
                json={"model": model, "max_tokens": int(max_tokens), "messages": [{"role": "user", "content": prompt}]},
                timeout=60,
            )
            try:
                payload = resp.json()
            except Exception:
                payload = {}
            resp.raise_for_status()
            text = "".join(block.get("text", "") for block in payload.get("content", []) if isinstance(block, dict)).strip()
        elif provider == "GEMINI":
            resp = requests.post(
                f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",
                headers={"x-goog-api-key": api_key, "Content-Type": "application/json"},
                json={
                    "contents": [{"role": "user", "parts": [{"text": prompt}]}],
                    "generationConfig": {"maxOutputTokens": int(max_tokens)},
                },
                timeout=60,
            )
            try:
                payload = resp.json()
            except Exception:
                payload = {}
            resp.raise_for_status()
            text = _gemini_output_text(payload)
        else:
            resp = requests.post(
                "https://api.openai.com/v1/responses",
                headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                json={"model": model, "input": prompt, "max_output_tokens": int(max_tokens)},
                timeout=60,
            )
            try:
                payload = resp.json()
            except Exception:
                payload = {}
            resp.raise_for_status()
            text = _openai_output_text(payload)
        if not text:
            raise ValueError("AI provider returned an empty response")
        _finish_ai_usage(event_id, provider, payload, status="success", http_status=getattr(resp, "status_code", None))
        return text
    except Exception as exc:
        _finish_ai_usage(
            event_id, provider, payload, status="error", http_status=getattr(resp, "status_code", None), error_type=exc.__class__.__name__,
        )
        raise


def _safe_external_http_error(exc):
    """Return a user-facing provider error without leaking raw request URLs.

    Provider HTTP exceptions still remain available to server logs/audit through
    their type/status, but the dashboard never prints endpoint URLs or query data.
    """
    response = getattr(exc, "response", None)
    status = getattr(response, "status_code", None)
    url = str(getattr(response, "url", "") or "")
    code = f"HTTP {status}" if status else "HTTP error"
    if "generativelanguage.googleapis.com" in url:
        if status == 404:
            return (
                "Google Gemini could not serve the configured model (HTTP 404). "
                "THE LAB Standard/QA uses Gemini 3.5 Flash in V4.8.33; if this persists, "
                "check the Standard Gemini project/key access in Google AI Studio."
            )
        return f"Google Gemini request failed ({code}). Your saved Snapshot remains available."
    if "intervals.icu" in url:
        return f"Intervals.icu request failed ({code}). Check the athlete connection and try again."
    return f"An external service request failed ({code}). Your saved data remain available."

def _test_ai_credentials(provider, api_key, model, user_id=None):
    owner_id = _data_owner_user_id(user_id)
    text = _call_ai_provider(provider, api_key, model, "Reply with exactly: THE LAB CONNECTED", max_tokens=80, usage_kind="CONNECTION_TEST", user_id=owner_id, credential_source="athlete_byok_test", counts_toward_limit=False, enforce_limit=False)
    if not text:
        raise ValueError("AI connection returned no text")
    return {"reply_received": True, "provider": provider, "model": model}


def save_and_test_ai(user_id, provider, model, api_key=None):
    owner_id = _data_owner_user_id(user_id)
    provider = str(provider or "").strip().upper()
    if provider not in _AI_PROVIDER_LABELS:
        raise ValueError("Choose Claude / Anthropic, OpenAI / GPT or Google Gemini")
    model = (model or "").strip()[:120] or _AI_DEFAULT_MODELS[provider]
    existing_rows = _db_execute("SELECT * FROM athlete_ai_integrations WHERE user_id=? LIMIT 1", (owner_id,), fetch=True)
    existing = dict(existing_rows[0]) if existing_rows else None
    submitted_key = (api_key or "").strip()
    # If provider changes, require a fresh key rather than silently trying the old provider's secret.
    if submitted_key:
        key_to_test = submitted_key
        ciphertext = _encrypt_credential(submitted_key)
    elif existing and existing.get("credential_ciphertext") and str(existing.get("provider") or "").upper() == provider:
        key_to_test = _decrypt_credential(existing.get("credential_ciphertext"))
        ciphertext = existing.get("credential_ciphertext")
    else:
        raise ValueError("AI API key is required the first time you connect this provider")

    now_text = _now_utc_text()
    try:
        _test_ai_credentials(provider, key_to_test, model, owner_id)
    except Exception as exc:
        safe_error = "AI connection failed. Check provider, API key, model access and provider billing/credits."
        if existing:
            _db_execute(
                "UPDATE athlete_ai_integrations SET provider=?, model=?, status='error', last_checked_at_utc=?, last_error=?, updated_at_utc=? WHERE user_id=?",
                (provider, model, now_text, safe_error, now_text, owner_id),
            )
        audit_event("AI_CONNECTION_FAILED", actor_user_id=owner_id, target_user_id=owner_id,
                    details={"provider": provider, "model": model, "error_type": exc.__class__.__name__})
        raise ValueError(safe_error) from exc

    if existing:
        _db_execute(
            "UPDATE athlete_ai_integrations SET provider=?, model=?, credential_ciphertext=?, status='connected', last_checked_at_utc=?, last_error=NULL, updated_at_utc=? WHERE user_id=?",
            (provider, model, ciphertext, now_text, now_text, owner_id),
        )
    else:
        _db_execute(
            "INSERT INTO athlete_ai_integrations (user_id, provider, model, credential_ciphertext, status, last_checked_at_utc, last_error, created_at_utc, updated_at_utc) VALUES (?, ?, ?, ?, 'connected', ?, NULL, ?, ?)",
            (owner_id, provider, model, ciphertext, now_text, now_text, now_text),
        )
    audit_event("AI_CONNECTED", actor_user_id=owner_id, target_user_id=owner_id,
                details={"provider": provider, "model": model})
    _refresh_setup_completed(owner_id)
    return get_ai_integration(owner_id)


def _resolve_ai_runtime(user_id=None):
    """Resolve the single AI gateway for this request.

    BYOK (beta default): the athlete uses only their encrypted provider credential.
    STANDARD: that athlete uses THE LAB's separate server-side Gemini credential.
    PLATFORM: that athlete uses the existing owner-managed premium credential selected
    by THE_LAB_PLATFORM_AI_PROVIDER/MODEL/API_KEY. The effective mode can be overridden
    per athlete from the Control Center without changing Snapshot or Coach Chat.
    """
    owner_id = _data_owner_user_id(user_id)
    user = _get_user_by_id(owner_id) or {}
    mode = _effective_ai_access_mode(owner_id)

    if mode == "STANDARD" and user.get("role") != "admin":
        standard = _standard_ai_runtime_config()
        if not standard.get("configured"):
            raise RuntimeError("THE LAB Standard AI is not configured by the owner yet.")
        return {
            "provider": standard["provider"], "model": standard["model"], "api_key": standard["api_key"],
            "source": "the_lab_standard", "user_id": owner_id,
        }

    if mode == "PLATFORM" and user.get("role") != "admin":
        platform = _platform_ai_runtime_config()
        if not platform.get("configured"):
            raise RuntimeError("THE LAB Managed AI is not configured by the owner yet.")
        return {
            "provider": platform["provider"], "model": platform["model"], "api_key": platform["api_key"],
            "source": "platform_managed", "user_id": owner_id,
        }

    integration = get_ai_integration(owner_id, include_secret=True)
    if integration and integration.get("status") == "connected" and integration.get("api_key"):
        return {
            "provider": str(integration.get("provider") or "").upper(),
            "model": integration.get("model") or _AI_DEFAULT_MODELS.get(str(integration.get("provider") or "").upper(), ""),
            "api_key": integration.get("api_key"),
            "source": "athlete_byok" if user.get("role") != "admin" else "owner_saved_integration",
            "user_id": owner_id,
        }
    if user.get("role") == "admin" and ANTHROPIC_API_KEY:
        return {"provider": "ANTHROPIC", "model": "claude-sonnet-4-6", "api_key": ANTHROPIC_API_KEY, "source": "owner_server_fallback", "user_id": owner_id}
    raise RuntimeError("AI is not configured for this athlete. Complete Athlete Settings first.")

def _v4831_admin_qa_ai_runtime(user_id=None):
    """Force the admin-only QA lane through THE LAB Standard · Gemini.

    This never reads or changes the admin's normal production AI selection. Provider
    pricing/quota still belongs to the configured Gemini account; the UI deliberately
    calls this "Gemini QA" rather than promising that a provider request is always free.
    """
    owner_id = _data_owner_user_id(user_id)
    user = _get_user_by_id(owner_id) or {}
    if str(user.get("role") or "").lower() != "admin":
        raise PermissionError("QA Console is available only to the admin account.")
    standard = _standard_ai_runtime_config()
    if not standard.get("configured"):
        raise RuntimeError("Gemini QA is not configured. Add THE_LAB_STANDARD_AI_API_KEY on Render first.")
    return {
        "provider": standard["provider"], "model": standard["model"], "api_key": standard["api_key"],
        "source": "the_lab_standard", "user_id": owner_id,
    }


def _v4831_json_clone(value):
    """JSON-safe clone used only for persisted replay context; never stores secrets."""
    return json.loads(json.dumps(value, ensure_ascii=False, default=_report_json_default))


def _v4831_context_fingerprint(analysis_args):
    """Stable QA fingerprint for the saved analysis context, not an athlete identifier."""
    payload = json.dumps(analysis_args or {}, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=_report_json_default)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:20]


def _v4831_build_replay_bundle(analysis_args):
    frozen = _v4831_json_clone(analysis_args or {})
    return {
        "schema": "V4.8.31-QA-REPLAY-1",
        "saved_at_local": get_rome_now().isoformat(timespec="seconds"),
        "context_fingerprint": _v4831_context_fingerprint(frozen),
        "analysis_args": frozen,
    }


def _v4831_qa_report(data, qa_kind, input_fingerprint, source_report=None, ai_runtime=None):
    """Build an ephemeral report envelope for rendering/downloading a QA run."""
    now = get_rome_now()
    raw = json.dumps(data or {}, ensure_ascii=False, separators=(",", ":"), default=_report_json_default)
    ai_runtime = ai_runtime or {}
    source_report = source_report or {}
    kind = str(qa_kind or "LIVE").upper()
    intervals_mode = "LIVE · current Intervals.icu fetch" if kind == "LIVE" else "REPLAY · zero Intervals.icu calls"
    return {
        "generated_at_local": now.isoformat(timespec="seconds"),
        "generated_at_utc": now.astimezone(ZoneInfo("UTC")).isoformat(timespec="seconds"),
        "generated_at_local_display": _format_report_timestamp(now.isoformat(timespec="seconds")),
        "app_version": APP_VERSION,
        "payload_bytes": len(raw.encode("utf-8")),
        "data": data,
        "qa_meta": {
            "report_mode": "QA TEST",
            "qa_kind": kind,
            "ai_provider": "THE LAB Standard · Gemini",
            "ai_model": ai_runtime.get("model") or STANDARD_AI_MODEL,
            "production_last_report_affected": "NO · production Snapshot payload/timestamp remain unchanged",
            "intervals_data": intervals_mode,
            "python_pipeline": "PRODUCTION SNAPSHOT PIPELINE" if kind == "LIVE" else "SAVED PRODUCTION CONTEXT + PRODUCTION AI NORMALIZERS/GUARDS",
            "input_fingerprint": input_fingerprint or "unknown",
            "source_snapshot_generated_local": source_report.get("generated_at_local") if source_report else None,
            "source_snapshot_version": source_report.get("app_version") if source_report else None,
        },
    }


def _validated_timezone(value):
    value = (value or "").strip()
    if not value:
        raise ValueError("Choose your timezone")
    try:
        ZoneInfo(value)
    except Exception as exc:
        raise ValueError("Timezone is not a valid IANA timezone, e.g. Europe/Rome") from exc
    return value


def _number_field(form, name, minimum=None, maximum=None, integer=False, required=False):
    raw = (form.get(name) or "").strip()
    if raw == "":
        if required:
            raise ValueError(f"{name.replace('_', ' ').title()} is required")
        return None
    try:
        value = int(raw) if integer else float(raw)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{name.replace('_', ' ').title()} must be numeric") from exc
    if minimum is not None and value < minimum:
        raise ValueError(f"{name.replace('_', ' ').title()} is below the allowed range")
    if maximum is not None and value > maximum:
        raise ValueError(f"{name.replace('_', ' ').title()} is above the allowed range")
    return value


def save_athlete_profile(user_id, form):
    owner_id = _data_owner_user_id(user_id)
    current = get_athlete_profile(owner_id)
    display_name = (form.get("display_name") or "").strip()[:120]
    if not display_name:
        raise ValueError("Display name is required")
    timezone_name = _validated_timezone(form.get("timezone_name"))
    sport = (form.get("sport") or "CYCLING").strip().upper()
    if sport not in {"CYCLING", "MULTISPORT", "OTHER"}:
        sport = "OTHER"
    training_environment = (form.get("training_environment") or "MIXED").strip().upper()
    if training_environment not in {"INDOOR", "OUTDOOR", "MIXED"}:
        training_environment = "MIXED"
    athlete_context = (form.get("athlete_context") or "").strip()[:2000]
    baseline_mode = (form.get("baseline_mode") or "AUTO").strip().upper()
    if baseline_mode not in {"AUTO", "MANUAL_AUTO"}:
        baseline_mode = "AUTO"

    baselines = {}
    baseline_ranges = {
        "hrv_low": (1, 300), "hrv_high": (1, 300),
        "resting_hr_low": (20, 120), "resting_hr_high": (20, 120),
        "sleep_minutes": (120, 900), "sleep_score": (0, 100), "spo2": (70, 100),
        "sleeping_respiration": (4, 40), "awake_respiration_low": (4, 50), "awake_respiration_high": (4, 50),
    }
    if baseline_mode == "MANUAL_AUTO":
        for key in _BASELINE_FIELDS:
            lo, hi = baseline_ranges[key]
            val = _number_field(form, key, lo, hi, integer=(key in {"sleep_minutes", "sleep_score"}))
            if val is not None:
                baselines[key] = val
        if baselines.get("hrv_low") is not None and baselines.get("hrv_high") is not None and baselines["hrv_low"] > baselines["hrv_high"]:
            raise ValueError("HRV low cannot be higher than HRV high")
        if baselines.get("resting_hr_low") is not None and baselines.get("resting_hr_high") is not None and baselines["resting_hr_low"] > baselines["resting_hr_high"]:
            raise ValueError("Resting HR low cannot be higher than Resting HR high")

    fueling = {
        "race_g_per_hour": _number_field(form, "race_g_per_hour", 0, 180, integer=True, required=True),
        "hard_outdoor_g_per_hour": _number_field(form, "hard_outdoor_g_per_hour", 0, 180, integer=True, required=True),
        "indoor_default_g_per_hour": _number_field(form, "indoor_default_g_per_hour", 0, 180, integer=True, required=True),
        "medium_outdoor_min": _number_field(form, "medium_outdoor_min", 30, 360, integer=True, required=True),
        "long_outdoor_min": _number_field(form, "long_outdoor_min", 60, 600, integer=True, required=True),
        "medium_outdoor_gph_low": _number_field(form, "medium_outdoor_gph_low", 0, 180, integer=True, required=True),
        "medium_outdoor_gph_high": _number_field(form, "medium_outdoor_gph_high", 0, 180, integer=True, required=True),
        "long_outdoor_gph_low": _number_field(form, "long_outdoor_gph_low", 0, 180, integer=True, required=True),
        "long_outdoor_gph_high": _number_field(form, "long_outdoor_gph_high", 0, 180, integer=True, required=True),
    }
    if fueling["medium_outdoor_min"] >= fueling["long_outdoor_min"]:
        raise ValueError("Long outdoor duration must be greater than medium outdoor duration")
    if fueling["medium_outdoor_gph_low"] > fueling["medium_outdoor_gph_high"] or fueling["long_outdoor_gph_low"] > fueling["long_outdoor_gph_high"]:
        raise ValueError("Fueling low target cannot be higher than its high target")

    now_text = _now_utc_text()
    existing = _db_execute("SELECT user_id FROM athlete_profiles WHERE user_id=?", (owner_id,), fetch=True)
    if existing:
        _db_execute(
            "UPDATE athlete_profiles SET display_name=?, timezone_name=?, sport=?, training_environment=?, athlete_context=?, baseline_mode=?, baselines_json=?, fueling_json=?, updated_at_utc=? WHERE user_id=?",
            (display_name, timezone_name, sport, training_environment, athlete_context, baseline_mode,
             json.dumps(baselines, separators=(",", ":")), json.dumps(fueling, separators=(",", ":")), now_text, owner_id),
        )
    else:
        _db_execute(
            "INSERT INTO athlete_profiles (user_id, display_name, timezone_name, sport, training_environment, athlete_context, baseline_mode, baselines_json, fueling_json, setup_completed, created_at_utc, updated_at_utc) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (owner_id, display_name, timezone_name, sport, training_environment, athlete_context, baseline_mode,
             json.dumps(baselines, separators=(",", ":")), json.dumps(fueling, separators=(",", ":")), 0, now_text, now_text),
        )
    audit_event("ATHLETE_PROFILE_UPDATED", actor_user_id=owner_id, target_user_id=owner_id,
                details={"baseline_mode": baseline_mode, "timezone": timezone_name, "sport": sport})
    _refresh_setup_completed(owner_id)
    return get_athlete_profile(owner_id)


def _test_intervals_credentials(external_athlete_id, api_key):
    athlete_id = (external_athlete_id or "").strip()
    api_key = (api_key or "").strip()
    if not athlete_id or not api_key:
        raise ValueError("Intervals Athlete ID and API key are required")
    newest = date.today().isoformat()
    oldest = (date.today() - timedelta(days=14)).isoformat()
    headers = {"Authorization": "Basic " + base64.b64encode(f"API_KEY:{api_key}".encode("utf-8")).decode("ascii")}
    act_url = f"https://intervals.icu/api/v1/athlete/{athlete_id}/activities?oldest={oldest}&newest={newest}&fields=id,type,start_date_local"
    wel_url = f"https://intervals.icu/api/v1/athlete/{athlete_id}/wellness?oldest={oldest}&newest={newest}&fields=id"
    act_resp = requests.get(act_url, headers=headers, timeout=20)
    act_resp.raise_for_status()
    wel_resp = requests.get(wel_url, headers=headers, timeout=20)
    wel_resp.raise_for_status()
    activities = act_resp.json()
    wellness = wel_resp.json()
    if not isinstance(activities, list) or not isinstance(wellness, list):
        raise ValueError("Intervals returned an unexpected response")
    return {
        "window_days": 14,
        "activities_found": len(activities),
        "wellness_days_found": len(wellness),
        "checked_oldest": oldest,
        "checked_newest": newest,
    }


def save_and_test_intervals(user_id, external_athlete_id, api_key=None):
    owner_id = _data_owner_user_id(user_id)
    athlete_id = (external_athlete_id or "").strip()[:120]
    if not athlete_id:
        raise ValueError("Intervals Athlete ID is required")
    existing_rows = _db_execute(
        "SELECT * FROM athlete_integrations WHERE user_id=? AND provider='INTERVALS' LIMIT 1", (owner_id,), fetch=True
    )
    existing = dict(existing_rows[0]) if existing_rows else None
    submitted_key = (api_key or "").strip()
    if submitted_key:
        key_to_test = submitted_key
        ciphertext = _encrypt_credential(submitted_key)
    elif existing and existing.get("credential_ciphertext"):
        key_to_test = _decrypt_credential(existing.get("credential_ciphertext"))
        ciphertext = existing.get("credential_ciphertext")
    else:
        raise ValueError("Intervals API key is required the first time you connect")

    now_text = _now_utc_text()
    try:
        summary = _test_intervals_credentials(athlete_id, key_to_test)
    except Exception as exc:
        safe_error = "Intervals connection failed. Check Athlete ID, API key and Intervals availability."
        if existing:
            _db_execute(
                "UPDATE athlete_integrations SET external_athlete_id=?, status='error', last_checked_at_utc=?, last_error=?, updated_at_utc=? WHERE user_id=? AND provider='INTERVALS'",
                (athlete_id, now_text, safe_error, now_text, owner_id),
            )
        audit_event("INTERVALS_CONNECTION_FAILED", actor_user_id=owner_id, target_user_id=owner_id,
                    details={"external_athlete_id": athlete_id, "error_type": exc.__class__.__name__})
        raise ValueError(safe_error) from exc

    payload = json.dumps(summary, separators=(",", ":"))
    if existing:
        _db_execute(
            "UPDATE athlete_integrations SET external_athlete_id=?, credential_ciphertext=?, status='connected', last_checked_at_utc=?, last_error=NULL, data_summary_json=?, updated_at_utc=? WHERE user_id=? AND provider='INTERVALS'",
            (athlete_id, ciphertext, now_text, payload, now_text, owner_id),
        )
    else:
        _db_execute(
            "INSERT INTO athlete_integrations (user_id, provider, external_athlete_id, credential_ciphertext, status, last_checked_at_utc, last_error, data_summary_json, created_at_utc, updated_at_utc) VALUES (?, 'INTERVALS', ?, ?, 'connected', ?, NULL, ?, ?, ?)",
            (owner_id, athlete_id, ciphertext, now_text, payload, now_text, now_text),
        )
    audit_event("INTERVALS_CONNECTED", actor_user_id=owner_id, target_user_id=owner_id,
                details={"external_athlete_id": athlete_id, **summary})
    _refresh_setup_completed(owner_id)
    return get_intervals_integration(owner_id)


def athlete_setup_status(user_id=None):
    owner_id = _data_owner_user_id(user_id)
    profile = get_athlete_profile(owner_id)
    integration = get_intervals_integration(owner_id)
    ai_integration = get_ai_integration(owner_id)
    profile_saved = bool(_db_execute("SELECT user_id FROM athlete_profiles WHERE user_id=?", (owner_id,), fetch=True))
    intervals_connected = bool(integration and integration.get("status") == "connected" and integration.get("has_credential"))
    ai_access_mode = _effective_ai_access_mode(owner_id)
    standard_ai = _standard_ai_runtime_config()
    platform_ai = _platform_ai_runtime_config()
    if ai_access_mode == "STANDARD":
        ai_connected = bool(standard_ai.get("configured"))
    elif ai_access_mode == "PLATFORM":
        ai_connected = bool(platform_ai.get("configured"))
    else:
        ai_connected = bool(ai_integration and ai_integration.get("status") == "connected" and ai_integration.get("has_credential"))
    complete = bool(profile_saved and intervals_connected and ai_connected)
    rows = _db_execute("SELECT ai_access_mode_override FROM users WHERE id=? LIMIT 1", (owner_id,), fetch=True)
    override = str(rows[0].get("ai_access_mode_override") or "").strip().upper() if rows else ""
    return {
        "profile_saved": profile_saved,
        "intervals_connected": intervals_connected,
        "ai_connected": ai_connected,
        "complete": complete,
        "profile": profile,
        "integration": integration,
        "ai_integration": ai_integration,
        "ai_access_mode": ai_access_mode,
        "ai_access_mode_override": override if override in {"BYOK", "STANDARD", "PLATFORM"} else None,
        "standard_ai": standard_ai,
        "platform_ai": platform_ai,
    }


def _refresh_setup_completed(user_id):
    owner_id = _data_owner_user_id(user_id)
    profile_exists = bool(_db_execute("SELECT user_id FROM athlete_profiles WHERE user_id=?", (owner_id,), fetch=True))
    intervals_connected = bool(_db_execute(
        "SELECT user_id FROM athlete_integrations WHERE user_id=? AND provider='INTERVALS' AND status='connected' LIMIT 1",
        (owner_id,), fetch=True,
    ))
    ai_mode = _effective_ai_access_mode(owner_id)
    if ai_mode == "STANDARD":
        ai_connected = bool(_standard_ai_runtime_config().get("configured"))
    elif ai_mode == "PLATFORM":
        ai_connected = bool(_platform_ai_runtime_config().get("configured"))
    else:
        ai_connected = bool(_db_execute(
            "SELECT user_id FROM athlete_ai_integrations WHERE user_id=? AND status='connected' LIMIT 1",
            (owner_id,), fetch=True,
        ))
    complete = bool(profile_exists and intervals_connected and ai_connected)
    if profile_exists:
        _db_execute("UPDATE athlete_profiles SET setup_completed=?, updated_at_utc=? WHERE user_id=?",
                    (1 if complete else 0, _now_utc_text(), owner_id))
    return complete


# ---------------------------------------------------------------------------
# PRODUCT V1 · Identity, entitlement, revocable sessions and audit trail
# ---------------------------------------------------------------------------
_USERNAME_RE = re.compile(r"^[A-Za-z0-9._-]{3,40}$")
_ACCESS_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
_DUMMY_PASSWORD_HASH = generate_password_hash("THE-LAB-DUMMY-PASSWORD-ONLY-FOR-TIMING")


def _normalize_username(value):
    return (value or "").strip().casefold()


def _normalize_email(value):
    return (value or "").strip().casefold()


def _utc_parse(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).replace(tzinfo=None)
    except (TypeError, ValueError):
        return None


def _security_hmac(value):
    key = (SECRET_KEY or "change-this-key").encode("utf-8")
    return hmac.new(key, str(value).encode("utf-8"), hashlib.sha256).hexdigest()


def _request_ip():
    # Render/Cloudflare may provide a forwarding chain. Trust only the first value
    # for logging/rate-context; authorization never depends on the IP address.
    forwarded = (request.headers.get("X-Forwarded-For") or "").split(",")[0].strip()
    return (forwarded or request.remote_addr or "")[:80]


def audit_event(action, actor_user_id=None, target_user_id=None, details=None):
    try:
        _db_execute(
            "INSERT INTO audit_log (id, created_at_utc, actor_user_id, action, target_user_id, ip_address, details_json) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (str(uuid.uuid4()), _now_utc_text(), actor_user_id, str(action)[:80], target_user_id, _request_ip(), json.dumps(details or {}, ensure_ascii=False)[:4000]),
        )
    except Exception as exc:
        app.logger.warning("Audit event could not be stored: %s", exc)


def _csrf_token():
    token = session.get("csrf_token")
    if not token:
        token = secrets.token_urlsafe(32)
        session["csrf_token"] = token
    return token


def _valid_csrf():
    expected = session.get("csrf_token") or ""
    supplied = request.form.get("csrf_token") or request.headers.get("X-CSRF-Token") or ""
    return bool(expected and supplied and hmac.compare_digest(expected, supplied))


app.jinja_env.globals["csrf_token"] = _csrf_token


def _parse_admin_date(value, field_label="Date"):
    """Parse owner-entered dates using the explicit European DD/MM/YYYY format.

    ISO YYYY-MM-DD is accepted only as a compatibility fallback for requests
    created by older Product builds; the V4.3 UI itself always shows DD/MM/YYYY.
    """
    raw = (value or "").strip()
    if not raw:
        return None
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(raw, fmt).date()
        except ValueError:
            pass
    raise ValueError(f"{field_label} must use DD/MM/YYYY (for example 30/09/2026).")


def _inclusive_expiry_to_utc(expiry_date):
    """Store an inclusive calendar expiry as exclusive next-midnight UTC.

    Existing Product releases already used this representation for invitation
    expiries. Keeping it preserves compatibility while V4.3 presents the date
    to the owner in the intuitive DD/MM/YYYY format.
    """
    if expiry_date is None:
        return None
    return datetime.combine(expiry_date + timedelta(days=1), datetime.min.time()).replace(microsecond=0).isoformat() + "Z"


def _stored_expiry_to_date(value):
    expiry = _utc_parse(value)
    if expiry is None:
        return None
    return (expiry - timedelta(days=1)).date()


def format_admin_datetime(value):
    if value in (None, ""):
        return "—"
    parsed = _utc_parse(value)
    if parsed is None:
        return str(value)
    return parsed.strftime("%d/%m/%Y %H:%M")


def format_admin_expiry(value):
    if value in (None, ""):
        return "No expiry"
    day = _stored_expiry_to_date(value)
    return day.strftime("%d/%m/%Y") if day else str(value)


app.add_template_filter(format_admin_datetime, "admin_dt")
app.add_template_filter(format_admin_expiry, "admin_expiry")


def _latest_license_for_user(user_id):
    rows = _db_execute(
        "SELECT * FROM licenses WHERE user_id=? ORDER BY created_at_utc DESC LIMIT 1",
        (user_id,), fetch=True,
    )
    return rows[0] if rows else None


def _license_effective_status(license_row):
    if not license_row:
        return "none"
    status = str(license_row.get("status") or "").lower()
    if status != "active":
        return status or "unknown"
    expiry = _utc_parse(license_row.get("expires_at_utc"))
    if expiry is not None and expiry < datetime.utcnow():
        return "expired"
    return "active"


def _active_license_for_user(user_id):
    rows = _db_execute(
        "SELECT * FROM licenses WHERE user_id=? AND status='active' ORDER BY created_at_utc DESC LIMIT 1",
        (user_id,), fetch=True,
    )
    if not rows:
        return None
    lic = rows[0]
    expiry = _utc_parse(lic.get("expires_at_utc"))
    if expiry is not None and expiry < datetime.utcnow():
        return None
    return lic


def _get_user_by_id(user_id):
    if not user_id:
        return None
    rows = _db_execute("SELECT * FROM users WHERE id=? LIMIT 1", (user_id,), fetch=True)
    return rows[0] if rows else None


def _get_user_by_username(username):
    key = _normalize_username(username)
    if not key:
        return None
    rows = _db_execute("SELECT * FROM users WHERE username_key=? LIMIT 1", (key,), fetch=True)
    return rows[0] if rows else None


def _start_auth_session(user):
    raw_token = secrets.token_urlsafe(48)
    now = _now_utc_text()
    _db_execute(
        "INSERT INTO auth_sessions (id, user_id, token_hash, created_at_utc, last_seen_at_utc, revoked_at_utc, ip_address, user_agent) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (str(uuid.uuid4()), user["id"], _security_hmac(raw_token), now, now, None, _request_ip(), (request.headers.get("User-Agent") or "")[:300]),
    )
    session.clear()
    session.permanent = True
    session["auth_token"] = raw_token
    session["csrf_token"] = secrets.token_urlsafe(32)
    session["logged_in"] = True  # retained only for old template conditionals
    session["username"] = user.get("username")
    session["user_id"] = user.get("id")
    session["role"] = user.get("role")


def _revoke_current_auth_session():
    raw = session.get("auth_token")
    if raw:
        _db_execute("UPDATE auth_sessions SET revoked_at_utc=? WHERE token_hash=? AND revoked_at_utc IS NULL", (_now_utc_text(), _security_hmac(raw)))


def current_user(touch=False):
    raw = session.get("auth_token")
    user_id = session.get("user_id")
    if not raw or not user_id:
        return None
    rows = _db_execute(
        "SELECT * FROM auth_sessions WHERE user_id=? AND token_hash=? AND revoked_at_utc IS NULL LIMIT 1",
        (user_id, _security_hmac(raw)), fetch=True,
    )
    if not rows:
        return None
    user = _get_user_by_id(user_id)
    if not user or str(user.get("status") or "").lower() != "active":
        return None
    if user.get("role") != "admin" and not _active_license_for_user(user_id):
        return None
    if touch:
        last_seen = _utc_parse(rows[0].get("last_seen_at_utc"))
        if last_seen is None or (datetime.utcnow() - last_seen) > timedelta(minutes=5):
            _db_execute("UPDATE auth_sessions SET last_seen_at_utc=? WHERE id=?", (_now_utc_text(), rows[0]["id"]))
    return user


def _authenticate_user(username, password):
    user = _get_user_by_username(username)
    now = datetime.utcnow()
    if not user:
        check_password_hash(_DUMMY_PASSWORD_HASH, password or "")
        audit_event("LOGIN_FAILED_UNKNOWN_USER", details={"username": str(username)[:80]})
        return None, "Incorrect username or password."

    locked_until = _utc_parse(user.get("locked_until_utc"))
    if locked_until and locked_until > now:
        audit_event("LOGIN_BLOCKED_LOCKOUT", target_user_id=user["id"])
        return None, "Incorrect username or password."

    ok = check_password_hash(user.get("password_hash") or _DUMMY_PASSWORD_HASH, password or "")
    if not ok:
        failures = int(user.get("failed_login_count") or 0) + 1
        locked_text = None
        if failures >= MAX_LOGIN_FAILURES:
            locked_text = (now + timedelta(minutes=LOGIN_LOCKOUT_MINUTES)).replace(microsecond=0).isoformat() + "Z"
            failures = 0
        _db_execute(
            "UPDATE users SET failed_login_count=?, locked_until_utc=?, updated_at_utc=? WHERE id=?",
            (failures, locked_text, _now_utc_text(), user["id"]),
        )
        audit_event("LOGIN_FAILED", target_user_id=user["id"], details={"lockout_started": bool(locked_text)})
        return None, "Incorrect username or password."

    if str(user.get("status") or "").lower() != "active":
        audit_event("LOGIN_BLOCKED_STATUS", target_user_id=user["id"], details={"status": user.get("status")})
        return None, "This account is not currently authorized."
    if user.get("role") != "admin" and not _active_license_for_user(user["id"]):
        audit_event("LOGIN_BLOCKED_LICENSE", target_user_id=user["id"])
        return None, "This account does not have an active THE LAB entitlement."

    now_text = _now_utc_text()
    _db_execute("UPDATE users SET failed_login_count=0, locked_until_utc=NULL, last_login_at_utc=?, updated_at_utc=? WHERE id=?", (now_text, now_text, user["id"]))
    user = _get_user_by_id(user["id"])
    audit_event("LOGIN_SUCCESS", actor_user_id=user["id"], target_user_id=user["id"])
    return user, None


def _validate_new_account(username, email, password):
    username = (username or "").strip()
    email = (email or "").strip()
    if not _USERNAME_RE.fullmatch(username):
        raise ValueError("Username must be 3–40 characters using letters, numbers, dot, dash or underscore.")
    if email and (len(email) > 254 or "@" not in email or email.startswith("@") or email.endswith("@")):
        raise ValueError("Enter a valid email address.")
    if len(password or "") < 12:
        raise ValueError("Password must be at least 12 characters long.")
    if _get_user_by_username(username):
        raise ValueError("That username is already in use.")
    if email:
        rows = _db_execute("SELECT id FROM users WHERE email_key=? LIMIT 1", (_normalize_email(email),), fetch=True)
        if rows:
            raise ValueError("That email is already linked to an account.")
    return username, email


def _generate_access_code():
    groups = []
    for _ in range(4):
        groups.append("".join(secrets.choice(_ACCESS_ALPHABET) for _ in range(4)))
    return "TLAB-" + "-".join(groups)


def create_access_code(created_by_user_id, license_type="BETA", expires_at_utc=None, note=""):
    license_type = (license_type or "BETA").strip().upper()[:32]
    for _ in range(10):
        raw_code = _generate_access_code()
        try:
            _db_execute(
                "INSERT INTO access_codes (id, code_hash, code_prefix, license_type, status, created_at_utc, expires_at_utc, redeemed_at_utc, redeemed_by_user_id, created_by_user_id, note) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (str(uuid.uuid4()), _security_hmac(raw_code.upper()), raw_code[:10], license_type, "unused", _now_utc_text(), expires_at_utc, None, None, created_by_user_id, (note or "")[:500]),
            )
            audit_event("ACCESS_CODE_CREATED", actor_user_id=created_by_user_id, details={"prefix": raw_code[:10], "license_type": license_type, "expires_at_utc": expires_at_utc})
            return raw_code
        except Exception:
            continue
    raise RuntimeError("Could not generate a unique access code.")


def redeem_access_code(raw_code, username, email, password):
    username, email = _validate_new_account(username, email, password)
    code_hash = _security_hmac((raw_code or "").strip().upper())
    if not raw_code:
        raise ValueError("Enter your THE LAB access code.")

    conn = _db_connect()
    try:
        cur = conn.cursor()
        if _db_is_postgres():
            cur.execute(_db_sql("SELECT * FROM access_codes WHERE code_hash=? FOR UPDATE"), (code_hash,))
        else:
            cur.execute("BEGIN IMMEDIATE")
            cur.execute(_db_sql("SELECT * FROM access_codes WHERE code_hash=?"), (code_hash,))
        raw = cur.fetchone()
        if not raw:
            raise ValueError("That access code is invalid or no longer available.")
        if _db_is_postgres():
            cols = [d[0] for d in cur.description]
            code = dict(zip(cols, raw))
        else:
            code = dict(raw)
        if str(code.get("status") or "") != "unused":
            raise ValueError("That access code is invalid or no longer available.")
        expiry = _utc_parse(code.get("expires_at_utc"))
        if expiry is not None and expiry < datetime.utcnow():
            cur.execute(_db_sql("UPDATE access_codes SET status='expired' WHERE id=?"), (code["id"],))
            conn.commit()
            raise ValueError("That access code is invalid or no longer available.")

        user_id = str(uuid.uuid4())
        license_id = str(uuid.uuid4())
        now_text = _now_utc_text()
        cur.execute(
            _db_sql("INSERT INTO users (id, username, username_key, email, email_key, password_hash, role, status, created_at_utc, updated_at_utc, failed_login_count) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)") ,
            (user_id, username, _normalize_username(username), email or None, _normalize_email(email) if email else None, generate_password_hash(password), "athlete", "active", now_text, now_text, 0),
        )
        cur.execute(
            _db_sql("INSERT INTO licenses (id, user_id, license_type, status, created_at_utc, activated_at_utc, expires_at_utc, revoked_at_utc, created_by_user_id, note) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)") ,
            (license_id, user_id, code.get("license_type") or "BETA", "active", now_text, now_text, code.get("expires_at_utc"), None, code.get("created_by_user_id"), code.get("note")),
        )
        cur.execute(
            _db_sql("UPDATE access_codes SET status='redeemed', redeemed_at_utc=?, redeemed_by_user_id=? WHERE id=?"),
            (now_text, user_id, code["id"]),
        )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    audit_event("ACCESS_CODE_REDEEMED", actor_user_id=user_id, target_user_id=user_id, details={"prefix": (raw_code or "")[:10]})
    return _get_user_by_id(user_id)


def revoke_all_user_sessions(user_id, actor_user_id=None):
    now_text = _now_utc_text()
    _db_execute("UPDATE auth_sessions SET revoked_at_utc=? WHERE user_id=? AND revoked_at_utc IS NULL", (now_text, user_id))
    audit_event("ALL_SESSIONS_REVOKED", actor_user_id=actor_user_id, target_user_id=user_id)


def _generate_temporary_password():
    """Return a strong human-typeable temporary password shown to the owner once."""
    groups = []
    for _ in range(3):
        groups.append("".join(secrets.choice(_ACCESS_ALPHABET) for _ in range(4)))
    return "TLAB-RESET-" + "-".join(groups)


def admin_reset_user_password(user_id, actor_user_id):
    """Replace an athlete password with a one-time temporary credential.

    The temporary password itself is never persisted or audited in plaintext.
    All active sessions are revoked and the athlete must choose a new password
    immediately after the next successful login.
    """
    target = _get_user_by_id(user_id)
    if not target or target.get("role") == "admin":
        raise ValueError("Password reset is available only for athlete accounts.")
    temporary_password = _generate_temporary_password()
    now_text = _now_utc_text()
    _db_execute(
        "UPDATE users SET password_hash=?, must_change_password=1, failed_login_count=0, locked_until_utc=NULL, updated_at_utc=? WHERE id=?",
        (generate_password_hash(temporary_password), now_text, user_id),
    )
    revoke_all_user_sessions(user_id, actor_user_id)
    audit_event(
        "ADMIN_PASSWORD_RESET",
        actor_user_id=actor_user_id,
        target_user_id=user_id,
        details={"forced_change": True},
    )
    return {"username": target.get("username") or "athlete", "temporary_password": temporary_password}


def complete_forced_password_change(user_id, new_password, confirm_password):
    """Commit a new athlete password after an owner-initiated reset."""
    user = _get_user_by_id(user_id)
    if not user or user.get("role") == "admin":
        raise ValueError("This password-change flow is available only for athlete accounts.")
    if not bool(int(user.get("must_change_password") or 0)):
        raise ValueError("A password change is not currently required for this account.")
    new_password = new_password or ""
    confirm_password = confirm_password or ""
    if new_password != confirm_password:
        raise ValueError("Passwords do not match.")
    if len(new_password) < 12:
        raise ValueError("Password must be at least 12 characters long.")
    if check_password_hash(user.get("password_hash") or _DUMMY_PASSWORD_HASH, new_password):
        raise ValueError("Choose a new password different from the temporary password.")
    now_text = _now_utc_text()
    _db_execute(
        "UPDATE users SET password_hash=?, must_change_password=0, failed_login_count=0, locked_until_utc=NULL, updated_at_utc=? WHERE id=?",
        (generate_password_hash(new_password), now_text, user_id),
    )
    audit_event("PASSWORD_CHANGED_AFTER_RESET", actor_user_id=user_id, target_user_id=user_id)
    return _get_user_by_id(user_id)


def set_user_access_state(user_id, action, actor_user_id):
    user = _get_user_by_id(user_id)
    if not user or user.get("role") == "admin":
        raise ValueError("Administrator access cannot be changed from this control.")
    now_text = _now_utc_text()
    action = (action or "").strip().lower()
    if action == "suspend":
        _db_execute("UPDATE users SET status='suspended', updated_at_utc=? WHERE id=?", (now_text, user_id))
        revoke_all_user_sessions(user_id, actor_user_id)
    elif action == "reactivate":
        # Reactivation always returns the athlete to the visible admin roster.
        _db_execute("UPDATE users SET status='active', admin_hidden=0, updated_at_utc=? WHERE id=?", (now_text, user_id))
        rows = _db_execute("SELECT id FROM licenses WHERE user_id=? ORDER BY created_at_utc DESC LIMIT 1", (user_id,), fetch=True)
        if rows:
            _db_execute("UPDATE licenses SET status='active', revoked_at_utc=NULL WHERE id=?", (rows[0]["id"],))
    elif action == "revoke":
        _db_execute("UPDATE users SET status='revoked', updated_at_utc=? WHERE id=?", (now_text, user_id))
        _db_execute("UPDATE licenses SET status='revoked', revoked_at_utc=? WHERE user_id=? AND status='active'", (now_text, user_id))
        revoke_all_user_sessions(user_id, actor_user_id)
    elif action == "logout_all":
        revoke_all_user_sessions(user_id, actor_user_id)
    else:
        raise ValueError("Unknown access action.")
    audit_event("USER_ACCESS_" + action.upper(), actor_user_id=actor_user_id, target_user_id=user_id)


def set_user_admin_visibility(user_id, hidden, actor_user_id):
    """Archive old non-admin accounts from the main roster without deleting history.

    This is deliberately a presentation/archive flag only: users, licenses,
    sessions, athlete data and audit records remain in PostgreSQL. Active users
    cannot be archived, so the owner cannot accidentally make a live entitlement
    disappear from the primary control surface.
    """
    user = _get_user_by_id(user_id)
    if not user or user.get("role") == "admin":
        raise ValueError("Administrator visibility cannot be changed from this control.")
    hidden = bool(hidden)
    if hidden and str(user.get("status") or "").lower() == "active":
        raise ValueError("Suspend or revoke an athlete before archiving it from the main roster.")
    now_text = _now_utc_text()
    _db_execute("UPDATE users SET admin_hidden=?, updated_at_utc=? WHERE id=?", (1 if hidden else 0, now_text, user_id))
    audit_event("ADMIN_USER_ARCHIVED" if hidden else "ADMIN_USER_RESTORED", actor_user_id=actor_user_id, target_user_id=user_id)


def update_user_license_expiry(user_id, action, expires_on, actor_user_id):
    """Update the latest athlete entitlement without replacing the account.

    Expiry changes never override an explicit user/license revocation. An expired
    but otherwise active license becomes usable again when extended into the
    future; a revoked athlete still requires the separate Reactivate action.
    """
    user = _get_user_by_id(user_id)
    if not user or user.get("role") == "admin":
        raise ValueError("Administrator licensing cannot be changed from this control.")
    lic = _latest_license_for_user(user_id)
    if not lic:
        raise ValueError("This athlete does not have a license to renew.")

    action = (action or "set").strip().lower()
    old_expiry = lic.get("expires_at_utc")
    today = datetime.utcnow().date()

    if action == "no_expiry":
        new_expiry = None
    elif action in {"add_30", "add_90"}:
        days = 30 if action == "add_30" else 90
        current_day = _stored_expiry_to_date(old_expiry)
        base_day = current_day if current_day and current_day > today else today
        new_expiry = _inclusive_expiry_to_utc(base_day + timedelta(days=days))
    elif action == "set":
        selected = _parse_admin_date(expires_on, "License expiry")
        if selected is None:
            raise ValueError("Enter the new expiry as DD/MM/YYYY, or use No expiry.")
        if selected < today:
            raise ValueError("License expiry cannot be earlier than today.")
        new_expiry = _inclusive_expiry_to_utc(selected)
    else:
        raise ValueError("Unknown license expiry action.")

    _db_execute("UPDATE licenses SET expires_at_utc=? WHERE id=?", (new_expiry, lic["id"]))
    audit_event(
        "LICENSE_EXPIRY_UPDATED", actor_user_id=actor_user_id, target_user_id=user_id,
        details={"action": action, "old_expiry": old_expiry, "new_expiry": new_expiry, "license_id": lic.get("id")},
    )
    return _latest_license_for_user(user_id)


def _admin_report_metadata_map():
    """Return persisted Product-report metadata keyed by user id.

    Control Center remains Product-Neon-only: this intentionally does not cross the
    owner Personal Neon bridge and never reads report payload_json. One row exists per
    Product athlete when at least one Snapshot has been successfully persisted.
    """
    rows = _db_execute(
        "SELECT user_id, generated_at_utc, generated_at_local, app_version FROM latest_report "
        "WHERE user_id IS NOT NULL AND user_id<>''",
        fetch=True,
    )
    return {str(row.get("user_id")): row for row in rows if row.get("user_id")}


def _enrich_admin_user_row(user, report_meta=None):
    lic = _latest_license_for_user(user["id"]) if user.get("role") != "admin" else None
    user["license"] = lic
    user["license_effective_status"] = _license_effective_status(lic) if lic else "owner"
    user["license_expiry_display"] = format_admin_expiry(lic.get("expires_at_utc")) if lic else "—"
    license_expiry_day = _stored_expiry_to_date(lic.get("expires_at_utc")) if lic and lic.get("expires_at_utc") else None
    user["license_expiry_iso"] = license_expiry_day.isoformat() if license_expiry_day else ""
    user["active_sessions"] = _count_rows("auth_sessions", "WHERE user_id=? AND revoked_at_utc IS NULL", (user["id"],))
    # Report visibility is metadata-only. Admin/owner reports may live on the separate
    # Personal Neon data plane, which Control Center deliberately does not inspect.
    if user.get("role") == "admin":
        user["report_generated"] = None
        user["report_generated_at_utc"] = None
        user["report_app_version"] = None
    else:
        report_meta = report_meta or {}
        user["report_generated"] = bool(report_meta.get("generated_at_utc") or report_meta.get("generated_at_local"))
        user["report_generated_at_utc"] = report_meta.get("generated_at_utc")
        user["report_app_version"] = report_meta.get("app_version")
    if user.get("role") != "admin":
        setup = athlete_setup_status(user["id"])
        user["setup_complete"] = setup["complete"]
        user["intervals_status"] = (setup.get("integration") or {}).get("status") or "not configured"
        user["ai_access_mode"] = setup.get("ai_access_mode") or _global_ai_access_mode()
        user["ai_access_mode_override"] = setup.get("ai_access_mode_override")
        ai_cfg = setup.get("ai_integration") or {}
        if user["ai_access_mode"] == "STANDARD":
            standard = setup.get("standard_ai") or _standard_ai_runtime_config()
            user["ai_status"] = "standard" if standard.get("configured") else "owner setup required"
            user["ai_provider"] = standard.get("provider") or "GEMINI"
            user["ai_model"] = standard.get("model") or "—"
        elif user["ai_access_mode"] == "PLATFORM":
            platform = setup.get("platform_ai") or _platform_ai_runtime_config()
            user["ai_status"] = "managed" if platform.get("configured") else "owner setup required"
            user["ai_provider"] = platform.get("provider") or "PLATFORM"
            user["ai_model"] = platform.get("model") or "—"
        else:
            user["ai_status"] = ai_cfg.get("status") or "not configured"
            user["ai_provider"] = ai_cfg.get("provider") or "—"
            user["ai_model"] = ai_cfg.get("model") or "—"
    else:
        user["setup_complete"] = True
        user["intervals_status"] = "owner env"
        user["ai_access_mode"] = "OWNER"
        user["ai_access_mode_override"] = None
        user["ai_status"] = "owner env" if ANTHROPIC_API_KEY else "not configured"
        user["ai_provider"] = "ANTHROPIC" if ANTHROPIC_API_KEY else "—"
        user["ai_model"] = "—"
    return user


def admin_dashboard_data():
    users = _db_execute(
        "SELECT id, username, email, role, status, created_at_utc, last_login_at_utc, locked_until_utc, admin_hidden, ai_access_mode_override, must_change_password "
        "FROM users WHERE role='admin' OR COALESCE(admin_hidden,0)=0 ORDER BY created_at_utc DESC",
        fetch=True,
    )
    hidden_users = _db_execute(
        "SELECT id, username, email, role, status, created_at_utc, last_login_at_utc, locked_until_utc, admin_hidden, ai_access_mode_override, must_change_password "
        "FROM users WHERE role!='admin' AND COALESCE(admin_hidden,0)=1 ORDER BY updated_at_utc DESC",
        fetch=True,
    )
    report_meta_by_user = _admin_report_metadata_map()
    users = [_enrich_admin_user_row(user, report_meta_by_user.get(str(user.get("id")))) for user in users]
    hidden_users = [_enrich_admin_user_row(user, report_meta_by_user.get(str(user.get("id")))) for user in hidden_users]
    codes = _db_execute(
        "SELECT c.id, c.code_prefix, c.license_type, c.status, c.created_at_utc, c.expires_at_utc, "
        "c.redeemed_at_utc, c.redeemed_by_user_id, c.note, r.username AS redeemed_by_username "
        "FROM access_codes c LEFT JOIN users r ON r.id=c.redeemed_by_user_id "
        "ORDER BY c.created_at_utc DESC LIMIT 50",
        fetch=True,
    )
    audits = _db_execute(
        "SELECT a.created_at_utc, a.action, a.ip_address, u.username AS actor_username, t.username AS target_username "
        "FROM audit_log a LEFT JOIN users u ON u.id=a.actor_user_id LEFT JOIN users t ON t.id=a.target_user_id "
        "ORDER BY a.created_at_utc DESC LIMIT 80",
        fetch=True,
    )
    return users, hidden_users, codes, audits


def _safe_iso_date(value, fallback=None):
    value = (value or "").strip()
    try:
        return date.fromisoformat(value).isoformat()
    except (ValueError, TypeError):
        return fallback


def format_ui_date(value):
    """Render stored ISO dates as DD/MM/YYYY without changing database storage."""
    if value in (None, ""):
        return "—"
    try:
        return date.fromisoformat(str(value)[:10]).strftime("%d/%m/%Y")
    except (ValueError, TypeError):
        return str(value)


def format_ui_time(value):
    """Render HH:MM values using a 12-hour clock with AM/PM."""
    if value in (None, ""):
        return "—"
    raw = str(value).strip()
    for fmt in ("%H:%M", "%H:%M:%S"):
        try:
            return datetime.strptime(raw, fmt).strftime("%I:%M %p")
        except ValueError:
            pass
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).strftime("%I:%M %p")
    except (ValueError, TypeError):
        return raw


app.add_template_filter(format_ui_date, "ui_date")
app.add_template_filter(format_ui_time, "ui_time")


def add_memory_item(text, category="GENERAL", owner_user_id=None):
    owner_id = _data_owner_user_id(owner_user_id)
    text = (text or "").strip()
