def add_planning_item(kind, title, start_date, end_date=None, restriction_type="NONE", note="", training_environment=None, training_demand=None, upsert=False, owner_user_id=None):
    owner_id = _data_owner_user_id(owner_user_id)
    kind = (kind or "EVENT").strip().upper()
    title = (title or kind.title()).strip()
    today = get_rome_now().date().isoformat()
    start_date = _safe_iso_date(start_date, today)
    end_date = _safe_iso_date(end_date, start_date)
    if end_date < start_date:
        start_date, end_date = end_date, start_date
    restriction_type = (restriction_type or "NONE").strip().upper()
    if kind in ("SICK", "REST", "UNAVAILABLE") and restriction_type == "NONE":
        restriction_type = "NO_TRAINING"
    if kind == "INJURY" and restriction_type == "NONE":
        restriction_type = "NO_INTENSITY"
    if kind in ("RACE", "TRAINING"):
        restriction_type = "NONE"

    if kind == "TRAINING":
        training_environment = str(training_environment or "OUTDOOR").strip().upper()
        if training_environment not in ("INDOOR", "OUTDOOR"):
            training_environment = "OUTDOOR"
        training_demand = str(training_demand or "COACH").strip().upper()
        if training_demand not in ("EASY", "NORMAL", "HARD", "COACH"):
            training_demand = "COACH"
    else:
        training_environment = None
        training_demand = None

    if upsert:
        existing = _data_execute(owner_id, 
            "SELECT id FROM planning_items WHERE user_id=? AND active=1 AND kind=? AND title=? AND start_date=? ORDER BY created_at_utc DESC LIMIT 1",
            (owner_id, kind, title, start_date), fetch=True,
        )
        if existing:
            _data_execute(owner_id, 
                "UPDATE planning_items SET end_date=?, restriction_type=?, note=?, training_environment=?, training_demand=? WHERE id=? AND user_id=?",
                (end_date, restriction_type, note or "", training_environment, training_demand, existing[0]["id"], owner_id),
            )
            return existing[0]["id"]
    item_id = uuid.uuid4().hex
    _data_execute(owner_id, 
        "INSERT INTO planning_items (id, user_id, created_at_utc, kind, title, note, start_date, end_date, restriction_type, training_environment, training_demand, active) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)",
        (item_id, owner_id, _now_utc_text(), kind, title, note or "", start_date, end_date, restriction_type, training_environment, training_demand),
    )
    return item_id


def archive_planning_item(item_id, owner_user_id=None):
    owner_id = _data_owner_user_id(owner_user_id)
    _data_execute(owner_id, "UPDATE planning_items SET active=0 WHERE id=? AND user_id=?", (item_id, owner_id))


def restore_planning_item(item_id, owner_user_id=None):
    owner_id = _data_owner_user_id(owner_user_id)
    _data_execute(owner_id, "UPDATE planning_items SET active=1 WHERE id=? AND user_id=?", (item_id, owner_id))


def update_planning_item(item_id, kind, title, start_date, end_date=None, restriction_type="NONE", note="", training_environment=None, training_demand=None, owner_user_id=None):
    owner_id = _data_owner_user_id(owner_user_id)
    kind = (kind or "OTHER").strip().upper()
    title = (title or kind.title()).strip()
    today = get_rome_now().date().isoformat()
    start_date = _safe_iso_date(start_date, today)
    end_date = _safe_iso_date(end_date, start_date)
    if end_date < start_date:
        start_date, end_date = end_date, start_date
    restriction_type = (restriction_type or "NONE").strip().upper()
    if restriction_type not in ("NONE", "NO_TRAINING", "NO_INTENSITY"):
        restriction_type = "NONE"
    if kind == "SICK" and restriction_type == "NONE":
        restriction_type = "NO_TRAINING"
    if kind == "INJURY" and restriction_type == "NONE":
        restriction_type = "NO_INTENSITY"
    if kind in ("RACE", "TRAINING"):
        restriction_type = "NONE"

    if kind == "TRAINING":
        training_environment = str(training_environment or "OUTDOOR").strip().upper()
        if training_environment not in ("INDOOR", "OUTDOOR"):
            training_environment = "OUTDOOR"
        training_demand = str(training_demand or "COACH").strip().upper()
        if training_demand not in ("EASY", "NORMAL", "HARD", "COACH"):
            training_demand = "COACH"
    else:
        training_environment = None
        training_demand = None

    _data_execute(owner_id, 
        "UPDATE planning_items SET kind=?, title=?, note=?, start_date=?, end_date=?, restriction_type=?, training_environment=?, training_demand=? WHERE id=? AND user_id=?",
        (kind, title, (note or "").strip(), start_date, end_date, restriction_type, training_environment, training_demand, item_id, owner_id),
    )


def delete_archived_planning_item(item_id, owner_user_id=None):
    owner_id = _data_owner_user_id(owner_user_id)
    _data_execute(owner_id, "DELETE FROM planning_items WHERE id=? AND user_id=? AND active=0", (item_id, owner_id))


