@app.route("/setup", methods=["GET", "POST"])
def athlete_setup():
    user = current_user(touch=True)
    if not user:
        return redirect(url_for("login"))
    if user.get("role") == "admin":
        return redirect(url_for("home"))
    notice = None
    error = None
    if request.method == "POST":
        action = (request.form.get("action") or "").strip()
        try:
            if action == "save_profile":
                save_athlete_profile(user["id"], request.form)
                notice = "Athlete profile saved."
            elif action == "connect_intervals":
                save_and_test_intervals(user["id"], request.form.get("intervals_athlete_id"), request.form.get("intervals_api_key"))
                notice = "Intervals.icu connected and tested successfully."
            elif action == "connect_ai":
                if _effective_ai_access_mode(user["id"]) in {"STANDARD", "PLATFORM"}:
                    raise ValueError("AI is currently supplied by THE LAB for your account; no personal AI key is required.")
                save_and_test_ai(user["id"], request.form.get("ai_provider"), request.form.get("ai_model"), request.form.get("ai_api_key"))
                notice = "AI provider connected and tested successfully."
            else:
                raise ValueError("Unknown setup action")
        except ValueError as exc:
            error = str(exc)
        except Exception:
            app.logger.exception("Athlete setup failed")
            error = "Setup could not be completed. No credential was exposed; try again or contact the owner."
    status = athlete_setup_status(user["id"])
    return render_template_string(
        ATHLETE_SETUP_PAGE, product_css=PRODUCT_SIMPLE_CSS, user=user, status=status,
        profile=status["profile"], integration=status["integration"], ai_integration=status["ai_integration"],
        ai_access_mode=status["ai_access_mode"], standard_ai=status.get("standard_ai") or {},
        platform_ai=status.get("platform_ai") or {}, notice=notice, error=error,
    )


@app.route("/session/csrf")
def session_csrf():
    """Return the current CSRF token for an already-authenticated browser session.

    This endpoint is same-origin, read-only, no-store and never calls Intervals or AI.
    It lets long-lived/PWA pages refresh a stale form token before an expensive POST.
    """
    user = current_user(touch=False)
    if not user:
        return jsonify({"ok": False, "error": "Session expired", "code": "SESSION_EXPIRED", "login_url": url_for("login")}), 401
    return jsonify({"ok": True, "csrf_token": _csrf_token()})


