def get_intervals_headers(runtime=None):
    runtime = runtime or _resolve_intervals_runtime()
    credentials = f"API_KEY:{runtime['api_key']}"
    encoded = base64.b64encode(credentials.encode("utf-8")).decode("utf-8")
    return {"Authorization": f"Basic {encoded}"}


def fetch_power_curve_payload(newest=None, curve="42d", timeout=12, runtime=None):
    """Fetch one Intervals.icu cycling power curve.

    ``42d`` is the recent-performance curve already used by THE LAB. ``s0`` is
    the current-season curve and is used only for transparent 42-day-vs-season
    comparisons in the power model. A resolved per-athlete runtime may be passed
    explicitly when this function runs inside a worker thread: Flask's request
    session is not available inside ``ThreadPoolExecutor`` workers.
    """
    runtime = runtime or _resolve_intervals_runtime()
    headers = get_intervals_headers(runtime)
    curve = str(curve or "42d").strip()
    url = (
        f"https://intervals.icu/api/v1/athlete/{runtime['athlete_id']}/power-curves.json"
        f"?type=Ride&curves={curve}"
    )
    if newest:
        url += f"&newest={newest}"
    timeout = max(3.0, min(float(timeout or 12), 30.0))
    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()
    return resp.json()


def extract_power_curve_points(payload):
    """The exact shape of this endpoint's response isn't officially documented.
    The real shape turned out to be a curve object with PARALLEL ARRAYS -
    e.g. {"secs": [5, 10, 15, ...], "watts": [900, 850, ...]} - rather than a
    list of {secs, watts} point dicts. Handle that first, and keep the
    point-list shape as a fallback in case a different curve type (e.g. "all")
    is structured differently."""
    array_results = []
    point_list_results = []

    def walk(node):
        if isinstance(node, dict):
            secs = node.get("secs")
            watts = node.get("watts")
            if watts is None:
                watts = node.get("power")
            if (
                isinstance(secs, list) and isinstance(watts, list)
                and len(secs) == len(watts) and len(secs) > 0
                and isinstance(secs[0], (int, float))
            ):
                array_results.append(
                    [{"secs": s, "watts": w} for s, w in zip(secs, watts) if w]
                )
            for v in node.values():
                walk(v)
        elif isinstance(node, list):
            if node and all(isinstance(i, dict) for i in node):
                keys0 = set(node[0].keys())
                if "secs" in keys0 and ("watts" in keys0 or "power" in keys0):
                    if isinstance(node[0].get("secs"), (int, float)):
                        point_list_results.append(node)
            for item in node:
                walk(item)

    walk(payload)
    if array_results:
        return max(array_results, key=len)
    return point_list_results[0] if point_list_results else None


def format_duration_label(secs):
    if secs < 60:
        return f"{secs}s"
    if secs < 3600:
        return f"{secs // 60}min"
    return f"{secs // 3600}h"


def best_watts_for_durations(points, target_secs_list):
    if not points:
        return []
    sorted_points = sorted(points, key=lambda p: p.get("secs", 0))
    results = []
    for target in target_secs_list:
        best = None
        for p in sorted_points:
            if p.get("secs", 0) <= target:
                best = p
            else:
                break
        if best is None:
            best = sorted_points[0]
        watts = best.get("watts") or best.get("power")
        if watts:
            results.append({"label": format_duration_label(target), "watts": round(watts)})

    if results:
        max_watts = max(r["watts"] for r in results)
        for r in results:
            r["pct"] = round(100 * r["watts"] / max_watts) if max_watts else 0
    return results


def get_best_watts():
    try:
        payload = fetch_power_curve_payload()
        points = extract_power_curve_points(payload)
        result = best_watts_for_durations(points, [5, 15, 60, 300, 1200, 3600])
        debug = None
        if not result:
            preview = json.dumps(payload)[:500]
            debug = "Power curve payload preview: {}".format(preview)
        return result, debug
    except requests.HTTPError as e:
        return [], "Power curve request failed: {}".format(e)
    except Exception as e:
        return [], "Power curve error: {}".format(e)



def _power_at_duration(points, target_secs):
    """Return curve power near a requested duration without inventing a peak.

    Intervals curves normally include standard durations directly. If a target is
    absent, use log-time interpolation only when it is bracketed by real curve
    points; otherwise return None.
    """
    usable = []
    for p in points or []:
        try:
            sec = float(p.get("secs"))
            watts = float(p.get("watts") if p.get("watts") is not None else p.get("power"))
        except (TypeError, ValueError):
            continue
        if sec > 0 and watts > 0:
            usable.append((sec, watts))
    usable.sort()
    if not usable:
        return None
    for sec, watts in usable:
        if abs(sec - target_secs) < 0.5:
            return watts
    lower = None
    upper = None
    for sec, watts in usable:
        if sec < target_secs:
            lower = (sec, watts)
        elif sec > target_secs:
            upper = (sec, watts)
            break
    if not lower or not upper:
        return None
    lo_s, lo_w = lower
    hi_s, hi_w = upper
    # Do not bridge a very sparse section of a curve.
    if hi_s / lo_s > 2.5:
        return None
    frac = (math.log(target_secs) - math.log(lo_s)) / (math.log(hi_s) - math.log(lo_s))
    return lo_w + frac * (hi_w - lo_w)


def fit_critical_power_model(points, durations=(180, 300, 480, 720, 1200)):
    """Two-parameter critical-power field estimate from Intervals best efforts.

    The linearised model is P = CP + W'/t. CP is the intercept of power versus
    inverse time and W' is the slope (joules). This is deliberately labelled a
    *field model*: the source points may come from different rides and are not a
    controlled laboratory CP protocol.
    """
    pairs = []
    for sec in durations:
        watts = _power_at_duration(points, sec)
        if watts is not None:
            pairs.append((float(sec), float(watts)))
    if len(pairs) < 4:
        return {"available": False, "reason": "Need at least four usable best-effort durations between 3 and 20 min."}

    xs = [1.0 / sec for sec, _ in pairs]
    ys = [watts for _, watts in pairs]
    x_mean = statistics.mean(xs)
    y_mean = statistics.mean(ys)
    denom = sum((x - x_mean) ** 2 for x in xs)
    if denom <= 0:
        return {"available": False, "reason": "Power-curve durations are not sufficiently distinct."}
    slope = sum((x - x_mean) * (y - y_mean) for x, y in zip(xs, ys)) / denom
    intercept = y_mean - slope * x_mean
    preds = [intercept + slope * x for x in xs]
    sse = sum((y - pred) ** 2 for y, pred in zip(ys, preds))
    sst = sum((y - y_mean) ** 2 for y in ys)
    r2 = 1.0 - sse / sst if sst > 0 else 1.0
    errors = [abs(y - pred) / y * 100.0 for y, pred in zip(ys, preds) if y > 0]
    mae_pct = statistics.mean(errors) if errors else None

    cp = intercept
    w_prime_j = slope
    if not (50 <= cp <= 600 and 1000 <= w_prime_j <= 80000):
        return {"available": False, "reason": "The fitted parameters fell outside a plausible cycling field-model range."}
    if r2 >= 0.985 and len(pairs) >= 5:
        confidence = "HIGH"
    elif r2 >= 0.95:
        confidence = "MODERATE"
    else:
        confidence = "LOW"
    return {
        "available": True,
        "cp": round(cp),
        "w_prime_j": round(w_prime_j),
        "w_prime_kj": round(w_prime_j / 1000.0, 1),
        "r2": round(max(-1.0, min(1.0, r2)), 3),
        "mean_error_pct": round(mae_pct, 1) if mae_pct is not None else None,
        "confidence": confidence,
        "confidence_class": confidence.lower(),
        "points": [
            {"secs": int(sec), "label": format_duration_label(int(sec)), "watts": round(watts)}
            for sec, watts in pairs
        ],
    }


def build_power_model(points_42d, points_season, weight_kg=None):
    recent = fit_critical_power_model(points_42d)
    season = fit_critical_power_model(points_season)
    model = {
        "available": bool(recent.get("available")),
        "equation": "P = CP + W′ / t",
        "recent": recent,
        "season": season,
        "curve_comparison": [],
        "weight_kg": round(float(weight_kg), 1) if isinstance(weight_kg, (int, float)) else None,
        "cp_wkg": None,
        "season_cp_wkg": None,
        "cp_gap_w": None,
        "cp_proximity_pct": None,
        "status": "MODEL UNAVAILABLE",
        "status_class": "grey",
        "explanation": "Not enough usable best-effort points were returned for a stable 3–20 min two-parameter model.",
        "disclaimer": "Field estimate from Intervals.icu best-power curves; not a laboratory CP/W′ test.",
    }
    for sec in (300, 1200, 3600):
        w42 = _power_at_duration(points_42d, sec)
        ws = _power_at_duration(points_season, sec)
        if w42 is not None or ws is not None:
            model["curve_comparison"].append({
                "label": format_duration_label(sec),
                "recent": round(w42) if w42 is not None else None,
                "season": round(ws) if ws is not None else None,
            })
    if not recent.get("available"):
        return model

    if isinstance(weight_kg, (int, float)) and weight_kg > 0:
        model["cp_wkg"] = round(recent["cp"] / float(weight_kg), 2)
        if season.get("available"):
            model["season_cp_wkg"] = round(season["cp"] / float(weight_kg), 2)

    if season.get("available") and season.get("cp"):
        gap = recent["cp"] - season["cp"]
        proximity = recent["cp"] / season["cp"] * 100.0
        model["cp_gap_w"] = round(gap)
        model["cp_proximity_pct"] = round(proximity, 1)
        if proximity >= 99:
            status, css = "NEAR SEASON PEAK", "green"
        elif proximity >= 96:
            status, css = "CLOSE TO SEASON PEAK", "cyan"
        elif proximity >= 92:
            status, css = "BELOW SEASON PEAK", "orange"
        else:
            status, css = "WELL BELOW SEASON PEAK", "red"
        model["status"], model["status_class"] = status, css
        model["explanation"] = (
            f"The 42-day CP field model is {abs(round(gap))} W "
            f"{'above' if gap > 0 else 'below' if gap < 0 else 'at'} the current-season model "
            f"({proximity:.1f}% proximity). This compares recent best-power capacity with the season-best curve; it is not a readiness score."
        )
    else:
        model["status"], model["status_class"] = "42-DAY MODEL", "cyan"
        model["explanation"] = "A 42-day CP/W′ model is available, but the current-season comparison could not be fitted reliably."
    return model


def _stored_power_snapshot():
    """Last valid power outputs for transient Intervals power-curve failures.

    Fresh Intervals data always wins. Stored values are a continuity fallback only
    and are explicitly marked in the UI; they never masquerade as a fresh curve.
    """
    try:
        report = load_latest_report(include_payload=True) or {}
        data = report.get("data") or {}
        best = data.get("best_watts") or []
        model = data.get("power_model") or {}
        return (best if isinstance(best, list) else []), (model if isinstance(model, dict) else {})
    except Exception:
        return [], {}


def _fetch_power_curve_resilient(newest=None, curve="42d", attempts=2, timeout=12):
    """Small bounded retry for the current power curve; never an unbounded loop."""
    last_exc = None
    attempts = max(1, min(int(attempts or 1), 2))
    for _ in range(attempts):
        try:
            return fetch_power_curve_payload(newest=newest, curve=curve, timeout=timeout)
        except Exception as exc:
            last_exc = exc
    if last_exc is not None:
        raise last_exc
    return None


def get_power_intelligence(weight_kg=None):
    """Build Best Watts + CP/W′ from one resilient fresh 42-day curve.

    The 42-day curve is fetched first with one bounded retry because it powers the
    athlete-facing Best Wattage Output, the recent CP/W′ model and today's
    Intervals 5-minute VO₂ estimate. The season curve remains secondary: failure
    there must never blank the current 42-day outputs.
    """
    errors = []
    payload_42 = None
    payload_s0 = None
    try:
        payload_42 = _fetch_power_curve_resilient(None, "42d", attempts=2)
    except Exception as exc:
        errors.append(f"42d: {exc}")
    try:
        payload_s0 = fetch_power_curve_payload(None, "s0", timeout=8)
    except Exception as exc:
        errors.append(f"s0: {exc}")

    points_42 = extract_power_curve_points(payload_42) if payload_42 is not None else None
    points_s0 = extract_power_curve_points(payload_s0) if payload_s0 is not None else None
    best = best_watts_for_durations(points_42, [5, 15, 60, 300, 1200, 3600]) if points_42 else []
    best_fallback = False
    debug = None

    if not best:
        stored_best, _stored_model = _stored_power_snapshot()
        if stored_best:
            best = stored_best
            best_fallback = True
            debug = "Fresh 42-day power curve unavailable; showing last valid stored Best Wattage Output."
        elif errors:
            debug = "Power curve request failed: " + " | ".join(errors)
        elif payload_42 is not None:
            debug = "Power curve payload preview: " + json.dumps(payload_42)[:500]
        else:
            debug = "42-day power curve unavailable."

    model = build_power_model(points_42 or [], points_s0 or [], weight_kg=weight_kg)
    if errors:
        model["api_note"] = " | ".join(errors)
    model["best_watts_fallback"] = best_fallback
    return best, debug, model, payload_42


# PRODUCT V4.8.22 · Intervals-native achievements / FTP breakthrough context.
# This layer reports only what Intervals exposes on completed activities. It does
# not invent PBs or independently declare an FTP increase.
def _achievement_num(value):
    try:
        if value is None or isinstance(value, bool):
            return None
        x = float(value)
        return x if math.isfinite(x) else None
    except (TypeError, ValueError):
        return None


def _normalize_icu_achievements(raw):
    if raw is None:
        return []
    if isinstance(raw, str):
        s = raw.strip()
        if not s:
            return []
        try:
            raw = json.loads(s)
        except Exception:
            return []
    if isinstance(raw, dict):
        # Be tolerant of wrapper objects returned by future API variants.
        for key in ("achievements", "items", "data"):
            if isinstance(raw.get(key), list):
                raw = raw.get(key)
                break
        else:
            raw = [raw]
    if not isinstance(raw, list):
        return []
    out = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        typ = str(item.get("type") or "").strip().upper()
        if typ not in {"BEST_POWER", "FTP_UP", "LTHR_UP", "BEST_PACE"}:
            continue
        secs = _achievement_num(item.get("secs"))
        watts = _achievement_num(item.get("watts"))
        value = _achievement_num(item.get("value"))
        message = str(item.get("message") or "").strip()
        label = typ.replace("_", " ").title()
        if typ == "BEST_POWER":
            label = "Power PB"
        elif typ == "FTP_UP":
            label = "FTP increase"
        elif typ == "LTHR_UP":
            label = "LTHR increase"
        elif typ == "BEST_PACE":
            label = "Pace PB"
        out.append({
            "id": item.get("id"), "type": typ, "label": label,
            "secs": int(round(secs)) if secs is not None and secs > 0 else None,
            "duration": format_duration_label(int(round(secs))) if secs is not None and secs > 0 else None,
            "watts": int(round(watts)) if watts is not None and watts > 0 else None,
            "value": round(value, 2) if value is not None else None,
            "message": message,
        })
    return out


def build_performance_breakthrough(recent_activities, now=None, window_days=7):
    """Return recent Intervals-native PB / FTP breakthrough evidence.

    BEST_POWER and FTP_UP are taken only from ``icu_achievements``. Rolling FTP
    fields are shown as Intervals estimates/context and never promoted to a THE LAB
    independently-computed FTP. The feature is intentionally descriptive and does
    not alter Training Direction adherence, readiness or Energy Bank.
    """
    now = now or get_rome_now()
    cutoff = now.date() - timedelta(days=max(1, int(window_days)) - 1)
    rows = []
    for a in recent_activities or []:
        ds = str(a.get("start_date_local") or "")[:10]
        try:
            d = date.fromisoformat(ds)
        except ValueError:
            continue
        if d < cutoff or d > now.date():
            continue
        achievements = _normalize_icu_achievements(a.get("icu_achievements"))
        rolling_ftp = _achievement_num(a.get("icu_rolling_ftp"))
        rolling_delta = _achievement_num(a.get("icu_rolling_ftp_delta"))
        pm_ftp = _achievement_num(a.get("icu_pm_ftp"))
        pm_secs = _achievement_num(a.get("icu_pm_ftp_secs"))
        pm_watts = _achievement_num(a.get("icu_pm_ftp_watts"))
        activity_ftp = _achievement_num(a.get("icu_ftp"))
        has_positive_rolling = bool(rolling_delta is not None and rolling_delta > 0)
        if not achievements and not has_positive_rolling:
            continue
        pb = [x for x in achievements if x.get("type") == "BEST_POWER"]
        ftp_events = [x for x in achievements if x.get("type") == "FTP_UP"]
        rows.append({
            "activity_id": a.get("id"),
            "activity_name": str(a.get("name") or a.get("type") or "Activity"),
            "date": d.isoformat(),
            "date_display": d.strftime("%d %b"),
            "achievements": achievements,
            "pb_count": len(pb),
            "ftp_up_count": len(ftp_events),
            "rolling_ftp": int(round(rolling_ftp)) if rolling_ftp is not None and rolling_ftp > 0 else None,
            "rolling_ftp_delta": int(round(rolling_delta)) if rolling_delta is not None else None,
            "pm_ftp": int(round(pm_ftp)) if pm_ftp is not None and pm_ftp > 0 else None,
            "pm_ftp_secs": int(round(pm_secs)) if pm_secs is not None and pm_secs > 0 else None,
            "pm_ftp_duration": format_duration_label(int(round(pm_secs))) if pm_secs is not None and pm_secs > 0 else None,
            "pm_ftp_watts": int(round(pm_watts)) if pm_watts is not None and pm_watts > 0 else None,
            "activity_ftp": int(round(activity_ftp)) if activity_ftp is not None and activity_ftp > 0 else None,
        })
    rows.sort(key=lambda x: (x.get("date") or "", str(x.get("activity_id") or "")), reverse=True)
    pb_count = sum(int(r.get("pb_count") or 0) for r in rows)
    ftp_achievement_count = sum(int(r.get("ftp_up_count") or 0) for r in rows)
    latest = rows[0] if rows else None
    ftp_detected = bool(ftp_achievement_count or any((r.get("rolling_ftp_delta") or 0) > 0 for r in rows))
    headline_bits = []
    if pb_count:
        headline_bits.append(f"{pb_count} Intervals power PB{'s' if pb_count != 1 else ''}")
    if ftp_detected:
        if latest and (latest.get("rolling_ftp_delta") or 0) > 0:
            headline_bits.append(f"FTP +{latest['rolling_ftp_delta']} W")
        else:
            headline_bits.append("FTP increase")
    headline = " · ".join(headline_bits) if headline_bits else "Recent Intervals achievement"
    return {
        "available": bool(rows), "window_days": int(window_days), "headline": headline,
        "pb_count": pb_count, "ftp_detected": ftp_detected,
        "ftp_achievement_count": ftp_achievement_count, "activities": rows[:5], "latest": latest,
        "method_note": "Intervals-native achievements and FTP fields only · THE LAB does not invent a PB or independently raise FTP.",
    }


def performance_breakthrough_text(context):
    c = context or {}
    if not c.get("available"):
        return "PERFORMANCE BREAKTHROUGH: no recent Intervals-native PB/FTP achievement in the current window."
    lines = [
        "PERFORMANCE BREAKTHROUGH (Intervals-native; deterministic Python presentation):",
        f"- {c.get('headline')} · window {c.get('window_days')}d",
    ]
    for r in c.get("activities") or []:
        lines.append(f"- {r.get('date')} | {r.get('activity_name')} | power PBs {r.get('pb_count', 0)} | FTP achievements {r.get('ftp_up_count', 0)}")
        if r.get("rolling_ftp") is not None:
            delta = r.get("rolling_ftp_delta")
            lines.append(f"  Intervals rolling FTP: {r.get('rolling_ftp')} W" + (f" ({delta:+d} W delta)" if isinstance(delta, int) else ""))
        if r.get("pm_ftp") is not None:
            basis = ""
            if r.get("pm_ftp_duration") and r.get("pm_ftp_watts"):
                basis = f" · activity model basis {r.get('pm_ftp_duration')} at {r.get('pm_ftp_watts')} W"
            lines.append(f"  Intervals activity PM FTP: {r.get('pm_ftp')} W{basis}")
        for ach in r.get("achievements") or []:
            detail = ach.get("message") or ""
            if ach.get("type") == "BEST_POWER":
                bits = [x for x in (ach.get("duration"), f"{ach.get('watts')} W" if ach.get("watts") else None) if x]
                if bits:
                    detail = " · ".join(bits) + (f" · {detail}" if detail else "")
            elif ach.get("type") == "FTP_UP":
                trigger = ""
                if ach.get("duration") and ach.get("watts"):
                    trigger = f"triggering effort {ach.get('duration')} at {ach.get('watts')} W"
                new_ftp = r.get("rolling_ftp") or r.get("pm_ftp")
                detail = (f"new Intervals FTP signal {new_ftp} W" if new_ftp else "Intervals FTP increase") + (f" · {trigger}" if trigger else "")
            lines.append(f"  {ach.get('type')}: {detail or ach.get('label')}")
    lines.append("- Treat these as Intervals-recognized performance events. They are progress context, not a reason by themselves to override recovery, health, race proximity or planned training constraints.")
    return "\n".join(lines)


FTP_ANCHOR_HISTORY_DAYS = 365
FTP_ANCHOR_VALID_DAYS = 120
FTP_ANCHOR_AGING_DAYS = 180
FTP_ANCHOR_METRIC_KEY = "FTP_INTERVALS_ANCHOR"
FTP_ANCHOR_EFFORT_SECS_KEY = "FTP_INTERVALS_ANCHOR_EFFORT_SECS"
FTP_ANCHOR_EFFORT_WATTS_KEY = "FTP_INTERVALS_ANCHOR_EFFORT_WATTS"


def _plausible_ftp(value):
    value = _achievement_num(value)
    return value if value is not None and 80 <= value <= 600 else None


def _ftp_up_event_from_activity(activity):
    """Extract an explicit Intervals FTP_UP event; never infer one from a lower rolling estimate."""
    achievements = _normalize_icu_achievements((activity or {}).get("icu_achievements"))
    ftp_achievements = [a for a in achievements if a.get("type") == "FTP_UP"]
    if not ftp_achievements:
        return None
    rolling = _plausible_ftp((activity or {}).get("icu_rolling_ftp"))
    pm_ftp = _plausible_ftp((activity or {}).get("icu_pm_ftp"))
    pm_secs = _achievement_num((activity or {}).get("icu_pm_ftp_secs"))
    pm_watts = _achievement_num((activity or {}).get("icu_pm_ftp_watts"))
    explicit_message_values = []
    achievement_values = []
    message = ""
    ach_secs = None
    ach_watts = None
    for ach in ftp_achievements:
        message = str(ach.get("message") or message or "")
        value = _plausible_ftp(ach.get("value"))
        if value is not None:
            achievement_values.append(value)
        raw_message = str(ach.get("message") or "")
        m = re.search(r"\bto\s+(\d{2,3})\s*w\b", raw_message, flags=re.I)
        if m:
            parsed = _plausible_ftp(m.group(1))
            if parsed is not None:
                explicit_message_values.append(parsed)
        if ach.get("secs"):
            ach_secs = ach.get("secs")
        if ach.get("watts"):
            ach_watts = ach.get("watts")
    # Prefer the explicit FTP_UP target itself.  Activity PM FTP is only a fallback
    # because it is a model estimate and must not overwrite a declared "to 291 W" event.
    if explicit_message_values:
        ftp = max(explicit_message_values)
    elif achievement_values:
        ftp = max(achievement_values)
    elif rolling is not None:
        ftp = rolling
    else:
        ftp = pm_ftp
    if ftp is None:
        return None
    effort_secs = pm_secs if pm_secs and pm_secs > 0 else ach_secs
    effort_watts = pm_watts if pm_watts and pm_watts > 0 else ach_watts
    if message:
        if not effort_secs:
            m = re.search(r"from\s+(\d+(?:\.\d+)?)\s*(s|sec|secs|m|min|mins|h|hr|hrs)\b", message, flags=re.I)
            if m:
                n = float(m.group(1)); unit = m.group(2).lower()
                effort_secs = n * (3600 if unit.startswith('h') else 60 if unit.startswith('m') else 1)
        if not effort_watts:
            m = re.search(r"at\s+(\d{2,4})\s*w\b", message, flags=re.I)
            if m:
                effort_watts = float(m.group(1))
    return {
        "ftp": round(float(ftp), 1),
        "effort_secs": int(round(effort_secs)) if effort_secs else None,
        "effort_watts": int(round(effort_watts)) if effort_watts else None,
        "message": message,
    }


def _persist_interval_metric_points(metric_key, points, source, user_id=None):
    owner_id = _data_owner_user_id(user_id)
    clean = {}
    for day, value in points or []:
        try:
            date.fromisoformat(str(day)[:10])
            v = float(value)
        except (TypeError, ValueError):
            continue
        if math.isfinite(v):
            clean[str(day)[:10]] = v
    if not clean:
        return 0
    init_memory_db()
    conn = _db_connect(); now_text = _now_utc_text(); saved = 0
    try:
        cur = conn.cursor()
        sql = _db_sql(
            "INSERT INTO intervals_metric_history (user_id, metric_key, metric_date, value, source, created_at_utc, updated_at_utc) "
            "VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT(user_id, metric_key, metric_date) DO UPDATE SET "
            "value=excluded.value, source=excluded.source, updated_at_utc=excluded.updated_at_utc"
        )
        for day, value in sorted(clean.items()):
            cur.execute(sql, (owner_id, metric_key, day, value, source, now_text, now_text)); saved += 1
        conn.commit(); return saved
    finally:
        conn.close()


def _persist_ftp_anchor_events(activities, user_id=None):
    anchors, effort_secs, effort_watts = [], [], []
    for a in activities or []:
        day = str(a.get("start_date_local") or "")[:10]
        try:
            date.fromisoformat(day)
        except Exception:
            continue
        event = _ftp_up_event_from_activity(a)
        if not event:
            continue
        anchors.append((day, event["ftp"]))
        if event.get("effort_secs"):
            effort_secs.append((day, event["effort_secs"]))
        if event.get("effort_watts"):
            effort_watts.append((day, event["effort_watts"]))
    saved = _persist_interval_metric_points(FTP_ANCHOR_METRIC_KEY, anchors, "INTERVALS_FTP_UP", user_id=user_id)
    _persist_interval_metric_points(FTP_ANCHOR_EFFORT_SECS_KEY, effort_secs, "INTERVALS_FTP_UP_BASIS", user_id=user_id)
    _persist_interval_metric_points(FTP_ANCHOR_EFFORT_WATTS_KEY, effort_watts, "INTERVALS_FTP_UP_BASIS", user_id=user_id)
    return saved


def _stored_interval_metric_points(metric_key, user_id=None):
    try:
        owner_id = _data_owner_user_id(user_id)
        rows = _db_execute(
            "SELECT metric_date, value, source FROM intervals_metric_history WHERE user_id=? AND metric_key=? ORDER BY metric_date ASC",
            (owner_id, metric_key), fetch=True,
        )
    except Exception:
        return []
    out = []
    for row in rows or []:
        day = str(row.get("metric_date") or "")[:10]
        try:
            date.fromisoformat(day); value = float(row.get("value"))
        except (TypeError, ValueError):
            continue
        if math.isfinite(value):
            out.append({"date": day, "value": value, "source": row.get("source")})
    return out


def build_ftp_anchor_context(history_activities, now=None, user_id=None):
    """Separate the current usable FTP anchor from the all-time historical peak.

    Explicit Intervals FTP_UP events are persisted.  The strongest non-stale event
    (<=180d) is the active prescription anchor; a stronger event older than that is
    retained only as HISTORICAL PEAK and cannot govern current zones/prescriptions.
    A lower rolling eFTP alone never lowers an active validated anchor.
    """
    now = now or get_rome_now()
    try:
        _persist_ftp_anchor_events(history_activities, user_id=user_id)
    except Exception as exc:
        app.logger.warning("FTP anchor persistence skipped: %s", exc)
    anchors = _stored_interval_metric_points(FTP_ANCHOR_METRIC_KEY, user_id=user_id)
    secs_rows = {r["date"]: r["value"] for r in _stored_interval_metric_points(FTP_ANCHOR_EFFORT_SECS_KEY, user_id=user_id)}
    watts_rows = {r["date"]: r["value"] for r in _stored_interval_metric_points(FTP_ANCHOR_EFFORT_WATTS_KEY, user_id=user_id)}
    current_rolling = None
    latest_rolling_day = None
    for a in sorted(history_activities or [], key=lambda x: str(x.get("start_date_local") or "")):
        rolling = _plausible_ftp(a.get("icu_rolling_ftp"))
        if rolling is not None:
            current_rolling = int(round(rolling)); latest_rolling_day = str(a.get("start_date_local") or "")[:10]
    if not anchors:
        return {
            "available": bool(current_rolling), "anchor_watts": None, "prescription_watts": None,
            "anchor_date": None, "status": "NO VALIDATED ANCHOR", "status_class": "grey",
            "age_days": None, "current_rolling_ftp": current_rolling, "current_rolling_date": latest_rolling_day,
            "retest_due": False, "historical_peak_watts": None, "historical_peak_date": None,
            "method_note": "No explicit Intervals FTP_UP has been persisted yet; rolling FTP/eFTP is shown as context only.",
        }

    def with_age(row):
        d = date.fromisoformat(row["date"])
        return row, d, max(0, (now.date() - d).days)

    aged = [with_age(r) for r in anchors]
    historical_row, historical_day, historical_age = max(aged, key=lambda x: (float(x[0].get("value") or 0), str(x[0].get("date") or "")))
    usable = [x for x in aged if x[2] <= FTP_ANCHOR_AGING_DAYS]
    active = max(usable, key=lambda x: (float(x[0].get("value") or 0), str(x[0].get("date") or ""))) if usable else None

    if active:
        anchor, anchor_day, age = active
        if age <= FTP_ANCHOR_VALID_DAYS:
            status, css, retest = "VALID", "green", False
        else:
            status, css, retest = "AGING", "orange", False
        prescription_watts = int(round(anchor["value"]))
    else:
        # No still-usable FTP_UP. Keep the historical peak visible, but never use it
        # as a precise prescription anchor once it is beyond the retest horizon.
        anchor, anchor_day, age = historical_row, historical_day, historical_age
        status, css, retest = "RETEST DUE", "red", True
        prescription_watts = None

    secs = secs_rows.get(anchor["date"]); watts = watts_rows.get(anchor["date"])
    historical_secs = secs_rows.get(historical_row["date"]); historical_watts = watts_rows.get(historical_row["date"])
    return {
        "available": True,
        "anchor_watts": int(round(anchor["value"])),
        "prescription_watts": prescription_watts,
        "anchor_date": anchor["date"], "anchor_date_display": anchor_day.strftime("%d %b %Y"),
        "age_days": age, "status": status, "status_class": css, "retest_due": retest,
        "effort_secs": int(round(secs)) if secs else None,
        "effort_duration": format_duration_label(int(round(secs))) if secs else None,
        "effort_watts": int(round(watts)) if watts else None,
        "current_rolling_ftp": current_rolling, "current_rolling_date": latest_rolling_day,
        "gap_vs_rolling": (int(round(current_rolling - anchor["value"])) if current_rolling is not None else None),
        "historical_peak_watts": int(round(historical_row["value"])),
        "historical_peak_date": historical_row["date"],
        "historical_peak_date_display": historical_day.strftime("%d %b %Y"),
        "historical_peak_age_days": historical_age,
        "historical_peak_effort_duration": format_duration_label(int(round(historical_secs))) if historical_secs else None,
        "historical_peak_effort_watts": int(round(historical_watts)) if historical_watts else None,
        "valid_days": FTP_ANCHOR_VALID_DAYS, "aging_days": FTP_ANCHOR_AGING_DAYS,
        "method_note": (
            "Active FTP anchor = strongest explicit Intervals FTP_UP still inside the 180-day usability horizon. "
            "Older stronger values remain historical peaks only; rolling FTP/eFTP is context and cannot lower an active validated anchor."
        ),
    }

def ftp_anchor_text(context):
    c = context or {}
    if not c.get("anchor_watts"):
        return f"FTP ANCHOR: no validated FTP_UP anchor yet | current Intervals rolling FTP/eFTP {c.get('current_rolling_ftp') or 'n/a'} W"
    basis = ""
    if c.get("effort_duration") and c.get("effort_watts"):
        basis = f" | validating effort {c.get('effort_duration')} at {c.get('effort_watts')} W"
    rolling = f" | current Intervals rolling FTP/eFTP {c.get('current_rolling_ftp')} W" if c.get("current_rolling_ftp") else ""
    hist = ""
    if c.get("historical_peak_watts") and c.get("historical_peak_watts") != c.get("anchor_watts"):
        hist = f" | historical peak {c.get('historical_peak_watts')} W ({c.get('historical_peak_date')})"
    precision = ("This value is eligible for current prescription." if c.get("prescription_watts") else "No stale FTP anchor may be used as a precise prescription target until a new FTP_UP is recorded.")
    return (f"CURRENT VALIDATED FTP ANCHOR: {c.get('anchor_watts')} W | {c.get('status')} | "
            f"validated {c.get('anchor_date')} ({c.get('age_days')}d ago){basis}{rolling}{hist}. {precision}")

def fetch_intervals_data():
    """Fetch one raw activity-history payload plus the existing Wellness window.

    V4.8.25 extends only the raw Activities evidence horizon to recover still-relevant
    explicit FTP_UP events. Before returning, normal Product activity inputs are
    narrowed back to the unchanged SEASON_DAYS_BACK / DAYS_BACK windows. Wellness
    remains on the existing season window. No additional external request is added.
    """
    today_local = get_rome_now().date()
    history_oldest = (today_local - timedelta(days=FTP_ANCHOR_HISTORY_DAYS)).isoformat()
    season_oldest = (today_local - timedelta(days=SEASON_DAYS_BACK)).isoformat()
    recent_oldest = (today_local - timedelta(days=DAYS_BACK)).isoformat()
    newest = today_local.isoformat()
    runtime = _resolve_intervals_runtime()
    headers = get_intervals_headers(runtime)

    activities_fields = (
        "id,name,type,start_date_local,moving_time,elapsed_time,distance,"
        "icu_training_load,icu_weighted_avg_watts,icu_average_watts,average_watts,average_heartrate,max_heartrate,stream_types,"
        "icu_zone_times,icu_hr_zone_times,icu_hr_zones,icu_hrr,icu_ftp,icu_pm_ftp,icu_pm_ftp_secs,icu_pm_ftp_watts,icu_rolling_ftp,icu_rolling_ftp_delta,icu_achievements,decoupling,"
        "calories,carbs_used,carbs_ingested,trainer,icu_intensity,"
        "icu_variability_index,joules,sub_type"
    )
    activities_url = (
        f"https://intervals.icu/api/v1/athlete/{runtime['athlete_id']}/activities"
        f"?oldest={history_oldest}&newest={newest}&fields={activities_fields}"
    )

    wellness_fields = "id,restingHR,tempRestingHR,hrv,hrvSDNN,sleepSecs,sleepScore,sleepQuality,avgSleepingHR,weight,tempWeight,steps,ctl,atl,rampRate,comments,readiness,spO2,vo2max,respiration,baevskySI,systolic,diastolic,sportInfo"
    wellness_url = (
        f"https://intervals.icu/api/v1/athlete/{runtime['athlete_id']}/wellness"
        f"?oldest={season_oldest}&newest={newest}&fields={wellness_fields}"
    )

    act_resp = requests.get(activities_url, headers=headers, timeout=30)
    act_resp.raise_for_status()
    wel_resp = requests.get(wellness_url, headers=headers, timeout=30)
    wel_resp.raise_for_status()

    history_activities = act_resp.json()
    history_activities = [
        a for a in history_activities if a.get("start_date_local", "")[:10] >= history_oldest
    ]
    season_activities = [
        a for a in history_activities if a.get("start_date_local", "")[:10] >= season_oldest
    ]
    recent_activities = [
        a for a in season_activities if a.get("start_date_local", "")[:10] >= recent_oldest
    ]

    season_wellness = wel_resp.json()
    season_wellness = [
        w for w in season_wellness if w.get("id", "") >= season_oldest
    ]
    recent_wellness = [w for w in season_wellness if w.get("id", "") >= recent_oldest]

    return recent_activities, season_activities, recent_wellness, season_wellness, history_activities


def _vo2_number(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    # Sanity filter only; this is not a physiological classification.
    return value if 15.0 <= value <= 100.0 else None


def extract_vo2max_5m(payload):
    """Return Intervals.icu's performance VO2max estimate from a power curve.

    The Intervals.icu server-side power-curve model exposes ``vo2max_5m``.
    The public endpoint payload can contain nested curve objects, so search
    recursively and keep a plausible numeric value. The URL asks only for the
    42-day Ride curve; if several nested representations are present we retain
    the highest identical/near-identical estimate rather than inventing a
    value from average power.
    """
    values = []

    def walk(node):
        if isinstance(node, dict):
            if "vo2max_5m" in node:
                v = _vo2_number(node.get("vo2max_5m"))
                if v is not None:
                    values.append(v)
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(payload)
    return round(max(values), 1) if values else None


def _sample_vo2_points(points, max_points=10):
    if len(points) <= max_points:
        return points
    if max_points <= 1:
        return [points[-1]]
    # Evenly retain the full time span, always keeping first and latest.
    idxs = []
    for i in range(max_points):
        idx = round(i * (len(points) - 1) / (max_points - 1))
        if idx not in idxs:
            idxs.append(idx)
    return [points[i] for i in idxs]


def _wellness_vo2_value(row):
    """Extract a plausible Intervals wellness VO₂max without assuming one JSON shape.

    The stable path is the top-level ``vo2max`` field. ``sportInfo`` is already
    requested from Intervals and may carry sport-specific wellness values, so a
    narrowly keyed fallback prevents a valid Intervals estimate from silently
    disappearing when the top-level field is absent.
    """
    row = row or {}
    direct = _vo2_number(row.get("vo2max"))
    if direct is not None:
        return direct

    found = []
    def walk(node):
        if isinstance(node, dict):
            for key, value in node.items():
                normalized = str(key or "").lower().replace("_", "").replace("-", "")
                if normalized == "vo2max":
                    v = _vo2_number(value)
                    if v is not None:
                        found.append(v)
                elif isinstance(value, (dict, list)):
                    walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)
    walk(row.get("sportInfo"))
    return found[0] if found else None


def build_wearable_vo2_series(wellness, max_points=10):
    """VO2max imported through Intervals wellness (typically wearable data).

    Consecutive identical values are collapsed to the *latest* date carrying
    that value. This keeps the chart readable instead of printing the same
    wearable estimate on dozens of consecutive days.
    """
    raw = []
    for w in sorted(wellness or [], key=lambda x: x.get("id", "")):
        v = _wellness_vo2_value(w)
        day = str(w.get("id") or "")[:10]
        if v is None or len(day) != 10:
            continue
        item = {"date": day, "value": round(v, 1)}
        if raw and abs(raw[-1]["value"] - item["value"]) < 0.05:
            raw[-1] = item
        else:
            raw.append(item)
    return _sample_vo2_points(raw, max_points=max_points)


_VO2_HISTORY_KEYS = {
    "wearable": ("VO2_WELLNESS", "INTERVALS_WELLNESS"),
    "performance": ("VO2_POWER_5M", "INTERVALS_POWER_CURVE_42D"),
}


def _vo2_history_key(kind):
    try:
        return _VO2_HISTORY_KEYS[str(kind).strip().lower()]
    except Exception:
        raise ValueError("Unknown VO₂ history series.")


def _stored_vo2_series(kind, user_id=None):
    """Load durable Intervals VO₂ history from Product storage, never Last Report.

    This is an integration-history cache keyed by athlete + metric + date. It is
    intentionally independent from Snapshot/report lifecycle: replacing Last Report
    cannot erase VO₂ history. OWNER rows are isolated by the owner user_id on Product
    Neon; no schema change or write is made to the legacy Personal Neon database.
    """
    try:
        owner_id = _data_owner_user_id(user_id)
        metric_key, _source = _vo2_history_key(kind)
        rows = _db_execute(
            "SELECT metric_date, value FROM intervals_metric_history "
            "WHERE user_id=? AND metric_key=? ORDER BY metric_date ASC",
            (owner_id, metric_key), fetch=True,
        )
    except Exception:
        return []
    clean = []
    for row in rows or []:
        day = str(row.get("metric_date") or "")[:10]
        value = _vo2_number(row.get("value"))
        try:
            date.fromisoformat(day)
        except Exception:
            continue
        if value is not None:
            clean.append({"date": day, "value": round(value, 1)})
    return clean


def _persist_vo2_series(kind, rows, user_id=None):
    """Upsert successful Intervals VO₂ observations into durable history.

    Failed/missing API checkpoints do nothing: they never delete an older observation.
    The database therefore accumulates real successful Intervals observations over time
    instead of treating a single replaceable Snapshot as historical storage.
    """
    owner_id = _data_owner_user_id(user_id)
    metric_key, source = _vo2_history_key(kind)
    clean = {}
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        day = str(row.get("date") or "")[:10]
        value = _vo2_number(row.get("value"))
        try:
            date.fromisoformat(day)
        except Exception:
            continue
        if value is not None:
            clean[day] = round(value, 1)
    if not clean:
        return 0

    init_memory_db()
    conn = _db_connect()
    saved = 0
    now_text = _now_utc_text()
    try:
        cur = conn.cursor()
        upsert_sql = _db_sql(
            "INSERT INTO intervals_metric_history "
            "(user_id, metric_key, metric_date, value, source, created_at_utc, updated_at_utc) "
            "VALUES (?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(user_id, metric_key, metric_date) DO UPDATE SET "
            "value=excluded.value, source=excluded.source, updated_at_utc=excluded.updated_at_utc"
        )
        for day, value in sorted(clean.items()):
            cur.execute(upsert_sql, (owner_id, metric_key, day, value, source, now_text, now_text))
            saved += 1
        conn.commit()
        return saved
    finally:
        conn.close()


def _performance_vo2_curve_range(day, window_days=42):
    """Return an explicit Intervals.icu date-range curve for a historical checkpoint.

    ``42d`` is relative to the server's current reference date.  A historical
    checkpoint therefore must not be emulated with ``newest=<past date>``.
    Intervals.icu supports explicit range curves as
    ``r.YYYY-MM-DD.YYYY-MM-DD``; using an inclusive 42-day range makes every
    checkpoint represent the same rolling window as the current 42-day curve.
    """
    if not isinstance(day, date):
        day = date.fromisoformat(str(day)[:10])
    try:
        window_days = int(window_days)
    except (TypeError, ValueError):
        window_days = 42
    window_days = max(1, min(window_days, 3660))
    start_day = day - timedelta(days=window_days - 1)
    return f"r.{start_day.isoformat()}.{day.isoformat()}"


def _performance_vo2_checkpoint(day, runtime=None):
    """Fetch one historical Intervals VO₂ checkpoint with explicit athlete credentials.

    The working historical semantics remain Intervals' native ``42d`` curve anchored
    with ``newest=<checkpoint date>``. Product must also pass the already-resolved
    per-athlete runtime into worker threads: Flask's request/session context does not
    propagate to ``ThreadPoolExecutor`` workers.
    """
    payload = fetch_power_curve_payload(
        newest=day.isoformat(), curve="42d", timeout=30, runtime=runtime
    )
    value = extract_vo2max_5m(payload)
    return {"date": day.isoformat(), "value": value} if value is not None else None


def _merge_vo2_series(stored, fresh, max_points=12):
    """Merge historical stored checkpoints with fresh Intervals values by date.

    Fresh values always replace a stored value on the same date. This prevents one
    successful current checkpoint from erasing an otherwise useful longitudinal
    history when older Intervals checkpoint requests are temporarily unavailable.
    """
    merged = {}
    stored_days = set()
    fresh_days = set()
    for source, bucket in ((stored or [], stored_days), (fresh or [], fresh_days)):
        for row in source:
            if not isinstance(row, dict):
                continue
            day = str(row.get("date") or "")[:10]
            value = _vo2_number(row.get("value"))
            try:
                date.fromisoformat(day)
            except Exception:
                continue
            if value is None:
                continue
            merged[day] = {"date": day, "value": round(value, 1)}
            bucket.add(day)
    rows = [merged[k] for k in sorted(merged)]
    if max_points and len(rows) > max_points:
        rows = _sample_vo2_points(rows, max_points=max_points)
    carried = any(day not in fresh_days for day in stored_days if day in {r["date"] for r in rows})
    return rows, carried


def build_performance_vo2_series(points=8, step_days=7, current_payload=None, current_day=None):
    """Historical Intervals 5-minute-power VO₂ trend with bounded API pressure.

    Today's already-fetched 42-day power curve is reused when supplied, avoiding a
    duplicate request. Older weekly checkpoints use Intervals' native ``42d`` curve
    anchored with ``newest=<checkpoint date>`` — the same retrieval semantics used
    by the earlier implementation in which the historical performance trend worked.
    Requests use modest concurrency; any misses are later merged with durable history
    by ``build_vo2max_trend`` instead of collapsing the whole graph to one point.
    """
    today = current_day or date.today()
    checkpoints = [today - timedelta(days=step_days * i) for i in reversed(range(points))]
    results = []

    if current_payload is not None:
        current_value = extract_vo2max_5m(current_payload)
        if current_value is not None:
            results.append({"date": today.isoformat(), "value": current_value})

    pending = [d for d in checkpoints if d != today or current_payload is None]
    checkpoint_errors = []
    pool_runtime = None
    if pending:
        try:
            # Resolve identity/credential ownership on the request thread. Flask's
            # session proxy is unavailable inside executor workers; passing this
            # immutable runtime dict keeps every request athlete-scoped without
            # falling back to owner/global credentials.
            pool_runtime = _resolve_intervals_runtime()
        except Exception as exc:
            checkpoint_errors.append(("runtime", str(exc)))

    if pending and pool_runtime is not None:
        try:
            with ThreadPoolExecutor(max_workers=4) as pool:
                futures = {pool.submit(_performance_vo2_checkpoint, d, pool_runtime): d for d in pending}
                for future in as_completed(futures):
                    checkpoint_day = futures[future]
                    try:
                        item = future.result()
                        if item:
                            results.append(item)
                    except Exception as exc:
                        checkpoint_errors.append((checkpoint_day.isoformat(), str(exc)))
        except Exception as exc:
            checkpoint_errors.append(("executor", str(exc)))

    if checkpoint_errors:
        app.logger.warning(
            "Intervals historical VO2 checkpoints incomplete: %s/%s issue(s); first=%s",
            len(checkpoint_errors), len(pending), checkpoint_errors[0][0],
        )

    if not any(r.get("date") == today.isoformat() for r in results):
        try:
            payload = _fetch_power_curve_resilient(today.isoformat(), "42d", attempts=2, timeout=30)
            value = extract_vo2max_5m(payload)
            if value is not None:
                results.append({"date": today.isoformat(), "value": value})
        except Exception:
            pass

    dedup = {}
    for row in results:
        dedup[row["date"]] = row
    return [dedup[k] for k in sorted(dedup)]


def _vo2_delta_28(series):
    if len(series) < 2:
        return None
    latest = series[-1]
    try:
        latest_day = date.fromisoformat(latest["date"])
    except Exception:
        return None
    target = latest_day - timedelta(days=28)
    candidates = []
    for p in series[:-1]:
        try:
            d = date.fromisoformat(p["date"])
        except Exception:
            continue
        candidates.append((abs((d - target).days), d, p))
    if not candidates:
        return None
    _, _, base = min(candidates, key=lambda x: x[0])
    return round(latest["value"] - base["value"], 1)


def _vo2_direction(delta):
    if delta is None:
        return None
    if delta >= 0.5:
        return "RISING"
    if delta <= -0.5:
        return "FALLING"
    return "STABLE"


def _vo2_path(points):
    return " ".join(("M" if i == 0 else "L") + f" {p['x']:.1f} {p['y']:.1f}" for i, p in enumerate(points))


def build_vo2max_trend(season_wellness, current_power_payload=None, current_power_day=None, history_user_id=None, persist_history=True):
    fresh_wearable = build_wearable_vo2_series(season_wellness, max_points=10)
    fresh_performance = build_performance_vo2_series(
        points=8, step_days=7, current_payload=current_power_payload, current_day=current_power_day
    )

    stored_wearable = []
    stored_performance = []
    if persist_history:
        # Successful Intervals observations are durable independently of Last Report.
        # A missing checkpoint never deletes a previously observed point.
        try:
            _persist_vo2_series("wearable", fresh_wearable, user_id=history_user_id)
            _persist_vo2_series("performance", fresh_performance, user_id=history_user_id)
            stored_wearable = _stored_vo2_series("wearable", user_id=history_user_id)
            stored_performance = _stored_vo2_series("performance", user_id=history_user_id)
        except Exception:
            # History persistence is supplementary; fresh Intervals values still render.
            stored_wearable = []
            stored_performance = []

    wearable, wearable_fallback = _merge_vo2_series(stored_wearable, fresh_wearable, max_points=12)
    performance, performance_fallback = _merge_vo2_series(stored_performance, fresh_performance, max_points=12)

    all_points = wearable + performance
    if not all_points:
        return {
            "available": False, "wearable": [], "performance": [],
            "wearable_current": None, "performance_current": None,
            "wearable_delta28": None, "performance_delta28": None,
            "wearable_fallback": False, "performance_fallback": False,
            "agreement": "INSUFFICIENT DATA", "agreement_class": "grey",
        }

    dated = []
    for p in all_points:
        try:
            dated.append((date.fromisoformat(p["date"]), float(p["value"])))
        except Exception:
            pass
    if not dated:
        return {"available": False, "wearable": [], "performance": [], "agreement": "INSUFFICIENT DATA", "agreement_class": "grey"}

    min_day = min(d for d, _ in dated)
    max_day = max(d for d, _ in dated)
    day_span = max(1, (max_day - min_day).days)
    values = [v for _, v in dated]
    vmin, vmax = min(values), max(values)
    pad = max(1.0, (vmax - vmin) * 0.18)
    ymin = math.floor((vmin - pad) * 2) / 2
    ymax = math.ceil((vmax + pad) * 2) / 2
    if ymax - ymin < 4:
        mid = (ymax + ymin) / 2
        ymin, ymax = mid - 2, mid + 2

    x0, x1 = 58.0, 942.0
    y0, y1 = 32.0, 188.0

    def map_series(series, label_offset):
        mapped = []
        for p in series:
            d = date.fromisoformat(p["date"])
            x = x0 + ((d - min_day).days / day_span) * (x1 - x0)
            y = y1 - ((p["value"] - ymin) / (ymax - ymin)) * (y1 - y0)
            mapped.append({
                **p,
                "x": round(x, 1), "y": round(y, 1),
                "label_y": round(max(17, min(211, y + label_offset)), 1),
                "date_label": d.strftime("%d %b"),
                "value_label": f"{p['value']:.1f}",
            })
        return mapped

    wearable_m = map_series(wearable, -12)
    performance_m = map_series(performance, 21)
    wd = _vo2_delta_28(wearable)
    pd = _vo2_delta_28(performance)
    wdir, pdir = _vo2_direction(wd), _vo2_direction(pd)
    if wdir is None or pdir is None:
        agreement = "INSUFFICIENT DATA"
        agreement_class = "grey"
    elif wdir == "RISING" and pdir == "RISING":
        agreement, agreement_class = "BOTH RISING", "green"
    elif wdir == "STABLE" and pdir == "STABLE":
        agreement, agreement_class = "BOTH STABLE", "cyan"
    elif {wdir, pdir} == {"RISING", "FALLING"}:
        agreement, agreement_class = "DIVERGING", "orange"
    else:
        agreement, agreement_class = "MIXED", "grey"

    ticks = []
    for frac in (0.0, 0.5, 1.0):
        value = ymax - frac * (ymax - ymin)
        ticks.append({"y": round(y0 + frac * (y1 - y0), 1), "value": round(value, 1)})

    date_ticks = []
    for frac in (0.0, 0.5, 1.0):
        d = min_day + timedelta(days=round(day_span * frac))
        date_ticks.append({"x": round(x0 + frac * (x1 - x0), 1), "label": d.strftime("%d %b")})

    return {
        "available": True,
        "wearable": wearable_m,
        "performance": performance_m,
        "wearable_path": _vo2_path(wearable_m) if wearable_m else "",
        "performance_path": _vo2_path(performance_m) if performance_m else "",
        "wearable_current": wearable[-1]["value"] if wearable else None,
        "performance_current": performance[-1]["value"] if performance else None,
        "wearable_delta28": wd,
        "performance_delta28": pd,
        "wearable_direction": wdir or "INSUFFICIENT",
        "performance_direction": pdir or "INSUFFICIENT",
        "agreement": agreement,
        "agreement_class": agreement_class,
        "wearable_fallback": wearable_fallback,
        "performance_fallback": performance_fallback,
        "ticks": ticks,
        "date_ticks": date_ticks,
        "ymin": ymin, "ymax": ymax,
    }


def percentile(sorted_values, pct):
    """Simple linear-interpolation percentile, no numpy dependency."""
    if not sorted_values:
        return None
    if len(sorted_values) == 1:
        return sorted_values[0]
    k = (len(sorted_values) - 1) * pct
    f, c = int(k), min(int(k) + 1, len(sorted_values) - 1)
    if f == c:
        return sorted_values[f]
    return sorted_values[f] + (sorted_values[c] - sorted_values[f]) * (k - f)


def personal_form_thresholds(season_wellness, min_points=14):
    """The athlete's own p33/p67 TSB range over the season window, so Form is
    judged against their normal baseline instead of a generic cutoff."""
    tsb_values = sorted(
        w["ctl"] - w["atl"] for w in season_wellness
        if w.get("ctl") is not None and w.get("atl") is not None
    )
    if len(tsb_values) < min_points:
        return None
    return percentile(tsb_values, 0.33), percentile(tsb_values, 0.67)


def personal_form_median(season_wellness, min_points=14):
    """The athlete's own typical TSB, so day-to-day form can be shown as a
    small delta from what's normal FOR THEM instead of a scary absolute
    number that's just a side effect of training at chronic high load."""
    tsb_values = sorted(
        w["ctl"] - w["atl"] for w in season_wellness
        if w.get("ctl") is not None and w.get("atl") is not None
    )
    if len(tsb_values) < min_points:
        return None
    return percentile(tsb_values, 0.5)


def personal_fatigue_thresholds(season_wellness, min_points=14):
    """The athlete's own p33/p67 ATL:CTL ratio range over the season window."""
    ratios = sorted(
        w["atl"] / w["ctl"] for w in season_wellness
        if w.get("ctl") not in (None, 0) and w.get("atl") is not None
    )
    if len(ratios) < min_points:
        return None
    return percentile(ratios, 0.33), percentile(ratios, 0.67)


def classify_form(tsb, personal_thresholds=None):
    if tsb is None:
        return "grey"
    if personal_thresholds:
        p33, p67 = personal_thresholds
        if tsb >= p67:
            return "green"
        if tsb <= p33:
            return "red"
        return "grey"
    # Fallback generic thresholds - only used when there isn't enough
    # history yet to learn the athlete's own normal range.
    if tsb >= 5:
        return "green"
    if tsb <= -10:
        return "red"
    return "grey"


def classify_fatigue(atl, ctl, personal_thresholds=None):
    if atl is None or ctl is None or ctl == 0:
        return "grey"
    ratio = atl / ctl
    if personal_thresholds:
        p33, p67 = personal_thresholds
        if ratio <= p33:
            return "green"
        if ratio >= p67:
            return "red"
        return "grey"
    if ratio >= 1.15:
        return "red"
    if ratio <= 0.95:
        return "green"
    return "grey"


def classify_fitness_trend(wellness):
    ctl_values = [(w.get("id"), w.get("ctl")) for w in wellness if w.get("ctl") is not None]
    ctl_values.sort(key=lambda x: x[0])
    if len(ctl_values) < 2:
        return "grey"
    change = ctl_values[-1][1] - ctl_values[0][1]
    if change >= 2:
        return "green"
    if change <= -2:
        return "red"
    return "grey"


def bucket_zone_seconds(zone_seconds):
    """Given an ordered list of seconds-per-zone (easiest to hardest), bucket
    into Low / Moderate / High using common Coggan-style zone groupings."""
    n = len(zone_seconds)
    if n == 0:
        return 0, 0, 0
    if n == 3:
        low, mod, high = zone_seconds[0], zone_seconds[1], zone_seconds[2]
    elif n in (5, 6):
        low = sum(zone_seconds[0:2])
        mod = zone_seconds[2] if n == 5 else sum(zone_seconds[2:4])
        high = sum(zone_seconds[3:]) if n == 5 else sum(zone_seconds[4:])
    elif n == 7:
        low = sum(zone_seconds[0:2])
        mod = sum(zone_seconds[2:4])
        high = sum(zone_seconds[4:])
    else:
        third = max(1, n // 3)
        low = sum(zone_seconds[0:third])
        mod = sum(zone_seconds[third:2 * third])
        high = sum(zone_seconds[2 * third:])
    return low, mod, high


def compute_season_stats(season_activities):
    total_secs = 0
    low_secs = mod_secs = high_secs = 0
    total_load = 0

    for a in season_activities:
        total_secs += a.get("moving_time") or a.get("elapsed_time") or 0
        total_load += a.get("icu_training_load") or 0
        zt = a.get("icu_zone_times")
        if zt:
            secs_list = [z.get("secs", 0) for z in zt]
            low, mod, high = bucket_zone_seconds(secs_list)
            low_secs += low
            mod_secs += mod
            high_secs += high

    zone_total = low_secs + mod_secs + high_secs
    if zone_total > 0:
        low_pct = round(100 * low_secs / zone_total)
        mod_pct = round(100 * mod_secs / zone_total)
        high_pct = round(100 * high_secs / zone_total)
    else:
        low_pct = mod_pct = high_pct = None

    return {
        "season_hours": round(total_secs / 3600, 1),
        "season_total_load": round(total_load),
        "zone_low_pct": low_pct if low_pct is not None else "n/a",
        "zone_mod_pct": mod_pct if mod_pct is not None else "n/a",
        "zone_high_pct": high_pct if high_pct is not None else "n/a",
    }


# ---------------------------------------------------------------------------
# PRODUCT V4.8 · Training Direction Engine
# ---------------------------------------------------------------------------
# The three-zone labels below are a THE LAB field model built from Intervals.icu
# power-zone time plus completed-session families. They are deliberately broad
# and are not presented as laboratory LT1/LT2 classification. The ordering rules
# mirror common TID language (pyramidal: low > moderate > high; polarized: low >
# high > moderate), while the target centres are transparent coaching heuristics
# used only to compute an internal adherence score.
