def _td_activity_day(activity):
    raw = str((activity or {}).get("start_date_local") or (activity or {}).get("start_date") or "")[:10]
    try:
        return date.fromisoformat(raw)
    except Exception:
        return None


def _td_family_bin(family):
    family = str(family or "")
    if family in {"Recovery", "Endurance / Z2"}:
        return "low"
    if family in {"Tempo", "Sweet Spot", "TTE", "Threshold", "Over-Under", "Tempo / Threshold Mixed"}:
        return "moderate"
    if family in {"VO2max", "Sprint / Neuromuscular", "High Intensity / Mixed"}:
        return "high"
    return None


def _td_distribution_stats(activities):
    low_secs = mod_secs = high_secs = 0.0
    zone_sessions = 0
    session_bins = {"low": 0, "moderate": 0, "high": 0}
    family_counts = {}
    usable_sessions = 0
    for activity in activities or []:
        family = classify_training_family(activity)
        family_counts[family] = family_counts.get(family, 0) + 1
        b = _td_family_bin(family)
        if b:
            session_bins[b] += 1
            usable_sessions += 1
        zt = activity.get("icu_zone_times") or []
        if zt:
            try:
                secs = [float(z.get("secs") or 0) for z in zt]
                low, mod, high = bucket_zone_seconds(secs)
                if (low + mod + high) > 0:
                    low_secs += low; mod_secs += mod; high_secs += high
                    zone_sessions += 1
            except (TypeError, ValueError):
                pass
    total = low_secs + mod_secs + high_secs
    zone_pct = None
    if total > 0:
        zone_pct = {
            "low": round(100.0 * low_secs / total, 1),
            "moderate": round(100.0 * mod_secs / total, 1),
            "high": round(100.0 * high_secs / total, 1),
        }
    sb_total = sum(session_bins.values())
    session_pct = None
    if sb_total:
        session_pct = {k: round(100.0 * v / sb_total, 1) for k, v in session_bins.items()}
    return {
        "zone_pct": zone_pct, "session_pct": session_pct,
        "zone_sessions": zone_sessions, "usable_sessions": usable_sessions,
        "family_counts": family_counts,
    }


def _td_classify_distribution(pct):
    if not pct:
        return "LEARNING"
    low = float(pct.get("low") or 0); mod = float(pct.get("moderate") or 0); high = float(pct.get("high") or 0)
    # Ordering is the primary classifier; minimum-share guards prevent a nearly
    # all-easy block from being mislabeled as polarized merely because 1% > 0%.
    if low >= 65 and high >= 5 and high >= mod + 2:
        return "POLARIZED"
    if low >= 58 and mod >= high + 2 and mod < 25:
        return "PYRAMIDAL"
    if mod >= 25 and mod >= high + 8:
        return "THRESHOLD"
    if low >= 68 and mod >= high + 2:
        return "PYRAMIDAL"
    return "MIXED"


def _td_alignment_score(pct, target):
    if not pct or target not in _TD_DISTRIBUTION_PROFILES:
        return None
    centre = _TD_DISTRIBUTION_PROFILES[target]
    moved_points = sum(abs(float(pct.get(k) or 0) - centre[k]) for k in ("low", "moderate", "high")) / 2.0
    score = max(0.0, 100.0 - 1.55 * moved_points)
    low = float(pct.get("low") or 0); mod = float(pct.get("moderate") or 0); high = float(pct.get("high") or 0)
    if target == "POLARIZED" and not (low > high > mod):
        score -= 10
    elif target == "PYRAMIDAL" and not (low > mod > high):
        score -= 10
    elif target == "THRESHOLD" and mod < 22:
        score -= 10
    return round(max(0.0, min(100.0, score)))


def _td_goal_score(activities, goal_key):
    cfg = _TD_GOALS.get(goal_key)
    if not cfg:
        return None, {"primary_count": 0, "hard_count": 0, "usable_sessions": 0}
    weighted = []
    primary_count = hard_count = 0
    for activity in activities or []:
        family = classify_training_family(activity)
        if family == "Other / Mixed":
            continue
        if family in cfg["primary"]:
            weight = 1.0; primary_count += 1
        elif family in cfg["support"]:
            weight = 0.72
        else:
            weight = 0.32
        if is_hard_training_family(family):
            hard_count += 1
        weighted.append(weight)
    if not weighted:
        return None, {"primary_count": 0, "hard_count": 0, "usable_sessions": 0}
    base = 100.0 * statistics.mean(weighted)
    minimum = int(cfg.get("anchor_min_14d") or 1)
    if primary_count == 0:
        base *= 0.58
    elif primary_count < minimum:
        base *= 0.82
    # Too many hard classifications in a 14-day window usually means specificity
    # is being purchased with fatigue. This is a small penalty, not a safety rule.
    if hard_count > 5:
        base -= min(15.0, (hard_count - 5) * 4.0)
    return round(max(0.0, min(100.0, base))), {
        "primary_count": primary_count, "hard_count": hard_count, "usable_sessions": len(weighted),
    }


def _td_score_label(score):
    if score is None:
        return "LEARNING", "learning"
    if score >= 85:
        return "STRONG ALIGNMENT", "strong"
    if score >= 70:
        return "GOOD ALIGNMENT", "good"
    if score >= 45:
        return "PARTIAL ALIGNMENT", "partial"
    return "LOW ALIGNMENT", "low"


def _td_distribution_correction(target, pct):
    if target == "AUTO" or not pct or target not in _TD_DISTRIBUTION_PROFILES:
        return None
    centre = _TD_DISTRIBUTION_PROFILES[target]
    deltas = {k: float(pct.get(k) or 0) - centre[k] for k in centre}
    excess = max(deltas, key=deltas.get)
    deficit = min(deltas, key=deltas.get)
    if deltas[excess] < 6 and deltas[deficit] > -6:
        return "The current intensity balance is already close to the selected distribution; preserve the pattern rather than chasing exact percentages."
    if excess == "moderate":
        return "Moderate/threshold time is the main drift. Reduce unplanned medium-hard accumulation before adding more quality."
    if excess == "high":
        return "High-intensity time is the main drift. Protect quality by reducing hard-session density and restoring low-intensity space."
    if deficit == "low":
        return "Low-intensity volume is under-represented. Rebuild the aerobic floor before increasing the density of quality work."
    if target == "POLARIZED" and deficit == "high":
        return "Low intensity is dominant, but the polarized high-intensity pole is under-represented. Add purposeful high-intensity work only when recovery permits."
    if target in {"PYRAMIDAL", "THRESHOLD"} and deficit == "moderate":
        return "The selected model calls for more controlled moderate/threshold work; add it deliberately rather than turning easy rides into accidental tempo."
    return "The current distribution is drifting from the selected model. Adjust the largest excess first instead of forcing every zone toward an exact percentage."


def _td_window_history(activities, start_day, end_day):
    window = [a for a in (activities or []) if (_td_activity_day(a) and start_day <= _td_activity_day(a) <= end_day)]
    stats = _td_distribution_stats(window)
    zone_model = _td_classify_distribution(stats.get("zone_pct"))
    session_model = _td_classify_distribution(stats.get("session_pct"))
    model = zone_model if zone_model not in {"LEARNING", "MIXED"} else session_model
    if model == "LEARNING":
        model = "MIXED" if stats.get("usable_sessions") else "LEARNING"
    return window, stats, model, zone_model, session_model


def _td_zone_text(pct):
    if not pct:
        return "n/a"
    return f"low {pct.get('low')}% · moderate {pct.get('moderate')}% · high {pct.get('high')}%"


def build_training_direction(season_activities, planning_context=None, plan=None, now=None):
    """Deterministic plan-vs-reality layer for both OWNER and athlete workspaces."""
    now = now or get_rome_now()
    today = now.date()
    planning_context = planning_context or {}
    if plan is None:
        try:
            plan = get_active_training_strategy_plan()
        except Exception:
            plan = None
    plan = dict(plan) if plan else None
    active = bool(plan)
    distribution_target = str((plan or {}).get("distribution_target") or "AUTO").upper()
    primary_goal = str((plan or {}).get("primary_goal") or "ENDURANCE_BASE").upper()
    if distribution_target not in TRAINING_DISTRIBUTION_KEYS:
        distribution_target = "AUTO"
    if primary_goal not in TRAINING_GOAL_KEYS:
        primary_goal = "ENDURANCE_BASE"
    goal_cfg = _TD_GOALS[primary_goal]

    plan_start = today
    if active:
        try:
            plan_start = date.fromisoformat(str(plan.get("started_on") or "")[:10])
        except Exception:
            plan_start = today
    # Historical context is deliberately separated from adherence. It describes
    # how the athlete trained before the declared plan but never scores or penalizes
    # the new block for sessions completed before ``started_on``.
    previous_end = plan_start - timedelta(days=1)
    previous_start = previous_end - timedelta(days=27)
    previous_window_days = 28
    previous_rows, previous_stats, previous_model, previous_zone_model, previous_session_model = _td_window_history(
        season_activities, previous_start, previous_end
    ) if active else ([], _td_distribution_stats([]), "LEARNING", "LEARNING", "LEARNING")
    if active and previous_stats.get("usable_sessions", 0) < 3:
        previous_start = previous_end - timedelta(days=41)
        previous_window_days = 42
        previous_rows, previous_stats, previous_model, previous_zone_model, previous_session_model = _td_window_history(
            season_activities, previous_start, previous_end
        )
    previous_available = bool(active and previous_stats.get("usable_sessions", 0) >= 3)

    assessment_start = max(plan_start, today - timedelta(days=TRAINING_STRATEGY_WINDOW_DAYS - 1)) if active else today - timedelta(days=27)
    assessed = [a for a in (season_activities or []) if (_td_activity_day(a) and assessment_start <= _td_activity_day(a) <= today)]
    stats = _td_distribution_stats(assessed)
    observed_zone = _td_classify_distribution(stats.get("zone_pct"))
    observed_session = _td_classify_distribution(stats.get("session_pct"))
    observed_model = observed_zone if observed_zone not in {"LEARNING", "MIXED"} else observed_session
    if observed_model == "LEARNING":
        observed_model = "MIXED" if stats.get("usable_sessions") else "LEARNING"

    time_score = _td_alignment_score(stats.get("zone_pct"), distribution_target) if distribution_target != "AUTO" else None
    session_score = _td_alignment_score(stats.get("session_pct"), distribution_target) if distribution_target != "AUTO" else None
    distribution_score = None
    available_scores = [(time_score, .75), (session_score, .25)]
    present = [(v, w) for v, w in available_scores if v is not None]
    if present:
        distribution_score = round(sum(v*w for v,w in present) / sum(w for _,w in present))

    recent14_start = max(assessment_start, today - timedelta(days=13))
    recent14 = [a for a in assessed if (_td_activity_day(a) and _td_activity_day(a) >= recent14_start)]
    goal_score, goal_meta = _td_goal_score(recent14, primary_goal)

    plan_age_days = max(0, (today - plan_start).days) if active else 0
    enough_data = active and stats.get("usable_sessions", 0) >= 3 and (stats.get("zone_sessions", 0) >= 2 or distribution_target == "AUTO")
    overall = None
    if enough_data:
        if distribution_target == "AUTO":
            overall = goal_score
        elif distribution_score is not None and goal_score is not None:
            overall = round(0.65 * distribution_score + 0.35 * goal_score)
        elif distribution_score is not None:
            overall = distribution_score
    label, score_class = _td_score_label(overall)

    if not active:
        headline = "Choose a training model and primary goal to let THE LAB measure plan adherence from that date forward."
    elif not enough_data:
        headline = f"THE LAB is learning this block. {stats.get('usable_sessions', 0)} usable session(s) have accumulated since {plan_start.strftime('%d/%m/%Y')}."
    elif distribution_target == "AUTO":
        headline = f"Goal alignment is {overall}%. Distribution is being monitored rather than enforced; current training reads as {observed_model}."
    elif observed_model == distribution_target:
        headline = f"You selected {distribution_target}; current training also reads as {observed_model}. Overall plan adherence is {overall}%."
    else:
        headline = f"You selected {distribution_target}, but current training reads as {observed_model}. Overall plan adherence is {overall}%."

    correction = _td_distribution_correction(distribution_target, stats.get("zone_pct"))
    health = planning_context.get("health_override")
    goal_missing = goal_meta.get("primary_count", 0) < int(goal_cfg.get("anchor_min_14d") or 1)
    if not active:
        micro = "Choose a training distribution and primary goal first. THE LAB will then assess only training completed from that declared start date forward."
    elif health:
        micro = "Current health/restriction context overrides strategy scoring. Keep the declared plan, but do not chase adherence until the restriction clears."
    elif not enough_data:
        micro = "Accumulate representative training first. THE LAB will begin scoring once enough post-selection sessions exist; do not manufacture intensity just to fill the meter."
    else:
        parts = []
        if correction:
            parts.append(correction)
        if goal_missing:
            parts.append(goal_cfg["micro"])
        elif not correction or (overall is not None and overall >= 70):
            parts.append(goal_cfg["micro"])
        micro = " ".join(parts[:2]) or goal_cfg["micro"]

    # A plan remains one declared block until the athlete changes it. The 28-day
    # number is the rolling adherence window, not an automatic four-week prescription.
    meso = goal_cfg["focus"] if active else "No mesocycle focus declared yet. Save a primary goal to activate strategy-aware coaching."
    if active:
        meso += f" · plan day {plan_age_days + 1} · adherence window {min(TRAINING_STRATEGY_WINDOW_DAYS, plan_age_days + 1)}d"

    if not active:
        journey_summary = "Choose a Training Direction to start a new block; historical training will then be shown separately from post-selection adherence."
    elif not previous_available:
        journey_summary = f"You chose {distribution_target if distribution_target != 'AUTO' else 'AUTO monitoring'} · {goal_cfg['label']} on {plan_start.strftime('%d/%m/%Y')}. There is not yet enough comparable pre-selection training inside the available Intervals window to label the previous block confidently."
    elif observed_model == "LEARNING":
        journey_summary = f"Before this decision THE LAB read your training as {previous_model}. You then chose {distribution_target if distribution_target != 'AUTO' else 'AUTO monitoring'} · {goal_cfg['label']}; the current block is still LEARNING and only post-selection sessions will count toward adherence."
    else:
        journey_summary = f"Before this decision THE LAB read {previous_model}; you chose {distribution_target if distribution_target != 'AUTO' else 'AUTO monitoring'} · {goal_cfg['label']}; the current block now reads {observed_model}. Pre-selection training is context only and never changes the adherence score."

    distribution_options = [
        {"key": key, "label": label, "description": description}
        for key, label, description in TRAINING_DISTRIBUTION_OPTIONS
    ]
    goal_options = [
        {"key": key, "emoji": emoji, "label": label}
        for key, emoji, label in TRAINING_GOAL_OPTIONS
    ]
    return {
        "active": active,
        "plan_id": (plan or {}).get("id"),
        "started_on": (plan or {}).get("started_on"),
        "started_on_display": (plan_start.strftime("%d/%m/%Y") if active else "—"),
        "distribution_target": distribution_target,
        "form_distribution_target": distribution_target,
        "distribution_label": (("AUTO · MONITOR" if distribution_target == "AUTO" else distribution_target) if active else "NOT SET"),
        "primary_goal": primary_goal,
        "form_primary_goal": primary_goal,
        "goal_label": (goal_cfg["label"] if active else "CHOOSE GOAL"), "goal_emoji": (goal_cfg["emoji"] if active else "🎯"),
        "observed_model": observed_model,
        "observed_zone_model": observed_zone,
        "observed_session_model": observed_session,
        "zone_pct": stats.get("zone_pct"), "session_pct": stats.get("session_pct"),
        "assessed_sessions": stats.get("usable_sessions", 0), "zone_sessions": stats.get("zone_sessions", 0),
        "assessment_start": assessment_start.isoformat(), "assessment_start_display": assessment_start.strftime("%d/%m/%Y"),
        "distribution_score": distribution_score, "goal_score": goal_score, "adherence_score": overall,
        "adherence_label": label, "adherence_class": score_class,
        "headline": headline,
        "mesocycle_focus": meso,
        "microcycle_direction": micro,
        "primary_sessions_14d": goal_meta.get("primary_count", 0),
        "hard_sessions_14d": goal_meta.get("hard_count", 0),
        "distribution_options": distribution_options, "goal_options": goal_options,
        "previous_available": previous_available,
        "previous_model": previous_model if previous_available else "LEARNING",
        "previous_zone_model": previous_zone_model if previous_available else "LEARNING",
        "previous_session_model": previous_session_model if previous_available else "LEARNING",
        "previous_zone_pct": previous_stats.get("zone_pct") if previous_available else None,
        "previous_sessions": previous_stats.get("usable_sessions", 0),
        "previous_window_days": previous_window_days,
        "previous_start_display": previous_start.strftime("%d/%m/%Y") if active else "—",
        "previous_end_display": previous_end.strftime("%d/%m/%Y") if active else "—",
        "journey_summary": journey_summary,
        "method_note": "THE LAB field model · Intervals.icu power-zone time + completed-session families. The pre-selection block is historical context only; adherence starts at the declared plan date. Adherence is a coaching index, not a physiological or clinical score; exact percentages are not treated as universal prescriptions.",
    }


def training_direction_text(direction):
    d = direction or {}
    if not d:
        return "TRAINING DIRECTION: unavailable"
    zone = d.get("zone_pct") or {}
    zone_text = "n/a" if not zone else f"low {zone.get('low')}% | moderate {zone.get('moderate')}% | high {zone.get('high')}%"
    return "\n".join([
        "TRAINING DIRECTION (deterministic Python; athlete-declared intent + observed execution):",
        f"- Active declared plan: {'YES' if d.get('active') else 'NO'} | model {d.get('distribution_label')} | primary goal {d.get('goal_label')} | started {d.get('started_on_display')}",
        f"- Previous block: {d.get('previous_model') if d.get('previous_available') else 'INSUFFICIENT DATA'} | {_td_zone_text(d.get('previous_zone_pct'))} | {d.get('previous_start_display')} → {d.get('previous_end_display')}",
        f"- Decision → now: {d.get('distribution_label')} + {d.get('goal_label')} → observed {d.get('observed_model')} | time-in-zone {zone_text} | sessions assessed {d.get('assessed_sessions')}",
        f"- Adherence: {d.get('adherence_score') if d.get('adherence_score') is not None else 'LEARNING'} | distribution {d.get('distribution_score') if d.get('distribution_score') is not None else 'n/a'} | goal stimulus {d.get('goal_score') if d.get('goal_score') is not None else 'n/a'}",
        f"- Mesocycle focus: {d.get('mesocycle_focus')}",
        f"- Next microcycle direction: {d.get('microcycle_direction')}",
        "- Strategy is subordinate to illness/injury restrictions, race proximity, recovery and explicit Calendar commitments. Do not chase percentages when those higher-priority constraints say otherwise.",
    ])


# PRODUCT V4.8.19 · Intervals wellness provenance. Intervals can carry forward
# weight/restingHR onto later wellness rows and marks those values with tempWeight /
# tempRestingHR. Carried-forward rows are context, never new physiological observations.
def _intervals_temp_flag(row, field):
    value = (row or {}).get(field)
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    if isinstance(value, (int, float)):
        return value != 0
    return str(value).strip().lower() in {"1", "true", "yes", "y", "t"}


def _wellness_value_rows(wellness, field, temp_field=None):
    rows = []
    for w in sorted(wellness or [], key=lambda x: x.get("id", "")):
        value = w.get(field)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            continue
        value_f = float(value)
        if not math.isfinite(value_f):
            continue
        ds = str(w.get("id") or "")[:10]
        try:
            day = date.fromisoformat(ds)
        except ValueError:
            continue
        rows.append({
            "date": day, "value": value,
            "temporary": bool(temp_field and _intervals_temp_flag(w, temp_field)),
            "row": w,
        })
    return rows


def _latest_wellness_observation(wellness, field, temp_field=None):
    rows = _wellness_value_rows(wellness, field, temp_field)
    if not rows:
        return {"value": None, "date": None, "temporary_only": False, "carried_forward": False, "latest_row_date": None}
    genuine = [r for r in rows if not r["temporary"]]
    latest_any = rows[-1]
    if not genuine:
        return {
            "value": latest_any["value"], "date": None, "temporary_only": True,
            "carried_forward": True, "latest_row_date": latest_any["date"],
        }
    latest = genuine[-1]
    carried = bool(latest_any["date"] > latest["date"] and latest_any["temporary"])
    return {
        "value": latest["value"], "date": latest["date"], "temporary_only": False,
        "carried_forward": carried, "latest_row_date": latest_any["date"],
    }


def _latest_weight_provenance(wellness):
    """Return a conservative provenance view of the latest Intervals weight.

    Intervals ``tempWeight`` identifies some carried-forward rows, but an upstream
    integration may also rewrite the same weight onto a newer non-temporary row.
    Therefore a non-temporary row is not treated as proof of a new physical weigh-in.

    For the currently displayed one-decimal weight, walk backwards through weight-
    bearing Wellness rows and find the start of the terminal same-value block.  The
    resulting date means only ``unchanged in Intervals since at least`` that day.
    It is deliberately conservative: a real later weigh-in that happens to return
    exactly the same one-decimal value cannot be distinguished from a sync rewrite.
    """
    rows = _wellness_value_rows(wellness, "weight", "tempWeight")
    if not rows:
        return {
            "value": None, "date": None, "latest_row_date": None,
            "unchanged_since": None, "same_value_rows": 0,
            "latest_row_temporary": False, "carried_forward": False,
        }

    latest = rows[-1]
    latest_display = round(float(latest["value"]), 1)
    block = [latest]
    for row in reversed(rows[:-1]):
        if round(float(row["value"]), 1) != latest_display:
            break
        block.append(row)
    block.reverse()

    unchanged_since = block[0]["date"]
    latest_row_date = latest["date"]
    latest_row_temporary = bool(latest.get("temporary"))
    return {
        "value": latest["value"],
        "date": unchanged_since,
        "unchanged_since": unchanged_since,
        "latest_row_date": latest_row_date,
        "same_value_rows": len(block),
        "latest_row_temporary": latest_row_temporary,
        "carried_forward": bool(latest_row_temporary or len(block) > 1),
    }


def _weight_observation_note(observation, now=None):
    """Describe Intervals weight without claiming freshness from an unverified row date."""
    observation = observation or {}
    value = _nutrition_number(observation.get("value"))
    if value is None:
        return None
    day = observation.get("unchanged_since") or observation.get("date")
    if isinstance(day, date):
        return f"Intervals shows {value:.1f} kg since at least {day.strftime('%d %b')} in the available data · physical weigh-in date unverified"
    return f"Intervals shows {value:.1f} kg · physical weigh-in date unverified"

def _wellness_observation_note(observation, now=None):
    observation = observation or {}
    if observation.get("value") is None:
        return None
    if observation.get("temporary_only"):
        return "Intervals carried this value forward · original capture date unavailable"
    day = observation.get("date")
    if not isinstance(day, date):
        return None
    now = now or get_rome_now()
    age = max(0, (now.date() - day).days)
    if observation.get("carried_forward"):
        return f"Captured {day.strftime('%d %b')} · {age}d ago · carried forward by Intervals"
    if age > 0:
        return f"Captured {day.strftime('%d %b')} · {age}d ago"
    return None


def last_two_values(wellness, field, temp_field=None):
    rows = _wellness_value_rows(wellness, field, temp_field)
    if temp_field:
        rows = [r for r in rows if not r["temporary"]]
    vals = [r["value"] for r in rows]
    if len(vals) < 2:
        return None, None
    return vals[-1], vals[-2]


def trend_arrow(current, previous, higher_is_better):
    """higher_is_better: True/False for a directional judgement, or None for
    a neutral metric where up/down isn't inherently good or bad."""
    if current is None or previous is None or current == previous:
        return None
    up = current > previous
    arrow = "▲" if up else "▼"
    if higher_is_better is None:
        color = "grey"
    else:
        good = up if higher_is_better else not up
        color = "green" if good else "red"
    return {"arrow": arrow, "color": color}


def _recent_numeric(wellness, field, days=RECENT_BASELINE_DAYS, exclude_latest=True, divisor=1.0, temp_field=None):
    """Numeric recent values for trend context; optional Intervals temp rows are excluded."""
    rows = _wellness_value_rows(wellness, field, temp_field)
    if temp_field:
        rows = [r for r in rows if not r["temporary"]]
    if exclude_latest and rows:
        rows = rows[:-1]
    return [r["value"] / divisor for r in rows[-days:]]


def _fmt_hours(hours):
    if not isinstance(hours, (int, float)):
        return "n/a"
    total = max(0, round(hours * 60))
    return f"{total // 60}h {total % 60:02d}m"


def _fmt_number(value, decimals=0, suffix=""):
    if not isinstance(value, (int, float)):
        return "n/a"
    rendered = f"{value:.{decimals}f}" if decimals else str(round(value))
    return f"{rendered}{suffix}"



def _median_minutes(values):
    vals = [float(v) for v in values if isinstance(v, (int, float)) and 180 <= float(v) <= 720]
    return statistics.median(vals) if vals else None


def _sleep_iqr_label(values):
    vals = sorted(float(v) for v in values if isinstance(v, (int, float)) and 180 <= float(v) <= 720)
    if len(vals) < 4:
        return None
    q1, _, q3 = statistics.quantiles(vals, n=4, method="inclusive")
    return f"{_fmt_hours(q1 / 60.0)}–{_fmt_hours(q3 / 60.0)}"


def build_adaptive_sleep_baseline(wellness, lookback_days=SLEEP_BASELINE_DAYS):
    """Learn the athlete's realistic sleep opportunity from their own history.

    Weekdays and weekends are separated because work/life constraints can make
    the attainable sleep opportunity structurally different. Garmin's 7h38m
    reference is retained as a reference only; the daily recovery penalty is
    driven by the matching habitual baseline instead of an aspirational target.
    """
    rows = []
    for w in sorted(wellness or [], key=lambda x: str(x.get("id") or "")):
        raw_day = str(w.get("id") or "")[:10]
        secs = w.get("sleepSecs")
        if not isinstance(secs, (int, float)) or not raw_day:
            continue
        try:
            d = date.fromisoformat(raw_day)
        except Exception:
            continue
        minutes = float(secs) / 60.0
        if not 180 <= minutes <= 720:
            continue
        rows.append({"date": d, "minutes": minutes, "kind": "WEEKDAY" if d.weekday() < 5 else "WEEKEND"})

    manual_sleep_reference = GARMIN_BASELINES.get("sleep_minutes")
    reference_label = (_fmt_hours(float(manual_sleep_reference) / 60.0) + " manual reference") if isinstance(manual_sleep_reference, (int, float)) else "No manual sleep reference"
    if not rows:
        return {
            "available": False, "days": lookback_days, "kind": "UNKNOWN",
            "current_minutes": None, "habitual_minutes": None, "current_delta_min": None,
            "weekday_minutes": None, "weekend_minutes": None, "overall_minutes": None,
            "weekday_label": "n/a", "weekend_label": "n/a", "overall_label": "n/a",
            "weekday_iqr": None, "weekend_iqr": None, "status": "NO DATA", "color": "grey", "pct": 0,
            "reference_minutes": manual_sleep_reference, "reference_label": reference_label,
            "reference_delta_min": None, "sample_count": 0, "weekday_samples": 0, "weekend_samples": 0,
            "trend_label": "NO TREND", "trend_delta_min": None,
        }

    current = rows[-1]
    cutoff = current["date"] - timedelta(days=lookback_days)
    baseline_rows = [r for r in rows[:-1] if r["date"] >= cutoff]
    if not baseline_rows:
        baseline_rows = rows[:-1]

    weekday = [r["minutes"] for r in baseline_rows if r["kind"] == "WEEKDAY"]
    weekend = [r["minutes"] for r in baseline_rows if r["kind"] == "WEEKEND"]
    overall = [r["minutes"] for r in baseline_rows]
    overall_median = _median_minutes(overall)
    weekday_median = _median_minutes(weekday) if len(weekday) >= 5 else overall_median
    weekend_median = _median_minutes(weekend) if len(weekend) >= 2 else overall_median
    habitual = weekday_median if current["kind"] == "WEEKDAY" else weekend_median
    delta = current["minutes"] - habitual if habitual is not None else None

    if delta is None:
        status, color, pct = "INSUFFICIENT DATA", "grey", 0
    else:
        # A modest night-to-night swing is normal. Only meaningful deviation
        # from the athlete's own opportunity baseline earns a penalty.
        if delta >= -20:
            status, color = "WITHIN HABITUAL", "green"
        elif delta >= -45:
            status, color = "SLIGHTLY SHORT", "grey"
        elif delta >= -75:
            status, color = "SHORT VS HABITUAL", "orange"
        else:
            status, color = "WELL BELOW HABITUAL", "red"
        pct = max(10, min(100, round(current["minutes"] / habitual * 100))) if habitual else 0

    # Short rolling trend, deliberately separate from the weekday/weekend baseline.
    prior_values = [r["minutes"] for r in rows[:-1]][-28:]
    recent14 = prior_values[-14:]
    prior14 = prior_values[-28:-14]
    trend_delta = None
    trend_label = "NO TREND"
    if len(recent14) >= 5 and len(prior14) >= 5:
        trend_delta = round(statistics.mean(recent14) - statistics.mean(prior14))
        if trend_delta >= 15:
            trend_label = "LONGER"
        elif trend_delta <= -15:
            trend_label = "SHORTER"
        else:
            trend_label = "STABLE"

    ref_delta = round(current["minutes"] - manual_sleep_reference) if isinstance(manual_sleep_reference, (int, float)) else None
    return {
        "available": habitual is not None,
        "days": lookback_days,
        "kind": current["kind"],
        "current_minutes": round(current["minutes"]),
        "habitual_minutes": round(habitual) if habitual is not None else None,
        "current_delta_min": round(delta) if delta is not None else None,
        "weekday_minutes": round(weekday_median) if weekday_median is not None else None,
        "weekend_minutes": round(weekend_median) if weekend_median is not None else None,
        "overall_minutes": round(overall_median) if overall_median is not None else None,
        "weekday_label": _fmt_hours(weekday_median / 60.0) if weekday_median is not None else "n/a",
        "weekend_label": _fmt_hours(weekend_median / 60.0) if weekend_median is not None else "n/a",
        "overall_label": _fmt_hours(overall_median / 60.0) if overall_median is not None else "n/a",
        "weekday_iqr": _sleep_iqr_label(weekday),
        "weekend_iqr": _sleep_iqr_label(weekend),
        "habitual_label": _fmt_hours(habitual / 60.0) if habitual is not None else "n/a",
        "status": status, "color": color, "pct": pct,
        "reference_minutes": manual_sleep_reference, "reference_label": reference_label,
        "reference_delta_min": ref_delta,
        "sample_count": len(baseline_rows), "weekday_samples": len(weekday), "weekend_samples": len(weekend),
        "trend_label": trend_label, "trend_delta_min": trend_delta,
    }


def _range_signal(value, low, high, kind="neutral"):
    """Status versus a mature personal range; missing reference stays in Learning."""
    if not isinstance(value, (int, float)):
        return {"color": "grey", "status": "No current data", "pct": 0}
    if not isinstance(low, (int, float)) or not isinstance(high, (int, float)) or high < low:
        return {"color": "grey", "status": "Learning baseline", "pct": 0}
    width = max(high - low, 1)
    if low <= value <= high:
        return {"color": "green", "status": "Within baseline", "pct": 100}
    if value < low:
        distance = low - value
        pct = max(10, round(100 - (distance / width) * 75))
        if kind == "hrv":
            color = "red" if distance > width * 0.25 else "grey"
            status = "Below baseline"
        elif kind == "heart_rate":
            color = "grey" if distance <= 3 else "red"
            status = "Below baseline"
        else:
            color, status = "grey", "Below baseline"
        return {"color": color, "status": status, "pct": pct}
    distance = value - high
    pct = max(10, round(100 - (distance / width) * 75))
    if kind == "hrv":
        color = "green" if distance <= width * 0.25 else "grey"
        status = "Above baseline"
    elif kind == "heart_rate":
        color = "red" if distance > 2 else "grey"
        status = "Above baseline"
    else:
        color, status = "grey", "Above baseline"
    return {"color": color, "status": status, "pct": pct}


def _target_signal(value, target, metric):
    if not isinstance(value, (int, float)):
        return {"color": "grey", "status": "No current data", "pct": 0}
    if not isinstance(target, (int, float)):
        return {"color": "grey", "status": "Learning baseline", "pct": 0}
    if metric == "sleep_minutes":
        diff = value - target
        pct = max(10, min(100, round(value / target * 100))) if target else 0
        if diff >= -30:
            return {"color": "green", "status": "On target", "pct": pct}
        if diff >= -75:
            return {"color": "grey", "status": "Below target", "pct": pct}
        return {"color": "red", "status": "Short sleep", "pct": pct}
    if metric == "sleep_score":
        pct = max(10, min(100, round(value)))
        if value >= target - 3:
            return {"color": "green", "status": "Near baseline", "pct": pct}
        if value >= target - 10:
            return {"color": "grey", "status": "Below baseline", "pct": pct}
        return {"color": "red", "status": "Low vs baseline", "pct": pct}
    if metric == "spo2":
        pct = max(10, min(100, round(value)))
        if value >= target - 1:
            return {"color": "green", "status": "Near baseline", "pct": pct}
        if value >= target - 2:
            return {"color": "grey", "status": "Below baseline", "pct": pct}
        return {"color": "red", "status": "Low vs baseline", "pct": pct}
    return {"color": "grey", "status": "Reference", "pct": 0}


def _robust_dynamic_range(values, min_samples=7):
    vals = sorted(float(v) for v in values if isinstance(v, (int, float)) and math.isfinite(float(v)))
    if len(vals) < min_samples:
        return None
    q1, med, q3 = statistics.quantiles(vals, n=4, method="inclusive")
    if q3 <= q1:
        spread = max(abs(med) * 0.02, 1.0)
        q1, q3 = med - spread, med + spread
    return float(q1), float(q3)


def _robust_dynamic_target(values, min_samples=7):
    vals = [float(v) for v in values if isinstance(v, (int, float)) and math.isfinite(float(v))]
    return float(statistics.median(vals)) if len(vals) >= min_samples else None


def _reference_range(manual_low, manual_high, history_values):
    if isinstance(manual_low, (int, float)) and isinstance(manual_high, (int, float)) and manual_high >= manual_low:
        return float(manual_low), float(manual_high), "MANUAL REFERENCE"
    learned = _robust_dynamic_range(history_values)
    if learned:
        return learned[0], learned[1], "DYNAMIC BASELINE"
    return None, None, "LEARNING"


def _reference_target(manual_target, history_values):
    if isinstance(manual_target, (int, float)):
        return float(manual_target), "MANUAL REFERENCE"
    learned = _robust_dynamic_target(history_values)
    return (learned, "DYNAMIC BASELINE") if learned is not None else (None, "LEARNING")


def _range_label(source, low, high, unit=""):
    if low is None or high is None:
        return "Learning · data needed"
    precision = 1 if any(abs(v - round(v)) > 1e-6 for v in (low, high)) else 0
    return f"{source.title()} · {low:.{precision}f}–{high:.{precision}f}{unit}"


def _target_label(source, target, unit=""):
    if target is None:
        return "Learning · data needed"
    precision = 1 if abs(target - round(target)) > 1e-6 else 0
    return f"{source.title()} · {target:.{precision}f}{unit}"


def compute_personal_baselines(wellness):
    """Resolve manual references first, then learn robust athlete-specific ranges.

    Product athletes never inherit OWNER Garmin values. If a manual reference is
    missing, >=7 historical observations can mature into a dynamic baseline;
    otherwise the metric remains visibly in LEARNING and has no hard influence.
    """
    ordered = sorted(wellness or [], key=lambda x: x.get("id", ""))
    latest = ordered[-1] if ordered else {}
    history = ordered[:-1] if len(ordered) > 1 else []

    hrv_recent = _recent_numeric(wellness, "hrv")
    rhr_recent = _recent_numeric(wellness, "restingHR", temp_field="tempRestingHR")
    score_recent = _recent_numeric(wellness, "sleepScore")
    spo2_recent = _recent_numeric(wellness, "spO2")
    sleeping_hr_recent = _recent_numeric(wellness, "avgSleepingHR")

    hrv_hist = [w.get("hrv") for w in history]
    rhr_rows = [r for r in _wellness_value_rows(wellness, "restingHR", "tempRestingHR") if not r["temporary"]]
    rhr_hist = [r["value"] for r in rhr_rows[:-1]] if rhr_rows else []
    score_hist = [w.get("sleepScore") for w in history]
    spo2_hist = [w.get("spO2") for w in history]

    rhr_low, rhr_high, rhr_source = _reference_range(
        GARMIN_BASELINES.get("resting_hr_low"), GARMIN_BASELINES.get("resting_hr_high"), rhr_hist
    )
    hrv_low, hrv_high, hrv_source = _reference_range(
        GARMIN_BASELINES.get("hrv_low"), GARMIN_BASELINES.get("hrv_high"), hrv_hist
    )
    score_target, score_source = _reference_target(GARMIN_BASELINES.get("sleep_score"), score_hist)
    spo2_target, spo2_source = _reference_target(GARMIN_BASELINES.get("spo2"), spo2_hist)

    current_rhr = rhr_rows[-1]["value"] if rhr_rows else None
    current_hrv = latest.get("hrv")
    current_score = latest.get("sleepScore")
    current_sleeping_hr = latest.get("avgSleepingHR")
    spo2_entries = [w for w in ordered if isinstance(w.get("spO2"), (int, float))]
    current_spo2 = spo2_entries[-1].get("spO2") if spo2_entries else None

    rhr_signal = _range_signal(current_rhr, rhr_low, rhr_high, "heart_rate")
    hrv_signal = _range_signal(current_hrv, hrv_low, hrv_high, "hrv")
    adaptive_sleep = build_adaptive_sleep_baseline(wellness)
    sleep_signal = {
        "color": adaptive_sleep.get("color", "grey"),
        "status": adaptive_sleep.get("status", "No current data"),
        "pct": adaptive_sleep.get("pct", 0),
    }
    score_signal = _target_signal(current_score, score_target, "sleep_score")
    spo2_signal = _target_signal(current_spo2, spo2_target, "spo2")
    sleeping_hr_signal = _range_signal(current_sleeping_hr, rhr_low, rhr_high, "heart_rate")

    manual_sleep = GARMIN_BASELINES.get("sleep_minutes")
    sleep_reference = (_fmt_hours(float(manual_sleep) / 60.0) + " manual reference") if isinstance(manual_sleep, (int, float)) else "Adaptive habitual baseline"
    sleeping_resp = GARMIN_BASELINES.get("sleeping_respiration")
    awake_low = GARMIN_BASELINES.get("awake_respiration_low")
    awake_high = GARMIN_BASELINES.get("awake_respiration_high")

    source_label = "Athlete manual references + dynamic baselines" if _runtime_is_athlete() else BASELINE_SOURCE
    return {
        "source": source_label,
        "days": RECENT_BASELINE_DAYS,
        "rhr": {**rhr_signal, "garmin": _range_label(rhr_source, rhr_low, rhr_high, " bpm"), "recent": _fmt_number(statistics.median(rhr_recent), 0, " bpm") if rhr_recent else "n/a", "reference_source": rhr_source},
        "hrv": {**hrv_signal, "garmin": _range_label(hrv_source, hrv_low, hrv_high, " ms"), "recent": _fmt_number(statistics.median(hrv_recent), 0, " ms") if hrv_recent else "n/a", "reference_source": hrv_source},
        "sleep": {
            **sleep_signal,
            "garmin": sleep_reference,
            "recent": f"{adaptive_sleep.get('kind', 'habitual').title()} habitual {adaptive_sleep.get('habitual_label', 'n/a')}",
            "habitual_minutes": adaptive_sleep.get("habitual_minutes"),
            "habitual_label": adaptive_sleep.get("habitual_label"),
            "current_delta_min": adaptive_sleep.get("current_delta_min"),
            "adaptive": adaptive_sleep,
        },
        "sleep_score": {**score_signal, "garmin": _target_label(score_source, score_target), "recent": _fmt_number(statistics.mean(score_recent), 0) if score_recent else "n/a", "reference_source": score_source},
        "spo2": {**spo2_signal, "garmin": _target_label(spo2_source, spo2_target, "%"), "recent": _fmt_number(statistics.median(spo2_recent), 1, "%") if spo2_recent else "n/a", "reference_source": spo2_source},
        "sleeping_hr": {**sleeping_hr_signal, "garmin": _range_label(rhr_source, rhr_low, rhr_high, " bpm"), "recent": _fmt_number(statistics.median(sleeping_hr_recent), 0, " bpm") if sleeping_hr_recent else "n/a"},
        "sleeping_respiration": {"garmin": _target_label("MANUAL REFERENCE" if isinstance(sleeping_resp, (int, float)) else "LEARNING", sleeping_resp, " brpm"), "recent": "not synced", "color": "grey", "status": "Manual reference only" if isinstance(sleeping_resp, (int, float)) else "Learning · data needed", "pct": 0},
        "awake_respiration": {"garmin": _range_label("MANUAL REFERENCE" if isinstance(awake_low, (int, float)) and isinstance(awake_high, (int, float)) else "LEARNING", awake_low, awake_high, " brpm"), "recent": "not synced", "color": "grey", "status": "Manual reference only" if isinstance(awake_low, (int, float)) and isinstance(awake_high, (int, float)) else "Learning · data needed", "pct": 0},
        "adaptive_sleep": adaptive_sleep,
        "resolved": {"hrv_low": hrv_low, "hrv_high": hrv_high, "rhr_low": rhr_low, "rhr_high": rhr_high, "sleep_score": score_target, "spo2": spo2_target},
    }

def compute_health_rings(metrics):
    """Small rings now show closeness to the athlete's Garmin baseline, while arrows still show day-to-day direction."""
    pb = metrics.get("personal_baselines") or {}
    rings = {}
    for key in ("rhr", "hrv", "sleep"):
        item = pb.get(key)
        if item:
            rings[key] = {"pct": item.get("pct", 0), "color": item.get("color", "grey"), "status": item.get("status", "Reference")}
    return rings

def compute_trend_arrows(wellness):
    rhr_latest, rhr_prev = last_two_values(wellness, "restingHR", temp_field="tempRestingHR")
    hrv_latest, hrv_prev = last_two_values(wellness, "hrv")
    sleep_latest, sleep_prev = last_two_values(wellness, "sleepSecs")
    weight_latest, weight_prev = last_two_values(wellness, "weight", temp_field="tempWeight")
    return {
        "rhr": trend_arrow(rhr_latest, rhr_prev, higher_is_better=False),
        "hrv": trend_arrow(hrv_latest, hrv_prev, higher_is_better=True),
        "sleep": trend_arrow(sleep_latest, sleep_prev, higher_is_better=True),
        "weight": trend_arrow(weight_latest, weight_prev, higher_is_better=None),
    }


def compute_recent_trend(wellness, n=5, form_thresholds=None, form_median=None):
    """Daily Form (TSB) for the last n days that have both CTL and ATL, for a
    quick at-a-glance trend next to the Energy Bank. Shown primarily as a
    delta from the athlete's own typical TSB, not the raw absolute number -
    for someone who trains at chronic high load, the raw number is nearly
    always a scary-looking double-digit negative even on a completely
    ordinary day."""
    daily = []
    for w in sorted(wellness, key=lambda x: x.get("id", "")):
        ctl, atl = w.get("ctl"), w.get("atl")
        if ctl is None or atl is None:
            continue
        tsb = round(ctl - atl, 1)
        try:
            weekday = date.fromisoformat(w["id"]).strftime("%a")
        except (ValueError, KeyError):
            weekday = w.get("id", "")[-2:]
        delta = round(tsb - form_median, 1) if form_median is not None else None
        daily.append({
            "date": w.get("id", ""), "weekday": weekday, "tsb": tsb, "delta": delta,
            "zone": classify_form(tsb, form_thresholds),
        })
    return daily[-n:]


def _energy_training_day_context(today_load, today_minutes, training_rhythm=None):
    """Compare today's accumulated work with the athlete's learned training-day norm.

    This is context, not a discount on physiology: load and duration always spend
    reserve. The learned baseline only decides whether today's accumulated work is
    ordinary or unusually large for this athlete. Number of files/sessions alone
    never carries a penalty.
    """
    rhythm = training_rhythm or {}
    typical_load = _rhythm_num(rhythm.get("typical_training_day_load"))
    q25_load = _rhythm_num(rhythm.get("training_day_load_q25"))
    q75_load = _rhythm_num(rhythm.get("training_day_load_q75"))
    typical_minutes = _rhythm_num(rhythm.get("typical_training_day_minutes"))
    q25_minutes = _rhythm_num(rhythm.get("training_day_minutes_q25"))
    q75_minutes = _rhythm_num(rhythm.get("training_day_minutes_q75"))
    load_samples = int(rhythm.get("training_day_load_samples") or 0)
    duration_samples = int(rhythm.get("training_day_duration_samples") or 0)
    learned = (
        str(rhythm.get("state") or "LEARNING") != "LEARNING"
        and (load_samples >= 3 or duration_samples >= 3)
        and (typical_load is not None or typical_minutes is not None)
    )

    if today_load <= 0 and today_minutes <= 0:
        return {
            "label": "NO TRAINING YET", "class": "grey", "learned": learned,
            "extra_cost": 0.0, "load_ratio": None, "duration_ratio": None,
            "typical_load": typical_load, "typical_minutes": typical_minutes,
        }
    if not learned:
        return {
            "label": "BASELINE LEARNING", "class": "grey", "learned": False,
            "extra_cost": 0.0,
            "load_ratio": round(today_load / typical_load, 2) if typical_load and today_load > 0 else None,
            "duration_ratio": round(today_minutes / typical_minutes, 2) if typical_minutes and today_minutes > 0 else None,
            "typical_load": typical_load, "typical_minutes": typical_minutes,
        }

    load_ratio = today_load / typical_load if typical_load and typical_load > 0 else None
    duration_ratio = today_minutes / typical_minutes if typical_minutes and typical_minutes > 0 else None
    ratios = [r for r in (load_ratio, duration_ratio) if r is not None]
    max_ratio = max(ratios) if ratios else 1.0

    light_load = q25_load is not None and today_load <= q25_load
    light_duration = q25_minutes is not None and today_minutes <= q25_minutes
    above_load = q75_load is not None and today_load > q75_load
    above_duration = q75_minutes is not None and today_minutes > q75_minutes

    if max_ratio >= 1.55 or (above_load and above_duration and max_ratio >= 1.30):
        label, css = "HIGH VS YOUR NORM", "orange"
    elif above_load or above_duration or max_ratio >= 1.20:
        label, css = "ABOVE YOUR NORM", "orange"
    elif (light_load or q25_load is None) and (light_duration or q25_minutes is None) and max_ratio <= 0.75:
        label, css = "LIGHT VS YOUR NORM", "green"
    else:
        label, css = "TYPICAL VS YOUR NORM", "grey"

    # Only *excess above the learned upper-quartile day* adds a small context cost.
    # A familiar high-volume or double-session day still costs energy through its
    # actual load/duration, but is not punished merely for being normal for the athlete.
    load_anchor = q75_load if q75_load and q75_load > 0 else (typical_load * 1.15 if typical_load else None)
    minute_anchor = q75_minutes if q75_minutes and q75_minutes > 0 else (typical_minutes * 1.15 if typical_minutes else None)
    load_excess = max(0.0, today_load - load_anchor) if load_anchor is not None else 0.0
    minute_excess = max(0.0, today_minutes - minute_anchor) if minute_anchor is not None else 0.0
    extra_cost = min(16.0, load_excess * 0.08 + minute_excess * 0.015)

    return {
        "label": label, "class": css, "learned": True, "extra_cost": extra_cost,
        "load_ratio": round(load_ratio, 2) if load_ratio is not None else None,
        "duration_ratio": round(duration_ratio, 2) if duration_ratio is not None else None,
        "typical_load": round(typical_load, 1) if typical_load is not None else None,
        "typical_minutes": round(typical_minutes, 1) if typical_minutes is not None else None,
    }



def _energy_ambulatory_activity(activity):
    """Return True when a completed activity likely contributes materially to daily steps.

    Daily Wellness steps can include steps accumulated during a recorded Run/Walk/Hike.
    Those activities already spend Energy Bank through their activity load/duration, so the
    step contribution is attenuated when such an overlap exists rather than counted in full.
    """
    activity = activity or {}
    kind = " ".join(str(activity.get(k) or "") for k in ("type", "sub_type")).strip().lower()
    if kind:
        return any(key in kind for key in ("run", "walk", "hike", "hiking"))
    # Name is only a fallback when Intervals did not return a structured activity type;
    # this avoids treating a cycling title such as "trail ride" as ambulatory overlap.
    name = str(activity.get("name") or "").strip().lower()
    return any(key in name for key in ("run", "walk", "hike", "hiking"))


def _energy_steps_context(wellness, now=None, today_activities=None):
    """Build a conservative intraday movement-cost context from Intervals Wellness steps.

    `steps` is cumulative for the current day, so THE LAB spends reserve as movement accrues
    but never interprets a low partial-day count as proof of unusually low movement. Prior
    complete days (up to 42d) are used only to identify unusually high movement versus the
    athlete's own recent norm. The absolute movement cost is deliberately modest and capped.
    """
    now = now or get_rome_now()
    today = now.date()
    history_start = today - timedelta(days=42)
    by_day = {}
    for row in wellness or []:
        raw_day = str((row or {}).get("id") or "")[:10]
        try:
            day = date.fromisoformat(raw_day)
        except ValueError:
            continue
        raw_steps = (row or {}).get("steps")
        if isinstance(raw_steps, bool):
            continue
        try:
            steps = int(round(float(raw_steps)))
        except (TypeError, ValueError):
            continue
        if steps < 0:
            continue
        by_day[day] = steps

    today_steps = by_day.get(today)
    if today_steps is None:
        return {
            "available": False, "steps": None, "steps_label": None, "label": None,
            "class": "grey", "learned": False, "samples": 0, "typical_steps": None,
            "q75_steps": None, "ratio": None, "cost": 0.0, "overlap_guard": False,
        }

    history = sorted(
        steps for day, steps in by_day.items()
        if history_start <= day < today and isinstance(steps, int) and steps > 0
    )
    learned = len(history) >= 7
    typical = statistics.median(history) if history else None
    q75 = percentile(history, 0.75) if learned else None
    ratio = (today_steps / typical) if typical and typical > 0 else None

    # Real movement spends a small amount of reserve even when it is typical. The absolute
    # component prevents a naturally high-step athlete from receiving zero cost, while the
    # personal component adds only for clearly above-normal movement. Both are capped.
    base_cost = min(4.5, max(0.0, float(today_steps)) / 4000.0)
    extra_cost = 0.0
    if learned and typical and typical > 0:
        anchor = q75 if q75 and q75 > 0 else typical * 1.20
        excess = max(0.0, float(today_steps) - float(anchor))
        extra_cost = min(3.0, excess / 2500.0)

    if learned and ratio is not None:
        if ratio >= 1.55 or (q75 is not None and today_steps >= q75 * 1.30):
            label, css = "HIGH MOVEMENT VS YOUR NORM", "orange"
        elif ratio >= 1.20 or (q75 is not None and today_steps > q75):
            label, css = "ABOVE MOVEMENT VS YOUR NORM", "orange"
        else:
            # Current-day steps are partial until the day is complete; never label them LOW.
            label, css = "WITHIN YOUR USUAL MOVEMENT SO FAR", "grey"
    else:
        label, css = "MOVEMENT BASELINE LEARNING", "grey"

    overlap_guard = any(_energy_ambulatory_activity(a) for a in (today_activities or []))
    cost = min(7.5, base_cost + extra_cost)
    if overlap_guard:
        cost *= 0.55

    return {
        "available": True,
        "steps": today_steps,
        "steps_label": f"{today_steps:,}",
        "label": label,
        "class": css,
        "learned": learned,
        "samples": len(history),
        "typical_steps": round(typical) if typical is not None else None,
        "q75_steps": round(q75) if q75 is not None else None,
        "ratio": round(ratio, 2) if ratio is not None else None,
        "cost": round(cost, 2),
        "overlap_guard": overlap_guard,
    }


def compute_energy_bank(form_zone, fatigue_zone, avg_sleep_hours, recent_activities=None, personal_baselines=None, now=None, sleep_quality=None, training_rhythm=None, wellness=None):
    """Intraday 0-100 reserve with athlete-specific recovery and training context.

    Recovery establishes the starting potential. Completed activities spend that
    potential from their real Intervals load, duration and intensity. The Training
    Rhythm Engine supplies a learned training-day load/duration baseline so an
    unusually large day can cost a little more *for that athlete*. Intervals Wellness
    steps add a modest intraday movement cost, with personal-history excess and an overlap
    guard for recorded Run/Walk/Hike activities. Session count by itself is never penalized:
    two rides with the same total work as one ride do not lose extra Energy Bank simply
    because Intervals contains two files.
    """
    now = now or get_rome_now()
    recent_activities = recent_activities or []
    wellness = wellness or []
    pb = personal_baselines or {}

    # Starting recovery potential. Duration matters, but quality is a first-class signal.
    starting = 62
    starting += {"green": 12, "grey": 0, "red": -14}.get(form_zone, 0)
    starting += {"green": 9, "grey": 0, "red": -11}.get(fatigue_zone, 0)

    if isinstance(avg_sleep_hours, (int, float)):
        sleep_target_minutes = (pb.get("sleep") or {}).get("habitual_minutes")
        if isinstance(sleep_target_minutes, (int, float)) and sleep_target_minutes > 0:
            sleep_delta = avg_sleep_hours * 60.0 - sleep_target_minutes
            if sleep_delta >= 20:
                starting += 3
            elif sleep_delta < -75:
                starting -= 6
            elif sleep_delta < -45:
                starting -= 3
            elif sleep_delta < -20:
                starting -= 1
        else:
            if avg_sleep_hours >= 7.5:
                starting += 4
            elif avg_sleep_hours < 6.5:
                starting -= 6
            elif avg_sleep_hours < 7.0:
                starting -= 2

    if sleep_quality == 1:
        starting += 10
    elif sleep_quality == 2:
        starting += 7
    elif sleep_quality == 3:
        starting -= 3
    elif sleep_quality == 4:
        starting -= 10

    hrv = pb.get("hrv", {})
    rhr = pb.get("rhr", {})
    sleep = pb.get("sleep", {})
    if hrv.get("color") == "red": starting -= 10
    elif hrv.get("color") == "grey": starting -= 4
    if rhr.get("color") == "red": starting -= 7
    elif rhr.get("color") == "grey" and rhr.get("status") == "Above baseline": starting -= 3

    if sleep.get("color") == "red":
        starting -= 2 if sleep_quality in (1, 2) else 7
    elif sleep.get("color") == "grey":
        starting -= 0 if sleep_quality in (1, 2) else 3

    starting = max(25, min(96, round(starting)))

    today = now.date().isoformat()
    today_activities = [a for a in recent_activities if str(a.get("start_date_local", ""))[:10] == today]
    today_load = 0.0
    today_minutes = 0.0
    hard_sessions = 0
    for a in today_activities:
        load = a.get("icu_training_load")
        if isinstance(load, (int, float)):
            today_load += max(0, float(load))
        secs = a.get("moving_time") or a.get("elapsed_time") or 0
        if isinstance(secs, (int, float)):
            today_minutes += max(0, float(secs)) / 60.0
        try:
            family = classify_training_family(a)
            if is_hard_training_family(family):
                hard_sessions += 1
        except Exception:
            pass

    training_context = _energy_training_day_context(today_load, today_minutes, training_rhythm)
    steps_context = _energy_steps_context(wellness, now=now, today_activities=today_activities)

    # Real completed work always spends reserve. There is deliberately NO cost for
    # "second session" as a category. A second ride costs only through its added
    # load/duration/intensity, exactly as the equivalent work inside one file would.
    # Daily steps are a separate low-grade movement expenditure; they are capped and
    # attenuated when a recorded ambulatory activity already accounts for part of them.
    load_cost = min(42.0, today_load * 0.26)
    duration_cost = min(10.0, max(0.0, today_minutes - 45.0) * 0.035)
    hard_cost = 5.0 if hard_sessions else 0.0
    rhythm_excess_cost = float(training_context.get("extra_cost") or 0.0)
    steps_cost = float(steps_context.get("cost") or 0.0)
    spent = min(62.0, load_cost + duration_cost + hard_cost + rhythm_excess_cost + steps_cost)

    score = max(5, min(100, round(starting - spent)))
    if score >= 72:
        label, zone = "Charged", "green"
    elif score >= 45:
        label, zone = "Available", "grey"
    elif score >= 25:
        label, zone = "Used", "orange"
    else:
        label, zone = "Drained", "red"

    theta = math.pi - (score / 100.0) * math.pi
    marker_radius = 87
    marker_x = round(100 + marker_radius * math.cos(theta), 1)
    marker_y = round(95 - marker_radius * math.sin(theta), 1)

    return {
        "energy_score": score, "energy_label": label, "energy_zone": zone,
        "marker_x": marker_x, "marker_y": marker_y,
        "energy_morning_score": starting,  # legacy key retained for stored-report/template compatibility
        "energy_starting_score": starting,
        "energy_today_load": round(today_load),
        "energy_today_minutes": round(today_minutes),
        "energy_today_sessions": len(today_activities),
        "energy_today_steps": steps_context.get("steps"),
        "energy_today_steps_label": steps_context.get("steps_label"),
        "energy_steps_cost": round(steps_cost, 1),
        "energy_steps_context": steps_context.get("label"),
        "energy_steps_context_class": steps_context.get("class", "grey"),
        "energy_steps_baseline_learned": bool(steps_context.get("learned")),
        "energy_steps_samples": steps_context.get("samples", 0),
        "energy_typical_steps": steps_context.get("typical_steps"),
        "energy_steps_q75": steps_context.get("q75_steps"),
        "energy_steps_ratio": steps_context.get("ratio"),
        "energy_steps_overlap_guard": bool(steps_context.get("overlap_guard")),
        "energy_spent": round(spent),
        "energy_sleep_quality": sleep_quality,
        "energy_training_context": training_context.get("label"),
        "energy_training_context_class": training_context.get("class", "grey"),
        "energy_training_baseline_learned": bool(training_context.get("learned")),
        "energy_typical_day_load": training_context.get("typical_load"),
        "energy_typical_day_minutes": training_context.get("typical_minutes"),
        "energy_today_load_ratio": training_context.get("load_ratio"),
        "energy_today_duration_ratio": training_context.get("duration_ratio"),
        "energy_rhythm_excess_cost": round(rhythm_excess_cost, 1),
        "energy_cost_method": "real load + duration + intensity + daily steps; learned training-day/movement excess; ambulatory overlap guard; no session-count penalty",
    }

def sleep_quality_details(value):
    """Intervals.icu sleepQuality: 1=Excellent, 2=Good, 3=Average, 4=Poor."""
    try:
        q = int(float(value))
    except (TypeError, ValueError):
        return "Q–", "No quality data", "qna"
    labels = {1: "Excellent", 2: "Good", 3: "Average", 4: "Poor"}
    q = max(1, min(4, q))
    return f"Q{q}", labels[q], f"q{q}"


def compute_race_readiness(form_zone, fatigue_zone, sleep_quality, personal_baselines):
    """0-100 readiness with a concise explanation; detailed baselines live elsewhere in the UI."""
    score = 50
    signals = []
    score += {"green": 18, "grey": 0, "red": -18}.get(form_zone, 0)
    score += {"green": 15, "grey": 0, "red": -15}.get(fatigue_zone, 0)

    # Sleep quality has deliberate weight. A Q1/Q2 night is meaningful even when
    # duration is modestly below the weekday target.
    if sleep_quality == 1:
        score += 12
    elif sleep_quality == 2:
        score += 9
    elif sleep_quality == 3:
        score -= 3; signals.append((2, "sleep quality average"))
    elif sleep_quality == 4:
        score -= 10; signals.append((3, "sleep quality poor"))

    pb = personal_baselines or {}
    hrv, rhr, sleep, spo2 = (pb.get(k, {}) for k in ("hrv", "rhr", "sleep", "spo2"))

    if hrv.get("status") == "Within baseline": score += 6
    elif hrv.get("status") == "Above baseline": score += 5
    elif hrv.get("status") == "Below baseline":
        score += -9 if hrv.get("color") == "red" else -4
        signals.append((3 if hrv.get("color") == "red" else 2, "HRV below personal range"))

    if rhr.get("status") == "Within baseline": score += 4
    elif rhr.get("status") == "Above baseline":
        score += -8 if rhr.get("color") == "red" else -3
        signals.append((3 if rhr.get("color") == "red" else 2, "resting HR elevated"))

    if sleep.get("color") == "green":
        score += 4
    elif sleep.get("color") == "grey":
        if sleep_quality not in (1, 2):
            score -= 3; signals.append((1, "sleep slightly short"))
    elif sleep.get("color") == "red":
        if sleep_quality in (1, 2):
            score -= 3; signals.append((1, "sleep short but quality good"))
        else:
            score -= 8; signals.append((3, "sleep well below habitual opportunity"))

    if spo2.get("status") != "No current data":
        if spo2.get("color") == "green": score += 2
        elif spo2.get("color") == "red":
            score -= 5; signals.append((2, "SpO2 below usual level"))

    score = max(0, min(100, round(score)))
    signals.sort(key=lambda x: x[0], reverse=True)
    if signals:
        reason = " · ".join(text for _, text in signals[:3])
    elif form_zone == "green" and fatigue_zone == "green":
        reason = "Load balance and recovery signals are supportive."
    else:
        reason = "Recovery signals are broadly stable."

    if score >= 70: return score, "Ready to Train", "green", reason
    if score <= 40: return score, "Recovery Bias", "red", reason
    return score, "Train Smart", "grey", reason

def compute_metrics(wellness, form_thresholds=None, fatigue_thresholds=None, baseline_wellness=None):
    sorted_wellness = sorted(wellness, key=lambda w: w.get("id", ""))
    latest = sorted_wellness[-1] if sorted_wellness else {}

    ctl = latest.get("ctl")
    atl = latest.get("atl")
    sleep_quality = latest.get("sleepQuality")
    sleep_quality_label, sleep_quality_text, sleep_quality_class = sleep_quality_details(sleep_quality)
    latest_sleep_score = latest.get("sleepScore")
    latest_sleep_secs = latest.get("sleepSecs")
    latest_sleep_hours = latest_sleep_secs / 3600.0 if isinstance(latest_sleep_secs, (int, float)) else None
    latest_sleep_duration = _fmt_hours(latest_sleep_hours) if latest_sleep_hours is not None else "n/a"
    latest_sleeping_hr = latest.get("avgSleepingHR")
    tsb = round(ctl - atl, 1) if (ctl is not None and atl is not None) else None

    sleep_values = [w["sleepSecs"] / 3600 for w in wellness if w.get("sleepSecs")]
    avg_sleep = round(statistics.mean(sleep_values), 1) if sleep_values else None

    observation_wellness = baseline_wellness or wellness
    rhr_observation = _latest_wellness_observation(observation_wellness, "restingHR", "tempRestingHR")
    weight_observation = _latest_weight_provenance(observation_wellness)
    latest_rhr = rhr_observation.get("value")
    latest_weight = weight_observation.get("value")
    latest_rhr_note = _wellness_observation_note(rhr_observation)
    latest_weight_note = _weight_observation_note(weight_observation)

    readiness_entries = [w for w in sorted_wellness if w.get("readiness") is not None]
    latest_readiness = readiness_entries[-1]["readiness"] if readiness_entries else None

    spo2_entries = [w for w in sorted_wellness if w.get("spO2") is not None]
    latest_spo2 = spo2_entries[-1]["spO2"] if spo2_entries else None

    form_zone = classify_form(tsb, form_thresholds)
    fatigue_zone = classify_fatigue(atl, ctl, fatigue_thresholds)
    personal_baselines = compute_personal_baselines(baseline_wellness or wellness)
    race_score, race_label, race_zone, race_reason = compute_race_readiness(
        form_zone, fatigue_zone, sleep_quality, personal_baselines
    )

    adaptive_sleep = personal_baselines.get("adaptive_sleep") or {}
    sleep_delta_min = adaptive_sleep.get("current_delta_min")
    sleep_reference_delta_min = adaptive_sleep.get("reference_delta_min")
    resolved_refs = personal_baselines.get("resolved") or {}
    score_ref = resolved_refs.get("sleep_score")
    spo2_ref = resolved_refs.get("spo2")
    sleep_score_delta = round(latest_sleep_score - score_ref) if isinstance(latest_sleep_score, (int, float)) and isinstance(score_ref, (int, float)) else None
    spo2_delta = round(latest_spo2 - spo2_ref, 1) if isinstance(latest_spo2, (int, float)) and isinstance(spo2_ref, (int, float)) else None

    return {
        "ctl": round(ctl, 1) if ctl is not None else "n/a",
        "atl": round(atl, 1) if atl is not None else "n/a",
        "tsb": tsb if tsb is not None else "n/a",
        "fitness_zone": classify_fitness_trend(wellness),
        "fatigue_zone": fatigue_zone,
        "form_zone": form_zone,
        "latest_rhr": latest_rhr if latest_rhr is not None else "n/a",
        "latest_rhr_note": latest_rhr_note,
        "latest_rhr_carried_forward": bool(rhr_observation.get("carried_forward")),
        "latest_hrv": latest.get("hrv", "n/a"),
        "avg_sleep": f"{avg_sleep}h" if avg_sleep is not None else "n/a",
        "avg_sleep_hours": avg_sleep,
        "latest_sleep_hours": round(latest_sleep_hours, 2) if latest_sleep_hours is not None else None,
        "latest_weight": f"{round(latest_weight, 1)}kg" if latest_weight is not None else "n/a",
        "latest_weight_note": latest_weight_note,
        "latest_weight_carried_forward": bool(weight_observation.get("carried_forward")),
        "latest_readiness": round(latest_readiness) if latest_readiness is not None else None,
        "latest_spo2": round(latest_spo2, 1) if latest_spo2 is not None else None,
        "sleep_quality": sleep_quality,
        "sleep_quality_label": sleep_quality_label,
        "sleep_quality_text": sleep_quality_text,
        "sleep_quality_class": sleep_quality_class,
        "latest_sleep_score": round(latest_sleep_score) if latest_sleep_score is not None else None,
        "latest_sleep_duration": latest_sleep_duration,
        "latest_sleeping_hr": round(latest_sleeping_hr) if latest_sleeping_hr is not None else None,
        "sleep_delta_min": sleep_delta_min,
        "sleep_reference_delta_min": sleep_reference_delta_min,
        "sleep_score_delta": sleep_score_delta,
        "spo2_delta": spo2_delta,
        "personal_baselines": personal_baselines,
        "adaptive_sleep": adaptive_sleep,
        "race_readiness_score": race_score,
        "race_readiness_label": race_label,
        "race_readiness_zone": race_zone,
        "race_readiness_css_color": {"green": "green", "red": "red", "grey": "grey-zone"}.get(race_zone, "grey-zone"),
        "race_readiness_reason": race_reason,
    }

def build_data_text(recent_activities, wellness, season_stats, notes=None, feelings=None, best_watts=None, vo2_trend=None, performance_breakthrough=None):
    lines = ["RECENT ACTIVITIES (last {} days):".format(DAYS_BACK)]
    if not recent_activities:
        lines.append("(no activities found on Intervals.icu for this period)")
    for a in recent_activities:
        duration_sec = a.get("moving_time") or a.get("elapsed_time") or 0
        power = a.get("icu_weighted_avg_watts") or a.get("average_watts") or "n/a"
        lines.append(
            "- {date} | {name} | {type} | {dur} min | load {load} | "
            "power {pwr} | HR {hr} | calories {cal} | Intervals CHO used {cho_used}g | CHO ingested {cho_in}g".format(
                date=a.get("start_date_local", "").replace("T", " ")[:16],
                name=a.get("name", ""),
                type=a.get("type", ""),
                dur=round(duration_sec / 60),
                load=a.get("icu_training_load", "n/a"),
                pwr=power,
                hr=a.get("average_heartrate", "n/a"),
                cal=a.get("calories", "n/a"),
                cho_used=a.get("carbs_used", "n/a"),
                cho_in=a.get("carbs_ingested", "n/a"),
            )
        )

    lines.append("\nSEASON SUMMARY (last {} days, time-in-zone based):".format(SEASON_DAYS_BACK))
    lines.append(
        "- Total training time: {}h | Total load: {} | "
        "Low intensity: {}% | Moderate intensity: {}% | High intensity: {}%".format(
            season_stats["season_hours"], season_stats["season_total_load"],
            season_stats["zone_low_pct"], season_stats["zone_mod_pct"], season_stats["zone_high_pct"],
        )
    )

    if performance_breakthrough and performance_breakthrough.get("available"):
        lines.append("\n" + performance_breakthrough_text(performance_breakthrough))

    if best_watts:
        lines.append("\nREAL POWER CURVE (actual best efforts, last 42 days - use these as the "
                     "ceiling for any power target you prescribe, never exceed them for that "
                     "duration or shorter):")
        for p in best_watts:
            lines.append("- {}: {}W".format(p["label"], p["watts"]))

    if vo2_trend and vo2_trend.get("available"):
        lines.append("\nVO2MAX TREND (MODEL ESTIMATES ONLY - longitudinal context, NOT a measured VO2max and NOT a primary readiness signal):")
        if vo2_trend.get("wearable_current") is not None:
            lines.append("- Wearable / Intervals Wellness: {} ml/kg/min | 28d delta {}".format(
                vo2_trend.get("wearable_current"), vo2_trend.get("wearable_delta28") if vo2_trend.get("wearable_delta28") is not None else "n/a"))
        if vo2_trend.get("performance_current") is not None:
            lines.append("- Intervals 5-min-power estimate: {} ml/kg/min | 28d delta {}".format(
                vo2_trend.get("performance_current"), vo2_trend.get("performance_delta28") if vo2_trend.get("performance_delta28") is not None else "n/a"))
        lines.append("- Trend agreement: {}. Use only as longitudinal performance context; do not let it override health, recovery, availability or recent training.".format(vo2_trend.get("agreement", "n/a")))

    lines.append("\nWELLNESS (last {} days):".format(DAYS_BACK))
    for w in sorted(wellness, key=lambda x: x.get("id", "")):
        line = (
            "- {date} | RHR {rhr} | HRV {hrv} | sleep {sleep}h | CTL {ctl} | ATL {atl}".format(
                date=w.get("id", ""),
                rhr=(str(w.get("restingHR", "n/a")) + (" [carried forward by Intervals]" if _intervals_temp_flag(w, "tempRestingHR") else "")),
                hrv=w.get("hrv", "n/a"),
                sleep=round(w["sleepSecs"] / 3600, 1) if w.get("sleepSecs") else "n/a",
                ctl=round(w["ctl"], 1) if w.get("ctl") is not None else "n/a",
                atl=round(w["atl"], 1) if w.get("atl") is not None else "n/a",
            )
            + " | sleepQ {} | sleepScore {} | sleepingHR {} | SpO2 {} | wearableReadiness {}".format(
                ("Q" + str(w.get("sleepQuality"))) if w.get("sleepQuality") is not None else "n/a",
                round(w.get("sleepScore")) if w.get("sleepScore") is not None else "n/a",
                round(w.get("avgSleepingHR")) if w.get("avgSleepingHR") is not None else "n/a",
                round(w.get("spO2"), 1) if w.get("spO2") is not None else "n/a",
                round(w.get("readiness")) if w.get("readiness") is not None else "n/a",
            )
        )
        if w.get("weight"):
            line += " | weight {}kg{}".format(
                round(w["weight"], 1),
                " [carried forward by Intervals]" if _intervals_temp_flag(w, "tempWeight") else "",
            )
        if w.get("comments"):
            line += " | note: {}".format(w["comments"])
        lines.append(line)

    if notes:
        lines.append("\nCOACH NOTES / DURABLE MEMORY (things the athlete has told you before, most recent last):")
        for n in notes:
            lines.append("- [{category}] {date}: {text}".format(category=n.get("category", "GENERAL"), date=n.get("date", ""), text=n.get("text", "")))
        lines.append("\n" + training_definitions_text(build_training_definitions(notes)))

    if feelings:
        lines.append("\nSELF-REPORTED DAILY LOG (1=bad, 10=amazing; context matters):")
        for f in feelings[-20:]:
            lines.append(
                "- {date} {time} | {value}/10 | {phase} | status {status} | sessions {sessions} | load {load} | note {note}".format(
                    date=f.get("date", ""), time=f.get("time", ""), value=f.get("value", ""), phase=f.get("phase", ""),
                    status=f.get("status", "NORMAL"), sessions=f.get("sessions", "n/a"), load=f.get("load", "n/a"), note=f.get("note") or "none"
                )
            )

    return "\n".join(lines)



def get_rome_now():
    """Compatibility name: return wall-clock time in the authenticated athlete's timezone."""
    return datetime.now(_runtime_timezone())


def parse_local_activity_datetime(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).replace(tzinfo=None)
    except (ValueError, TypeError):
        return None


# ---------------------------------------------------------------------------
# PRODUCT V4.8.4 · Adaptive Training Rhythm Engine
# ---------------------------------------------------------------------------
RHYTHM_RECENT_DAYS = 14
RHYTHM_ESTABLISHED_DAYS = 42
RHYTHM_SEASON_DAYS = 90
RHYTHM_MIN_SESSION_SECONDS = 600
_RHYTHM_WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")


def _rhythm_num(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def _rhythm_quantile(values, q):
    vals = sorted(float(v) for v in values if _rhythm_num(v) is not None)
    if not vals:
        return None
    if len(vals) == 1:
        return vals[0]
    pos = (len(vals) - 1) * max(0.0, min(1.0, float(q)))
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return vals[lo]
    frac = pos - lo
    return vals[lo] + (vals[hi] - vals[lo]) * frac


def _rhythm_weighted_median(pairs):
    clean = []
    for value, weight in pairs:
        v, w = _rhythm_num(value), _rhythm_num(weight)
        if v is not None and w is not None and w > 0:
            clean.append((v, w))
    if not clean:
        return None
    clean.sort(key=lambda x: x[0])
    half = sum(w for _, w in clean) / 2.0
    acc = 0.0
    for value, weight in clean:
        acc += weight
        if acc >= half:
            return value
    return clean[-1][0]


def _rhythm_format_minutes(minutes):
    if minutes is None:
        return None
    minutes = int(round(minutes)) % 1440
    hour, minute = divmod(minutes, 60)
    stamp = datetime(2000, 1, 1, hour, minute)
    return stamp.strftime("%I:%M %p").lstrip("0")


def _rhythm_format_duration(minutes):
    if minutes is None:
        return None
    minutes = max(1, int(round(minutes / 5.0) * 5))
    if minutes < 90:
        return f"~{minutes} min"
    h, m = divmod(minutes, 60)
    return f"~{h}h{m:02d}" if m else f"~{h} h"


def _rhythm_activity_records(activities, now=None):
    """Normalize meaningful completed training records from Intervals history.

    Tiny accidental recordings (<10 min with no meaningful load) are excluded so
    commute fragments or device glitches do not create false double-session days.
    """
    now = now or get_rome_now()
    cutoff = now.replace(tzinfo=None)
    out = []
    for activity in activities or []:
        dt = parse_local_activity_datetime(activity.get("start_date_local"))
        if dt is None or dt > cutoff:
            continue
        duration_sec = _rhythm_num(activity.get("moving_time")) or _rhythm_num(activity.get("elapsed_time")) or 0.0
        load = _rhythm_num(activity.get("icu_training_load"))
        if duration_sec < RHYTHM_MIN_SESSION_SECONDS and (load is None or load < 5):
            continue
        out.append({
            "date": dt.date(), "dt": dt, "weekday": dt.weekday(),
            "start_minute": dt.hour * 60 + dt.minute,
            "duration_min": duration_sec / 60.0 if duration_sec > 0 else None,
            "load": load,
            "name": activity.get("name") or activity.get("type") or "Activity",
            "type": activity.get("type") or "",
        })
    out.sort(key=lambda x: x["dt"])
    return out


def _rhythm_span_stats(records, start_date, end_date):
    if not start_date or not end_date or end_date < start_date:
        return {
            "days_observed": 0, "training_days": 0, "sessions": 0, "hours": 0.0,
            "days_per_week": 0.0, "sessions_per_week": 0.0, "hours_per_week": 0.0,
            "sessions_per_training_day": 0.0, "double_days": 0, "double_day_pct": 0.0,
            "median_duration_min": None, "duration_q25_min": None, "duration_q75_min": None,
            "median_day_load": None, "day_load_q25": None, "day_load_q75": None, "load_day_samples": 0,
            "median_day_minutes": None, "day_minutes_q25": None, "day_minutes_q75": None, "duration_day_samples": 0,
            "weekday_probability": {i: 0.0 for i in range(7)},
            "weekday_double_probability": {i: 0.0 for i in range(7)},
        }
    days_observed = (end_date - start_date).days + 1
    selected = [r for r in records if start_date <= r["date"] <= end_date]
    by_day = {}
    for r in selected:
        by_day.setdefault(r["date"], []).append(r)
    training_days = len(by_day)
    sessions = len(selected)
    hours = sum((r.get("duration_min") or 0.0) for r in selected) / 60.0
    weeks = max(days_observed / 7.0, 1 / 7.0)
    double_days = sum(1 for rows in by_day.values() if len(rows) >= 2)
    weekday_occurrences = {i: 0 for i in range(7)}
    cursor = start_date
    while cursor <= end_date:
        weekday_occurrences[cursor.weekday()] += 1
        cursor += timedelta(days=1)
    weekday_training = {i: 0 for i in range(7)}
    weekday_double = {i: 0 for i in range(7)}
    for d, rows in by_day.items():
        wd = d.weekday()
        weekday_training[wd] += 1
        if len(rows) >= 2:
            weekday_double[wd] += 1
    durations = [r["duration_min"] for r in selected if r.get("duration_min")]
    day_loads = []
    day_minutes = []
    for rows in by_day.values():
        raw_loads = [_rhythm_num(r.get("load")) for r in rows]
        raw_minutes = [_rhythm_num(r.get("duration_min")) for r in rows]
        # Day-level baselines must not be built from partial days. If one session is
        # missing load/duration, skip that dimension for the day rather than
        # understating what is normal for a multi-session athlete.
        if raw_loads and all(v is not None for v in raw_loads):
            day_loads.append(sum(max(0.0, float(v)) for v in raw_loads))
        if raw_minutes and all(v is not None for v in raw_minutes):
            day_minutes.append(sum(max(0.0, float(v)) for v in raw_minutes))
    return {
        "start_date": start_date.isoformat(), "end_date": end_date.isoformat(),
        "days_observed": days_observed, "training_days": training_days, "sessions": sessions,
        "hours": round(hours, 1),
        "days_per_week": round(training_days / weeks, 2),
        "sessions_per_week": round(sessions / weeks, 2),
        "hours_per_week": round(hours / weeks, 2),
        "sessions_per_training_day": round(sessions / training_days, 2) if training_days else 0.0,
        "double_days": double_days,
        "double_day_pct": round(double_days / training_days, 3) if training_days else 0.0,
        "median_duration_min": round(statistics.median(durations), 1) if durations else None,
        "duration_q25_min": round(_rhythm_quantile(durations, 0.25), 1) if durations else None,
        "duration_q75_min": round(_rhythm_quantile(durations, 0.75), 1) if durations else None,
        "median_day_load": round(statistics.median(day_loads), 1) if day_loads else None,
        "day_load_q25": round(_rhythm_quantile(day_loads, 0.25), 1) if day_loads else None,
        "day_load_q75": round(_rhythm_quantile(day_loads, 0.75), 1) if day_loads else None,
        "load_day_samples": len(day_loads),
        "median_day_minutes": round(statistics.median(day_minutes), 1) if day_minutes else None,
        "day_minutes_q25": round(_rhythm_quantile(day_minutes, 0.25), 1) if day_minutes else None,
        "day_minutes_q75": round(_rhythm_quantile(day_minutes, 0.75), 1) if day_minutes else None,
        "duration_day_samples": len(day_minutes),
        "weekday_probability": {
            i: round(weekday_training[i] / weekday_occurrences[i], 3) if weekday_occurrences[i] else 0.0
            for i in range(7)
        },
        "weekday_double_probability": {
            i: round(weekday_double[i] / weekday_training[i], 3) if weekday_training[i] else 0.0
            for i in range(7)
        },
    }


def _rhythm_window_stats(records, end_date, days, history_start=None):
    nominal = end_date - timedelta(days=days - 1)
    start = max(nominal, history_start) if history_start else nominal
    return _rhythm_span_stats(records, start, end_date)


def _rhythm_clock_profile(records, today, history_start=None):
    end = today - timedelta(days=1)
    start = max(end - timedelta(days=41), history_start) if history_start else end - timedelta(days=41)
    selected = [r for r in records if start <= r["date"] <= end]
    by_day = {}
    for r in selected:
        by_day.setdefault(r["date"], []).append(r)
    first_by_weekday = {i: [] for i in range(7)}
    second_by_weekday = {i: [] for i in range(7)}
    duration_by_weekday = {i: [] for i in range(7)}
    first_all, second_all, duration_all = [], [], []
    for d, rows in by_day.items():
        rows = sorted(rows, key=lambda x: x["dt"])
        age = (today - d).days
        weight = 2.5 if age <= 14 else 1.0
        first = rows[0]
        first_by_weekday[d.weekday()].append((first["start_minute"], weight))
        first_all.append((first["start_minute"], weight))
        if len(rows) >= 2:
            second_by_weekday[d.weekday()].append((rows[1]["start_minute"], weight))
            second_all.append((rows[1]["start_minute"], weight))
        for row in rows:
            if row.get("duration_min"):
                duration_by_weekday[d.weekday()].append((row["duration_min"], weight))
                duration_all.append((row["duration_min"], weight))
    return {
        "first_start_min": {i: _rhythm_weighted_median(first_by_weekday[i]) for i in range(7)},
        "second_start_min": {i: _rhythm_weighted_median(second_by_weekday[i]) for i in range(7)},
        "duration_min": {i: _rhythm_weighted_median(duration_by_weekday[i]) for i in range(7)},
        "overall_first_start_min": _rhythm_weighted_median(first_all),
        "overall_second_start_min": _rhythm_weighted_median(second_all),
        "overall_duration_min": _rhythm_weighted_median(duration_all),
    }


def _rhythm_training_gap(records, today):
    dates = sorted({r["date"] for r in records if r["date"] < today})
    if len(dates) < 2:
        return None
    dates = dates[-20:]
    gaps = [(b - a).days for a, b in zip(dates, dates[1:]) if (b - a).days > 0]
    return round(statistics.median(gaps), 1) if gaps else None


def build_training_rhythm(season_activities, now=None):
    """Learn frequency, volume, timing and double-session propensity from history.

    The model is intentionally deterministic and recalculated every Snapshot. Recent
    14-day behavior is weighted against the established 42-day rhythm and 90-day
    season context, so sustained changes progressively replace old habits without
    letting a few unusual days rewrite the athlete overnight.
    """
    now = now or get_rome_now()
    today = now.date()
    records = _rhythm_activity_records(season_activities, now)
    historical = [r for r in records if r["date"] < today]
    history_start = min((r["date"] for r in historical), default=None)
    end = today - timedelta(days=1)
    recent = _rhythm_window_stats(historical, end, RHYTHM_RECENT_DAYS, history_start)
    established = _rhythm_window_stats(historical, end, RHYTHM_ESTABLISHED_DAYS, history_start)
    season = _rhythm_window_stats(historical, end, RHYTHM_SEASON_DAYS, history_start)
    prior_end = end - timedelta(days=RHYTHM_RECENT_DAYS)
    prior_start = max(prior_end - timedelta(days=27), history_start) if history_start else prior_end - timedelta(days=27)
    prior = _rhythm_span_stats(historical, prior_start, prior_end) if prior_end >= prior_start else _rhythm_span_stats([], None, None)

    shift_signals = []
    if recent.get("days_observed", 0) >= 10 and prior.get("days_observed", 0) >= 14 and recent.get("training_days", 0) >= 3 and prior.get("training_days", 0) >= 3:
        if abs(recent["days_per_week"] - prior["days_per_week"]) >= 1.25:
            shift_signals.append("training-day frequency changed")
        if abs(recent["sessions_per_week"] - prior["sessions_per_week"]) >= 1.5:
            shift_signals.append("session frequency changed")
        prior_hours = prior.get("hours_per_week") or 0.0
        if prior_hours >= 2.0:
            hours_change = abs(recent.get("hours_per_week", 0.0) - prior_hours)
            if hours_change >= max(2.5, prior_hours * 0.30):
                shift_signals.append("weekly volume changed")
        if abs(recent.get("double_day_pct", 0.0) - prior.get("double_day_pct", 0.0)) >= 0.25:
            shift_signals.append("double-session pattern changed")
        rdur, pdur = recent.get("median_duration_min"), prior.get("median_duration_min")
        if rdur and pdur and abs(rdur - pdur) >= max(30, pdur * 0.35):
            shift_signals.append("typical session duration changed")

    if established.get("days_observed", 0) < 14 or established.get("training_days", 0) < 3:
        state = "LEARNING"
        confidence = "LOW"
    elif shift_signals:
        state = "ADAPTING"
        confidence = "MODERATE" if established.get("training_days", 0) >= 6 else "LOW"
    elif established.get("days_observed", 0) >= 35 and established.get("training_days", 0) >= 8:
        state = "STABLE"
        confidence = "HIGH"
    else:
        state = "TRACKING"
        confidence = "MODERATE"

    if state == "ADAPTING":
        raw_weights = ((recent, 0.72), (established, 0.23), (season, 0.05))
    elif recent.get("training_days", 0) >= 3:
        raw_weights = ((recent, 0.52), (established, 0.33), (season, 0.15))
    elif established.get("training_days", 0) >= 4:
        raw_weights = ((recent, 0.15), (established, 0.62), (season, 0.23))
    else:
        raw_weights = ((recent, 0.10), (established, 0.45), (season, 0.45))
    valid = [(stats, weight) for stats, weight in raw_weights if stats.get("days_observed", 0) > 0]
    total_weight = sum(weight for _, weight in valid) or 1.0
    valid = [(stats, weight / total_weight) for stats, weight in valid]

    def blend(key):
        return sum(float(stats.get(key) or 0.0) * weight for stats, weight in valid)

    def blend_optional(key):
        pairs = []
        for stats, weight in valid:
            value = _rhythm_num(stats.get(key))
            if value is not None:
                pairs.append((value, weight))
        if not pairs:
            return None
        denom = sum(weight for _, weight in pairs) or 1.0
        return sum(value * weight for value, weight in pairs) / denom

    weekday_scores = {}
    weekday_double = {}
    for wd in range(7):
        weekday_scores[wd] = round(sum(float(stats.get("weekday_probability", {}).get(wd) or 0.0) * weight for stats, weight in valid), 3)
        weekday_double[wd] = round(sum(float(stats.get("weekday_double_probability", {}).get(wd) or 0.0) * weight for stats, weight in valid), 3)

    est_days = max(0.0, min(7.0, blend("days_per_week")))
    est_sessions = max(est_days, blend("sessions_per_week"))
    est_hours = max(0.0, blend("hours_per_week"))
    double_propensity = max(0.0, min(1.0, blend("double_day_pct")))
    target_days = 0 if state == "LEARNING" else max(1, min(7, int(round(est_days or 1))))
    ranked_days = sorted(range(7), key=lambda wd: (-weekday_scores[wd], wd))
    likely_weekdays = ranked_days[:target_days] if target_days else []
    if target_days >= 7:
        pattern_strength = "HIGH"
    elif target_days and target_days < 7:
        top = [weekday_scores[i] for i in likely_weekdays]
        rest = [weekday_scores[i] for i in ranked_days[target_days:]]
        separation = (statistics.mean(top) if top else 0) - (statistics.mean(rest) if rest else 0)
        pattern_strength = "HIGH" if separation >= 0.28 else ("MODERATE" if separation >= 0.12 else "LOW")
    else:
        pattern_strength = "LOW"

    clock_profile = _rhythm_clock_profile(historical, today, history_start)
    median_duration = _rhythm_weighted_median([
        (stats.get("median_duration_min"), weight) for stats, weight in valid if stats.get("median_duration_min")
    ])
    if median_duration is None:
        median_duration = clock_profile.get("overall_duration_min")
    median_gap = _rhythm_training_gap(historical, today)

    typical_day_load = blend_optional("median_day_load")
    day_load_q25 = blend_optional("day_load_q25")
    day_load_q75 = blend_optional("day_load_q75")
    typical_day_minutes = blend_optional("median_day_minutes")
    day_minutes_q25 = blend_optional("day_minutes_q25")
    day_minutes_q75 = blend_optional("day_minutes_q75")

    typical_days = [_RHYTHM_WEEKDAYS[wd][:3] for wd in sorted(likely_weekdays)]
    recent_label = f'{recent.get("training_days",0)}d/{recent.get("sessions",0)}s · {recent.get("hours_per_week",0):.1f} h/wk'
    established_label = f'{established.get("training_days",0)}d/{established.get("sessions",0)}s · {established.get("hours_per_week",0):.1f} h/wk'
    short_label = f'{est_days:.1f} d/wk · {est_hours:.1f} h/wk' if state != "LEARNING" else "Learning from Intervals"
    detail_parts = [state]
    if typical_days and pattern_strength != "LOW":
        detail_parts.append("likely " + " · ".join(typical_days))
    if double_propensity >= 0.35:
        detail_parts.append(f'doubles {round(double_propensity*100)}%')
    elif state != "LEARNING":
        detail_parts.append("single-session days dominate")
    if shift_signals:
        detail_parts.append("recent pattern weighted up")

    return {
        "state": state, "confidence": confidence, "shift_detected": bool(shift_signals), "shift_signals": shift_signals,
        "recent": recent, "established": established, "season": season, "prior": prior,
        "estimated_days_per_week": round(est_days, 1), "estimated_sessions_per_week": round(est_sessions, 1),
        "estimated_hours_per_week": round(est_hours, 1), "double_propensity": round(double_propensity, 3),
        "weekday_scores": weekday_scores, "weekday_double_scores": weekday_double,
        "likely_weekdays": likely_weekdays, "pattern_strength": pattern_strength,
        "median_training_gap_days": median_gap, "median_session_duration_min": round(median_duration, 1) if median_duration else None,
        "typical_training_day_load": round(typical_day_load, 1) if typical_day_load is not None else None,
        "training_day_load_q25": round(day_load_q25, 1) if day_load_q25 is not None else None,
        "training_day_load_q75": round(day_load_q75, 1) if day_load_q75 is not None else None,
        "typical_training_day_minutes": round(typical_day_minutes, 1) if typical_day_minutes is not None else None,
        "training_day_minutes_q25": round(day_minutes_q25, 1) if day_minutes_q25 is not None else None,
        "training_day_minutes_q75": round(day_minutes_q75, 1) if day_minutes_q75 is not None else None,
        "training_day_load_samples": max(int(recent.get("load_day_samples") or 0), int(established.get("load_day_samples") or 0)),
        "training_day_duration_samples": max(int(recent.get("duration_day_samples") or 0), int(established.get("duration_day_samples") or 0)),
        "clock_profile": clock_profile, "short_label": short_label, "detail": " · ".join(detail_parts),
        "recent_label": recent_label, "established_label": established_label,
        "history_records": len(historical),
        "method_note": "14d recent behavior is blended with 42d established rhythm and 90d season context; sustained changes progressively outrank older habits.",
    }


def training_rhythm_text(rhythm):
    rhythm = rhythm or {}
    return (
        "TRAINING RHYTHM (deterministic Intervals-history model; timing/frequency context, not a commitment):\n"
        f'- State {rhythm.get("state", "LEARNING")} | confidence {rhythm.get("confidence", "LOW")} | pattern strength {rhythm.get("pattern_strength", "LOW")}.\n'
        f'- Recent 14d: {rhythm.get("recent_label", "n/a")}. Established 42d: {rhythm.get("established_label", "n/a")}.\n'
        f'- Learned estimate: {rhythm.get("estimated_days_per_week", "n/a")} training day(s)/week | {rhythm.get("estimated_sessions_per_week", "n/a")} session(s)/week | {rhythm.get("estimated_hours_per_week", "n/a")} h/week.\n'
        f'- Double-session propensity: {round(float(rhythm.get("double_propensity") or 0)*100)}%. Shift signals: {", ".join(rhythm.get("shift_signals") or []) or "none"}.\n'
        "- This rhythm decides which future timing opportunities are plausible. Daily Log ratings/comments NEVER create a slot. Calendar/race/health constraints outrank learned rhythm."
    )


def _subjective_activity_summary(row):
    dur = row.get("duration_min")
    dur_text = f' · {round(dur)} min' if dur else ''
    load = row.get("load")
    load_text = f' · load {round(load,1)}' if load is not None else ''
    return f'{row.get("dt").strftime("%I:%M %p").lstrip("0")} {row.get("name")}{dur_text}{load_text}'


def build_subjective_activity_context(logs, activities, now=None, max_logs=12):
    """Give Daily Log notes candidate retrospective activity context without scheduling.

    Python only establishes temporal candidates. The AI may link note meaning to a
    candidate when wording supports it, but must not assume that the latest activity
    caused the feeling or that another session should follow.
    """
    now = now or get_rome_now()
    today = now.date()
    records = _rhythm_activity_records(activities, now)
    by_date = {}
    for row in records:
        by_date.setdefault(row["date"].isoformat(), []).append(row)
    rows = sorted(list(logs or []), key=lambda x: (str(x.get("local_date") or ""), str(x.get("logged_at_utc") or "")))[-max_logs:]
    items = []
    for log in rows:
        ds = str(log.get("local_date") or "")[:10]
        try:
            d = date.fromisoformat(ds)
        except ValueError:
            continue
        acts = sorted(by_date.get(ds, []), key=lambda x: x["dt"])
        relation = "GENERAL"
        candidates = []
        if d < today:
            relation = "DAY_LEVEL" if acts else "GENERAL"
            candidates = acts
        elif d == today:
            try:
                hh, mm = [int(x) for x in str(log.get("local_time") or "").split(":")[:2]]
                log_dt = datetime.combine(d, datetime.min.time()).replace(hour=hh, minute=mm)
            except Exception:
                log_dt = now.replace(tzinfo=None)
            completed = []
            for act in acts:
                duration = act.get("duration_min") or 0
                end_dt = act["dt"] + timedelta(minutes=duration)
                if end_dt <= log_dt:
                    completed.append(act)
            if len(completed) == 1:
                relation, candidates = "POSSIBLE_ACTIVITY_LINK", completed
            elif len(completed) >= 2:
                recent = [a for a in completed if 0 <= (log_dt - (a["dt"] + timedelta(minutes=a.get("duration_min") or 0))).total_seconds() <= 4*3600]
                relation = "POSSIBLE_ACTIVITY_LINK" if len(recent) == 1 else "DAY_LEVEL"
                candidates = recent if len(recent) == 1 else completed
        items.append({
            "log_id": log.get("id"), "date": ds, "time": log.get("local_time"),
            "feeling": log.get("feeling"), "note": log.get("note") or "", "relation": relation,
            "candidate_activities": [
                {"name": a.get("name"), "time": a.get("dt").strftime("%H:%M"), "duration_min": round(a.get("duration_min") or 0), "load": a.get("load")}
                for a in candidates
            ],
        })
    return {"items": items, "rule": "retrospective context only; never creates a future training opportunity"}


def subjective_activity_context_text(context):
    context = context or {}
    lines = ["SUBJECTIVE ↔ COMPLETED-ACTIVITY CONTEXT (candidate linkage; not a scheduling signal):"]
    for item in context.get("items") or []:
        candidates = item.get("candidate_activities") or []
        cand_text = "; ".join(
            f'{c.get("time")} {c.get("name") or "Activity"} · {c.get("duration_min")} min' + (f' · load {c.get("load")}' if c.get("load") is not None else '')
            for c in candidates
        ) or "none"
        lines.append(
            f'- {item.get("date")} {item.get("time")} | {item.get("feeling")}/10 | {item.get("relation")} | candidates {cand_text} | note {item.get("note") or "none"}'
        )
    lines.append(
        "- AI may associate note meaning with a candidate only when the wording supports it. Never interpret a rating/comment as proof that the day has another workout remaining."
    )
    return "\n".join(lines)



def get_clock_preview(now=None):
    now = now or get_rome_now()
    return {
        "time": now.strftime("%I:%M %p"), "time_clock": now.strftime("%I:%M"), "time_period": now.strftime("%p"),
        "phase": "Adaptive rhythm · refreshed with Snapshot",
    }



def build_coach_clock(season_activities, now=None, planning_context=None, training_rhythm=None):
    """Adaptive deterministic Coach Clock driven by real athlete history.

    There is no universal AM/PM schedule. Intervals history learns frequency,
    weekly volume, preferred training days/times and double-session propensity.
    Explicit Calendar/race/health rules remain authoritative. A same-day second
    opportunity is exposed only when one session is already complete and the
    athlete's learned rhythm strongly supports doubles.
    """
    now = now or get_rome_now()
    planning_context = planning_context or build_planning_context(now)
    rhythm = training_rhythm or build_training_rhythm(season_activities, now)
    today = now.date()
    today_iso = today.isoformat()
    records = _rhythm_activity_records(season_activities, now)
    today_rows = [r for r in records if r["date"] == today]
    today_rows.sort(key=lambda x: x["dt"])
    today_load = sum(r.get("load") or 0 for r in today_rows)
    today_minutes = sum(r.get("duration_min") or 0 for r in today_rows)
    today_acts = [
        {"name": r.get("name"), "hour": r["dt"].hour, "time": r["dt"].strftime("%I:%M %p").lstrip("0"), "duration_min": round(r.get("duration_min") or 0)}
        for r in today_rows
    ]

    blackout = set(planning_context.get("blackout_dates") or [])
    easy_only = set(planning_context.get("no_intensity_dates") or [])
    race_by_date = planning_context.get("race_by_date") or {}
    training_by_date = planning_context.get("training_by_date") or {}
    health = planning_context.get("health_override")
    blocked_today = today_iso in blackout
    no_intensity_today = today_iso in easy_only

    clock_profile = rhythm.get("clock_profile") or {}
    weekday_scores = rhythm.get("weekday_scores") or {}
    weekday_double = rhythm.get("weekday_double_scores") or {}
    likely_weekdays = set(rhythm.get("likely_weekdays") or [])
    pattern_strength = rhythm.get("pattern_strength") or "LOW"

    def predicted_start(slot_date, second=False):
        mapping = clock_profile.get("second_start_min" if second else "first_start_min") or {}
        value = mapping.get(slot_date.weekday())
        if value is None:
            value = clock_profile.get("overall_second_start_min" if second else "overall_first_start_min")
        return int(round(value)) if value is not None else None

    def predicted_duration(slot_date):
        mapping = clock_profile.get("duration_min") or {}
        value = mapping.get(slot_date.weekday())
        if value is None:
            value = rhythm.get("median_session_duration_min") or clock_profile.get("overall_duration_min")
        return round(value, 1) if value is not None else None

    def day_word(slot_date):
        if slot_date == today:
            return "Today"
        if slot_date == today + timedelta(days=1):
            return "Tomorrow"
        return slot_date.strftime("%A")

    def base_slot(slot_date, period, event=None, source="RHYTHM", second=False):
        ds = slot_date.isoformat() if slot_date else None
        training_environment = None
        training_demand = None
        event_note = None
        restriction = "NO_INTENSITY" if ds in easy_only else "NONE"
        start_minute = predicted_start(slot_date, second=second) if slot_date else None
        duration_hint = predicted_duration(slot_date) if slot_date else rhythm.get("median_session_duration_min")
        timing_conf = rhythm.get("confidence") or "LOW"
        if period == "RACE":
            label = f'{day_word(slot_date)} · RACE · {event.get("title") or "Priority event"}'
            window = "priority event"
            restriction = "RACE"
            source = "CALENDAR"
            start_minute = None
            duration_hint = None
            timing_conf = "EXPLICIT"
        elif period == "PLANNED":
            training_environment = str(event.get("training_environment") or ATHLETE_FUELING_PROFILE["default_training_environment"]).upper()
            if training_environment not in ("INDOOR", "OUTDOOR"):
                training_environment = ATHLETE_FUELING_PROFILE["default_training_environment"]
            training_demand = str(event.get("training_demand") or "COACH").upper()
            if training_demand not in ("EASY", "NORMAL", "HARD", "COACH"):
                training_demand = "COACH"
            label = f'{day_word(slot_date)} · PLANNED · {training_environment} · {event.get("title") or "Training"}'
            window = "athlete-planned"
            event_note = event.get("note") or ""
            source = "CALENDAR"
            start_minute = None
            timing_conf = "EXPLICIT"
        elif period == "SAME_DAY_SECOND":
            when = _rhythm_format_minutes(start_minute)
            label = f'{day_word(slot_date)} · likely second session' + (f' · around {when}' if when else '')
            window = "history-learned same-day opportunity"
            source = "RHYTHM"
        elif period == "RHYTHM_SECOND":
            when = _rhythm_format_minutes(start_minute)
            label = f'{day_word(slot_date)} · likely second session' + (f' · around {when}' if when else '')
            window = "history-learned future second-session opportunity"
            source = "RHYTHM"
        elif period == "RHYTHM":
            when = _rhythm_format_minutes(start_minute)
            label = f'{day_word(slot_date)} · learned rhythm' + (f' · around {when}' if when else '')
            window = "history-learned opportunity"
        else:
            label = "Next training opportunity · timing still learning"
            window = "timing not inferred yet"
            source = "LEARNING"
            timing_conf = "LOW"
            start_minute = None
        return {
            "date": ds, "period": period, "window": window, "label": label,
            "restriction": restriction,
            "restriction_until": next((i.get("end_date") for i in planning_context.get("upcoming_items", []) if i.get("restriction_type") == restriction and slot_date and _date_in_item(i, slot_date)), None) if restriction == "NO_INTENSITY" else None,
            "is_race": period == "RACE", "is_planned_training": period == "PLANNED",
            "event_title": event.get("title") if event else None, "event_note": event_note,
            "training_environment": training_environment, "training_demand": training_demand,
            "planning_item_id": event.get("id") if event and period == "PLANNED" else None,
            "source": source, "timing_confidence": timing_conf, "start_minute": start_minute,
            "duration_hint_min": duration_hint, "duration_hint_label": _rhythm_format_duration(duration_hint),
        }

    candidates = []
    seen_dates = set()
    today_explicit = bool(race_by_date.get(today_iso) or training_by_date.get(today_iso))

    # Explicit today commitments first, but a day-level planned commitment is
    # considered completed once today's activity history already contains work.
    if not blocked_today:
        if race_by_date.get(today_iso) and not no_intensity_today:
            candidates.append(base_slot(today, "RACE", race_by_date[today_iso]))
            seen_dates.add(today_iso)
        elif training_by_date.get(today_iso) and not today_rows:
            candidates.append(base_slot(today, "PLANNED", training_by_date[today_iso]))
            seen_dates.add(today_iso)

    # Learned same-day second session is deliberately conservative. A Daily Log is
    # not consulted here: only completed Intervals history + learned rhythm matter.
    same_day_second = False
    if (
        not blocked_today and not today_explicit and len(today_rows) == 1 and rhythm.get("state") != "LEARNING"
        and float(rhythm.get("double_propensity") or 0) >= 0.45
        and float(weekday_double.get(today.weekday()) or 0) >= 0.45
    ):
        second_start = predicted_start(today, second=True)
        now_minute = now.hour * 60 + now.minute
        if second_start is None or now_minute <= second_start + 90:
            candidates.append(base_slot(today, "SAME_DAY_SECOND", source="RHYTHM", second=True))
            seen_dates.add(today_iso)
            same_day_second = True

    # If no session is complete yet, today is only a learned opportunity when the
    # weekday pattern supports it and the typical start window has not clearly passed.
    if not today_rows and not blocked_today and not today_explicit and rhythm.get("state") != "LEARNING":
        score = float(weekday_scores.get(today.weekday()) or 0)
        start_min = predicted_start(today)
        now_min = now.hour * 60 + now.minute
        day_supported = today.weekday() in likely_weekdays if pattern_strength != "LOW" else score >= 0.45
        timing_open = start_min is None or now_min <= start_min + 120
        if day_supported and timing_open and today_iso not in seen_dates:
            candidates.append(base_slot(today, "RHYTHM"))
            seen_dates.add(today_iso)

    # Build a conservative frequency-based fallback for athletes whose training
    # weekdays are irregular but whose overall cadence is learnable.
    frequency_targets = set()
    if rhythm.get("state") != "LEARNING" and pattern_strength == "LOW":
        gap = rhythm.get("median_training_gap_days")
        if gap is None:
            days_wk = float(rhythm.get("estimated_days_per_week") or 0)
            gap = max(1, round(7.0 / days_wk)) if days_wk > 0 else 2
        gap = max(1, int(round(gap)))
        last_training = max((r["date"] for r in records if r["date"] <= today), default=today - timedelta(days=gap))
        d = last_training + timedelta(days=gap)
        while d <= today:
            d += timedelta(days=gap)
        while len(frequency_targets) < 8 and d <= today + timedelta(days=42):
            frequency_targets.add(d.isoformat())
            d += timedelta(days=gap)

    # Future dates: Calendar/race commitments always win. Otherwise expose learned
    # opportunities. A second future opportunity is emitted only when this athlete's
    # own double-session history is strong for that weekday; there is no universal
    # AM/PM assumption. The global cap remains three opportunities, not three dates.
    d = today + timedelta(days=1)
    guard = 0
    while len(candidates) < 3 and guard < 42:
        ds = d.isoformat()
        guard += 1
        if ds in blackout:
            d += timedelta(days=1)
            continue
        race = race_by_date.get(ds)
        if race and ds not in easy_only:
            candidates.append(base_slot(d, "RACE", race))
            seen_dates.add(ds)
            d += timedelta(days=1)
            continue
        planned = training_by_date.get(ds)
        if planned:
            candidates.append(base_slot(d, "PLANNED", planned))
            seen_dates.add(ds)
            d += timedelta(days=1)
            continue
        if rhythm.get("state") != "LEARNING":
            score = float(weekday_scores.get(d.weekday()) or 0)
            if pattern_strength == "LOW":
                supported = ds in frequency_targets
            else:
                supported = d.weekday() in likely_weekdays and score >= 0.25
            if supported:
                candidates.append(base_slot(d, "RHYTHM"))
                seen_dates.add(ds)
                # Preserve athlete-specific doubles in the future opportunity stream.
                # Require both a strong overall double propensity and weekday-specific
                # evidence, plus a learned second-session clock. This is deliberately
                # stricter than merely knowing that the athlete sometimes doubles.
                double_supported = (
                    len(candidates) < 3
                    and float(rhythm.get("double_propensity") or 0) >= 0.45
                    and float(weekday_double.get(d.weekday()) or 0) >= 0.45
                    and predicted_start(d, second=True) is not None
                )
                if double_supported:
                    candidates.append(base_slot(d, "RHYTHM_SECOND", source="RHYTHM", second=True))
        d += timedelta(days=1)

    # Sparse-history safety: provide one undated coaching opportunity instead of
    # fabricating Tomorrow/AM/PM. Explicit dated events already collected remain.
    if rhythm.get("state") == "LEARNING":
        has_today_explicit = bool(candidates and candidates[0].get("date") == today_iso and candidates[0].get("source") == "CALENDAR")
        if not has_today_explicit:
            candidates.insert(0, base_slot(None, "UNSCHEDULED"))

    next_slots = candidates[:3]
    if health:
        phase = "HEALTH OVERRIDE"
        headline = "Health context has priority"
        explanation = (
            f'{health.get("kind")} is active through {health.get("until")}. '
            "Learned rhythm remains visible as background, but health/restrictions decide what is actually allowed."
        )
    elif blocked_today:
        phase = "NO TRAINING"
        headline = "Today is blocked from training"
        explanation = "Calendar/health availability removes today before learned rhythm can create an opportunity."
    elif no_intensity_today:
        phase = "RESTRICTED"
        headline = "No-intensity restriction active"
        explanation = "Training may be possible, but Python limits any valid opportunity to easy aerobic/recovery work."
    elif same_day_second:
        phase = "RHYTHM · SAME-DAY"
        headline = "Another session is plausible today"
        explanation = "That possibility comes from your recent/established Intervals history — never from the Daily Log. Recovery and current context can still shorten, soften or cancel it."
    elif today_rows:
        phase = "TRAINING LOGGED"
        headline = "Today's completed work is in context"
        explanation = "THE LAB does not assume a second workout. The next opportunity is inferred from your learned rhythm or explicit Calendar commitments."
    elif rhythm.get("state") == "LEARNING":
        phase = "RHYTHM · LEARNING"
        headline = "THE LAB is learning your training rhythm"
        explanation = "There is not enough history yet to invent a training date or AM/PM slot. Timing becomes more specific as Intervals history accumulates."
    elif next_slots and next_slots[0].get("date") == today_iso:
        phase = "RHYTHM · TODAY"
        headline = "Training is plausible later today"
        explanation = "This timing comes from your observed history and remains a probability, not a commitment."
    else:
        phase = "RHYTHM · NEXT"
        headline = "Training timing follows your learned pattern"
        explanation = "Recent 14-day behavior is blended with the established 42-day rhythm and 90-day season context so sustained changes progressively replace old habits."

    if blocked_today:
        today_status, today_class = "BLOCKED", "missed"
    elif today_rows:
        today_status, today_class = f'{len(today_rows)} SESSION' + ("S" if len(today_rows) != 1 else ""), "done"
    elif no_intensity_today:
        today_status, today_class = "EASY ONLY", "upcoming"
    elif next_slots and next_slots[0].get("date") == today_iso:
        today_status, today_class = "LIKELY WINDOW", "open"
    else:
        today_status, today_class = "NO SESSION YET", "missed"
    if today_rows:
        today_detail = f'{round(today_minutes)} min completed' + (f' · load {round(today_load,1)}' if today_load else '')
    else:
        today_detail = "No completed activity logged"

    rhythm_class = "open" if rhythm.get("state") == "STABLE" else ("upcoming" if rhythm.get("state") in ("TRACKING", "ADAPTING") else "missed")
    acts_text = ", ".join(f'{a["time"]} {a["name"]}' for a in today_acts)
    minutes = now.hour * 60 + now.minute
    day_progress = round(minutes / 1440 * 100, 1)
    clock_angle = (day_progress / 100.0) * 2 * math.pi - (math.pi / 2)
    timezone_name = getattr(now.tzinfo, "key", None) or now.tzname() or "Local"
    return {
        "iso": now.isoformat(), "time": now.strftime("%I:%M %p"), "time_clock": now.strftime("%I:%M"), "time_period": now.strftime("%p"),
        "timezone": now.tzname() or timezone_name, "timezone_name": timezone_name,
        "date_label": now.strftime("%d/%m/%Y"), "phase": phase, "headline": headline, "explanation": explanation,
        # Legacy observed fields retained for old report/export compatibility only.
        "am_done": any(a["hour"] < 12 for a in today_acts if a["hour"] is not None),
        "pm_done": any(a["hour"] >= 17 for a in today_acts if a["hour"] is not None),
        "am_status": None, "pm_status": None, "am_status_class": None, "pm_status_class": None,
        "today_activity_count": len(today_acts), "today_activities_text": acts_text,
        "today_status": today_status, "today_status_class": today_class, "today_detail": today_detail,
        "rhythm": rhythm, "rhythm_status_class": rhythm_class,
        "next_slots": next_slots, "next_slot_label": next_slots[0]["label"] if next_slots else "No valid training opportunity",
        "day_progress": day_progress, "marker_x": round(90 + 68 * math.cos(clock_angle), 1), "marker_y": round(90 + 68 * math.sin(clock_angle), 1),
        "planning_summary": planning_context.get("summary", "Training as planned"),
    }




def coach_clock_text(clock):
    slot_lines = []
    for i, slot in enumerate(clock.get("next_slots") or []):
        extras = [f'source {slot.get("source") or "n/a"}', f'timing confidence {slot.get("timing_confidence") or "n/a"}']
        if slot.get("duration_hint_label"):
            extras.append(f'historical duration context {slot.get("duration_hint_label")}')
        if slot.get("is_planned_training"):
            extras.append(f'environment {slot.get("training_environment") or "n/a"}')
            extras.append(f'expected demand {slot.get("training_demand") or "COACH"}')
            if slot.get("event_note"):
                extras.append(f'note {slot.get("event_note")}')
        date_text = slot.get("date") or "date not inferred"
        slot_lines.append(f'{i+1}. {slot["label"]} ({date_text}) | restriction {slot.get("restriction", "NONE")} | ' + " | ".join(extras))
    slots = "\n".join(slot_lines) or "(none)"
    activities = clock.get("today_activities_text") or "none logged yet"
    rhythm = clock.get("rhythm") or {}
    return (
        "COACH CLOCK (authoritative adaptive timing context):\n"
        f'- Snapshot requested at {clock["time"]} {clock.get("timezone_name") or clock.get("timezone") or "local"} on {clock["date_label"]}.\n'
        f'- Current phase: {clock["phase"]}. Planning state: {clock.get("planning_summary", "Training as planned")}.\n'
        f'- Completed activities today: {activities}. Today status: {clock.get("today_status", "n/a")} ({clock.get("today_detail", "")}).\n'
        + training_rhythm_text(rhythm) + "\n"
        "- VALID NEXT TRAINING OPPORTUNITIES after Python filtering (up to 3; these are learned probabilities unless source=CALENDAR):\n"
        f"{slots}\n"
        "Never invent an AM/PM slot. Never create a second session because a Daily Log was saved. NO_INTENSITY means easy aerobic/recovery only. RACE is the event itself. PLANNED is an athlete-created commitment and outranks learned rhythm for that date."
    )




def classify_training_family(activity):
    """Classify a completed activity into a coaching family using its title first,
    then time-in-zone as a conservative fallback. This is intentionally broad: the
    goal is to stop Claude from accidentally repeating the same quality stimulus,
    not to pretend we can perfectly reverse-engineer every Zwift workout."""
    name = str(activity.get("name") or "").lower()
    compact = name.replace("-", " ").replace("_", " ")

    keyword_groups = [
        ("Recovery", ("recovery", "recuper", "easy spin", "scarico")),
        ("Sprint / Neuromuscular", ("sprint", "neuromus", "anaerobic", "anaerobico")),
        ("VO2max", ("vo2", "vo₂", "vo 2", "max aerobic")),
        ("Over-Under", ("over under", "overunder", "o&u", "over / under")),
        ("TTE", ("tte", "time to exhaustion", "time-to-exhaustion")),
        ("Threshold", ("threshold", "soglia", "ftp", "z4", "zone 4")),
        ("Sweet Spot", ("sweet spot", "sweetspot")),
        ("Tempo", ("tempo", "z3", "zone 3")),
        ("Endurance / Z2", ("z2", "zone 2", "endurance", "aerobic", "endurance ride")),
    ]
    for label, keys in keyword_groups:
        if any(k in compact for k in keys):
            return label

    zone_times = activity.get("icu_zone_times") or []
    if zone_times:
        try:
            secs = [float(z.get("secs") or 0) for z in zone_times]
            low, mod, high = bucket_zone_seconds(secs)
            total = low + mod + high
            if total > 0:
                high_pct = 100 * high / total
                mod_pct = 100 * mod / total
                if high_pct >= 15:
                    return "High Intensity / Mixed"
                if mod_pct >= 30:
                    return "Tempo / Threshold Mixed"
                if low / total >= 0.75:
                    return "Endurance / Z2"
        except (TypeError, ValueError):
            pass
    return "Other / Mixed"


def is_hard_training_family(family):
    f = (family or "").lower()
    return any(k in f for k in (
        "vo2", "threshold", "tte", "over-under", "sprint", "neuromuscular",
        "high intensity", "tempo / threshold"
    ))


def _num(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _zone_secs(value):
    if not value:
        return []
    out = []
    for z in value:
        if isinstance(z, dict):
            out.append(int(z.get("secs") or 0))
        else:
            try:
                out.append(int(z or 0))
            except (TypeError, ValueError):
                out.append(0)
    return out


def fetch_activity_detail(activity_id):
    """Fetch Intervals' analysed intervals for one completed activity.

    Single-activity fallback used if the batch endpoint is unavailable. Failure
    degrades to summary data instead of breaking the whole Snapshot.
    """
    if not activity_id:
        return None
    url = f"https://intervals.icu/api/v1/activity/{activity_id}?intervals=true"
    try:
        r = requests.get(url, headers=get_intervals_headers(), timeout=20)
        r.raise_for_status()
        return r.json()
    except Exception:
        return None


def fetch_activity_details(activity_ids):
    """Fetch up to a few activity details in one Intervals request.

    Intervals supports a comma-separated activity detail endpoint with
    intervals=true. A parallel single-activity fallback keeps the Snapshot
    resilient if that endpoint ever rejects a request.
    """
    ids = [str(x) for x in activity_ids if x]
    if not ids:
        return {}
    runtime = _resolve_intervals_runtime()
    url = (
        f"https://intervals.icu/api/v1/athlete/{runtime['athlete_id']}/activities/"
        f"{','.join(ids)}?intervals=true"
    )
    try:
        r = requests.get(url, headers=get_intervals_headers(runtime), timeout=25)
        r.raise_for_status()
        payload = r.json()
        if isinstance(payload, list):
            found = {str(x.get("id")): x for x in payload if isinstance(x, dict) and x.get("id")}
            if found:
                return found
    except Exception:
        pass

    found = {}
    with ThreadPoolExecutor(max_workers=min(3, len(ids))) as pool:
        futures = {pool.submit(fetch_activity_detail, activity_id): activity_id for activity_id in ids}
        for future in as_completed(futures):
            activity_id = futures[future]
            try:
                detail = future.result()
            except Exception:
                detail = None
            if isinstance(detail, dict):
                found[str(activity_id)] = detail
    return found


def _interval_line(interval):
    secs = int(interval.get("moving_time") or interval.get("elapsed_time") or 0)
    if secs < 45:
        return None
    mins = secs / 60.0
    dur = f"{round(mins)}m" if mins >= 2 else f"{secs}s"
    watts = _num(interval.get("average_watts"))
    hr = _num(interval.get("average_heartrate"))
    zone = interval.get("zone")
    bits = [dur]
    if watts is not None:
        bits.append(f"{round(watts)} W")
    if hr is not None:
        bits.append(f"HR {round(hr)}")
    if zone is not None:
        bits.append(f"Z{zone}")
    return " · ".join(bits)


def _zone_summary(zone_secs):
    parts = []
    for idx, secs in enumerate(zone_secs or [], start=1):
        secs = int(secs or 0)
        if secs <= 0:
            continue
        if secs >= 60:
            parts.append(f"Z{idx} {round(secs / 60)}m")
        else:
            parts.append(f"Z{idx} {secs}s")
    return " · ".join(parts[:7])


def _is_heat_name(name):
    return bool(re.search(r"\bHEAT\b", str(name or ""), flags=re.IGNORECASE))


def build_previous_training_blocks(recent_activities, limit=3):
    """Most recent completed activities enriched with Intervals interval detail."""
    now = get_rome_now().replace(tzinfo=None)
    candidates = []
    for a in recent_activities or []:
        dt = parse_local_activity_datetime(a.get("start_date_local") or "")
        if dt and dt <= now:
            candidates.append((dt, a))
    candidates.sort(key=lambda x: x[0], reverse=True)
    candidates = candidates[:limit]
    details = fetch_activity_details([a.get("id") for _, a in candidates])

    blocks = []
    for dt, summary in candidates:
        detail = details.get(str(summary.get("id"))) or summary
        name = detail.get("name") or summary.get("name") or "Activity"
        is_heat = _is_heat_name(name)
        intervals = detail.get("icu_intervals") or []
        work = []
        for it in intervals:
            # Intervals currently documents WORK and RECOVERY interval types.
            if str(it.get("type") or "WORK").upper() != "WORK":
                continue
            line = _interval_line(it)
            if line:
                work.append(line)
        if not work:
            for it in intervals:
                line = _interval_line(it)
                if line:
                    work.append(line)
        work = work[:6]

        pz = _zone_secs(detail.get("icu_zone_times") or summary.get("icu_zone_times"))
        hz = _zone_secs(detail.get("icu_hr_zone_times") or summary.get("icu_hr_zone_times"))
        dec = _num(detail.get("decoupling") if detail.get("decoupling") is not None else summary.get("decoupling"))
        family = classify_training_family(detail)
        avg_w = _num(detail.get("average_watts") or summary.get("average_watts"))
        avg_hr = _num(detail.get("average_heartrate") or summary.get("average_heartrate"))
        ftp = detail.get("icu_ftp") or summary.get("icu_ftp")
        pz_text = _zone_summary(pz)
        hz_text = _zone_summary(hz)

        if is_heat:
            if dec is not None and dec >= 5:
                consideration = "🔥 HEAT signature · meaningful cardiovascular drift. Treat the mechanical load and thermal/autonomic strain as separate stressors."
            else:
                consideration = "🔥 HEAT signature · interpret average watts cautiously: thermal strain can raise cardiovascular cost without raising mechanical output."
        elif is_hard_training_family(family):
            consideration = "⚡ Quality stimulus · include this in hard-session spacing before prescribing the next intensity block."
        else:
            consideration = "🫀 Aerobic context · use zone distribution and HR response, not average power alone, when judging recovery cost."

        blocks.append({
            "date": dt.date().isoformat(), "time": dt.strftime("%I:%M %p"), "name": name,
            "heat": is_heat, "family": family,
            "duration_min": round((detail.get("moving_time") or summary.get("moving_time") or 0) / 60),
            "load": detail.get("icu_training_load", summary.get("icu_training_load")),
            "avg_watts": round(avg_w) if avg_w is not None else None,
            "avg_hr": round(avg_hr) if avg_hr is not None else None,
            "decoupling": round(dec, 1) if dec is not None else None,
            "ftp": ftp, "power_zones": pz, "hr_zones": hz,
            "power_zone_summary": pz_text, "hr_zone_summary": hz_text,
            "intervals": work, "consideration": consideration,
        })
    return blocks

def previous_training_blocks_text(blocks):
    if not blocks:
        return "PREVIOUS TRAINING BLOCKS:\n- No completed activity detail available."
    lines = ["PREVIOUS TRAINING BLOCKS (Intervals.icu analysed detail — use these before interpreting recovery):"]
    for b in blocks:
        tag = "HEAT" if b.get("heat") else b.get("family")
        lines.append(
            f'- {b["date"]} {b["time"]} | {tag} | {b["name"]} | {b["duration_min"]} min | '
            f'load {b.get("load")} | avg {b.get("avg_watts") or "n/a"} W / HR {b.get("avg_hr") or "n/a"} | '
            f'decoupling {b.get("decoupling") if b.get("decoupling") is not None else "n/a"}% | FTP {b.get("ftp") or "n/a"} W'
        )
        if b.get("power_zone_summary"):
            lines.append("  Power zones: " + b["power_zone_summary"])
        if b.get("hr_zone_summary"):
            lines.append("  HR zones: " + b["hr_zone_summary"])
        if b.get("intervals"):
            lines.append("  Intervals: " + " ; ".join(b["intervals"]))
        lines.append("  Interpretation cue: " + b["consideration"])
    return "\n".join(lines)


def _daily_training_map(activities):
    days = {}
    for a in activities or []:
        ds = str(a.get("start_date_local") or "")[:10]
        if not ds:
            continue
        d = days.setdefault(ds, {"load": 0.0, "heat": False, "names": []})
        d["load"] += _num(a.get("icu_training_load")) or 0.0
        name = a.get("name") or ""
        d["names"].append(name)
        if _is_heat_name(name):
            d["heat"] = True
    return days

def build_heat_response_pattern(season_activities, season_wellness):
    """Build season-aware HEAT response and adaptation intelligence.

    HEAT is identified only from deliberately named HEAT activities.  The current
    thermal season is data-defined as the latest contiguous HEAT block inside the
    90-day Product window; a gap >28 days starts a new block so distant winter and
    summer protocols are not silently treated as physiologically equivalent.

    The detector keeps three questions separate:
      1) acute next-morning response (HRV and other wellness perturbations),
      2) HEAT specificity versus same-season load-matched non-HEAT training days,
      3) adaptation/tolerance trend from early to recent exposures in this HEAT block.

    These are observational signals, not direct measurements of plasma volume,
    core temperature, sweat rate or heat acclimation.  Missing signals stay ASSESSING.
    """
    wellness = {str(w.get("id")): w for w in season_wellness or [] if w.get("id")}
    days = _daily_training_map(season_activities)

    # Aggregate the cardiovascular signature of named HEAT activities by day.  Use
    # actual average power (icu_average_watts first) rather than normalized power.
    heat_features = {}
    heat_dates = []
    for a in season_activities or []:
        name = str(a.get("name") or "")
        if not _is_heat_name(name):
            continue
        ds = str(a.get("start_date_local") or "")[:10]
        try:
            d = date.fromisoformat(ds)
        except Exception:
            continue
        heat_dates.append(d)
        rec = heat_features.setdefault(ds, {
            "duration_s": 0.0, "power_num": 0.0, "power_den": 0.0,
            "hr_num": 0.0, "hr_den": 0.0, "dec_num": 0.0, "dec_den": 0.0,
        })
        secs = max(0.0, _num(a.get("moving_time") or a.get("elapsed_time")) or 0.0)
        weight = secs if secs > 0 else 1.0
        rec["duration_s"] += secs
        watts = _num(a.get("icu_average_watts"))
        if watts is None:
            watts = _num(a.get("average_watts"))
        hr = _num(a.get("average_heartrate"))
        if watts is not None and 40 <= watts <= 600:
            rec["power_num"] += watts * weight
            rec["power_den"] += weight
        if hr is not None and 50 <= hr <= 220:
            rec["hr_num"] += hr * weight
            rec["hr_den"] += weight
        dec = _num(a.get("decoupling"))
        if dec is not None and abs(dec) <= 40:
            rec["dec_num"] += dec * weight
            rec["dec_den"] += weight

    heat_dates = sorted(set(heat_dates))
    season_start = season_end = None
    if heat_dates:
        season_end = heat_dates[-1]
        season_start = season_end
        cursor = season_end
        for d in reversed(heat_dates[:-1]):
            if (cursor - d).days > 28:
                break
            season_start = d
            cursor = d

    finalized_heat = {}
    for ds, rec in heat_features.items():
        try:
            d = date.fromisoformat(ds)
        except Exception:
            continue
        if season_start and season_end and not (season_start <= d <= season_end):
            continue
        watts = rec["power_num"] / rec["power_den"] if rec["power_den"] else None
        hr = rec["hr_num"] / rec["hr_den"] if rec["hr_den"] else None
        dec = rec["dec_num"] / rec["dec_den"] if rec["dec_den"] else None
        finalized_heat[ds] = {
            "avg_watts": watts, "avg_hr": hr,
            "power_hr_ratio": (watts / hr) if watts is not None and hr else None,
            "decoupling": dec,
            "duration_min": rec["duration_s"] / 60.0 if rec["duration_s"] else None,
        }

    def _w_value(ds, field):
        row = wellness.get(ds) or {}
        if field == "restingHR" and _intervals_temp_flag(row, "tempRestingHR"):
            return None
        return _num(row.get(field))

    def _prior_median(field, exposure_day, minimum=3):
        vals = []
        for back in range(1, 8):
            v = _w_value((exposure_day - timedelta(days=back)).isoformat(), field)
            if v is not None:
                vals.append(v)
        return statistics.median(vals) if len(vals) >= minimum else None

    # Build same-season training-day records.  HEAT rows may contribute to adaptation
    # even if HRV is missing, while HRV specificity uses only genuinely paired rows.
    heat_rows = []
    hrv_samples = []
    controls = []
    if season_start and season_end:
        for ds, info in sorted(days.items()):
            try:
                d = date.fromisoformat(ds)
            except ValueError:
                continue
            if not (season_start <= d <= season_end):
                continue
            next_ds = (d + timedelta(days=1)).isoformat()
            hrv = _w_value(next_ds, "hrv")
            hrv_base = _prior_median("hrv", d)
            hrv_delta = ((hrv - hrv_base) / hrv_base * 100.0) if hrv is not None and hrv_base else None
            if not info.get("heat"):
                if hrv_delta is not None:
                    controls.append({"date": ds, "day": d, "delta_pct": hrv_delta, "load": info["load"]})
                continue

            rhr = _w_value(next_ds, "restingHR")
            rhr_base = _prior_median("restingHR", d)
            sleep_score = _w_value(next_ds, "sleepScore")
            sleep_score_base = _prior_median("sleepScore", d)
            sleep_secs = _w_value(next_ds, "sleepSecs")
            sleep_secs_base = _prior_median("sleepSecs", d)
            feat = finalized_heat.get(ds) or {}
            row = {
                "date": ds, "day": d, "load": info["load"],
                "hrv_delta_pct": hrv_delta,
                "rhr_delta_bpm": (rhr - rhr_base) if rhr is not None and rhr_base is not None else None,
                "sleep_score_delta": (sleep_score - sleep_score_base) if sleep_score is not None and sleep_score_base is not None else None,
                "sleep_delta_min": ((sleep_secs - sleep_secs_base) / 60.0) if sleep_secs is not None and sleep_secs_base is not None else None,
                "avg_watts": feat.get("avg_watts"), "avg_hr": feat.get("avg_hr"),
                "power_hr_ratio": feat.get("power_hr_ratio"), "decoupling": feat.get("decoupling"),
                "duration_min": feat.get("duration_min"),
            }
            heat_rows.append(row)
            if hrv_delta is not None:
                hrv_samples.append({"date": ds, "day": d, "delta_pct": hrv_delta, "load": info["load"]})

    # Same-season, unique, load-matched controls.  This directly answers whether the
    # HRV disturbance is stronger after HEAT than after ordinary training of similar load.
    matched_controls = []
    used_control_dates = set()
    for sample in hrv_samples:
        tol = max(15.0, abs(sample["load"]) * 0.35)
        eligible = [
            c for c in controls
            if c["date"] not in used_control_dates and abs(c["load"] - sample["load"]) <= tol
        ]
        if eligible:
            chosen = min(eligible, key=lambda c: (abs(c["load"] - sample["load"]), abs((c["day"] - sample["day"]).days)))
            matched_controls.append(chosen)
            used_control_dates.add(chosen["date"])
    if len(matched_controls) >= 3:
        comparator_pool = matched_controls
        comparator_mode = "LOAD-MATCHED"
    else:
        comparator_pool = controls
        comparator_mode = "BROAD"

    neg = [x for x in hrv_samples if x["delta_pct"] < -3.0]
    n = len(hrv_samples)
    median_delta = statistics.median([x["delta_pct"] for x in hrv_samples]) if hrv_samples else None
    control_delta = statistics.median([x["delta_pct"] for x in comparator_pool]) if comparator_pool else None
    consistency = len(neg) / n if n else 0.0
    specificity_gap = (median_delta - control_delta) if median_delta is not None and control_delta is not None else None

    if n < 3:
        specificity_state = "ASSESSING"
        specificity_confidence = "ASSESSING"
        specificity_headline = "Too few paired next-morning HRV observations to judge whether HEAT has a specific autonomic effect."
    elif control_delta is None or len(comparator_pool) < 3:
        specificity_state = "HEAT RESPONSE OBSERVED"
        specificity_confidence = "LOW"
        specificity_headline = "A post-HEAT HRV response is observable, but same-season non-HEAT comparators are still insufficient to call it HEAT-specific."
    else:
        if n >= 8 and len(comparator_pool) >= 5 and comparator_mode == "LOAD-MATCHED":
            specificity_confidence = "HIGH"
        elif n >= 5 and len(comparator_pool) >= 3:
            specificity_confidence = "MODERATE"
        else:
            specificity_confidence = "LOW"
        if specificity_gap <= -3.0 and consistency >= 0.60:
            specificity_state = "HEAT-SPECIFIC HRV PENALTY"
            specificity_headline = f"Post-HEAT HRV is {abs(specificity_gap):.1f} pp more suppressed than the {comparator_mode.lower()} non-HEAT comparator."
        elif specificity_gap <= -3.0:
            specificity_state = "POSSIBLE HEAT-SPECIFIC PENALTY"
            specificity_headline = f"Median post-HEAT HRV is {abs(specificity_gap):.1f} pp lower than controls, but the response is not consistent enough across exposures yet."
        elif specificity_gap >= 3.0:
            specificity_state = "NO HEAT-SPECIFIC HRV PENALTY"
            specificity_headline = f"Post-HEAT HRV is {specificity_gap:.1f} pp less suppressed than comparable non-HEAT training days; the observed drop is not uniquely worse after HEAT."
        else:
            specificity_state = "NO CLEAR HEAT-SPECIFIC DIFFERENCE"
            specificity_headline = f"Post-HEAT HRV differs from the non-HEAT comparator by only {specificity_gap:+.1f} pp, so a distinct HEAT penalty is not established."

    def _med(rows, key):
        vals = [x.get(key) for x in rows if isinstance(x.get(key), (int, float))]
        return statistics.median(vals) if vals else None

    def _sig(label, early, recent, threshold, better="higher", unit="", decimals=1, change_unit=None):
        if early is None or recent is None:
            return None, 0
        delta = recent - early
        if better == "higher":
            grade = 1 if delta >= threshold else (-1 if delta <= -threshold else 0)
        else:
            grade = 1 if delta <= -threshold else (-1 if delta >= threshold else 0)
        state = "IMPROVING" if grade > 0 else ("WORSENING" if grade < 0 else "STABLE")
        fmt = f"{{:.{decimals}f}}"
        if unit == "%":
            early_text, recent_text = fmt.format(early) + "%", fmt.format(recent) + "%"
        elif unit:
            early_text, recent_text = fmt.format(early) + f" {unit}", fmt.format(recent) + f" {unit}"
        else:
            early_text, recent_text = fmt.format(early), fmt.format(recent)
        cu = change_unit if change_unit is not None else unit
        if cu == "pp":
            change = f"{delta:+.{decimals}f} pp"
        elif cu == "%":
            change = f"{delta:+.{decimals}f}%"
        elif cu:
            change = f"{delta:+.{decimals}f} {cu}"
        else:
            change = f"{delta:+.{decimals}f}"
        return {"label": label, "early": early_text, "recent": recent_text, "change": change, "state": state, "state_class": state.lower()}, grade

    adaptation_signals = []
    grades = []
    early_rows = recent_rows = []
    if len(heat_rows) >= 6:
        k = min(8, max(3, len(heat_rows) // 3))
        early_rows, recent_rows = heat_rows[:k], heat_rows[-k:]

        for args in (
            ("Next-morning HRV vs baseline", _med(early_rows, "hrv_delta_pct"), _med(recent_rows, "hrv_delta_pct"), 2.0, "higher", "%", 1, "pp"),
            ("Next-morning resting HR", _med(early_rows, "rhr_delta_bpm"), _med(recent_rows, "rhr_delta_bpm"), 1.5, "lower", "bpm", 1, "bpm"),
            ("Next-morning sleep score", _med(early_rows, "sleep_score_delta"), _med(recent_rows, "sleep_score_delta"), 3.0, "higher", "pts", 1, "pts"),
            ("Next-morning sleep duration", _med(early_rows, "sleep_delta_min"), _med(recent_rows, "sleep_delta_min"), 15.0, "higher", "min", 0, "min"),
            ("HEAT decoupling", _med(early_rows, "decoupling"), _med(recent_rows, "decoupling"), 1.0, "lower", "%", 1, "pp"),
        ):
            sig, grade = _sig(*args)
            if sig:
                adaptation_signals.append(sig); grades.append(grade)

        # Directly capture the user's "same watts, fewer beats" adaptation signal when
        # power is similar.  If protocol power changed materially, fall back to W/bpm.
        ew, rw = _med(early_rows, "avg_watts"), _med(recent_rows, "avg_watts")
        eh, rh = _med(early_rows, "avg_hr"), _med(recent_rows, "avg_hr")
        er, rr = _med(early_rows, "power_hr_ratio"), _med(recent_rows, "power_hr_ratio")
        similar_power = bool(ew and rw and abs(rw - ew) / max((rw + ew) / 2.0, 1.0) <= 0.10)
        if similar_power and eh is not None and rh is not None:
            hr_delta = rh - eh
            grade = 1 if hr_delta <= -2.0 else (-1 if hr_delta >= 2.0 else 0)
            state = "IMPROVING" if grade > 0 else ("WORSENING" if grade < 0 else "STABLE")
            adaptation_signals.append({
                "label": "HR cost at similar HEAT power",
                "early": f"{ew:.0f} W / {eh:.0f} bpm", "recent": f"{rw:.0f} W / {rh:.0f} bpm",
                "change": f"HR {hr_delta:+.1f} bpm · power {(rw/ew-1)*100:+.1f}%",
                "state": state, "state_class": state.lower(),
            })
            grades.append(grade)
        elif er is not None and rr is not None and er > 0:
            ratio_change = (rr / er - 1.0) * 100.0
            grade = 1 if ratio_change >= 2.0 else (-1 if ratio_change <= -2.0 else 0)
            state = "IMPROVING" if grade > 0 else ("WORSENING" if grade < 0 else "STABLE")
            adaptation_signals.append({
                "label": "HEAT power / HR efficiency",
                "early": f"{er:.3f} W/bpm", "recent": f"{rr:.3f} W/bpm",
                "change": f"{ratio_change:+.1f}%", "state": state, "state_class": state.lower(),
            })
            grades.append(grade)

    # Protocol comparability is deliberately explicit: less HR drift after a radically
    # easier HEAT protocol is not treated as acclimation.
    comparability_note = "Protocol comparability is still assessing."
    protocol_comparable = None
    if early_rows and recent_rows:
        el, rl = _med(early_rows, "load"), _med(recent_rows, "load")
        ed, rd = _med(early_rows, "duration_min"), _med(recent_rows, "duration_min")
        checks = []
        if el and rl:
            checks.append(abs(rl - el) / max((rl + el) / 2.0, 1.0) <= 0.25)
        if ed and rd:
            checks.append(abs(rd - ed) / max((rd + ed) / 2.0, 1.0) <= 0.25)
        if checks:
            protocol_comparable = all(checks)
            comparability_note = (
                "Early and recent HEAT protocol load/duration are broadly comparable, strengthening the longitudinal read."
                if protocol_comparable else
                "HEAT protocol load/duration changed materially; adaptation signals are shown but confidence is capped because the stimulus itself is not equivalent."
            )

    usable_signal_count = len(grades)
    if len(heat_rows) < 6 or usable_signal_count < 2:
        adaptation_state = "ASSESSING"
        adaptation_confidence = "ASSESSING"
        adaptation_headline = "More paired exposures are needed before THE LAB compares early-season and recent HEAT tolerance."
    else:
        score = sum(grades)
        improving = sum(1 for g in grades if g > 0)
        worsening = sum(1 for g in grades if g < 0)
        if score >= 2:
            adaptation_state = "IMPROVING"
            adaptation_headline = f"Recent HEAT exposures show lower physiological cost on {improving} tracked signal{'s' if improving != 1 else ''} versus the early part of this HEAT season."
        elif score <= -2:
            adaptation_state = "WORSENING"
            adaptation_headline = f"Recent HEAT exposures show greater physiological cost on {worsening} tracked signal{'s' if worsening != 1 else ''}; accumulated strain or a changed protocol should be considered."
        elif improving and worsening:
            adaptation_state = "MIXED"
            adaptation_headline = "Some tolerance signals are improving while others are not, so THE LAB does not collapse the response into a single acclimation claim."
        else:
            adaptation_state = "STABLE"
            adaptation_headline = "Early and recent HEAT responses are broadly similar across the available signals."
        if len(heat_rows) >= 12 and usable_signal_count >= 3:
            adaptation_confidence = "HIGH"
        elif len(heat_rows) >= 8 and usable_signal_count >= 2:
            adaptation_confidence = "MODERATE"
        else:
            adaptation_confidence = "LOW"
        if protocol_comparable is False and adaptation_confidence in {"HIGH", "MODERATE"}:
            adaptation_confidence = "LOW"

    adaptation_class = adaptation_state.lower().replace(" ", "-")
    specificity_class = specificity_confidence.lower().replace(" ", "-")

    if median_delta is None:
        acute_headline = "Next-morning HRV response is still assessing."
    else:
        acute_headline = f"Median next-morning HRV is {median_delta:+.1f}% versus its preceding 7-day baseline after HEAT."

    if specificity_state == "HEAT-SPECIFIC HRV PENALTY":
        interpretation = "A repeatable HEAT-specific autonomic cost is present in the current thermal season; adaptation is evaluated separately so a lower recent cost can emerge even when the acute effect remains real."
    elif specificity_state == "POSSIBLE HEAT-SPECIFIC PENALTY":
        interpretation = "A possible HEAT-specific autonomic cost is present, but exposure-to-exposure consistency is not yet strong enough for a firm call."
    elif specificity_state in {"NO HEAT-SPECIFIC HRV PENALTY", "NO CLEAR HEAT-SPECIFIC DIFFERENCE"}:
        interpretation = "HRV can fall after HEAT, but the current same-season comparison does not show a clearly larger penalty than ordinary training of similar load. Adaptation is therefore judged from the longitudinal multi-signal trend, not from HRV suppression alone."
    else:
        interpretation = "THE LAB is separating ordinary training stress from a HEAT-specific response while it builds enough same-season evidence for a reliable conclusion."

    comparator = None
    if control_delta is not None and len(comparator_pool) >= 3:
        comparator = (
            f"{comparator_mode.title()} non-HEAT comparator: {control_delta:+.1f}% median next-morning HRV deviation "
            f"({len(comparator_pool)} days)."
        )

    # Use the most recent wellness day that actually contains HRV.
    hrv_dates = sorted(ds for ds, w in wellness.items() if _num(w.get("hrv")) is not None)
    latest_w = hrv_dates[-1] if hrv_dates else None
    latest_hrv = _w_value(latest_w, "hrv") if latest_w else None
    previous_day = (date.fromisoformat(latest_w) - timedelta(days=1)).isoformat() if latest_w else None
    current_heat = bool(previous_day and (days.get(previous_day) or {}).get("heat"))
    hrv_low_ref = GARMIN_BASELINES.get("hrv_low")
    if not isinstance(hrv_low_ref, (int, float)):
        historical_hrv = [_w_value(ds, "hrv") for ds in hrv_dates[:-1]]
        learned_hrv = _robust_dynamic_range(historical_hrv)
        hrv_low_ref = learned_hrv[0] if learned_hrv else None
    current_relevance = bool(current_heat and latest_hrv is not None and isinstance(hrv_low_ref, (int, float)) and latest_hrv < hrv_low_ref)
    current_note = (
        "The latest below-baseline HRV was recorded the morning after a named HEAT exposure. Treat it as current thermal-load context and interpret it alongside resting HR, sleep, subjective status and performance."
        if current_relevance else None
    )

    season_exposures = len([d for d in heat_dates if season_start and season_end and season_start <= d <= season_end])
    season_definition = "latest contiguous HEAT block; a >28-day gap starts a new thermal season"
    method_note = "Season-aware observational model only: without ambient/core temperature, sweat rate or plasma-volume measurements, THE LAB can identify tolerance patterns but cannot claim a measured heat-acclimation mechanism."

    return {
        "available": bool(season_exposures),
        "confidence": specificity_confidence, "confidence_class": specificity_class,
        "samples": n, "negative_count": len(neg), "consistency_pct": round(consistency * 100),
        "median_delta_pct": round(median_delta, 1) if median_delta is not None else None,
        "control_delta_pct": round(control_delta, 1) if control_delta is not None else None,
        "control_samples": len(comparator_pool), "control_mode": comparator_mode,
        "headline": acute_headline, "acute_headline": acute_headline, "comparator": comparator,
        "specificity_state": specificity_state, "specificity_confidence": specificity_confidence,
        "specificity_class": specificity_class,
        "specificity_gap_pp": round(specificity_gap, 1) if specificity_gap is not None else None,
        "specificity_headline": specificity_headline,
        "adaptation_state": adaptation_state, "adaptation_confidence": adaptation_confidence,
        "adaptation_class": adaptation_class, "adaptation_headline": adaptation_headline,
        "adaptation_signals": adaptation_signals,
        "adaptation_samples": len(heat_rows), "adaptation_early_samples": len(early_rows), "adaptation_recent_samples": len(recent_rows),
        "season_start": season_start.isoformat() if season_start else None,
        "season_end": season_end.isoformat() if season_end else None,
        "season_exposures": season_exposures, "season_definition": season_definition,
        "interpretation": interpretation, "comparability_note": comparability_note, "method_note": method_note,
        "current_relevance": current_relevance, "current_note": current_note,
        "confidence_note": specificity_headline,
    }


def heat_response_pattern_text(pattern):
    if not pattern or not pattern.get("available"):
        return "PERSONAL HEAT ADAPTATION:\n- No usable current HEAT season yet. Do not infer heat adaptation."

    # Backward-compatible rendering for a stored report created before V4.8.17.
    if pattern.get("adaptation_state") is None:
        lines = ["PERSONAL HEAT RESPONSE PATTERN (legacy stored model; correlation is not causation):",
                 f'- Confidence: {pattern.get("confidence", "n/a")} | paired HEAT days {pattern.get("samples", 0)} | HRV >3% below prior 7-day median on {pattern.get("negative_count", 0)}/{pattern.get("samples", 0)} ({pattern.get("consistency_pct", 0)}%).',
                 '- ' + str(pattern.get("headline") or "No clear conclusion.")]
        if pattern.get("comparator"):
            lines.append('- ' + pattern["comparator"])
        return "\n".join(lines)

    lines = ["PERSONAL HEAT ADAPTATION INTELLIGENCE (Python; observational, season-aware):"]
    if pattern.get("season_start") and pattern.get("season_end"):
        lines.append(f'- Current HEAT season: {pattern["season_start"]} → {pattern["season_end"]} | {pattern.get("season_exposures", 0)} exposure days. {pattern.get("season_definition", "")}')
    lines.append(f'- Acute response: {pattern.get("acute_headline", "ASSESSING")} {pattern.get("negative_count", 0)}/{pattern.get("samples", 0)} paired HEAT days exceeded 3% HRV suppression.')
    lines.append(f'- HEAT specificity: {pattern.get("specificity_state", "ASSESSING")} | confidence {pattern.get("specificity_confidence", "ASSESSING")}. {pattern.get("specificity_headline", "")}')
    if pattern.get("comparator"):
        lines.append('- ' + pattern["comparator"])
    lines.append(f'- Adaptation/tolerance: {pattern.get("adaptation_state", "ASSESSING")} | confidence {pattern.get("adaptation_confidence", "ASSESSING")}. {pattern.get("adaptation_headline", "")}')
    for sig in pattern.get("adaptation_signals") or []:
        lines.append(f'- Adaptation signal · {sig.get("label")}: {sig.get("early")} → {sig.get("recent")} ({sig.get("change")}) · {sig.get("state")}')
    if pattern.get("comparability_note"):
        lines.append('- Protocol check: ' + pattern["comparability_note"])
    if pattern.get("current_note"):
        lines.append('- CURRENT CONTEXT: ' + pattern["current_note"])
    lines.append('- Interpretation rule: never equate this observational trend with measured plasma-volume expansion, core-temperature adaptation or sweat-rate adaptation unless those measurements actually exist.')
    return "\n".join(lines)


def build_aerobic_efficiency(season_activities, now=None):
    """Track repeatable aerobic power/HR behaviour in comparable steady Z2 rides.

    HEAT sessions are deliberately excluded because their purpose is to increase
    cardiovascular strain. The ratio is a longitudinal context metric, not a
    laboratory measure of mechanical or metabolic efficiency. Intervals' own
    decoupling value is retained alongside it as the durability signal.

    V4.8.13 eligibility rule: normal warm-up/cool-down must not disqualify an
    otherwise aerobic ride merely because whole-file VI is a little above 1.12.
    When power-zone time is available, >=75% in the low bucket (Z1+Z2 in the
    existing Product bucketing) is accepted as steadiness evidence up to VI 1.20.
    Without zone evidence the historical VI <=1.12 guard remains conservative.

    V4.8.16 data-plumbing fix: the Intervals activity summary field for actual
    average power is icu_average_watts. Older code requested/read average_watts,
    which can be absent even when the activity has perfectly valid power data.
    """
    now = now or get_rome_now()
    today = now.date()
    recent_start = today - timedelta(days=13)
    prior_start = today - timedelta(days=41)
    prior_end = today - timedelta(days=14)
    candidates = []
    recent_diag = {
        "z2_detected": 0, "accepted": 0, "too_short": 0, "missing_power_hr": 0,
        "implausible_power_hr": 0, "zone_mix": 0, "variability": 0, "heat": 0,
    }

    for a in season_activities or []:
        if classify_training_family(a) != "Endurance / Z2":
            continue
        raw = str(a.get("start_date_local") or "")[:10]
        try:
            d = date.fromisoformat(raw)
        except Exception:
            continue
        is_recent = recent_start <= d <= today
        if is_recent:
            recent_diag["z2_detected"] += 1
        if _is_heat_name(a.get("name")):
            if is_recent:
                recent_diag["heat"] += 1
            continue

        secs = _num(a.get("moving_time") or a.get("elapsed_time"))
        if secs is None or secs < 2400:
            if is_recent:
                recent_diag["too_short"] += 1
            continue
        # Intervals activity-level average power is exposed as icu_average_watts.
        # Keep average_watts as a compatibility fallback for older/detail payloads,
        # but never substitute normalized/weighted power into the Power/HR ratio.
        watts = _num(a.get("icu_average_watts"))
        if watts is None:
            watts = _num(a.get("average_watts"))
        hr = _num(a.get("average_heartrate"))
        if watts is None or hr is None:
            if is_recent:
                recent_diag["missing_power_hr"] += 1
            continue
        if not (80 <= watts <= 500 and 80 <= hr <= 210):
            if is_recent:
                recent_diag["implausible_power_hr"] += 1
            continue

        zone_secs = _zone_secs(a.get("icu_zone_times"))
        low_share = None
        if zone_secs:
            try:
                low, mod, high = bucket_zone_seconds(zone_secs)
                zone_total = low + mod + high
                if zone_total > 0:
                    low_share = low / zone_total
            except (TypeError, ValueError):
                low_share = None
        if low_share is not None and low_share < 0.75:
            if is_recent:
                recent_diag["zone_mix"] += 1
            continue

        vi = _num(a.get("icu_variability_index"))
        if vi is not None and vi > 1.20:
            if is_recent:
                recent_diag["variability"] += 1
            continue
        if vi is not None and vi > 1.12 and low_share is None:
            if is_recent:
                recent_diag["variability"] += 1
            continue

        trainer = a.get("trainer") is True or str(a.get("trainer") or "").lower() == "true"
        dec = _num(a.get("decoupling"))
        if dec is not None and abs(dec) > 40:
            dec = None
        candidates.append({
            "date": d, "date_iso": raw, "environment": "INDOOR" if trainer else "OUTDOOR",
            "watts": watts, "hr": hr, "ratio": watts / hr, "decoupling": dec,
            "duration_min": round(float(secs) / 60.0), "name": a.get("name") or "Endurance / Z2",
            "vi": round(vi, 3) if vi is not None else None,
            "low_zone_pct": round(low_share * 100.0, 1) if low_share is not None else None,
            "steadiness_evidence": "LOW-ZONE DOMINANT" if low_share is not None else ("VI" if vi is not None else "TITLE + DURATION"),
        })
        if is_recent:
            recent_diag["accepted"] += 1

    def split(items):
        recent = [x for x in items if recent_start <= x["date"] <= today]
        prior = [x for x in items if prior_start <= x["date"] <= prior_end]
        return recent, prior

    chosen_env = None
    selected = candidates
    viable = []
    for env in ("INDOOR", "OUTDOOR"):
        group = [x for x in candidates if x["environment"] == env]
        rec, old = split(group)
        if len(rec) >= 2 and len(old) >= 3:
            viable.append((len(rec) + len(old), env, group))
    if viable:
        _, chosen_env, selected = max(viable, key=lambda x: x[0])
    recent, prior = split(selected)

    result = {
        "available": len(recent) >= 2,
        "cohort": chosen_env or "MIXED",
        "cohort_label": f"{chosen_env.title()} steady Z2" if chosen_env else "Steady Z2 · mixed environment",
        "recent_samples": len(recent), "baseline_samples": len(prior),
        "recent_decoupling_samples": sum(1 for x in recent if x.get("decoupling") is not None),
        "baseline_decoupling_samples": sum(1 for x in prior if x.get("decoupling") is not None),
        "recent_ratio": None, "baseline_ratio": None, "trend_pct": None,
        "recent_decoupling": None, "baseline_decoupling": None, "decoupling_change": None,
        "status": "LEARNING", "status_class": "grey", "confidence": "LOW",
        "headline": "More comparable steady Z2 sessions are needed before THE LAB calls a trend.",
        "latest_sessions": [],
        "recent_eligibility": recent_diag,
        "eligibility_note": "",
        "note": "HEAT sessions are excluded so deliberate thermal cardiovascular strain does not contaminate the normal aerobic baseline.",
    }
    excluded = max(0, recent_diag["z2_detected"] - recent_diag["accepted"])
    if recent_diag["z2_detected"]:
        result["eligibility_note"] = f"Eligibility · {recent_diag['z2_detected']} recent Z2 detected · {recent_diag['accepted']} comparable"
        if excluded:
            reason_labels = []
            for key, label in (("too_short", "short"), ("missing_power_hr", "missing power/HR"), ("implausible_power_hr", "invalid power/HR"), ("zone_mix", "mixed zones"), ("variability", "high variability"), ("heat", "HEAT")):
                if recent_diag.get(key):
                    reason_labels.append(f"{label} {recent_diag[key]}")
            if reason_labels:
                result["eligibility_note"] += " · excluded " + ", ".join(reason_labels)
    else:
        result["eligibility_note"] = "Eligibility · no recent Z2-labelled/zone-classified rides detected"
    if recent:
        result["recent_ratio"] = round(statistics.median(x["ratio"] for x in recent), 3)
        recent_dec = [x["decoupling"] for x in recent if x.get("decoupling") is not None]
        if recent_dec:
            result["recent_decoupling"] = round(statistics.median(recent_dec), 1)
    if prior:
        result["baseline_ratio"] = round(statistics.median(x["ratio"] for x in prior), 3)
        prior_dec = [x["decoupling"] for x in prior if x.get("decoupling") is not None]
        if prior_dec:
            result["baseline_decoupling"] = round(statistics.median(prior_dec), 1)
    if result["recent_ratio"] is not None and result["baseline_ratio"]:
        result["trend_pct"] = round((result["recent_ratio"] / result["baseline_ratio"] - 1.0) * 100.0, 1)
    if result["recent_decoupling"] is not None and result["baseline_decoupling"] is not None:
        result["decoupling_change"] = round(result["recent_decoupling"] - result["baseline_decoupling"], 1)

    if len(recent) >= 3 and len(prior) >= 5:
        result["confidence"] = "HIGH"
    elif len(recent) >= 2 and len(prior) >= 3:
        result["confidence"] = "MODERATE"

    trend = result.get("trend_pct")
    recent_dec = result.get("recent_decoupling")
    old_dec = result.get("baseline_decoupling")
    if trend is not None:
        baseline_ready = result.get("baseline_samples", 0) >= 3 and result.get("baseline_decoupling_samples", 0) >= 3 and result.get("confidence") in ("MODERATE", "HIGH")
        if not baseline_ready:
            result["status"], result["status_class"] = "LEARNING", "grey"
            if recent_dec is not None and old_dec is not None:
                result["headline"] = f"Provisional decoupling difference is {recent_dec-old_dec:+.1f} pp, but only {result.get('baseline_decoupling_samples', 0)} prior comparable baseline sample(s) exist; THE LAB will not issue a durability/trend call yet."
            else:
                result["headline"] = f"A provisional power/HR difference ({trend:+.1f}%) is visible, but the comparable baseline is not mature enough for a directional call."
        elif recent_dec is not None and old_dec is not None and recent_dec >= old_dec + 2.0 and recent_dec >= 5.0:
            result["status"], result["status_class"] = "DURABILITY WATCH", "orange"
            result["headline"] = f"Power/HR ratio is {trend:+.1f}% vs the prior baseline, and aerobic decoupling has worsened by {recent_dec-old_dec:+.1f} pp."
        elif trend >= 1.5:
            result["status"], result["status_class"] = "IMPROVING", "green"
            result["headline"] = f"At comparable steady Z2, recent power per heartbeat is {trend:+.1f}% above the prior baseline."
        elif trend <= -2.5:
            result["status"], result["status_class"] = "BELOW RECENT NORM", "orange"
            result["headline"] = f"At comparable steady Z2, recent power per heartbeat is {trend:+.1f}% below the prior baseline."
        else:
            result["status"], result["status_class"] = "STABLE", "cyan"
            result["headline"] = f"Steady-Z2 power/HR ratio is stable ({trend:+.1f}% vs the prior baseline)."

    for x in sorted(selected, key=lambda z: z["date"], reverse=True)[:3]:
        result["latest_sessions"].append({
            "date": x["date_iso"], "watts": round(x["watts"]), "hr": round(x["hr"]),
            "ratio": round(x["ratio"], 3), "decoupling": round(x["decoupling"], 1) if x.get("decoupling") is not None else None,
            "duration_min": x["duration_min"], "environment": x["environment"],
        })
    return result


def _wellness_value_near(wellness, field, target_day, max_gap_days=4):
    best = None
    for w in wellness or []:
        value = w.get(field)
        if not isinstance(value, (int, float)):
            continue
        try:
            d = date.fromisoformat(str(w.get("id") or "")[:10])
        except Exception:
            continue
        gap = abs((d - target_day).days)
        if gap <= max_gap_days and (best is None or gap < best[0]):
            best = (gap, float(value))
    return best[1] if best else None


def build_training_state(season_activities, season_wellness, planning_context, metrics, feeling_trend=None, now=None):
    """Deterministic periodisation state built from load trend + calendar context.

    This is not an AI label and never infers tapering from illness/injury-driven
    loss of load. Health/restriction context has absolute priority.
    """
    now = now or get_rome_now()
    today = now.date()
    planning_context = planning_context or {}
    health = planning_context.get("health_override")
    next_race = planning_context.get("next_race") or {}

    def load_between(start_day, end_day):
        total = 0.0
        count = 0
        for a in season_activities or []:
            raw = str(a.get("start_date_local") or "")[:10]
            try:
                d = date.fromisoformat(raw)
            except Exception:
                continue
            if start_day <= d <= end_day:
                load = a.get("icu_training_load")
                if isinstance(load, (int, float)):
                    total += max(0.0, float(load))
                count += 1
        return total, count

    load7, sessions7 = load_between(today - timedelta(days=6), today)
    prior21, prior_sessions = load_between(today - timedelta(days=27), today - timedelta(days=7))
    prior_weekly = prior21 / 3.0 if prior21 > 0 else None
    load_ratio = load7 / prior_weekly if prior_weekly and prior_weekly > 0 else None

    latest_w = sorted(season_wellness or [], key=lambda x: str(x.get("id") or ""))[-1] if season_wellness else {}
    ctl_now = latest_w.get("ctl") if isinstance(latest_w.get("ctl"), (int, float)) else None
    atl_now = latest_w.get("atl") if isinstance(latest_w.get("atl"), (int, float)) else None
    ctl_28 = _wellness_value_near(season_wellness, "ctl", today - timedelta(days=28))
    ctl_delta_28 = round(ctl_now - ctl_28, 1) if ctl_now is not None and ctl_28 is not None else None
    ramp = latest_w.get("rampRate") if isinstance(latest_w.get("rampRate"), (int, float)) else None
    atl_ctl = atl_now / ctl_now if atl_now is not None and ctl_now and ctl_now > 0 else None

    pb = metrics.get("personal_baselines") or {}
    recovery_flags = []
    if (pb.get("hrv") or {}).get("color") == "red": recovery_flags.append("HRV below personal range")
    if (pb.get("rhr") or {}).get("color") == "red": recovery_flags.append("resting HR outside personal range")
    if (pb.get("sleep") or {}).get("color") in ("red", "orange"): recovery_flags.append("sleep below habitual opportunity")
    if (feeling_trend or {}).get("label") == "TRENDING DOWN": recovery_flags.append("subjective trend is falling")

    try:
        race_days = int(next_race.get("days_away")) if next_race and next_race.get("days_away") is not None else None
    except Exception:
        race_days = None

    if health:
        state, css, icon = "HEALTH HOLD", "red", "🛡️"
        headline = "Health/restriction context overrides periodisation labels."
        why = f"{health.get('kind', 'Health restriction')} is active through {health.get('until', 'the current restriction window')}; falling ATL or rising TSB is not treated as tapering or peaking."
    elif race_days is not None and race_days <= 2:
        state, css, icon = "RACE PREP", "green", "🏁"
        headline = "Preserve freshness and race specificity; there is no fitness to gain now."
        why = f"The priority race is {race_days} day(s) away. THE LAB prioritises readiness, fueling and low-cost activation over new training load."
    elif race_days is not None and 3 <= race_days <= 8:
        state, css, icon = "TAPER", "purple", "🎚️"
        headline = "Reduce accumulated fatigue while preserving the qualities already built."
        why = f"The priority race is {race_days} days away. This window is classified as taper even if a recent long ride temporarily keeps ATL high; health context would override this label if present."
    elif race_days is not None and 9 <= race_days <= 14:
        state, css, icon = "RACE PREP", "cyan", "🎯"
        headline = "Training is becoming race-specific while total fatigue must stay controlled."
        why = f"The priority race is {race_days} days away, so the final useful stimulus is balanced against the recovery time still available."
    elif len(recovery_flags) >= 2 or (atl_ctl is not None and atl_ctl >= 1.18) or (load_ratio is not None and load_ratio >= 1.35):
        state, css, icon = "RECOVERY", "orange", "♻️"
        headline = "Absorb the recent block before adding another dense stimulus."
        why = "Multiple load/recovery signals point to accumulated strain rather than a need to chase more training stress."
    elif (ctl_delta_28 is not None and ctl_delta_28 >= 1.5 and (load_ratio is None or load_ratio >= 0.95)) or (ramp is not None and ramp >= 0.5):
        state, css, icon = "BUILD", "cyan", "🏗️"
        headline = "Chronic load is progressing and the calendar still allows productive accumulation."
        why = "Recent load and CTL trajectory are consistent with a controlled build rather than maintenance or unloading."
    else:
        state, css, icon = "MAINTENANCE", "green", "⚖️"
        headline = "Hold fitness with purposeful work instead of forcing load progression."
        why = "Load and CTL are broadly stable, with no stronger race, recovery or health signal requiring another phase."

    signals = []
    if ctl_delta_28 is not None: signals.append(f"CTL 28d {ctl_delta_28:+.1f}")
    if ramp is not None: signals.append(f"Ramp {ramp:+.1f}")
    if prior_weekly is not None: signals.append(f"7d load {round(load7)} vs prior weekly {round(prior_weekly)}")
    if atl_ctl is not None: signals.append(f"ATL/CTL {atl_ctl:.2f}")
    if race_days is not None: signals.append(f"Race {race_days}d")
    if recovery_flags: signals.append(" · ".join(recovery_flags[:2]))

    wellness_count = sum(1 for w in season_wellness or [] if isinstance(w.get("ctl"), (int, float)))
    if wellness_count >= 28 and prior_sessions >= 4:
        confidence = "HIGH"
    elif wellness_count >= 14:
        confidence = "MODERATE"
    else:
        confidence = "LOW"
    return {
        "state": state, "state_class": css, "icon": icon, "confidence": confidence,
        "headline": headline, "why": why, "signals": signals[:5],
        "load_7d": round(load7), "prior_weekly_load": round(prior_weekly) if prior_weekly is not None else None,
        "load_ratio": round(load_ratio, 2) if load_ratio is not None else None,
        "ctl_delta_28": ctl_delta_28, "ramp_rate": round(ramp, 1) if ramp is not None else None,
        "atl_ctl": round(atl_ctl, 2) if atl_ctl is not None else None,
        "race_days": race_days,
    }


def build_physiological_state(metrics, training_state, aerobic_efficiency, metabolic_context, heat_pattern=None, feeling_trend=None):
    """Multi-signal state matrix; deliberately not collapsed into another 0–100 score."""
    pb = metrics.get("personal_baselines") or {}
    hrv = pb.get("hrv") or {}
    rhr = pb.get("rhr") or {}
    sleep = pb.get("sleep") or {}
    heat_current = bool((heat_pattern or {}).get("current_relevance"))

    if hrv.get("color") == "red" and rhr.get("color") == "red":
        autonomous = ("STRAINED", "red", "HRV is suppressed while resting HR is also outside the personal range.")
    elif hrv.get("color") == "red" and heat_current:
        autonomous = ("HEAT STRAIN", "orange", "Low HRV follows HEAT and matches the learned context; THE LAB still cross-checks resting HR and recovery.")
    elif hrv.get("color") == "red" or rhr.get("color") == "red":
        autonomous = ("WATCH", "orange", "One autonomic marker is outside the personal range while the other signals provide context.")
    elif hrv.get("color") == "green" and rhr.get("color") == "green":
        autonomous = ("BALANCED", "green", "HRV and resting HR are both inside the athlete's established range.")
    else:
        autonomous = ("MIXED", "grey", "Autonomic markers are not aligned strongly enough for a single directional call.")

    sq = metrics.get("sleep_quality")
    subjective_down = (feeling_trend or {}).get("label") == "TRENDING DOWN"
    if sleep.get("color") == "red" and (sq in (3, 4) or subjective_down):
        recovery = ("LOW", "red", "Sleep is well below habitual opportunity and another recovery signal is also negative.")
    elif sleep.get("color") in ("red", "orange") or sq in (3, 4) or subjective_down:
        recovery = ("WATCH", "orange", "At least one sleep/subjective recovery signal is below the athlete's recent norm.")
    else:
        recovery = ("NORMAL", "green", "Sleep opportunity/quality and subjective context do not show a major recovery warning.")

    state = (training_state or {}).get("state")
    atl_ctl = (training_state or {}).get("atl_ctl")
    if state == "HEALTH HOLD":
        load_state = ("HOLD", "red", "Training-load interpretation is subordinated to the active health restriction.")
    elif atl_ctl is not None and atl_ctl >= 1.18:
        load_state = ("LOADED", "orange", f"ATL/CTL is {atl_ctl:.2f}; acute load is elevated relative to chronic load.")
    elif atl_ctl is not None and atl_ctl <= 0.85:
        load_state = ("FRESH", "green", f"ATL/CTL is {atl_ctl:.2f}; acute load is relatively low versus chronic load.")
    else:
        load_state = ("CONTROLLED", "cyan", "Acute and chronic load are in a broadly controlled relationship for this athlete.")

    ae = aerobic_efficiency or {}
    if not ae.get("available"):
        aerobic = ("LEARNING", "grey", "Not enough comparable steady Z2 sessions yet for a reliable longitudinal efficiency call.")
    else:
        aerobic = (ae.get("status", "STABLE"), ae.get("status_class", "cyan"), ae.get("headline", "Aerobic trend available."))

    pressure = str((metabolic_context or {}).get("glycogen_pressure") or "LOW").upper()
    if pressure == "HIGH":
        energy = ("HIGH DEMAND", "orange", "Recent training creates high glycogen/replenishment pressure; this is a fueling context, not a fatigue diagnosis.")
    elif pressure == "MODERATE":
        energy = ("MODERATE", "cyan", "Recent exercise creates meaningful but manageable glycogen/replenishment demand.")
    else:
        energy = ("LOW DEMAND", "green", "Recent exercise-only glycogen pressure is currently low.")

    entries = [
        ("AUTONOMIC", "❤️", autonomous),
        ("RECOVERY", "😴", recovery),
        ("TRAINING LOAD", "⚡", load_state),
        ("AEROBIC", "🫁", aerobic),
        ("ENERGY", "🍚", energy),
    ]
    return {
        "systems": [
            {"label": label, "icon": icon, "status": values[0], "status_class": values[1], "reason": values[2]}
            for label, icon, values in entries
        ],
        "note": "Training/recovery interpretation only · not a medical diagnosis. THE LAB keeps the systems separate instead of hiding them inside one opaque score.",
    }


def training_state_text(state):
    if not state:
        return "TRAINING STATE: unavailable"
    return "\n".join([
        f"TRAINING STATE (deterministic Python): {state.get('state')} | confidence {state.get('confidence')}",
        f"- {state.get('headline')}",
        f"- Why: {state.get('why')}",
        "- Signals: " + (" | ".join(state.get("signals") or []) or "insufficient trend data"),
    ])


def adaptive_sleep_text(adaptive):
    if not adaptive or not adaptive.get("available"):
        return "ADAPTIVE SLEEP BASELINE: insufficient data"
    return (
        "ADAPTIVE SLEEP BASELINE (42-day habitual opportunity; Garmin 7h38 is reference only):\n"
        f"- Current context: {adaptive.get('kind')} | habitual {adaptive.get('habitual_label')} | current delta {adaptive.get('current_delta_min'):+d} min | {adaptive.get('status')}\n"
        f"- Weekday habitual {adaptive.get('weekday_label')} | weekend habitual {adaptive.get('weekend_label')} | 14d trend {adaptive.get('trend_label')}"
    )


def aerobic_efficiency_text(ae):
    if not ae or not ae.get("available"):
        return "AEROBIC EFFICIENCY / DURABILITY: learning; insufficient comparable non-HEAT steady Z2 sessions."
    return (
        f"AEROBIC EFFICIENCY / DURABILITY ({ae.get('cohort_label')}): {ae.get('status')} | confidence {ae.get('confidence')}\n"
        f"- Recent power/HR {ae.get('recent_ratio')} W/bpm vs prior {ae.get('baseline_ratio')} | change {ae.get('trend_pct'):+.1f}%\n"
        f"- Recent decoupling {ae.get('recent_decoupling')}% vs prior {ae.get('baseline_decoupling')}%. HEAT sessions excluded from this baseline."
    )


def power_model_text(model):
    if not model or not model.get("available"):
        return "POWER MODEL: unavailable / insufficient power-curve points."
    r = model.get("recent") or {}
    s = model.get("season") or {}
    lines = [
        "POWER MODEL (two-parameter field estimate; P = CP + W′/t; not a lab CP test):",
        f"- 42d: CP {r.get('cp')} W | W′ {r.get('w_prime_kj')} kJ | fit R² {r.get('r2')} | {r.get('confidence')}",
    ]
    # The fit may be low-confidence, but these points are the athlete's observed
    # power-duration inputs. They are essential for calibrating whether a proposed
    # interval is actually demanding for THIS athlete rather than merely sitting in
    # a generic percentage-of-FTP band.
    recent_points = []
    for point in r.get("points") or []:
        try:
            secs = int(round(float(point.get("secs"))))
            watts = int(round(float(point.get("watts"))))
        except Exception:
            continue
        if secs > 0 and watts > 0:
            recent_points.append(f"{format_duration_label(secs)} {watts} W")
    if recent_points:
        lines.append("- Observed 42d power-duration references: " + " | ".join(recent_points))
    if s.get("available"):
        lines.append(f"- Current season: CP {s.get('cp')} W | W′ {s.get('w_prime_kj')} kJ | fit R² {s.get('r2')}")
        lines.append(f"- 42d vs season CP: {model.get('cp_gap_w'):+d} W | {model.get('status')}")
    if model.get("cp_wkg") is not None:
        lines.append(f"- 42d CP relative to current weight: {model.get('cp_wkg')} W/kg")
    return "\n".join(lines)


def physiological_state_text(state):
    if not state:
        return "PHYSIOLOGICAL STATE: unavailable"
    lines = ["PHYSIOLOGICAL STATE MATRIX (deterministic; not a medical diagnosis):"]
    for item in state.get("systems") or []:
        lines.append(f"- {item.get('label')}: {item.get('status')} — {item.get('reason')}")
    return "\n".join(lines)


def build_week_memory(recent_activities, now=None):
    """Reconstruct the current Monday→now training week directly from Intervals.icu.

    This is fresh on every snapshot, so it survives deploys and does not rely on
    Claude remembering what happened yesterday.
    """
    now = now or get_rome_now()
    today = now.date()
    monday = today - timedelta(days=today.weekday())
    items = []

    for activity in recent_activities:
        raw = activity.get("start_date_local") or ""
        dt = parse_local_activity_datetime(raw)
        if not dt:
            continue
        d = dt.date()
        if d < monday or d > today:
            continue
        # If an activity is timestamped later today than the snapshot, ignore it.
        if d == today and dt.time() > now.replace(tzinfo=None).time():
            continue

        family = classify_training_family(activity)
        duration_sec = activity.get("moving_time") or activity.get("elapsed_time") or 0
        item = {
            "date": d.isoformat(),
            "day": d.strftime("%A"),
            "day_short": d.strftime("%a"),
            "time": dt.strftime("%I:%M %p"),
            "name": activity.get("name") or activity.get("type") or "Activity",
            "family": family,
            "family_short": family.replace("Endurance / ", "").replace(" / Mixed", ""),
            "duration_min": round(duration_sec / 60) if duration_sec else None,
            "load": activity.get("icu_training_load"),
            "hard": is_hard_training_family(family),
        }
        items.append(item)

    items.sort(key=lambda x: (x["date"], x["time"]))
    hard_items = [x for x in items if x["hard"]]
    hard_families = []
    for x in hard_items:
        if x["family"] not in hard_families:
            hard_families.append(x["family"])

    # Days since the most recent hard session is useful spacing information for Claude.
    last_hard = hard_items[-1] if hard_items else None
    days_since_last_hard = None
    if last_hard:
        days_since_last_hard = (today - date.fromisoformat(last_hard["date"])).days

    return {
        "week_start": monday.isoformat(),
        "week_end": today.isoformat(),
        "activities": items,
        "hard_count": len(hard_items),
        "hard_families": hard_families,
        "hard_summary": ", ".join(hard_families),
        "last_hard": last_hard,
        "days_since_last_hard": days_since_last_hard,
    }


def week_memory_text(memory):
    if not memory or not memory.get("activities"):
        return (
            "CURRENT WEEK TRAINING HISTORY (Monday to snapshot time):\n"
            "- No completed activities found yet this week."
        )

    lines = ["CURRENT WEEK TRAINING HISTORY (Monday to snapshot time — authoritative):"]
    for a in memory["activities"]:
        dur = f'{a["duration_min"]} min' if a.get("duration_min") is not None else "duration n/a"
        load = a.get("load") if a.get("load") is not None else "n/a"
        quality = "HARD/QUALITY" if a.get("hard") else "easy/moderate"
        lines.append(
            f'- {a["day"]} {a["date"]} {a["time"]} | {a["family"]} | {quality} | '
            f'{dur} | load {load} | {a["name"]}'
        )
    if memory.get("last_hard"):
        lh = memory["last_hard"]
        lines.append(
            f'- Most recent hard/quality stimulus: {lh["family"]} on {lh["day"]} {lh["date"]} '
            f'({memory.get("days_since_last_hard")} day(s) ago).'
        )
    lines.append(
        "Use this history before prescribing the next sessions. Do not repeat the same hard workout family "
        "simply because it fits the next slot. In particular, avoid another TTE/threshold, VO2max, Over-Under "
        "or sprint/neuromuscular stimulus too close to the same family already completed. Prefer complementary "
        "work and adequate spacing. A repeat is allowed only when there is a clear coaching reason, and that "
        "reason must be stated explicitly in the session rationale."
    )
    return "\n".join(lines)


def _positive_intensity_term(value, patterns):
    """Return True only when a quality term is used as a positive prescription.

    The Coach sometimes writes endurance ceilings such as "no sustained efforts
    above tempo" or "stay below threshold" inside the intensity field. Earlier
    versions treated the mere presence of TEMPO/THRESHOLD/VO2 as proof of a hard
    session, which could incorrectly promote a long Z2 ride to the ~80 g/h hard-
    outdoor fueling baseline. V28 inspects the local language before each quality
    term and ignores negated/ceiling references.
    """
    v = str(value or "").lower().replace("vo₂", "vo2")
    if not v:
        return False
    negative_cues = re.compile(
        r"\b(?:no|not|without|avoid|avoiding|never|resist|resisting|below|under|beneath|"
        r"non|senza|evita|evitare|sotto)\b"
    )
    # Work inside the current clause so a previous "no" does not suppress a real
    # quality prescription later in the sentence.
    clause_break = re.compile(r"[;,.]|\s+[–—]\s+|\n")
    for pattern in patterns:
        for match in re.finditer(pattern, v):
            prefix = v[max(0, match.start() - 72):match.start()]
            clause_prefix = clause_break.split(prefix)[-1]
            if negative_cues.search(clause_prefix):
                continue
            return True
    return False


def intensity_class(value):
    """Classify the prescribed session, not words used to describe its ceiling."""
    v = str(value or "").lower().replace("vo₂", "vo2")

    positive_vo2 = _positive_intensity_term(v, (r"\bvo2(?:max)?\b", r"\banaer(?:obic|obico|obica)?\b"))
    positive_threshold = _positive_intensity_term(v, (r"\bthreshold\b", r"\bsoglia\b"))
    positive_tempo = _positive_intensity_term(v, (r"\btempo\b", r"\bsweet\s*spot\b", r"\bsweetspot\b"))

    if positive_vo2:
        return "vo2"
    if positive_threshold:
        return "threshold"
    if positive_tempo:
        return "tempo"
    if any(k in v for k in ("recover", "recovery", "easy", "facile", "recupero")):
        return "recovery"
    return "endurance"



def _v4827_prescribed_power_range(*texts):
    """Extract the actual prescribed watt range, preferring the work set over warm-up/recovery.

    V4.8.35 keeps the original reference-number exclusions but stops treating the
    first watt range in a session description as automatically authoritative. A
    warm-up or recovery range can precede the real main set, so candidate wattages
    are filtered by their local prescription context before selection.
    """
    reference_terms = ("pb", "personal best", "best", "record", "ftp anchor", "rolling ftp", "observed max")
    phase_terms = ("warm-up", "warmup", "warm up", "cool-down", "cooldown", "cool down", "recovery", "recover", "easy spin")
    range_re = re.compile(r"(?<!\d)(\d{2,3})\s*[–—-]\s*(\d{2,3})\s*w\b", re.I)
    single_re = re.compile(r"(?:target|at|@|around|circa|~)\s*(\d{2,3})\s*w\b", re.I)

    def local_prefix(text, pos):
        # Use the current semantic clause, not the whole sentence, so an earlier
        # warm-up mention does not contaminate a later 'Main set: ... @ X W'.
        prefix = text[max(0, pos - 180):pos]
        cut = max(prefix.rfind("."), prefix.rfind(";"), prefix.rfind("\n"), prefix.rfind(":"))
        if cut >= 0:
            prefix = prefix[cut + 1:]
        return prefix.lower()

    def is_reference(text, match):
        ctx = text[max(0, match.start()-42):min(len(text), match.end()+42)].lower()
        if any(term in ctx for term in reference_terms):
            before = text[max(0, match.start()-42):match.start()].lower()
            if any(term in before for term in reference_terms):
                return True
        return False

    def is_phase_number(text, match):
        before = local_prefix(text, match.start())
        # A structured repeat target immediately before the wattage outranks a
        # distant phase word; e.g. 'Main set: 4 × 3 min @ 330–350 W'.
        structured_target = bool(re.search(r"(?:\d+\s*[×x]\s*)?\d+(?:\.\d+)?\s*(?:min|m|sec|s)?[^.;:]{0,28}(?:@|\bat\s*)$", before, flags=re.I))
        return any(term in before for term in phase_terms) and not structured_target

    for text in texts:
        original = str(text or "")
        if not original:
            continue

        # If the author explicitly labels a Main Set, prioritize the portion after
        # that label. This preserves warm-up/cool-down text for display while making
        # the work prescription authoritative for coherence/classification.
        main_markers = list(re.finditer(r"\bmain\s+set\s*:\s*", original, flags=re.I))
        variants = []
        if main_markers:
            variants.append(original[main_markers[-1].end():])
        variants.append(original)

        for s in variants:
            ranges = []
            for m in range_re.finditer(s):
                if is_reference(s, m) or is_phase_number(s, m):
                    continue
                lo, hi = float(m.group(1)), float(m.group(2))
                if 50 <= lo <= 800 and 50 <= hi <= 800:
                    ranges.append((min(lo, hi), max(lo, hi)))
            if ranges:
                return ranges[0]

            singles = []
            for m in single_re.finditer(s):
                if is_reference(s, m) or is_phase_number(s, m):
                    continue
                w = float(m.group(1))
                if 50 <= w <= 800:
                    singles.append(w)
            if singles:
                return (min(singles), max(singles))
    return (None, None)


def _v4827_rationale_reference_mismatch(why, prescribed_low, prescribed_high):
    """Detect a different remembered watt target being used to justify this workout."""
    if not why or prescribed_low is None or prescribed_high is None:
        return False
    low = str(why).lower()
    if not any(k in low for k in ("memory", "remember", "target", "goal", "directly serves", "repeatability")):
        return False
    nums = [float(x) for x in re.findall(r"(?<!\d)(\d{2,3})(?=\s*w\b)", str(why), flags=re.I)]
    if not nums:
        # Also catch compact ranges such as 350–370 W; the look-ahead above captures 370 only.
        nums = [float(x) for x in re.findall(r"(?<!\d)(\d{2,3})", str(why)) if 80 <= float(x) <= 700]
    midpoint = (float(prescribed_low) + float(prescribed_high)) / 2.0
    return any(abs(n - midpoint) / midpoint >= 0.15 for n in nums if 50 <= n <= 800)


def _v4827_session_coherence(title, intensity, main_set, why, ftp_anchor=None, training_definitions=None):
    """Deterministically align workout naming and rationale with the actual prescription.

    The AI may suggest the work, but it cannot call sub-threshold power "Z4 threshold",
    use TTE without an athlete-owned definition, or justify one workout with a materially
    different remembered power target.  Prescribed work is preserved; labels/rationale are
    the only things normalized here.
    """
    title, intensity, main_set, why = map(lambda x: str(x or ""), (title, intensity, main_set, why))
    reasons = []
    has_tte_definition = _has_explicit_tte_definition(training_definitions)
    tte_re = r"\bTTE\b|time[-\s]+to[-\s]+exhaustion"
    any_tte = bool(re.search(tte_re, " ".join((title, intensity, main_set, why)), flags=re.I))
    if any_tte and not has_tte_definition:
        title = re.sub(tte_re, "Threshold", title, flags=re.I)
        intensity = re.sub(tte_re, "Threshold", intensity, flags=re.I)
        main_set = re.sub(tte_re, "threshold", main_set, flags=re.I)
        why = re.sub(tte_re, "quality work", why, flags=re.I)
        reasons.append("TTE_WITHOUT_DEFINITION")

    p_lo, p_hi = _v4827_prescribed_power_range(main_set, intensity, title)
    anchor = None
    if isinstance(ftp_anchor, dict):
        try:
            raw = ftp_anchor.get("prescription_watts") if ftp_anchor.get("prescription_watts") is not None else (ftp_anchor.get("anchor_watts") if not ftp_anchor.get("retest_due") else None)
            anchor = float(raw) if raw is not None and not isinstance(raw, bool) else None
        except (TypeError, ValueError):
            anchor = None
        if anchor is not None and not (80 <= anchor <= 600):
            anchor = None

    ratio_lo = ratio_hi = None
    band = None
    if anchor and p_lo is not None and p_hi is not None:
        ratio_lo, ratio_hi = p_lo / anchor, p_hi / anchor
        # Conservative field-language bands for naming coherence only. These do not
        # redefine the athlete's physiological zones or alter the prescribed watts.
        if ratio_hi < 0.80:
            band = "endurance"
        elif ratio_hi < 0.86:
            band = "tempo"
        elif ratio_hi < 0.93:
            band = "sub-threshold"
        elif ratio_lo <= 1.02 and ratio_hi <= 1.05:
            band = "threshold"
        else:
            band = "above-threshold"

    claimed_threshold = bool(re.search(r"\bthreshold\b|\bz4\b|\bzone\s*4\b|\bsoglia\b", " ".join((title, intensity, main_set)), flags=re.I))
    if band == "sub-threshold" and claimed_threshold:
        # Do not turn an already-correct "Sub-threshold" label into
        # "Sub-Sub-threshold" while normalizing stray Z4/Threshold claims.
        title = re.sub(r"(?<!sub-)(?<!sub )\bThreshold\b", "Sub-threshold", title, flags=re.I)
        title = re.sub(r"\(\s*Z4\s*\)", "", title, flags=re.I)
        intensity = re.sub(r"\bZ4\s*threshold\b|(?<!sub-)(?<!sub )\bthreshold\b|\bZ4\b|\bzone\s*4\b|\bsoglia\b", "sub-threshold", intensity, flags=re.I)
        intensity = re.sub(r"^\s*Hard\s*[—–-]\s*", "Controlled — ", intensity, flags=re.I)
        main_set = re.sub(r"\bat\s+(?:Z4|zone\s*4|(?<!sub-)(?<!sub )threshold|soglia)\b", "at controlled sub-threshold", main_set, flags=re.I)
        reasons.append("POWER_BELOW_THRESHOLD_LABEL")

    memory_mismatch = _v4827_rationale_reference_mismatch(why, p_lo, p_hi)
    if memory_mismatch:
        reasons.append("RATIONALE_DIFFERENT_POWER_TARGET")

    # If any coherence violation occurred, replace rather than patch the rationale:
    # stale/contradictory AI prose must not survive around a corrected prescription.
    if reasons:
        rationale = []
        if anchor and p_lo is not None and p_hi is not None:
            if abs(p_hi - p_lo) < 0.5:
                watts_label = f"{p_lo:.0f} W"
            else:
                watts_label = f"{p_lo:.0f}–{p_hi:.0f} W"
            pct_lo, pct_hi = ratio_lo * 100.0, ratio_hi * 100.0
            pct_label = f"{pct_lo:.0f}–{pct_hi:.0f}%" if abs(pct_hi-pct_lo) >= 0.5 else f"{pct_lo:.0f}%"
            if band == "sub-threshold":
                rationale.append(f"The prescribed work is {watts_label} ({pct_label} of the validated THE LAB FTP anchor of {anchor:.0f} W), so this is controlled sub-threshold work rather than Z4 threshold.")
            elif band == "threshold":
                rationale.append(f"The prescribed work is {watts_label} ({pct_label} of the validated THE LAB FTP anchor of {anchor:.0f} W), consistent with a threshold prescription.")
            else:
                rationale.append(f"The session rationale is anchored to its actual prescription: {watts_label} ({pct_label} of the validated THE LAB FTP anchor of {anchor:.0f} W).")
        elif "TTE_WITHOUT_DEFINITION" in reasons:
            rationale.append("THE LAB does not use TTE as a generic synonym for threshold work; this session is classified by its actual structure. An optional TRAINING DEFINITION can teach THE LAB the athlete's exact TTE protocol.")
        if re.search(r"post[-\s]?race|race effort|recent race|after the race", why, flags=re.I):
            rationale.append("The recent race context supports a controlled return to quality rather than turning this session into a maximal test.")
        if memory_mismatch:
            rationale.append("Stored targets for a different interval duration or workout remain separate athlete context and are not used as direct justification for this session.")
        if rationale:
            why = " ".join(rationale)

    cls = intensity_class(intensity)
    if band == "sub-threshold":
        cls = "tempo"
    return {
        "title": title.strip(), "intensity": re.sub(r"\s{2,}", " ", intensity).strip(),
        "main_set": main_set.strip(), "why": why.strip(), "intensity_class": cls,
        "coherence_adjusted": bool(reasons), "coherence_reasons": reasons,
        "prescribed_power_low": int(round(p_lo)) if p_lo is not None else None,
        "prescribed_power_high": int(round(p_hi)) if p_hi is not None else None,
        "ftp_anchor_watts": int(round(anchor)) if anchor is not None else None,
        "power_band": band,
    }


def _v4829_parse_activity_start(activity):
    raw = str((activity or {}).get("start_date_local") or "").strip()
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
    except Exception:
        try:
            return datetime.strptime(raw[:16], "%Y-%m-%dT%H:%M")
        except Exception:
            return None


def _v4829_activity_end(activity):
    start = _v4829_parse_activity_start(activity)
    if start is None:
        return None
    durations = []
    for key in ("moving_time", "elapsed_time"):
        value = _rhythm_num((activity or {}).get(key))
        if value is not None and 0 <= float(value) <= 172800:
            durations.append(float(value))
    sec = max(durations) if durations else 0.0
    return start + timedelta(seconds=sec)


def _v4829_is_quality_activity(activity):
    if _v40_is_hard_candidate(activity):
        return True
    blob = " ".join(str((activity or {}).get(k) or "") for k in ("name", "type", "sub_type")).lower()
    return any(k in blob for k in ("race", "granfondo", "gran fondo", "criterium", "time trial"))


def _v4829_latest_hard_end(activities):
    ends = [_v4829_activity_end(a) for a in (activities or []) if _v4829_is_quality_activity(a)]
    ends = [x for x in ends if x is not None]
    return max(ends) if ends else None


def _v4829_spacing_truth_guard(text, actual_hours=None):
    """Remove unsupported '72 h satisfied' prose and replace it with measured spacing."""
    s = str(text or "")
    if actual_hours is None:
        return s
    actual_label = f"{actual_hours:.0f} h"
    chunks = re.split(r'(?<=[.!?])\s+', s)
    out = []
    for chunk in chunks:
        low = chunk.lower()
        if "72" in low and any(k in low for k in ("spacing", "spaced", "since", "hours", " h")):
            out.append(f"Measured spacing from the previous hard/race load to this session is about {actual_label}; THE LAB reports the measured interval instead of claiming a fixed spacing rule was satisfied.")
        else:
            out.append(chunk)
    return " ".join(x for x in out if x).strip()


def _v4829_physiology_language_guard(text):
    """Remove deterministic overclaims from AI prose while preserving the recommendation."""
    s = str(text or "")
    replacements = [
        (r"\bzero additional fatigue cost\b", "relatively low additional fatigue cost"),
        (r"\bwithout adding (?:meaningful )?fatigue cost\b", "with relatively low additional fatigue cost"),
        (r"\bwithout adding fatigue\b", "with relatively low additional training cost"),
        (r"\band supports? glycogen restoration through the overnight window\b", "while carbohydrate intake supports overnight glycogen replenishment"),
        (r"\bsupports? glycogen restoration through the overnight window\b", "keeps training demand low while carbohydrate intake supports overnight glycogen replenishment"),
        (r"\baccelerates? glycogen resynthesis(?: and lactate clearance)?\b", "supports low-intensity aerobic continuity while carbohydrate intake drives glycogen restoration"),
        (r"\baccelerates? lactate clearance\b", "provides low-intensity active movement"),
        (r"\bclearing the lactate\b", "easy active recovery"),
        (r"\bshould normalize\b", "should be re-checked for normalization"),
        (r"\bwhich is healthy variety\b", "which indicates greater day-to-day load variation than the recent habitual pattern"),
        (r"\bbelow personal baseline in a positive direction\b", "below the personal baseline and best interpreted alongside HRV, sleep and subjective recovery"),
    ]
    for pat, repl in replacements:
        s = re.sub(pat, repl, s, flags=re.I)
    return re.sub(r"\s{2,}", " ", s).strip()


def _v4830_title_language_guard(title):
    s = str(title or "")
    s = re.sub(r"\bAerobic\s+Flush\b", "Aerobic Maintenance", s, flags=re.I)
    s = re.sub(r"\bRecovery\s+Flush\b", "Recovery Ride", s, flags=re.I)
    return re.sub(r"\s{2,}", " ", s).strip()


def _v4829_ftp_language_guard(text, ftp_anchor):
    """Keep AI prose aligned with the active-vs-rolling FTP contract."""
    s = str(text or "")
    c = ftp_anchor or {}
    active = c.get("prescription_watts")
    rolling = c.get("current_rolling_ftp")
    try:
        active = float(active) if active is not None else None
        rolling = float(rolling) if rolling is not None else None
    except (TypeError, ValueError):
        return s
    if active is not None and rolling is not None and rolling < active:
        s = re.sub(r"\bgenuine\s+FTP\s+confirmation\b", "recent Intervals FTP signal", s, flags=re.I)
        s = re.sub(r"\bFTP\s+confirmation\b", "Intervals FTP signal", s, flags=re.I)
        s = re.sub(r"\bconfirmed\s+FTP\b", "Intervals FTP signal", s, flags=re.I)
        s = re.sub(r"\bnew\s+FTP\s+(?:of\s+)?" + re.escape(str(int(round(rolling)))) + r"\s*W\b", f"new Intervals rolling FTP signal of {int(round(rolling))} W", s, flags=re.I)
    return s


def _v4829_undefined_training_intent(daily_logs, training_definitions, now=None):
    """Detect athlete-reported TTE intent; definition availability changes interpretation, not visibility."""
    now = now or get_rome_now()
    definition_available = _has_explicit_tte_definition(training_definitions)
    logs = sorted((daily_logs or []), key=lambda x: str(x.get("logged_at_utc") or x.get("local_date") or ""), reverse=True)
    for log in logs[:3]:
        note = str(log.get("note") or "")
        if not re.search(r"\bTTE\b|time[-\s]+to[-\s]+exhaustion", note, flags=re.I):
            continue
        ds = str(log.get("local_date") or log.get("date") or "")[:10]
        try:
            base = date.fromisoformat(ds)
        except ValueError:
            base = now.date()
        target = base + timedelta(days=1) if re.search(r"\btomorrow\b|\bdomani\b", note, flags=re.I) else None
        return {
            "term": "TTE", "target_date": target.isoformat() if target else None, "source_note": note[:500],
            "definition_available": bool(definition_available),
        }
    return None


def _v4829_is_quality_session(session_item):
    return str((session_item or {}).get("intensity_class") or "").lower() in ("tempo", "threshold", "vo2")


def _v4830_interval_minutes(*texts):
    blob = " ".join(str(x or "") for x in texts).lower()
    patterns = (
        r"(?:×|x)\s*(\d+(?:\.\d+)?)\s*(?:min|m)\b",
        r"\b(\d+(?:\.\d+)?)\s*(?:min|m)\s+(?:at|@|effort|repeat|interval)",
    )
    for pat in patterns:
        m = re.search(pat, blob, flags=re.I)
        if m:
            try:
                value = float(m.group(1))
                if 0.1 <= value <= 60:
                    return value
            except Exception:
                pass
    return None


def _v4830_workout_classification(title, intensity, main_set, coherence=None, restriction="NONE", planned_demand=None):
    """Final deterministic workout class used by spacing, nutrition and rendering.

    AI prose is descriptive only.  Power band plus explicit work cues outrank words such as
    'recovery' that may merely describe the recovery between hard repetitions.
    """
    restriction = str(restriction or "NONE").upper()
    if restriction == "RACE":
        return "vo2"
    if restriction == "NO_INTENSITY" or str(planned_demand or "").upper() == "EASY":
        return "recovery"
    coherence = coherence or {}
    band = str(coherence.get("power_band") or "").lower()
    blob = " ".join(str(x or "") for x in (title, intensity, main_set)).lower().replace("vo₂", "vo2")
    interval_min = _v4830_interval_minutes(title, intensity, main_set)
    explicit_vo2 = _positive_intensity_term(blob, (
        r"\bvo2(?:max)?\b", r"\bmaximal[-\s]+aerobic\b", r"\bmax[-\s]+aerobic\b",
        r"\bz5\b", r"\bzone\s*5\b", r"\bz6\b", r"\bzone\s*6\b",
    ))
    explicit_threshold = _positive_intensity_term(blob, (r"\bthreshold\b", r"\bsoglia\b", r"\bz4\b", r"\bzone\s*4\b"))
    explicit_tempo = _positive_intensity_term(blob, (r"\btempo\b", r"\bsweet\s*spot\b", r"\bsweetspot\b"))
    interval_structure = bool(re.search(r"(?:×|\bx\b|interval|repeat|effort)", blob, flags=re.I))

    if explicit_vo2 or (band == "above-threshold" and interval_structure and (interval_min is None or interval_min <= 8.0)):
        return "vo2"
    # When a validated FTP anchor produced a usable power band, the actual
    # prescription outranks stray/legacy zone words in title or prose.
    if band == "threshold":
        return "threshold"
    if band in ("sub-threshold", "tempo"):
        return "tempo"
    if band == "endurance":
        if any(k in blob for k in ("easy", "recovery", "recover", "z1", "z2", "zone 1", "zone 2")):
            return "recovery"
        return "endurance"
    if explicit_threshold:
        return "threshold"
    if explicit_tempo:
        return "tempo"
    # No usable power anchor: explicit hard language still outranks recovery-between-reps prose.
    if _positive_intensity_term(blob, (r"\bhard\b",)) and interval_structure and interval_min is not None and interval_min <= 8.0:
        return "vo2"
    return intensity_class(intensity)


def _v4830_slot_datetime(slot):
    try:
        d = date.fromisoformat(str((slot or {}).get("date") or "")[:10])
        sm = _rhythm_num((slot or {}).get("start_minute"))
        if sm is None:
            return None
        hh, mm = divmod(max(0, min(1439, int(round(sm)))), 60)
        return datetime.combine(d, datetime.min.time()).replace(hour=hh, minute=mm)
    except Exception:
        return None


def _v4830_strip_untrusted_spacing_claims(text):
    """Remove AI-authored clock arithmetic; deterministic spacing is appended separately."""
    s = str(text or "")
    chunks = re.split(r'(?<=[.!?])\s+', s)
    kept = []
    for chunk in chunks:
        low = chunk.lower()
        has_hours = bool(re.search(r"\b\d+(?:\.\d+)?\s*(?:h|hours?)\b", low))
        spacing_context = any(k in low for k in ("from race", "from the race", "race end", "hard load", "spacing", "since sunday", "since the race", "since yesterday"))
        if has_hours and spacing_context:
            continue
        if "earliest reasonable return to structured quality" in low:
            continue
        kept.append(chunk)
    return " ".join(x for x in kept if x).strip()


def _v4830_first_quality_summary(sessions):
    sessions = list(sessions or [])
    first_quality = next((s for s in sessions if (s.get("hard_spacing_relevant") if "hard_spacing_relevant" in s else _v4829_is_quality_session(s))), None)
    if not first_quality:
        return ""
    spacing = first_quality.get("hard_spacing_hours")
    label = str(first_quality.get("slot") or first_quality.get("date") or "the first quality slot")
    if isinstance(spacing, (int, float)):
        return f"Current prescription places the first quality session at {label}; measured spacing from the previous hard/race load is {float(spacing):.1f} h."
    return f"Current prescription places the first quality session at {label}."


def _v4830_recommendation_consistency_guard(text, sessions):
    base = _v4830_strip_untrusted_spacing_claims(text)
    summary = _v4830_first_quality_summary(sessions)
    if summary and summary.lower() not in base.lower():
        base = (base.rstrip() + " " + summary).strip()
    return base


def _v4835_standalone_recommendation_guard(text):
    """Make the standalone Coach Call readable without an invisible prior sentence."""
    s = str(text or "").strip()
    # The recommendation card is rendered under its own heading. A leading
    # 'Instead,' depends on prose in another card and reads like a missing sentence.
    m = re.match(r"^instead\s*[,;:]\s*", s, flags=re.I)
    if m:
        s = s[m.end():].lstrip()
        if s:
            s = s[0].upper() + s[1:]
    return s


def _v4830_power_point(power_model, seconds):
    if not isinstance(power_model, dict):
        return None
    for section in (power_model.get("recent"), power_model.get("season")):
        for point in ((section or {}).get("points") or []):
            try:
                if int(round(float(point.get("secs")))) == int(seconds):
                    return int(round(float(point.get("watts"))))
            except Exception:
                continue
    return None


def _v4830_duration_reference_guard(text, power_model):
    """Do not compare a 3-min target directly with a 5-min best as if durations were interchangeable."""
    s = str(text or "")
    p3 = _v4830_power_point(power_model, 180)
    if p3 is None:
        return s
    if re.search(r"5[-\s]?min(?:ute)?[^.]{0,120}(?:gap|versus|vs\.?)[^.]{0,120}(?:repeatability\s+target|3[-\s]?min)", s, flags=re.I):
        s = re.sub(
            r"[^.]*5[-\s]?min(?:ute)?[^.]{0,160}(?:gap|versus|vs\.?)[^.]*\.?",
            f" For the 3-min repeatability target, the same-duration field reference is the recent 3-min best of {p3} W; the 5-min best remains separate context.",
            s, count=1, flags=re.I
        )
    s = re.sub(r"(?<=[.!?])(?=[A-Z])", " ", s)
    return re.sub(r"\s{2,}", " ", s).strip()


def _v4830_session_duration_reference_guard(why, main_set, power_model):
    s = str(why or "")
    p3 = _v4830_power_point(power_model, 180)
    if p3 is None:
        return s
    interval_min = _v4830_interval_minutes(main_set)
    if interval_min is not None and 2.5 <= interval_min <= 3.5 and re.search(r"5[-\s]?min", s, flags=re.I):
        s = re.sub(r"[^.]*5[-\s]?min[^.]*\.?", f" For these 3-min repeats, the relevant same-duration field reference is your recent 3-min best of {p3} W.", s, count=1, flags=re.I)
    s = re.sub(r"(?<=[.!?])(?=[A-Z])", " ", s)
    return re.sub(r"\s{2,}", " ", s).strip()


def _v4836_observed_power_reference(power_model, interval_minutes):
    """Estimate the athlete's observed same-duration power reference.

    Uses the recent power-duration points already stored in POWER MODEL.  This is
    not a CP/physiology estimate: exact points are observed best powers; missing
    durations are interpolated only between adjacent observed durations on log-time.
    It exists solely to stop generic %FTP labels from masquerading as athlete-specific
    intensity.
    """
    try:
        target_secs = float(interval_minutes) * 60.0
    except (TypeError, ValueError):
        return None
    if not (30 <= target_secs <= 7200):
        return None
    points = []
    for section_name in ("recent", "season"):
        section = (power_model or {}).get(section_name) or {}
        for point in section.get("points") or []:
            try:
                secs = float(point.get("secs"))
                watts = float(point.get("watts"))
            except (TypeError, ValueError):
                continue
            if 30 <= secs <= 7200 and 50 <= watts <= 1000:
                points.append((secs, watts, section_name))
        if points:
            break
    if not points:
        return None
    # Deduplicate by duration and keep the strongest observed value at that duration.
    by_secs = {}
    for secs, watts, _ in points:
        by_secs[secs] = max(watts, by_secs.get(secs, 0.0))
    pts = sorted(by_secs.items())
    for secs, watts in pts:
        if abs(secs - target_secs) <= 1:
            return round(watts, 1)
    lower = max((p for p in pts if p[0] < target_secs), default=None, key=lambda x: x[0])
    upper = min((p for p in pts if p[0] > target_secs), default=None, key=lambda x: x[0])
    if lower and upper:
        # Power-duration relationships are closer to linear over log(time) than raw
        # seconds; this interpolation is descriptive calibration only.
        x0, x1, xt = math.log(lower[0]), math.log(upper[0]), math.log(target_secs)
        frac = (xt - x0) / (x1 - x0) if x1 != x0 else 0.0
        return round(lower[1] + frac * (upper[1] - lower[1]), 1)
    return None


def _v4836_quality_calibration(coherence, main_set, power_model):
    """Classify how meaningful a sub-threshold interval is for this athlete.

    FTP band still defines workout family.  Observed duration-specific capability
    defines whether low/sub-threshold work deserves to be sold as a hard-quality
    anchor.  We intentionally down-rank only clear cases; threshold/VO2 prescriptions
    are never downgraded by this helper.
    """
    coherence = coherence or {}
    band = str(coherence.get("power_band") or "").lower()
    p_hi = _rhythm_num(coherence.get("prescribed_power_high"))
    interval_min = _v4830_interval_minutes(main_set)
    ref = _v4836_observed_power_reference(power_model, interval_min)
    ratio = (float(p_hi) / float(ref)) if p_hi is not None and ref else None
    state = "UNASSESSED"
    if band in ("tempo", "sub-threshold") and ratio is not None:
        # <=86% of observed same-duration capability is clearly controlled work,
        # not the athlete's maximal-aerobic / hard-quality anchor.  The threshold is
        # deliberately conservative so ordinary challenging tempo is not erased.
        state = "ROUTINE_SUBTHRESHOLD" if ratio <= 0.86 else "MEANINGFUL"
    elif band in ("threshold", "above-threshold"):
        state = "MEANINGFUL"
    return {
        "state": state,
        "interval_minutes": round(interval_min, 1) if interval_min is not None else None,
        "reference_watts": round(ref, 1) if ref is not None else None,
        "target_ratio": round(ratio, 3) if ratio is not None else None,
    }


def _v4836_health_language_guard(text):
    """Keep training copy out of medical/absolute territory."""
    s = str(text or "")
    replacements = [
        (r"\bcycling load today is not contraindicated\b", "THE LAB has no active cycling restriction today"),
        (r"\b(?:training|cycling|this session) is not contraindicated\b", "THE LAB has no active training restriction for this session"),
        (r"\bshould be softened, not skipped\b", "should be softened or skipped"),
        (r"\bmust not be skipped\b", "may need to be skipped"),
        (r"\bdoes not restrict cycling today\b", "does not currently create an active cycling restriction in THE LAB"),
    ]
    for pat, repl in replacements:
        s = re.sub(pat, repl, s, flags=re.I)
    return re.sub(r"\s{2,}", " ", s).strip()


def _v4836_recommendation_session_truth_guard(text, sessions):
    """Align the standalone Coach Call with the normalized session truth."""
    s = str(text or "").strip()
    sessions = list(sessions or [])
    if not s or not sessions:
        return s
    first = sessions[0]
    first_state = str(first.get("quality_relevance") or "").upper()
    first_cls = str(first.get("intensity_class") or "").lower()
    first_is_max_aerobic = first_cls == "vo2" and first_state != "ROUTINE_SUBTHRESHOLD"
    later_hard = next((x for x in sessions[1:] if x.get("hard_spacing_relevant") and str(x.get("intensity_class") or "").lower() in ("threshold", "vo2")), None)

    # Fixed-window prose is not a Product rule. Measured spacing and athlete context
    # are authoritative instead.
    chunks = re.split(r'(?<=[.!?])\s+', s)
    out = []
    for chunk in chunks:
        low = chunk.lower()
        if re.search(r"\b24[-\s]?hour\b", low) and any(k in low for k in ("limit", "one proper quality", "one quality")):
            out.append("Avoid stacking meaningful hard-quality sessions on a short turnaround when recovery signals are mixed; use the measured spacing shown for each slot.")
            continue
        # If the first normalized workout is not VO2/maximal-aerobic, do not let the
        # Coach claim that this first prescription delivers that stimulus.
        if not first_is_max_aerobic and any(k in low for k in ("maximal-aerobic", "maximal aerobic", "vo2", "vo₂")) and any(k in low for k in ("introduc", "satisf", "this", "re-entry", "stimulus")):
            if first_state == "ROUTINE_SUBTHRESHOLD":
                out.append("Use the first slot as controlled sub-threshold work; against the athlete's observed power-duration history it is not the maximal-aerobic or puncheur anchor.")
            else:
                out.append("The first slot is not the maximal-aerobic anchor; its purpose is the work described in the normalized session card.")
            continue
        if first_state == "ROUTINE_SUBTHRESHOLD" and "quality work" in low and "today" in low:
            out.append("Keep the next low-intensity slot easy so it adds aerobic volume without turning familiar sub-threshold work into a false quality anchor.")
            continue
        if later_hard and re.search(r"\bthis is where the (?:puncheur|quality|vo2|vo₂) anchor belongs\b", low):
            out.append(f"{later_hard.get('slot')} is where the puncheur/quality anchor belongs.")
            continue
        out.append(chunk)
    s = " ".join(x for x in out if x).strip()

    if later_hard and first_state == "ROUTINE_SUBTHRESHOLD":
        already_explicit = (
            "actual hard-quality anchor" in s.lower()
            or ("first quality session" in s.lower() and str(later_hard.get("slot") or "").lower() in s.lower())
        )
        if not already_explicit:
            s = (s.rstrip() + f" The actual hard-quality anchor is {later_hard.get('slot')}: {later_hard.get('title')}.").strip()
    return re.sub(r"\s{2,}", " ", s).strip()


def _v4829_hard_spacing_context_text(recent_activities, coach_clock):
    last_end = _v4829_latest_hard_end(recent_activities)
    if last_end is None:
        return "HARD-SPACING CONTEXT: no prior hard/race end time available."
    lines = [f"HARD-SPACING CONTEXT: previous hard/race load ended {last_end.strftime('%Y-%m-%d %H:%M')} local."]
    for slot in (coach_clock or {}).get("next_slots") or []:
        try:
            d = date.fromisoformat(str(slot.get("date") or "")[:10])
            sm = _rhythm_num(slot.get("start_minute"))
            if sm is None:
                continue
            hh, mm = divmod(max(0, min(1439, int(round(sm)))), 60)
            dt = datetime.combine(d, datetime.min.time()).replace(hour=hh, minute=mm)
            if dt > last_end:
                hours = (dt - last_end).total_seconds()/3600.0
                lines.append(f"- {slot.get('label')}: {hours:.1f} h from previous hard/race end to slot start.")
        except Exception:
            continue
    lines.append("Use these measured intervals; never claim a generic 72 h interval was satisfied unless the measured value actually supports it.")
    return "\n".join(lines)


def normalize_next_sessions(raw_sessions, clock, training_definitions=None, ftp_anchor=None, recent_activities=None, undefined_training_intent=None, power_model=None):
    raw_sessions = raw_sessions if isinstance(raw_sessions, list) else []
    normalized = []
    previous_hard_end = _v4829_latest_hard_end(recent_activities)
    for idx, slot in enumerate(clock.get("next_slots") or []):
        raw = raw_sessions[idx] if idx < len(raw_sessions) and isinstance(raw_sessions[idx], dict) else {}
        planned_env = slot.get("training_environment") if slot.get("is_planned_training") else None
        planned_demand = slot.get("training_demand") if slot.get("is_planned_training") else None
        duration_fallback = slot.get("duration_hint_label") or "Coach-selected duration"
        slot_dt = _v4830_slot_datetime(slot)
        since_last_hard_hours = None
        if slot_dt is not None and previous_hard_end is not None and slot_dt > previous_hard_end:
            since_last_hard_hours = round((slot_dt - previous_hard_end).total_seconds() / 3600.0, 1)

        if slot.get("is_race"):
            normalized.append({
                "slot": slot["label"], "date": slot.get("date"), "period": "RACE",
                "title": slot.get("event_title") or "Race day", "duration": str(raw.get("duration") or "Priority event"),
                "intensity": "Race", "intensity_class": "vo2",
                "main_set": "Race day. No additional training session is prescribed for this opportunity.",
                "why": "This registered race/event has priority over routine training.",
                "restriction": "RACE", "environment": "OUTDOOR", "planned_demand": "RACE",
                "is_planned_training": False, "source": slot.get("source"), "timing_confidence": slot.get("timing_confidence"),
                "start_minute": slot.get("start_minute"), "duration_hint_min": slot.get("duration_hint_min"),
                "hard_spacing_hours": since_last_hard_hours, "since_last_hard_hours": since_last_hard_hours,
                "athlete_intent_notice": None, "definition_notice": None,
            })
            if slot_dt is not None:
                dur_min = _parse_duration_minutes(str(raw.get("duration") or duration_fallback)) or slot.get("duration_hint_min") or 0
                previous_hard_end = slot_dt + timedelta(minutes=max(0, float(dur_min or 0)))
            continue

        if slot.get("restriction") == "NO_INTENSITY":
            normalized.append({
                "slot": slot["label"], "date": slot.get("date"), "period": slot.get("period"),
                "title": "Aerobic endurance · restriction active", "duration": str(raw.get("duration") or duration_fallback),
                "intensity": "Z1–Z2 only", "intensity_class": "recovery",
                "main_set": "Easy aerobic riding only. No threshold, VO₂, over-under, sprint or other intentional intensity.",
                "why": f'Python-enforced no-intensity restriction is active through {slot.get("restriction_until") or "the active restriction end date"}; health/availability constraints outrank AI prescription and learned rhythm.',
                "restriction": "NO_INTENSITY", "environment": planned_env or ATHLETE_FUELING_PROFILE["default_training_environment"],
                "planned_demand": planned_demand, "is_planned_training": bool(slot.get("is_planned_training")),
                "source": slot.get("source"), "timing_confidence": slot.get("timing_confidence"),
                "start_minute": slot.get("start_minute"), "duration_hint_min": slot.get("duration_hint_min"),
                "hard_spacing_hours": None, "since_last_hard_hours": since_last_hard_hours,
                "athlete_intent_notice": None, "definition_notice": None,
            })
            continue

        intensity = str(raw.get("intensity") or "Training")
        title = str(raw.get("title") or (slot.get("event_title") if slot.get("is_planned_training") else None) or "Coach-selected session")
        main_set = str(raw.get("main_set") or "See coach recommendation.")
        why = str(raw.get("why") or ("Built around the athlete's planned training commitment and current recovery context." if slot.get("is_planned_training") else "Selected from current recovery, load, learned training rhythm, timing and event context."))

        coherence = _v4827_session_coherence(
            title, intensity, main_set, why, ftp_anchor=ftp_anchor, training_definitions=training_definitions
        )
        title = _v4830_title_language_guard(coherence["title"])
        intensity = coherence["intensity"]
        main_set = coherence["main_set"]
        why = coherence["why"]
        original_cls = coherence["intensity_class"]
        cls = _v4830_workout_classification(
            title, intensity, main_set, coherence=coherence, restriction="NONE", planned_demand=planned_demand
        )
        coherence_reasons = list(coherence.get("coherence_reasons") or [])
        if cls != original_cls:
            coherence_reasons.append(f"DETERMINISTIC_CLASS_{original_cls.upper()}_TO_{cls.upper()}")

        quality_calibration = _v4836_quality_calibration(coherence, main_set, power_model)
        quality_relevance = quality_calibration.get("state")
        hard_spacing_relevant = cls in ("tempo", "threshold", "vo2") and quality_relevance != "ROUTINE_SUBTHRESHOLD"
        if quality_relevance == "ROUTINE_SUBTHRESHOLD":
            # Preserve the workout family but stop presenting familiar controlled work
            # as a hard/intensity anchor for an athlete whose observed duration-specific
            # capacity is materially higher.
            if re.match(r"^\s*hard\s*$", intensity, flags=re.I):
                intensity = "CONTROLLED SUB-THRESHOLD"
            coherence_reasons.append("ATHLETE_CAPABILITY_DOWNRANKED")
            ref = quality_calibration.get("reference_watts")
            mins = quality_calibration.get("interval_minutes")
            ratio = quality_calibration.get("target_ratio")
            if ref is not None and mins is not None and ratio is not None:
                calibration_note = (
                    f"Against the athlete's observed ~{mins:g}-min power reference of about {ref:.0f} W, "
                    f"the top target is {ratio*100:.0f}% of that reference; THE LAB treats this as controlled "
                    "sub-threshold work rather than the hard-quality anchor."
                )
                # Remove claims that this clearly routine sub-threshold prescription
                # itself supplies VO2/maximal-aerobic/puncheur intensity. Preserve
                # unrelated rationale and then append the athlete-specific calibration.
                why_chunks = re.split(r'(?<=[.!?])\s+', why)
                kept_why = []
                for chunk in why_chunks:
                    low_chunk = chunk.lower().replace("vo₂", "vo2")
                    false_quality_claim = (
                        any(k in low_chunk for k in ("maximal-aerobic", "maximal aerobic", "vo2", "puncheur", "goal-stimulus", "goal stimulus"))
                        and any(k in low_chunk for k in ("introduc", "anchor", "stimulus", "serves", "satisf", "builds"))
                    )
                    if not false_quality_claim:
                        kept_why.append(chunk)
                why = " ".join(x for x in kept_why if x).strip()
                if calibration_note.lower() not in why.lower():
                    why = ((why.rstrip() + " ") if why else "") + calibration_note

        if slot.get("is_planned_training") and planned_demand == "EASY" and cls not in ("recovery", "endurance"):
            intensity = "Easy aerobic / recovery"
            cls = "recovery"
            main_set = "Keep the athlete-planned session easy: Z1–Z2 only, with no intentional threshold, VO₂, over-under or sprint work."
            why = "The Calendar marks this planned training as EASY; Python prevents an accidental hard prescription."
            coherence_reasons.append("PLANNED_EASY_CEILING")
            hard_spacing_relevant = False
            quality_relevance = "NOT_HARD"

        why = _v4829_physiology_language_guard(why)
        why = _v4836_health_language_guard(why)
        why = _v4830_session_duration_reference_guard(why, main_set, power_model)
        why = _v4830_strip_untrusted_spacing_claims(why)

        spacing_hours = since_last_hard_hours if hard_spacing_relevant else None
        if spacing_hours is not None:
            measured = f"Measured spacing from the previous hard/race load to this quality slot is {spacing_hours:.1f} h."
            if measured.lower() not in why.lower():
                why = (why.rstrip() + " " + measured).strip()

        athlete_intent_notice = None
        definition_notice = None  # retained for backward-compatible stored-report rendering
        if undefined_training_intent and str(undefined_training_intent.get("target_date") or "") == str(slot.get("date") or "") and str(undefined_training_intent.get("term") or "").upper() == "TTE":
            definition_available = bool(undefined_training_intent.get("definition_available"))
            final_mentions_tte = bool(re.search(r"\bTTE\b|time[-\s]+to[-\s]+exhaustion", " ".join((title, intensity, main_set)), flags=re.I))
            if cls not in ("tempo", "threshold", "vo2"):
                athlete_intent_notice = "ATHLETE-REPORTED TTE · NOT RECOMMENDED FOR THIS SLOT"
                spacing_note = f" Measured spacing from the previous hard/race load to this slot is {since_last_hard_hours:.1f} h." if since_last_hard_hours is not None else ""
                prefix = (
                    "You reported TTE for this slot, but THE LAB is not recommending a TTE/quality session here; the current prescription remains easy aerobic work after considering the recent hard/race load, recovery signals and plan context."
                    + spacing_note + " "
                )
                if not definition_available:
                    prefix += "A TRAINING DEFINITION is optional and only needed if you want THE LAB to learn your exact TTE protocol. "
            elif final_mentions_tte and definition_available:
                athlete_intent_notice = "ATHLETE-REPORTED TTE · COACH ALIGNED"
                prefix = "You reported TTE for this slot and the prescribed session remains explicitly aligned with your saved TTE definition. "
            elif definition_available:
                athlete_intent_notice = "ATHLETE-REPORTED TTE · DIFFERENT QUALITY PRESCRIBED"
                prefix = "You reported TTE for this slot, but THE LAB selected a different quality structure; it does not present that alternative as if it fulfilled your TTE protocol. "
            else:
                athlete_intent_notice = "ATHLETE-REPORTED TTE · EXACT PROTOCOL NOT DEFINED"
                prefix = (
                    "You reported TTE for this slot. THE LAB is prescribing quality work, but it will not claim that this session is your TTE protocol because no athlete-specific TTE definition is saved. "
                    "If TTE has a precise structure for you, you can save that protocol as a TRAINING DEFINITION in Memory. "
                )
            why = prefix + why

        normalized.append({
            "slot": slot["label"], "date": slot.get("date"), "period": slot.get("period"),
            "title": title, "duration": str(raw.get("duration") or duration_fallback), "intensity": intensity,
            "intensity_class": cls, "main_set": main_set, "why": why.strip(), "restriction": "NONE",
            "environment": planned_env or ATHLETE_FUELING_PROFILE["default_training_environment"],
            "planned_demand": planned_demand, "is_planned_training": bool(slot.get("is_planned_training")),
            "source": slot.get("source"), "timing_confidence": slot.get("timing_confidence"),
            "start_minute": slot.get("start_minute"), "duration_hint_min": slot.get("duration_hint_min"),
            "coherence_adjusted": bool(coherence.get("coherence_adjusted", False) or cls != original_cls or coherence_reasons),
            "coherence_reasons": coherence_reasons,
            "prescribed_power_low": coherence.get("prescribed_power_low"),
            "prescribed_power_high": coherence.get("prescribed_power_high"),
            "ftp_anchor_watts": coherence.get("ftp_anchor_watts"),
            "power_band": coherence.get("power_band"),
            "quality_relevance": quality_relevance,
            "quality_reference_watts": quality_calibration.get("reference_watts"),
            "quality_reference_interval_min": quality_calibration.get("interval_minutes"),
            "quality_target_ratio": quality_calibration.get("target_ratio"),
            "hard_spacing_relevant": bool(hard_spacing_relevant),
            "hard_spacing_hours": spacing_hours,
            "since_last_hard_hours": since_last_hard_hours,
            "athlete_intent_notice": athlete_intent_notice,
            "definition_notice": definition_notice,
        })
        if hard_spacing_relevant and slot_dt is not None:
            dur_min = _parse_duration_minutes(str(raw.get("duration") or duration_fallback)) or slot.get("duration_hint_min") or 0
            previous_hard_end = slot_dt + timedelta(minutes=max(0, float(dur_min or 0)))
    return normalized



def _nutrition_number(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def _activity_local_dt(activity):
    raw = str(activity.get("start_date_local") or "")
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        try:
            return datetime.strptime(raw[:16], "%Y-%m-%dT%H:%M")
        except ValueError:
            return None


def build_weight_context(season_wellness, now=None):
    """Return weight value without inventing physical-measurement freshness.

    Intervals can carry or rewrite the same weight.  Even a non-temporary Wellness
    row does not prove a physical weigh-in on that date.  THE LAB therefore exposes
    the numeric value as context but marks date/freshness UNVERIFIED unless a future
    source provides explicit measurement provenance.
    """
    now = now or get_rome_now()
    observation = _latest_weight_provenance(season_wellness)
    kg = _nutrition_number(observation.get("value"))
    if kg is None or kg <= 0:
        return {
            "kg": None, "date": None, "age_days": None, "status": "MISSING",
            "needs_update": True, "label": "No weight in the current data window",
            "detail": "Update body weight before calculating a precise carb-loading total.",
            "carried_forward": False, "latest_row_date": None, "provenance_verified": False,
        }
    observed_since = observation.get("unchanged_since") or observation.get("date")
    latest_row_date = observation.get("latest_row_date")
    observed_label = observed_since.strftime("%d %b") if isinstance(observed_since, date) else "unknown date"
    detail = (
        f"{kg:.1f} kg · Intervals shows this value (observed in the available Wellness data since at least {observed_label}), "
        "but THE LAB cannot verify the date of the physical weigh-in. Sync/carried-forward rows must not reset weight freshness. "
        "Refresh/confirm weight before any precision-sensitive g/kg total."
    )
    return {
        "kg": round(kg, 1), "date": None, "observed_since": observed_since.isoformat() if isinstance(observed_since, date) else None,
        "age_days": None, "status": "DATE UNVERIFIED", "needs_update": True,
        "label": f"{kg:.1f} kg · DATE UNVERIFIED", "detail": detail,
        "carried_forward": bool(observation.get("carried_forward")),
        "latest_row_date": latest_row_date.isoformat() if isinstance(latest_row_date, date) else None,
        "provenance_verified": False,
    }

def assess_intervals_cho(activity):
    """Sanity-check Intervals.icu's estimated carbohydrate utilisation.

    Intervals exposes carbs_used and carbs_ingested. carbs_used is modelled, not
    directly measured. Known model limitations make very short/long sessions and
    impossible energy relationships unsuitable for quantitative glycogen context.
    """
    used = _nutrition_number(activity.get("carbs_used"))
    ingested = _nutrition_number(activity.get("carbs_ingested")) or 0.0
    kcal = _nutrition_number(activity.get("calories"))
    secs = _nutrition_number(activity.get("moving_time") or activity.get("elapsed_time")) or 0.0
    mins = secs / 60.0
    result = {
        "used_g": round(used, 1) if used is not None else None,
        "ingested_g": round(max(0.0, ingested), 1),
        "valid": False, "reason": "No Intervals CHO-use estimate", "duration_min": round(mins, 1),
    }
    if used is None or used < 0:
        return result
    if mins < 30 or mins > 90:
        result["reason"] = "Low confidence: Intervals CHO model is least reliable outside roughly 30–90 min"
        return result
    if kcal is not None and kcal > 0 and used * 4.0 > kcal * 1.10:
        result["reason"] = "Low confidence: estimated CHO energy exceeds total session calories"
        return result
    result["valid"] = True
    result["reason"] = "Accepted as a model estimate after duration/energy sanity checks"
    return result


def build_metabolic_context(recent_activities, season_wellness, planning_context, now=None):
    """Build deterministic energy/glycogen/race context before the AI is called."""
    now = now or get_rome_now()
    planning_context = planning_context or {}
    local_now = now.replace(tzinfo=None) if now.tzinfo else now
    since36 = local_now - timedelta(hours=36)
    since48 = local_now - timedelta(hours=48)
    acts36, acts48 = [], []
    for a in recent_activities or []:
        dt = _activity_local_dt(a)
        if not dt:
            continue
        if dt.tzinfo:
            dt = dt.astimezone(_runtime_timezone()).replace(tzinfo=None)
        if dt >= since48:
            acts48.append(a)
        if dt >= since36:
            acts36.append(a)

    kcal36 = round(sum(_nutrition_number(a.get("calories")) or 0 for a in acts36))
    kcal48 = round(sum(_nutrition_number(a.get("calories")) or 0 for a in acts48))
    load48 = round(sum(_nutrition_number(a.get("icu_training_load")) or 0 for a in acts48), 1)
    hard48 = sum(1 for a in acts48 if is_hard_training_family(classify_training_family(a)))

    cho_checks = [assess_intervals_cho(a) for a in acts48]
    valid_cho = [c for c in cho_checks if c["valid"]]
    invalid_cho = [c for c in cho_checks if c.get("used_g") is not None and not c["valid"]]
    used48 = round(sum(c["used_g"] or 0 for c in valid_cho), 1) if valid_cho else None
    ingested48 = round(sum(c["ingested_g"] or 0 for c in valid_cho), 1) if valid_cho else None
    exercise_gap = round(max(0.0, (used48 or 0) - (ingested48 or 0)), 1) if valid_cho else None

    score = 0
    if kcal48 >= 1400: score += 2
    elif kcal48 >= 700: score += 1
    if load48 >= 140: score += 2
    elif load48 >= 70: score += 1
    if hard48 >= 2: score += 2
    elif hard48 == 1: score += 1
    if exercise_gap is not None:
        if exercise_gap >= 160: score += 2
        elif exercise_gap >= 80: score += 1
    glycogen_pressure = "HIGH" if score >= 5 else ("MODERATE" if score >= 2 else "LOW")

    weight = build_weight_context(season_wellness, now)
    race = planning_context.get("next_race") or None
    health = planning_context.get("health_override")
    if not race:
        race_state = "OFF"
        race_detail = "No upcoming race is registered in the active planning horizon."
    elif health or race.get("conflict"):
        race_state = "PAUSED"
        race_detail = "Health/restriction context outranks race-prep nutrition until the conflict is resolved."
    else:
        days = int(race.get("days_away") or 0)
        if days <= 0:
            race_state = "RACE DAY"
            race_detail = "Race day: prioritize pre-race availability and the athlete's practised ~100 g CHO/h race fueling strategy."
        elif days <= ATHLETE_FUELING_PROFILE["carb_loading_active_days"]:
            race_state = "ACTIVE"
            race_detail = "Carbohydrate-loading relevance is high: raise daily carbohydrate availability rather than judging recovery meal-by-meal."
        elif days <= ATHLETE_FUELING_PROFILE["carb_loading_approaching_days"]:
            race_state = "APPROACHING"
            race_detail = "Race carbohydrate-loading window is approaching; begin protecting glycogen availability while taper volume falls."
        else:
            race_state = "NOT YET"
            race_detail = f"Race is {days} days away; deliberate carbohydrate loading is not active yet."

    gkg_low = ATHLETE_FUELING_PROFILE["carb_loading_gkg_low"]
    gkg_high = ATHLETE_FUELING_PROFILE["carb_loading_gkg_high"]
    total_range = None
    if race_state == "ACTIVE" and weight.get("kg") and not weight.get("needs_update"):
        lo = int(round(weight["kg"] * gkg_low / 10.0) * 10)
        hi = int(round(weight["kg"] * gkg_high / 10.0) * 10)
        total_range = f"~{lo}–{hi} g CHO/day"

    return {
        "kcal_36h": kcal36, "kcal_48h": kcal48, "load_48h": load48,
        "hard_sessions_48h": hard48, "glycogen_pressure": glycogen_pressure,
        "cho_used_48h": used48, "cho_ingested_48h": ingested48,
        "exercise_cho_gap_48h": exercise_gap, "cho_valid_count": len(valid_cho),
        "cho_low_confidence_count": len(invalid_cho), "weight": weight,
        "race_strategy": {
            "state": race_state, "detail": race_detail,
            "title": race.get("title") if race else None,
            "date": race.get("start_date") if race else None,
            "days_away": race.get("days_away") if race else None,
            "race_fueling": f'~{ATHLETE_FUELING_PROFILE["race_g_per_hour"]} g CHO/h',
            "loading_gkg": f"{gkg_low:.0f}–{gkg_high:.0f} g/kg/day reference" if race_state in ("ACTIVE", "APPROACHING") else None,
            "loading_total": total_range,
            "weight_update_required": bool(race_state == "ACTIVE" and weight.get("needs_update")),
        },
    }


def metabolic_context_text(context):
    c = context or {}
    r = c.get("race_strategy") or {}
    w = c.get("weight") or {}
    used = c.get("cho_used_48h")
    ing = c.get("cho_ingested_48h")
    gap = c.get("exercise_cho_gap_48h")
    cho_line = "No reliable Intervals CHO-use estimate in the last 48h."
    if used is not None:
        cho_line = f"Accepted Intervals estimate: {used} g CHO used; {ing or 0} g recorded ingested; exercise-only gap {gap} g."
    return (
        "NUTRITION / GLYCOGEN CONTEXT (Python-derived; use for reasoning, do not invent glycogen stores):\n"
        f'- Athlete fueling baseline: race ~{ATHLETE_FUELING_PROFILE["race_g_per_hour"]} g CHO/h; hard outdoor training ~{ATHLETE_FUELING_PROFILE["hard_outdoor_g_per_hour"]} g/h; indoor training usually 0 g/h during the session, with carbohydrate handled in recovery.\n'
        f'- Duration-aware outdoor baseline: 90–150 min endurance ~{ATHLETE_FUELING_PROFILE["medium_outdoor_gph_low"]}–{ATHLETE_FUELING_PROFILE["medium_outdoor_gph_high"]} g/h; >150 min endurance ~{ATHLETE_FUELING_PROFILE["long_outdoor_gph_low"]}–{ATHLETE_FUELING_PROFILE["long_outdoor_gph_high"]} g/h even when intensity is Z2/easy, because duration itself increases carbohydrate demand.\n'
        f'- Completed training last 36h: {c.get("kcal_36h", 0)} kcal. Last 48h: {c.get("kcal_48h", 0)} kcal, load {c.get("load_48h", 0)}, hard/quality sessions {c.get("hard_sessions_48h", 0)}.\n'
        f'- Glycogen replenishment pressure: {c.get("glycogen_pressure", "LOW")}. {cho_line} Low-confidence CHO estimates ignored: {c.get("cho_low_confidence_count", 0)}.\n'
        f'- Weight confidence: {w.get("status", "MISSING")} | {w.get("detail", "No weight available")}.\n'
        f'- Race carb strategy: {r.get("state", "OFF")} | {r.get("detail", "")}' + (f' | {r.get("loading_gkg")}' if r.get("loading_gkg") else '') + (f' | {r.get("loading_total")}' if r.get("loading_total") else '') + "\n"
        "- CRITICAL INTERPRETATION RULE: keep SESSION DEMAND, DURATION DEMAND and RECOVERY NEED separate. A long easy/Z2 ride can remain LOW or LOW–MODERATE intensity demand while still requiring substantial intra-ride carbohydrate and HIGH daily replenishment priority.\n"
        "- POST-RIDE RULE: an initial recovery target is the first feeding, not an instruction to replace all ride calories immediately. For long rides, reason across the following meals and the whole-day carbohydrate/energy context. If recovery time is <4 h, rapid glycogen restoration can justify ~1.0–1.2 g/kg/h.\n"
        "- If carb loading is ACTIVE and weight is stale/missing, explicitly ask the athlete to update weight before giving a precise total grams/day target."
    )


def classify_upcoming_session_demand(session_item):
    """Classify prescribed demand from structured fields, never main-set prose."""
    restriction = str(session_item.get("restriction") or "").upper()
    intensity_cls = str(session_item.get("intensity_class") or "endurance").lower()
    title = str(session_item.get("title") or "").lower()
    intensity = str(session_item.get("intensity") or "").lower()
    short_text = f"{title} {intensity}"
    planned_demand = str(session_item.get("planned_demand") or "").upper() or None

    if restriction == "RACE" or str(session_item.get("period") or "").upper() == "RACE":
        kind = "RACE"
    elif restriction == "NO_INTENSITY" or intensity_cls == "recovery" or planned_demand == "EASY":
        kind = "RECOVERY"
    elif intensity_cls == "endurance":
        kind = "HEAT" if any(k in short_text for k in ("heat", "thermal", "hot room", "caldo")) else "ENDURANCE"
    elif intensity_cls == "tempo":
        kind = "TEMPO"
    elif intensity_cls == "threshold":
        kind = "THRESHOLD"
    elif intensity_cls == "vo2":
        kind = "VO2"
    else:
        kind = "ENDURANCE"

    demand = {
        "RECOVERY": "LOW", "ENDURANCE": "LOW–MODERATE", "HEAT": "MODERATE",
        "TEMPO": "MODERATE–HIGH", "THRESHOLD": "HIGH", "VO2": "HIGH", "RACE": "VERY HIGH",
    }[kind]
    if planned_demand == "HARD" and kind != "RECOVERY" and restriction not in ("NO_INTENSITY", "RACE"):
        demand = "HIGH"
    elif planned_demand == "NORMAL" and kind in ("RECOVERY", "ENDURANCE") and restriction != "NO_INTENSITY":
        demand = "MODERATE"

    structured_env = str(session_item.get("environment") or "").upper()
    if structured_env in ("INDOOR", "OUTDOOR"):
        environment = structured_env
    else:
        explicit_outdoor = any(k in short_text for k in ("outdoor", "road", "outside", "granfondo", "gran fondo", "race"))
        explicit_indoor = any(k in short_text for k in ("indoor", "zwift", "trainer"))
        environment = "OUTDOOR" if (kind == "RACE" or explicit_outdoor) else ("INDOOR" if explicit_indoor else ATHLETE_FUELING_PROFILE["default_training_environment"])
    return {"kind": kind, "demand": demand, "environment": environment, "planned_demand": planned_demand}



def _parse_duration_minutes(value):
    """Best-effort parser for Coach duration strings such as 4 h, 3h30, 90 min or 1:45.

    For a displayed range (e.g. 3–4 h or 90–120 min), use the upper bound for
    fueling so THE LAB does not under-fuel the planned session merely because the
    exact finish time is flexible.
    """
    if isinstance(value, (int, float)):
        v = _nutrition_number(value)
        return round(v, 1) if v and v > 0 else None
    text = str(value or "").strip().lower().replace(",", ".")
    if not text:
        return None

    hr_range = re.search(r"(\d+(?:\.\d+)?)\s*[–—-]\s*(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|h|ore|ora)\b", text)
    if hr_range:
        return round(float(hr_range.group(2)) * 60.0, 1)
    min_range = re.search(r"(\d+(?:\.\d+)?)\s*[–—-]\s*(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|min|m)\b", text)
    if min_range:
        return round(float(min_range.group(2)), 1)

    clock = re.search(r"(?<!\d)(\d{1,2}):(\d{2})(?!\d)", text)
    if clock:
        hours, minutes = int(clock.group(1)), int(clock.group(2))
        if minutes < 60:
            return round(hours * 60.0 + minutes, 1)

    hour = re.search(r"(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|h|ore|ora)", text)
    minute = re.search(r"(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|min|m)\b", text)
    if hour:
        total = float(hour.group(1)) * 60.0
        # Handles compact forms such as 3h30 or 3h30m.
        tail = text[hour.end():]
        compact_min = re.match(r"\s*(\d{1,2})(?:\s*(?:minutes?|mins?|min|m))?\b", tail)
        if compact_min:
            total += float(compact_min.group(1))
        elif minute and minute.start() >= hour.end():
            total += float(minute.group(1))
        return round(total, 1) if total > 0 else None
    if minute:
        return round(float(minute.group(1)), 1)
    return None


def _session_duration_minutes(session_item):
    for key in ("duration_minutes", "duration_min"):
        value = _nutrition_number((session_item or {}).get(key))
        if value and value > 0:
            return round(value, 1)
    return _parse_duration_minutes((session_item or {}).get("duration"))


def _format_duration_hours(duration_min):
    if not duration_min:
        return None
    hours = duration_min / 60.0
    if abs(hours - round(hours)) < 0.05:
        return f"{int(round(hours))} h"
    return f"{hours:.1f} h"


def _fuel_total_display(low_gph, high_gph, duration_min):
    if duration_min is None or low_gph is None or high_gph is None or high_gph <= 0:
        return None
    hours = duration_min / 60.0
    low_total = int(round((low_gph * hours) / 10.0) * 10)
    high_total = int(round((high_gph * hours) / 10.0) * 10)
    dur = _format_duration_hours(duration_min)
    if low_gph == high_gph:
        return f"~{high_total} g CHO across {dur}"
    return f"~{low_total}–{high_total} g CHO across {dur}"


# V28 guardrail: intra-session fueling must follow the normalized physiological
# prescription. Negative mentions such as "no tempo" or "below threshold" are
# not allowed to turn an ENDURANCE/Z2 session into HARD OUTDOOR.
def _intra_fueling_strategy(kind, environment, planned_demand, duration_min, glycogen_pressure="LOW"):
    """Return athlete-specific intra-session CHO, with duration as its own axis."""
    if kind == "RACE":
        g = ATHLETE_FUELING_PROFILE["race_g_per_hour"]
        return {
            "display": f"~{g} g CHO/h", "label": "PRACTISED RACE TARGET",
            "low_gph": g, "high_gph": g,
            "total": _fuel_total_display(g, g, duration_min),
            "duration_driver": "RACE",
        }

    if environment == "INDOOR":
        hard_quality = kind in ("TEMPO", "THRESHOLD", "VO2") or (planned_demand == "HARD" and kind != "RECOVERY")
        if hard_quality and ((duration_min is not None and duration_min >= 60) or str(glycogen_pressure).upper() == "HIGH"):
            lo, hi = 20, 40
            return {
                "display": "20–40 g CHO/h if pre-session fueling is incomplete", "label": "INDOOR QUALITY · CONDITIONAL",
                "low_gph": lo, "high_gph": hi, "total": _fuel_total_display(lo, hi, duration_min),
                "duration_driver": "QUALITY + GLYCOGEN CONTEXT",
            }
        g = ATHLETE_FUELING_PROFILE["indoor_default_g_per_hour"]
        return {
            "display": f"{g} g/h usual", "label": "INDOOR BASELINE",
            "low_gph": g, "high_gph": g, "total": None,
            "duration_driver": "ATHLETE BASELINE",
        }

    if environment != "OUTDOOR":
        return {
            "display": "No fixed target", "label": "MATCH DURATION / DEMAND",
            "low_gph": None, "high_gph": None, "total": None,
            "duration_driver": "UNKNOWN DURATION/ENVIRONMENT",
        }

    hard_quality = (
        (planned_demand == "HARD" and kind != "RECOVERY")
        or kind in ("TEMPO", "THRESHOLD", "VO2")
    )
    if hard_quality:
        g = ATHLETE_FUELING_PROFILE["hard_outdoor_g_per_hour"]
        return {
            "display": f"~{g} g CHO/h", "label": "HARD OUTDOOR BASELINE",
            "low_gph": g, "high_gph": g,
            "total": _fuel_total_display(g, g, duration_min),
            "duration_driver": "INTENSITY + DURATION" if duration_min else "INTENSITY",
        }

    medium_min = ATHLETE_FUELING_PROFILE["medium_outdoor_min"]
    long_min = ATHLETE_FUELING_PROFILE["long_outdoor_min"]
    if duration_min is not None and duration_min > long_min:
        lo = ATHLETE_FUELING_PROFILE["long_outdoor_gph_low"]
        hi = ATHLETE_FUELING_PROFILE["long_outdoor_gph_high"]
        return {
            "display": f"{lo}–{hi} g CHO/h", "label": "LONG ENDURANCE · DURATION-DRIVEN",
            "low_gph": lo, "high_gph": hi,
            "total": _fuel_total_display(lo, hi, duration_min),
            "duration_driver": "HIGH",
        }
    if duration_min is not None and duration_min >= medium_min:
        lo = ATHLETE_FUELING_PROFILE["medium_outdoor_gph_low"]
        hi = ATHLETE_FUELING_PROFILE["medium_outdoor_gph_high"]
        return {
            "display": f"{lo}–{hi} g CHO/h", "label": "ENDURANCE · DURATION-AWARE",
            "low_gph": lo, "high_gph": hi,
            "total": _fuel_total_display(lo, hi, duration_min),
            "duration_driver": "MODERATE",
        }
    if duration_min is not None:
        return {
            "display": "0–30 g CHO/h", "label": "SHORT OUTDOOR · OPTIONAL / CONTEXTUAL",
            "low_gph": 0, "high_gph": 30,
            "total": _fuel_total_display(0, 30, duration_min),
            "duration_driver": "LOW",
        }
    return {
        "display": "No fixed target", "label": "MATCH DURATION / DEMAND",
        "low_gph": None, "high_gph": None, "total": None,
        "duration_driver": "UNKNOWN",
    }



def _session_clock(session_item):
    ds = str((session_item or {}).get("date") or "")[:10]
    try:
        d = date.fromisoformat(ds)
    except ValueError:
        return None
    start_minute = _rhythm_num((session_item or {}).get("start_minute"))
    if start_minute is None:
        # Date-only Calendar/race entries intentionally do not invent a clock time;
        # Nutrition turnaround logic only uses a gap when timing is actually known.
        return None
    start_minute = max(0, min(1439, int(round(start_minute))))
    hour, minute = divmod(start_minute, 60)
    return datetime.combine(d, datetime.min.time()).replace(hour=hour, minute=minute)


def _base_post_workout_range(kind, metabolic_context, next_gap_hours=None):
    """Legacy session-scaled first-feeding target for non-long sessions."""
    base = {
        "RECOVERY": (0, 20), "ENDURANCE": (0, 30), "HEAT": (30, 40),
        "TEMPO": (40, 50), "THRESHOLD": (50, 60), "VO2": (50, 60), "RACE": (60, 90),
    }[kind]
    boost = 0
    pressure = str((metabolic_context or {}).get("glycogen_pressure") or "LOW")
    if pressure == "HIGH": boost += 15
    elif pressure == "MODERATE": boost += 5
    if next_gap_hours is not None:
        if next_gap_hours <= 10: boost += 10
        elif next_gap_hours <= 20: boost += 5
    race_state = str(((metabolic_context or {}).get("race_strategy") or {}).get("state") or "OFF")
    if race_state == "ACTIVE": boost += 20
    elif race_state == "APPROACHING": boost += 10
    caps = {"RECOVERY": 60, "ENDURANCE": 60, "HEAT": 70, "TEMPO": 80, "THRESHOLD": 90, "VO2": 90, "RACE": 100}
    lo = min(caps[kind], base[0] + boost)
    hi = min(caps[kind], base[1] + boost)
    lo = int(round(lo / 10.0) * 10)
    hi = int(round(hi / 10.0) * 10)
    if hi <= 20:
        return "0–20 g CHO", "LIGHT"
    if lo == hi:
        return f"~{hi} g CHO", "MODERATE" if hi < 60 else "HIGH"
    return f"{lo}–{hi} g CHO", "MODERATE" if hi < 60 else "HIGH"


def _weight_scaled_target(weight_context, low_gkg, high_gkg=None, per_hour=False, suffix=""):
    high_gkg = low_gkg if high_gkg is None else high_gkg
    weight_context = weight_context or {}
    kg = _nutrition_number(weight_context.get("kg"))
    usable = bool(kg and kg > 0 and not weight_context.get("needs_update"))
    unit = "g CHO/h" if per_hour else "g CHO"
    if usable:
        lo = int(round((kg * low_gkg) / 5.0) * 5)
        hi = int(round((kg * high_gkg) / 5.0) * 5)
        amount = f"~{lo} {unit}" if lo == hi else f"~{lo}–{hi} {unit}"
        return f"{amount}{suffix}"
    amount = f"~{low_gkg:.1f} g/kg" if abs(low_gkg - high_gkg) < 0.01 else f"~{low_gkg:.1f}–{high_gkg:.1f} g/kg"
    if per_hour:
        amount += "/h"
    return f"{amount} CHO{suffix}"


def _post_workout_strategy(kind, metabolic_context, next_gap_hours=None, duration_min=None):
    """Separate the first recovery feeding from whole-day replenishment priority."""
    metabolic_context = metabolic_context or {}
    pressure = str(metabolic_context.get("glycogen_pressure") or "LOW")
    race_state = str((metabolic_context.get("race_strategy") or {}).get("state") or "OFF")
    weight = metabolic_context.get("weight") or {}
    long_ride = bool(duration_min is not None and duration_min > ATHLETE_FUELING_PROFILE["long_outdoor_min"])
    medium_ride = bool(duration_min is not None and duration_min >= ATHLETE_FUELING_PROFILE["medium_outdoor_min"])
    rapid_recovery = bool(next_gap_hours is not None and next_gap_hours < 4)

    if rapid_recovery:
        post_cho = _weight_scaled_target(
            weight,
            ATHLETE_FUELING_PROFILE["rapid_recovery_gkg_low"],
            ATHLETE_FUELING_PROFILE["rapid_recovery_gkg_high"],
            per_hour=True,
            suffix=" · first 3–4 h",
        )
        recovery_need = "VERY HIGH"
        post_label = "RAPID GLYCOGEN RESTORATION"
    elif long_ride or kind == "RACE":
        gkg = ATHLETE_FUELING_PROFILE["long_ride_initial_gkg"]
        post_cho = _weight_scaled_target(weight, gkg, suffix=" initial")
        recovery_need = "HIGH"
        post_label = "LONG-RIDE INITIAL RECOVERY" if kind != "RACE" else "POST-RACE INITIAL RECOVERY"
    else:
        post_cho, recovery_need = _base_post_workout_range(kind, metabolic_context, next_gap_hours)
        post_label = None

    priority_score = 0
    if long_ride or kind == "RACE": priority_score += 3
    elif medium_ride: priority_score += 1
    if kind in ("TEMPO", "THRESHOLD", "VO2"): priority_score += 2
    elif kind == "HEAT": priority_score += 1
    if pressure == "HIGH": priority_score += 2
    elif pressure == "MODERATE": priority_score += 1
    if rapid_recovery: priority_score += 3
    elif next_gap_hours is not None and next_gap_hours <= 10: priority_score += 2
    elif next_gap_hours is not None and next_gap_hours <= 20: priority_score += 1
    if race_state == "ACTIVE": priority_score += 2
    elif race_state == "APPROACHING": priority_score += 1

    if long_ride or kind == "RACE" or rapid_recovery:
        daily_priority = "HIGH"
    elif priority_score >= 4:
        daily_priority = "HIGH"
    elif priority_score >= 2:
        daily_priority = "MODERATE"
    else:
        daily_priority = "LOW"

    if rapid_recovery:
        replenishment_guidance = "Short turnaround: distribute carbohydrate repeatedly during the first 3–4 hours. The hourly target is for rapid glycogen restoration, not a one-off meal."
    elif long_ride:
        replenishment_guidance = "The initial target is only the first recovery feeding. A long ride creates substantial cumulative energy and glycogen demand: continue carbohydrate-rich meals/snacks over the next 4–6 hours and across the day rather than trying to replace all ride calories immediately."
    elif kind == "RACE":
        replenishment_guidance = "Treat the first feeding as the start of recovery, then continue carbohydrate and total energy replacement across subsequent meals according to appetite, GI tolerance and the next training demand."
    elif daily_priority == "HIGH":
        replenishment_guidance = "Recent load, race context and/or short turnaround make whole-day carbohydrate availability a priority; do not judge recovery from the first snack alone."
    elif daily_priority == "MODERATE":
        replenishment_guidance = "Use the first recovery feeding as part of the next normal meals; total carbohydrate availability across the day matters more than perfectly matching exercise calories."
    else:
        replenishment_guidance = "Normal meals can cover most recovery needs. The first post-ride target is contextual, not a requirement to replace every exercise calorie immediately."

    return {
        "post_cho": post_cho,
        "recovery_need": recovery_need,
        "post_label_override": post_label,
        "daily_replenishment_priority": daily_priority,
        "replenishment_guidance": replenishment_guidance,
        "rapid_recovery": rapid_recovery,
        "long_ride": long_ride,
        "medium_ride": medium_ride,
    }


def build_nutrition_plan(next_sessions, metabolic_context, now=None):
    """Structured Nutrition Engine: intensity demand != duration demand != recovery need.

    No keyword scan of main_set is allowed here. Session demand comes from the
    normalized intensity class/restriction. Duration independently drives outdoor
    fueling, while recent calories, accepted Intervals CHO estimates, race proximity,
    weight freshness and next-session spacing alter recovery need without changing
    what the workout actually is.
    """
    now = now or get_rome_now()
    metabolic_context = metabolic_context or {}
    sessions = list(next_sessions or [])
    plans = []
    for idx, session_item in enumerate(sessions):
        cls = classify_upcoming_session_demand(session_item)
        kind, demand, environment = cls["kind"], cls["demand"], cls["environment"]
        planned_demand = cls.get("planned_demand")
        duration_min = _session_duration_minutes(session_item)
        current_dt = _session_clock(session_item)
        next_dt = _session_clock(sessions[idx + 1]) if idx + 1 < len(sessions) else None
        gap_hours = None
        if current_dt and next_dt and next_dt > current_dt:
            gap_hours = round((next_dt - current_dt).total_seconds() / 3600.0, 1)

        intra_strategy = _intra_fueling_strategy(kind, environment, planned_demand, duration_min, glycogen_pressure=metabolic_context.get("glycogen_pressure"))
        recovery = _post_workout_strategy(kind, metabolic_context, gap_hours, duration_min)
        post_cho = recovery["post_cho"]
        recovery_need = recovery["recovery_need"]
        race_state = str((metabolic_context.get("race_strategy") or {}).get("state") or "OFF")
        pressure = str(metabolic_context.get("glycogen_pressure") or "LOW")

        if recovery.get("post_label_override"):
            post_label = recovery["post_label_override"]
            guidance = recovery["replenishment_guidance"]
        elif kind == "RECOVERY" and (race_state == "ACTIVE" or pressure == "HIGH"):
            post_label = "RACE-PREP / GLYCOGEN TOP-UP" if race_state == "ACTIVE" else "GLYCOGEN TOP-UP"
            guidance = "The ride itself is low demand. The higher recovery target, if shown, comes from recent carbohydrate pressure and/or race preparation — not because this recovery ride is being classified as hard."
        elif kind == "RECOVERY":
            post_label = "LIGHT RECOVERY"
            guidance = "Low-demand ride: a normal carbohydrate-containing meal is usually enough unless duration, recent training or the next session raises replenishment priority."
        elif kind == "HEAT":
            post_label = "HEAT RECOVERY"
            guidance = "Moderate carbohydrate replacement plus fluid/electrolyte replacement; heat stress raises recovery priority without automatically making the workout a hard glycogen session."
        elif kind in ("TEMPO", "THRESHOLD", "VO2"):
            post_label = "GLYCOGEN REPLENISHMENT"
            guidance = "Quality work has meaningful carbohydrate demand. Recovery is scaled further by duration, recent workload, time to the next session and race proximity."
        elif kind == "RACE":
            post_label = "POST-RACE REPLENISHMENT"
            guidance = "Race-day recovery is high priority, but immediate intake should still fit the athlete's overall post-race meal and gastrointestinal tolerance."
        else:
            post_label = "LIGHT–MODERATE REPLENISHMENT"
            guidance = "Aerobic intensity is lower than quality training, but long duration can still create substantial carbohydrate and energy demand. Recovery is scaled by duration, recent load, turnaround and race preparation."

        if recovery.get("rapid_recovery"):
            timing = f"Very high urgency · next session ~{gap_hours:g} h later · begin promptly and repeat feeding across the first 3–4 h"
        elif gap_hours is not None and gap_hours <= 10:
            timing = f"High urgency · next session ~{gap_hours:g} h later · start within ~30–60 min and continue through subsequent meals"
        elif gap_hours is not None and gap_hours <= 20:
            timing = f"Moderate urgency · next session ~{gap_hours:g} h later · first feeding within ~60 min is practical"
        elif recovery.get("long_ride"):
            timing = "High daily priority · start with the next practical feeding, then continue replenishment across the next 4–6 h and the rest of the day"
        else:
            timing = "Normal urgency · integrate with the next normal meal within ~60–90 min"

        plans.append({
            "slot": session_item.get("slot", "Upcoming session"), "title": session_item.get("title") or "Upcoming session",
            "kind": kind, "session_demand": demand, "environment": environment, "planned_demand": planned_demand,
            "duration_min": duration_min, "duration_display": _format_duration_hours(duration_min),
            "duration_driver": intra_strategy.get("duration_driver"),
            "intra_cho": intra_strategy["display"], "intra_label": intra_strategy["label"],
            "intra_total": intra_strategy.get("total"),
            "post_cho": post_cho, "post_label": post_label, "recovery_need": recovery_need,
            "daily_replenishment_priority": recovery["daily_replenishment_priority"],
            "replenishment_guidance": recovery["replenishment_guidance"],
            "guidance": guidance, "timing": timing, "next_gap_hours": gap_hours,
        })
    return plans


# Backward-compatible name retained for any old preview/session object paths.
def build_post_workout_nutrition(next_sessions, metabolic_context=None):
    return build_nutrition_plan(next_sessions, metabolic_context or {
        "glycogen_pressure": "LOW", "race_strategy": {"state": "OFF"}
    })


def personal_baseline_text(metrics):
    pb = metrics.get("personal_baselines") or {}
    adaptive = metrics.get("adaptive_sleep") or pb.get("adaptive_sleep") or {}
    def line(label, key):
        item = pb.get(key) or {}
        return f"- {label}: Reference {item.get('garmin', 'n/a')} | recent {RECENT_BASELINE_DAYS}d {item.get('recent', 'n/a')} | status {item.get('status', 'n/a')}"
    sleep_line = (
        f"- Sleep duration: habitual {adaptive.get('kind', 'n/a')} {adaptive.get('habitual_label', 'n/a')} "
        f"({SLEEP_BASELINE_DAYS}d adaptive; weekday {adaptive.get('weekday_label', 'n/a')} / weekend {adaptive.get('weekend_label', 'n/a')}) "
        f"| current delta {adaptive.get('current_delta_min', 'n/a')} min | Garmin 7h38m retained as reference, not daily penalty target"
    )
    return "\n".join([
        f"PERSONAL BASELINES ({BASELINE_SOURCE}; sleep opportunity is adaptive):",
        line("HRV", "hrv"),
        line("Resting HR", "rhr"),
        sleep_line,
        line("Sleep Score", "sleep_score"),
        line("SpO2", "spo2"),
        line("Sleeping HR", "sleeping_hr"),
        f"- Sleeping respiration: Reference {pb.get('sleeping_respiration', {}).get('garmin', '11 brpm')} | live value not currently imported",
        f"- Awake respiration: Reference {pb.get('awake_respiration', {}).get('garmin', '13–14 brpm')} | live value not currently imported",
    ])

def extract_snapshot_daily_question(logs=None, now=None):
    """Return the most recent explicit question in today's Daily Log, if any.

    Saving a Daily Log remains a zero-AI action. When the athlete subsequently
    generates a Snapshot (which already performs the normal AI Coach call), an
    explicit question written in today's note should be answered inside that same
    Snapshot rather than requiring a second /coach-chat call.
    """
    logs = logs if logs is not None else load_daily_logs(80)
    today_iso = (now or get_rome_now()).date().isoformat()
    today_logs = [
        log for log in (logs or [])
        if str(log.get("local_date") or "") == today_iso
    ]
    if not today_logs:
        return None
    # logged_at_utc is an ISO timestamp and is the safest ordering key.  Only
    # the latest Daily Note is authoritative: an older question should not be
    # resurrected after the athlete has logged a newer note without it.
    today_logs.sort(key=lambda log: str(log.get("logged_at_utc") or ""), reverse=True)
    note = str(today_logs[0].get("note") or "").strip()
    if not note or "?" not in note:
        return None
    return note[:1200]



def ask_ai_analysis(data_text, metrics, coach_clock, week_memory, planning_context=None, feeling_trend=None, metabolic_context=None, snapshot_question=None, science_context=None, subjective_activity_context=None, training_definitions=None, ftp_anchor=None, recent_activities=None, undefined_training_intent=None, power_model=None, ai_runtime_override=None, usage_kind="SNAPSHOT", athlete_context_override=None):
    planning_context = planning_context or build_planning_context()
    feeling_trend = feeling_trend or compute_feeling_trend()
    metabolic_context = metabolic_context or {}
    slot_lines = "\n".join(
        f'{i+1}. {slot["label"]} | date {slot.get("date") or "not inferred"} | source {slot.get("source") or "n/a"} | timing confidence {slot.get("timing_confidence") or "n/a"} | restriction {slot.get("restriction", "NONE")}'
        + (f' | historical duration context {slot.get("duration_hint_label")}' if slot.get("duration_hint_label") else '')
        + (f' | planned environment {slot.get("training_environment")} | expected demand {slot.get("training_demand") or "COACH"} | athlete note {slot.get("event_note") or "none"}' if slot.get("is_planned_training") else '')
        for i, slot in enumerate(coach_clock.get("next_slots") or [])
    )
    opportunity_count = len(coach_clock.get("next_slots") or [])
    prompt = (
        "You are an expert cycling coach inside THE LAB. There is NO universal once-daily or twice-daily schedule. "
        "Python's adaptive COACH CLOCK learns the athlete's actual timing, frequency, duration and double-session propensity from Intervals history. "
        "The COACH CLOCK and HEALTH / AVAILABILITY / EVENT CONTEXT below are authoritative for when a training opportunity exists. Activities already logged are completed. Opportunities removed by Python do not exist for you. "
        "A NO_INTENSITY opportunity permits only easy aerobic/recovery work. A RACE opportunity is the event itself and must not receive an extra workout. A PLANNED opportunity is an athlete-created commitment: its INDOOR/OUTDOOR environment is authoritative. EASY is an intensity ceiling; HARD is expected demand unless health/restrictions or race-proximity safety justify backing off; COACH means choose from context.\n\n"
        "{planning_context}\n\n"
        "{clock_context}\n\n"
        "{week_context}\n\n"
        "{subjective_context}\n\n"
        "{baseline_context}\n\n"
        "{metabolic_context}\n\n"
        "{science_context}\n\n"
        "ATHLETE CONTEXT:\n{athlete_context}\n\n"
        "Current metrics: Fitness (CTL) {ctl} [{fitness_zone}], Fatigue (ATL) {atl} [{fatigue_zone}], Form (TSB) {tsb} [{form_zone}]. "
        "Health/restriction state is more important than those training-load metrics. If illness or injury explains reduced training, NEVER call the resulting freshness tapering, peaking, race readiness, or improved form. "
        "Instead prioritize health metrics, athlete-reported status and the active restriction. For HRV, resting HR, Sleep Score and SpO2 use personal manual/dynamic baselines plus recent trend, not population thresholds. "
        "SLEEP RULE: sleep duration is interpreted primarily against THE LAB's adaptive 42-day weekday/weekend habitual sleep opportunity. Any manual sleep reference is visible context only, NOT the daily penalty target. Q1/Q2 sleep quality remains a high-priority recovery signal and can partially offset a modest shortfall versus habitual opportunity; severe or accumulating short sleep still matters.\n\n"
        "TRAINING RHYTHM RULE: 14-day recent behavior is blended with 42-day established rhythm and 90-day season context. When RHYTHM is ADAPTING, recent sustained behavior is intentionally weighted more strongly. Treat learned dates/times as probabilities, not promises. Never add an AM/PM opportunity that Python did not provide. A same-day second session exists only when Python explicitly exposes SAME_DAY_SECOND; a future second session exists only when Python explicitly exposes RHYTHM_SECOND from athlete-specific double-session evidence. Athlete Context is descriptive and must NEVER override the deterministic rhythm for timing/frequency. Historical duration context is a personal reference, not a hard cap; shape duration around recovery, goal, session purpose and the athlete's learned volume. There is no universal 60-minute workout limit.\n\n"
        "DAILY LOG RULE: the 1–10 rating/comment is subjective retrospective context. Candidate activity links only tell you what completed work may relate to the note; connect the note to an activity only when wording/timing reasonably supports it. A Daily Log NEVER creates a future training opportunity. A high rating does not justify adding an extra workout; a poor rating may justify shortening, softening or skipping an already-valid opportunity.\n\n"
        "DETERMINISTIC ENGINE RULE: TRAINING STATE, TRAINING DIRECTION, TRAINING RHYTHM, PHYSIOLOGICAL STATE, AEROBIC EFFICIENCY/DURABILITY and POWER MODEL entries in DATA are computed by Python. Use them as structured context and explain them when relevant; do not silently relabel a health-driven load drop as tapering, and do not treat CP/W′ field estimates as laboratory measurements.\n\n"
        "TRAINING STRATEGY RULE: if TRAINING DIRECTION says an active athlete-declared model/goal exists, use its deterministic adherence, mesocycle focus and microcycle direction when shaping season_outlook, recommendation and upcoming sessions. Do not invent a different declared goal. Health/restrictions, race proximity, recovery and explicit Calendar commitments still outrank strategy; never prescribe extra intensity merely to improve an adherence percentage. If the plan is LEARNING, say so rather than pretending the block has already proved its structure.\n\n"
        "TRAINING VOCABULARY RULE: Threshold and TTE are NOT synonyms. Generic Z4/threshold intervals, including 15-minute repetitions, must be called Threshold unless the ATHLETE TRAINING DEFINITIONS below explicitly define that structure as TTE. TTE may be used only when the athlete-owned definition is actually satisfied. Never invent an athlete-specific TTE definition.\n\n"
        "SESSION COHERENCE RULE: title, intensity, main_set and why must describe the SAME workout. When the prescribed interval range sits materially below a validated THE LAB FTP anchor, do not call it Z4/Threshold solely because it is a quality session. Never cite a stored target from a materially different interval duration/power as direct proof that the current workout serves that target. The rationale must justify the actual prescribed work, not a different remembered workout. Python will normalize contradictions after your response.\n\n"
        "ATHLETE CAPABILITY CALIBRATION RULE: intensity is athlete-relative, not just a percentage-of-FTP label. Use the observed POWER MODEL duration points and recent workout history to judge whether a prescription is actually demanding for this athlete. If the athlete can already sustain materially more power for the same or a longer duration, do NOT sell familiar sub-threshold work as maximal-aerobic, a puncheur stimulus, or the day's hard-quality anchor. Either call it controlled tempo/sub-threshold maintenance, or prescribe genuinely goal-relevant work when recovery permits. If recovery does not permit real intensity, say that plainly instead of disguising easy/familiar work as quality.\n\n"
        "CONFIDENCE LANGUAGE RULE: LOW-confidence or LEARNING physiology is provisional context only. Never promote one weak-baseline comparison into a definite WATCH conclusion, and never say a low-confidence abnormality 'should normalize'. Say it needs confirmation/re-checking.\n\n"
        "PHYSIOLOGY LANGUAGE RULE: no training session has zero fatigue cost. Do not claim an easy ride accelerates glycogen resynthesis; carbohydrate availability drives glycogen restoration. Do not use next-day 'lactate clearance' as the physiological reason for recovery riding.\n\n"
        "SPACING TRUTH RULE: do not claim a fixed 72-hour spacing has been satisfied unless Python explicitly supplies that exact measured interval. Use the actual measured spacing supplied by Python and treat it as context, not a universal biological law.\n\n"
        "ATHLETE-REPORTED TTE INTENT RULE: if the athlete explicitly requests TTE, treat that as athlete intent, not as permission to force a TTE session. If current recovery/spacing/plan context makes quality inappropriate, prescribe the safer/more coherent session and explicitly say that TTE was athlete-reported but is not recommended for this slot. A TRAINING DEFINITION is optional: it is only needed to teach THE LAB the athlete's exact TTE protocol, not to acknowledge the athlete's intent. Never silently relabel another workout as TTE.\n\n"
        "{training_definitions}\n\n"
        "KNOWLEDGE-LAYER RULE: The Cyclist's Science excerpts are athlete-authored explanatory reference material. They rank below Python hard rules, real athlete data, restrictions, planning and personal fueling logic. Generic book fueling advice must NEVER replace the deterministic Nutrition Engine. Cite only excerpts that materially influence the recommendation or a session rationale.\n\n"
        "EVENT RULE: an upcoming registered race changes the purpose and spacing of sessions as race day approaches. Respect days-to-race and do not schedule gratuitous fatigue close to the event. ATHLETE-PLANNED TRAINING RULE: use active Calendar TRAINING entries to shape the days around them and never silently switch their structured environment. "
        "RESTRICTION RULE: temporary restrictions have exact dates. A 12-day no-intensity block means no intentional intensity on any one of those dates, even when CTL/ATL/TSB would otherwise encourage it.\n\n"
        "WEEK-MEMORY RULE: avoid automatically repeating Threshold or TTE, VO2max, Over-Under or sprint/neuromuscular work within about 72h unless there is a clear coaching reason. "
        "HEAT-RESPONSE RULE: activities whose name contains HEAT are deliberate high thermal-strain sessions. Use PREVIOUS TRAINING BLOCKS to inspect their actual interval power, HR response, zones and decoupling instead of judging them from average watts alone. Use the Python PERSONAL HEAT RESPONSE association to contextualize next-morning HRV, but never claim causation and never dismiss low HRV when resting HR, sleep, subjective status or performance also worsen. "
        "SNAPSHOT QUESTION RULE: if SNAPSHOT ATHLETE QUESTION below is not NONE, answer that question explicitly inside the recommendation field during THIS SAME Snapshot AI call. Do not require the athlete to send it again in AI Coach Chat. Put the direct answer first, then continue with the normal coaching recommendation. If it is NONE, behave exactly as usual. "
        "Do not repeat dashboard numbers or baseline ranges unnecessarily; interpret what matters.\n\n"
        "Writing style: concise, visual and decisive. training_load, season_distribution and fatigue_signals normally 1-2 useful sentences; season_outlook 2-3; recommendation 3-5 when needed. "
        "For each valid opportunity give a specific prescription and short rationale.\n\n"
        "Return ONLY valid JSON with exactly these keys:\n"
        '- "training_load": string\n'
        '- "season_distribution": string\n'
        '- "season_outlook": string\n'
        '- "fatigue_signals": string\n'
        '- "recommendation": string\n'
        '- "science_sources": array of zero to 3 exact The Cyclist\'s Science chunk ids supplied above; include an id only if that excerpt materially influenced recommendation or a session rationale.\n'
        '- "next_sessions": array of exactly {opportunity_count} object(s), SAME ORDER as VALID NEXT TRAINING OPPORTUNITIES. Each object contains "title", "duration", "intensity", "main_set", "why". Python owns whether/date/timing/source and will enforce restrictions. If timing is not inferred, do not invent a date/time in your prose.\n\n'
        "VALID NEXT TRAINING OPPORTUNITIES:\n{slot_lines}\n\n"
        "SNAPSHOT ATHLETE QUESTION (from today's most recent Daily Note; answer in recommendation if present):\n{snapshot_question}\n\n"
        "DATA:\n{data_text}"
    ).format(
        planning_context=planning_context_text(planning_context),
        clock_context=coach_clock_text(coach_clock), week_context=week_memory_text(week_memory),
        subjective_context=subjective_context_text(feeling_trend, activity_context=subjective_activity_context), baseline_context=personal_baseline_text(metrics),
        metabolic_context=metabolic_context_text(metabolic_context), science_context=science_prompt_context(science_context), athlete_context=(athlete_context_override if athlete_context_override is not None else _runtime_athlete_context()), training_definitions=training_definitions_text(training_definitions),
        ctl=metrics["ctl"], fitness_zone=metrics["fitness_zone"],
        atl=metrics["atl"], fatigue_zone=metrics["fatigue_zone"], tsb=metrics["tsb"], form_zone=metrics["form_zone"],
        opportunity_count=opportunity_count, slot_lines=slot_lines or "(none)", snapshot_question=(snapshot_question or "NONE"), data_text=data_text,
    )
    ai_runtime = ai_runtime_override or _resolve_ai_runtime()
    raw_text = _call_ai_provider(ai_runtime["provider"], ai_runtime["api_key"], ai_runtime["model"], prompt, max_tokens=5000, usage_kind=str(usage_kind or "SNAPSHOT"), user_id=ai_runtime.get("user_id"), credential_source=ai_runtime.get("source")).strip()
    if raw_text.startswith("```"):
        raw_text = raw_text.strip("`")
        if raw_text.startswith("json"):
            raw_text = raw_text[4:]
    try:
        parsed = json.loads(raw_text)
    except json.JSONDecodeError as exc:
        preview = raw_text[:300].replace("\n", " ")
        raise json.JSONDecodeError(f"{exc.msg} | raw response preview: {preview}", exc.doc, exc.pos)
    parsed["next_sessions"] = normalize_next_sessions(
        parsed.get("next_sessions"), coach_clock, training_definitions=training_definitions, ftp_anchor=ftp_anchor,
        recent_activities=recent_activities, undefined_training_intent=undefined_training_intent, power_model=power_model,
    )
    for field in ("training_load", "season_distribution", "season_outlook", "fatigue_signals", "recommendation"):
        parsed[field] = _v4829_physiology_language_guard(parsed.get(field))
        parsed[field] = _v4836_health_language_guard(parsed[field])
        parsed[field] = _v4830_strip_untrusted_spacing_claims(parsed[field])
        parsed[field] = _v4829_ftp_language_guard(parsed[field], ftp_anchor)
        parsed[field] = _v4830_duration_reference_guard(parsed[field], power_model)
    parsed["recommendation"] = _v4830_recommendation_consistency_guard(parsed.get("recommendation"), parsed["next_sessions"])
    parsed["recommendation"] = _v4835_standalone_recommendation_guard(parsed.get("recommendation"))
    parsed["recommendation"] = _v4836_recommendation_session_truth_guard(parsed.get("recommendation"), parsed["next_sessions"])
    parsed["science_sources"] = normalize_science_sources(parsed.get("science_sources"), science_context)
    return parsed



def _chat_context_section(label, builder, value):
    if not value:
        return None
    try:
        rendered = builder(value)
        if rendered:
            return f"{label}:\n{rendered}"
    except Exception:
        return None
    return None


def build_ai_coach_chat_context(snapshot):
    """Build a compact, high-signal context from the already-saved Snapshot only.

    No Intervals.icu fetch happens here. Deterministic Python outputs are carried
    forward so the conversational layer explains THE LAB instead of reinventing it.
    """
    snapshot = snapshot or {}
    lines = ["CURRENT THE LAB SNAPSHOT (authoritative for this chat):"]
    lines.append(
        "- CTL {ctl} [{fz}] | ATL {atl} [{az}] | TSB {tsb} [{tz}] | Energy Bank {energy}/100 [{el}] | Daily Readiness {race}/100 [{rl}]".format(
            ctl=snapshot.get("ctl", "n/a"), fz=snapshot.get("fitness_zone", "n/a"),
            atl=snapshot.get("atl", "n/a"), az=snapshot.get("fatigue_zone", "n/a"),
            tsb=snapshot.get("tsb", "n/a"), tz=snapshot.get("form_zone", "n/a"),
            energy=snapshot.get("energy_score", "n/a"), el=snapshot.get("energy_label", "n/a"),
            race=snapshot.get("race_readiness_score", "n/a"), rl=snapshot.get("race_readiness_label", "n/a"),
        )
    )
    lines.append(
        "- Latest HRV {hrv} | Resting HR {rhr} | Avg sleep {sleep} | Sleep quality {sq} | Weight {weight}".format(
            hrv=snapshot.get("latest_hrv", "n/a"), rhr=snapshot.get("latest_rhr", "n/a"),
            sleep=snapshot.get("avg_sleep", "n/a"), sq=snapshot.get("sleep_quality", "n/a"),
            weight=snapshot.get("latest_weight", "n/a"),
        )
    )
    if snapshot.get("recommendation"):
        lines.append(f"- COACH SNAPSHOT: {snapshot.get('recommendation')}")

    sessions = snapshot.get("next_sessions") or []
    fuels = snapshot.get("nutrition_plan") or []
    if sessions:
        lines.append("\nUPCOMING SESSIONS + FUEL:")
        for idx, sess in enumerate(sessions[:3]):
            fuel = fuels[idx] if idx < len(fuels) and isinstance(fuels[idx], dict) else {}
            lines.append(
                "- {slot} | {title} | {duration} | {intensity} | Fuel {fueling} | demand {demand} | recovery {recovery}".format(
                    slot=sess.get("slot", f"Session {idx+1}"), title=sess.get("title", "Session"),
                    duration=sess.get("duration", "n/a"), intensity=sess.get("intensity", "n/a"),
                    fueling=fuel.get("intra_cho") or "n/a",
                    demand=fuel.get("session_demand", "n/a"), recovery=fuel.get("recovery_need", "n/a"),
                )
            )
            if sess.get("main_set"):
                lines.append(f"  Main set: {sess.get('main_set')}")
            if sess.get("why"):
                lines.append(f"  Why: {sess.get('why')}")
            if fuel.get("guidance"):
                lines.append(f"  Nutrition: {fuel.get('guidance')}")
            if fuel.get("replenishment_guidance"):
                lines.append(f"  Replenishment: {fuel.get('replenishment_guidance')}")

    sections = [
        # COACH CLOCK already embeds the deterministic Training Rhythm text. Keep
        # one canonical copy in chat context to avoid duplicated instructions/tokens.
        _chat_context_section("COACH CLOCK", coach_clock_text, snapshot.get("coach_clock")),
        _chat_context_section("TRAINING STATE", training_state_text, snapshot.get("training_state")),
        _chat_context_section("TRAINING DIRECTION", training_direction_text, snapshot.get("training_direction")),
        _chat_context_section("PHYSIOLOGICAL STATE", physiological_state_text, snapshot.get("physiological_state")),
        _chat_context_section("ADAPTIVE SLEEP", adaptive_sleep_text, snapshot.get("adaptive_sleep")),
        _chat_context_section("AEROBIC EFFICIENCY / DURABILITY", aerobic_efficiency_text, snapshot.get("aerobic_efficiency")),
        _chat_context_section("POWER MODEL", power_model_text, snapshot.get("power_model")),
        _chat_context_section("FTP ANCHOR", ftp_anchor_text, snapshot.get("ftp_anchor")),
        _chat_context_section("PERFORMANCE BREAKTHROUGH", performance_breakthrough_text, snapshot.get("performance_breakthrough")),
        _chat_context_section("CURRENT WEEK", week_memory_text, snapshot.get("week_memory")),
        _chat_context_section("PREVIOUS TRAINING BLOCKS", previous_training_blocks_text, snapshot.get("previous_training_blocks")),
        _chat_context_section("PERSONAL HEAT RESPONSE", heat_response_pattern_text, snapshot.get("heat_pattern")),
        _chat_context_section("CALENDAR / RESTRICTIONS", planning_context_text, snapshot.get("planning_context")),
        _chat_context_section("METABOLIC / NUTRITION CONTEXT", metabolic_context_text, snapshot.get("metabolic_context")),
        _chat_context_section("ADVANCED PHYSIOLOGY / LEARNING LAB", advanced_physiology_text, snapshot.get("advanced_physiology")),
    ]
    lines.extend("\n" + x for x in sections if x)
    if snapshot.get("feeling_trend"):
        try:
            lines.append("\nSUBJECTIVE TREND:\n" + subjective_context_text(snapshot.get("feeling_trend"), logs=[], activity_context=snapshot.get("subjective_activity_context")))
        except Exception:
            pass

    vo2 = snapshot.get("vo2_trend") or {}
    if isinstance(vo2, dict) and vo2:
        lines.append(
            "\nVO2MAX TREND (estimated, not measured): wearable {w}, performance {p}, agreement {a}.".format(
                w=vo2.get("wearable_current", "n/a"), p=vo2.get("performance_current", "n/a"), a=vo2.get("agreement", "n/a")
            )
        )
    return "\n".join(lines)


def _normalize_chat_history(raw_history, max_messages=10):
    clean = []
    if not isinstance(raw_history, list):
        return clean
    for item in raw_history[-max_messages:]:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip().lower()
        text = str(item.get("text") or "").strip()
        if role not in ("user", "assistant") or not text:
            continue
        clean.append({"role": role, "text": text[:2500]})
    return clean


def ask_ai_coach_chat(question, snapshot, history=None, report_meta=None):
    """One explicit AI call against the stored Snapshot; never refresh Intervals.icu."""
    now = get_rome_now()
    notes = load_notes()
    notes_text = "\n".join(
        "- [{category}] {date}: {text}".format(
            category=n.get("category", "GENERAL"), date=n.get("date", ""), text=n.get("text", "")
        ) for n in notes[-50:]
    ) or "(none)"
    snapshot_text = build_ai_coach_chat_context(snapshot)
    science_chat_hits = search_science_knowledge(question, limit=4, diversify=True)
    science_chat_text = science_prompt_context(science_chat_hits)
    history = _normalize_chat_history(history)
    history_text = "\n".join(
        ("ATHLETE" if m["role"] == "user" else "AI COACH") + ": " + m["text"] for m in history
    ) or "(new conversation)"
    report_stamp = (report_meta or {}).get("generated_at_local_display") or "unknown timestamp"

    prompt = (
        "You are AI Coach inside THE LAB, a personal cycling decision dashboard. "
        "Answer the athlete's question using the stored Snapshot below. This is a conversational explanation layer: "
        "do not pretend to refresh Intervals.icu, Garmin, weather, or any external source. The Snapshot was generated at {report_stamp}.\n\n"
        "RULES:\n"
        "- Reply in the same language as the athlete's latest question.\n"
        "- Reason from the Snapshot, adaptive Training Rhythm, recent training blocks, calendar/restrictions, personal patterns and deterministic Nutrition Engine outputs.\n"
        "- Never invent a future AM/PM or second-session slot that the stored Coach Clock did not expose. Daily Log ratings/comments are retrospective context and never create a new training opportunity.\n"
        "- Treat Python-derived classifications and guardrails as authoritative. Explain them; do not silently override them.\n"
        "- Respect the athlete-declared Training Direction and primary goal when present. Use its adherence and microcycle guidance as context, but never let a strategy target override health/restrictions, race timing, recovery or explicit calendar commitments.\n"
        "- The Cyclist's Science is an athlete-authored knowledge layer below Python rules, real data, restrictions, planning and personal fueling logic. Generic fueling passages never override the deterministic Nutrition Engine.\n"
        "- The Cyclist's Science works as silent background knowledge. Do not surface book/source citations unless the athlete explicitly asks where a concept came from.\n"
        "- If the data does not support a claim, say what is missing instead of inventing it.\n"
        "- HEAT/HRV findings are associations, not proof of causation.\n"
        "- You may discuss alternatives, but do not claim that the stored Snapshot or calendar has been modified.\n"
        "- Do not mention the underlying AI provider.\n"
        "- Be concise but substantive: normally 2-6 short paragraphs, with a short list only if it materially improves clarity.\n\n"
        "ATHLETE CONTEXT:\n{athlete_context}\n\n"
        "DURABLE MEMORY:\n{notes_text}\n\n"
        "{snapshot_text}\n\n"
        "{science_chat_text}\n\n"
        "CONVERSATION SO FAR:\n{history_text}\n\n"
        "LATEST ATHLETE QUESTION:\n{question}\n"
    ).format(
        report_stamp=report_stamp, athlete_context=_runtime_athlete_context(), notes_text=notes_text,
        snapshot_text=snapshot_text, science_chat_text=science_chat_text, history_text=history_text, question=question,
    )

    ai_runtime = _resolve_ai_runtime()
    answer = _call_ai_provider(ai_runtime["provider"], ai_runtime["api_key"], ai_runtime["model"], prompt, max_tokens=1800, usage_kind="COACH_CHAT", user_id=ai_runtime.get("user_id"), credential_source=ai_runtime.get("source")).strip()
    if not answer:
        raise ValueError("AI Coach returned an empty answer")
    return answer


def build_vo2max_trend_preview(today=None):
    today = today or date.today()
    wearable = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 68.0},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 68.4},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 68.7},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 69.0},
        {"date": today.isoformat(), "value": 69.2},
    ]
    performance = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 70.7},
        {"date": (today - timedelta(days=42)).isoformat(), "value": 70.8},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=28)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=14)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 71.8},
        {"date": today.isoformat(), "value": 71.8},
    ]
    # Reuse the chart geometry without making API calls.
    original_w = build_wearable_vo2_series
    original_p = build_performance_vo2_series
    try:
        globals()["build_wearable_vo2_series"] = lambda *_args, **_kwargs: wearable
        globals()["build_performance_vo2_series"] = lambda *_args, **_kwargs: performance
        return build_vo2max_trend([], persist_history=False)
    finally:
        globals()["build_wearable_vo2_series"] = original_w
        globals()["build_performance_vo2_series"] = original_p


def build_preview_data():
    """Complete sample dashboard for visual testing. No external API calls."""
    now = get_rome_now()
    today = now.date()
    monday = today - timedelta(days=today.weekday())
    sample_activities = []
    # Synthetic mature athlete: 4 training days/week with long weekend volume.
    # Preview stays deterministic and demonstrates that Coach Clock is not an AM/PM template.
    for weeks_ago in range(8, 0, -1):
        base = today - timedelta(days=weeks_ago * 7)
        for weekday, hour, minutes, load, label in (
            (1, 18, 105, 72, "Tempo / Endurance"),
            (3, 18, 90, 68, "Quality session"),
            (5, 8, 240, 145, "Long endurance"),
            (6, 9, 180, 112, "Endurance"),
        ):
            d = base + timedelta(days=(weekday - base.weekday()) % 7)
            if d >= today:
                continue
            sample_activities.append({
                "start_date_local": f"{d.isoformat()}T{hour:02d}:10:00", "name": label,
                "moving_time": minutes * 60, "icu_training_load": load,
                "average_watts": 196, "average_heartrate": 130, "decoupling": 2.8,
                "trainer": hour >= 17, "icu_variability_index": 1.04,
                "stream_types": ["heartrate","watts"], "icu_zone_times": [{"secs": max(0, minutes*60-700)},{"secs": 500},{"secs": 200}],
            })
    # Current-week examples for Week Memory and Today card.
