# This serializer is intentionally generic: it exports the complete persisted
# Snapshot structure and separately indexes semantic/status-like fields so QA can
# catch contradictions such as WEAK confidence paired with overconfident prose.
# It never regenerates a Snapshot and never calls Intervals or an AI provider.
_CONTENT_AUDIT_SENSITIVE_KEY_RE = re.compile(
    r"(^|_)(?:api_?key|password|secret|token|authorization|cookie|credential|private_?key|license_?code|reset_?code)(?:_|$)",
    re.I,
)
_CONTENT_AUDIT_SIGNAL_KEY_RE = re.compile(
    r"(^|_)(?:status|state|confidence|assessment|class|zone|signal|trend|label|source|mode|quality|readiness|restriction|environment|demand|available|eligible|eligibility|retest|warning)(?:_|$)",
    re.I,
)


def _content_audit_sensitive_key(key):
    return bool(_CONTENT_AUDIT_SENSITIVE_KEY_RE.search(str(key or "")))


def _content_audit_scalar(value):
    """Lossless compact scalar representation suitable for Markdown QA files."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if isinstance(value, float) and not math.isfinite(value):
            return json.dumps(str(value), ensure_ascii=False)
        return str(value)
    return json.dumps(str(value), ensure_ascii=False)


def _content_audit_render_node(node, indent=0):
    """Render every persisted field recursively; no content-value truncation."""
    pad = "  " * indent
    lines = []
    if isinstance(node, dict):
        if not node:
            return [pad + "- {}"]
        for key, value in node.items():
            key_text = str(key)
            prefix = f"{pad}- `{key_text}`"
            if _content_audit_sensitive_key(key_text):
                lines.append(prefix + ": [REDACTED]")
            elif isinstance(value, (dict, list)):
                lines.append(prefix + ":")
                lines.extend(_content_audit_render_node(value, indent + 1))
            else:
                lines.append(prefix + ": " + _content_audit_scalar(value))
        return lines
    if isinstance(node, list):
        if not node:
            return [pad + "- []"]
        for idx, value in enumerate(node):
            prefix = f"{pad}- `[{idx}]`"
            if isinstance(value, (dict, list)):
                lines.append(prefix + ":")
                lines.extend(_content_audit_render_node(value, indent + 1))
            else:
                lines.append(prefix + ": " + _content_audit_scalar(value))
        return lines
    return [pad + "- " + _content_audit_scalar(node)]


def _content_audit_signal_index(node, path="data"):
    """Collect status/confidence/label-like scalars with their exact payload path."""
    out = []
    if isinstance(node, dict):
        for key, value in node.items():
            key_text = str(key)
            child_path = f"{path}.{key_text}" if path else key_text
            if _content_audit_sensitive_key(key_text):
                continue
            if isinstance(value, (dict, list)):
                out.extend(_content_audit_signal_index(value, child_path))
            elif _CONTENT_AUDIT_SIGNAL_KEY_RE.search(key_text):
                out.append((child_path, value))
    elif isinstance(node, list):
        for idx, value in enumerate(node):
            out.extend(_content_audit_signal_index(value, f"{path}[{idx}]"))
    return out


def _content_audit_compact_payload(data):
    """Remove structural duplication while preserving every unique Snapshot value.

    Advanced Physiology stores identical card dictionaries in `cards`, `groups`,
    `display_sections` and `gap_cards` for UI convenience.  The audit keeps the
    canonical full `cards` once and converts duplicate containers to key references.
    """
    try:
        out = json.loads(json.dumps(data, ensure_ascii=False, default=str))
    except Exception:
        return data
    ap = out.get("advanced_physiology") if isinstance(out, dict) else None
    if isinstance(ap, dict) and isinstance(ap.get("cards"), list):
        def card_key(card):
            return card.get("key") if isinstance(card, dict) else None
        groups = []
        for g in ap.get("groups") or []:
            if not isinstance(g, dict):
                continue
            groups.append({k:v for k,v in g.items() if k != "cards"} | {"card_keys":[card_key(c) for c in (g.get("cards") or []) if card_key(c)]})
        sections = []
        for s in ap.get("display_sections") or []:
            if not isinstance(s, dict):
                continue
            sections.append({k:v for k,v in s.items() if k != "cards"} | {"card_keys":[card_key(c) for c in (s.get("cards") or []) if card_key(c)]})
        ap["groups"] = groups
        ap["display_sections"] = sections
        ap["gap_card_keys"] = [card_key(c) for c in (ap.get("gap_cards") or []) if card_key(c)]
        ap.pop("gap_cards", None)
        ap["audit_structure_note"] = "Full metric bodies are stored once in advanced_physiology.cards; groups/display_sections/gap_card_keys reference those canonical cards by key."
    return out


def build_content_audit_markdown(report):
    """Build a compact-but-complete QA artifact from the already-stored Snapshot."""
    report = report or {}
    data = _content_audit_compact_payload(report.get("data") or {})
    generated_local = report.get("generated_at_local") or "unknown"
    generated_utc = report.get("generated_at_utc") or "unknown"
    version = report.get("app_version") or APP_VERSION
    payload_bytes = report.get("payload_bytes")
    qa_meta = report.get("qa_meta") if isinstance(report.get("qa_meta"), dict) else None
    signal_rows = _content_audit_signal_index(data)

    if qa_meta:
        lines = [
            "# THE LAB · QA CONTENT AUDIT",
            "",
            "Purpose: semantic/content QA of one ephemeral admin QA Snapshot. The audit itself triggers no calls; the QA run metadata below declares whether Intervals.icu was live or replayed.",
            "",
            f"- REPORT MODE: {qa_meta.get('report_mode', 'QA TEST')}",
            f"- QA TYPE: {qa_meta.get('qa_kind', 'UNKNOWN')}",
            f"- AI PROVIDER: {qa_meta.get('ai_provider', 'THE LAB Standard · Gemini')}",
            f"- AI MODEL: {qa_meta.get('ai_model', 'unknown')}",
            f"- PRODUCTION LAST REPORT AFFECTED: {qa_meta.get('production_last_report_affected', 'NO')}",
            f"- INTERVALS DATA: {qa_meta.get('intervals_data', 'unknown')}",
            f"- PYTHON PIPELINE: {qa_meta.get('python_pipeline', 'unknown')}",
            f"- INPUT FINGERPRINT: {qa_meta.get('input_fingerprint', 'unknown')}",
            f"- SOURCE PRODUCTION SNAPSHOT: {qa_meta.get('source_snapshot_generated_local') or 'LIVE QA · not a replay'}",
            f"- Snapshot generated local: {generated_local}",
            f"- Snapshot generated UTC: {generated_utc}",
            f"- Snapshot Product version: {version}",
            f"- Audit exporter Product version: {APP_VERSION}",
            f"- QA payload bytes: {payload_bytes if payload_bytes is not None else 'unknown'}",
            f"- Audit generated local: {get_rome_now().isoformat(timespec='seconds')}",
            "- Safety: credential/token/password-like keys are automatically redacted if ever present.",
            "",
            "## QA SIGNAL / LABEL INDEX",
            "",
            "Every scalar field whose key looks like a status, confidence, class, zone, assessment, trend, label, source, state or related QA signal is indexed below. Values are not normalized, so labels such as WEAK, TRACKING, AGING, MIXED or future labels remain exactly as stored.",
            "",
        ]
    else:
        lines = [
            "# THE LAB · CONTENT AUDIT",
            "",
            "Purpose: semantic/content QA of one already-persisted Snapshot. This file does not trigger Intervals.icu or AI calls.",
            "",
            f"- Snapshot generated local: {generated_local}",
            f"- Snapshot generated UTC: {generated_utc}",
            f"- Snapshot Product version: {version}",
            f"- Audit exporter Product version: {APP_VERSION}",
            f"- Persisted payload bytes: {payload_bytes if payload_bytes is not None else 'unknown'}",
            f"- Audit generated local: {get_rome_now().isoformat(timespec='seconds')}",
            "- Safety: credential/token/password-like keys are automatically redacted if ever present.",
            "",
            "## QA SIGNAL / LABEL INDEX",
            "",
            "Every scalar field whose key looks like a status, confidence, class, zone, assessment, trend, label, source, state or related QA signal is indexed below. Values are not normalized, so labels such as WEAK, TRACKING, AGING, MIXED or future labels remain exactly as stored.",
            "",
        ]
    if signal_rows:
        for path, value in signal_rows:
            lines.append(f"- `{path}` = {_content_audit_scalar(value)}")
    else:
        lines.append("- *(no status-like scalar fields found)*")

    lines.extend([
        "",
        "## FULL STRUCTURED SNAPSHOT",
        "",
        "The complete semantic Snapshot follows. Duplicate Advanced Physiology card copies are replaced by key references to the canonical card list; unique values, ordering and labels are preserved. Credential-like keys are redacted.",
        "",
    ])
    lines.extend(_content_audit_render_node(data, 0))
    lines.append("")
    return "\n".join(lines)


