@app.route("/qa/replay", methods=["POST"])
def qa_replay_last_snapshot():
    if not require_login():
        return redirect(url_for("login"))
    user = current_user(touch=False)
    if not user or str(user.get("role") or "").lower() != "admin":
        abort(403)
    report = load_latest_report(include_payload=True, include_qa_replay=True)
    if not report or not report.get("data"):
        return redirect(url_for("home", notice="NO PRODUCTION SNAPSHOT", detail="Generate a production Snapshot first."))
    replay = report.get("qa_replay") or {}
    analysis_args = replay.get("analysis_args") if isinstance(replay, dict) else None
    if not isinstance(analysis_args, dict):
        return redirect(url_for("home", notice="REPLAY NOT AVAILABLE", detail="Generate one production Snapshot with V4.8.31 first; older reports do not contain the QA replay context."))
    try:
        qa_ai_runtime = _v4831_admin_qa_ai_runtime(user["id"])
        analysis = ask_ai_analysis(
            **analysis_args,
            ai_runtime_override=qa_ai_runtime,
            usage_kind="QA_REPLAY_SNAPSHOT",
        )
        # Start from the immutable production Snapshot and replace only the AI-owned
        # fields plus the deterministic nutrition plan that depends on normalized
        # next_sessions. No Intervals.icu fetch or production report write occurs.
        data = _v4831_json_clone(report.get("data") or {})
        for key, value in analysis.items():
            data[key] = value
        data["nutrition_plan"] = build_nutrition_plan(data.get("next_sessions"), data.get("metabolic_context") or {})
        fingerprint = str(replay.get("context_fingerprint") or _v4831_context_fingerprint(analysis_args))
        qa_report = _v4831_qa_report(
            data, "REPLAY", fingerprint,
            source_report=report, ai_runtime=qa_ai_runtime,
        )
        qa_audit = build_content_audit_markdown(qa_report)
        audit_event(
            "QA_REPLAY_SNAPSHOT", actor_user_id=user["id"], target_user_id=user["id"],
            details={"provider": "GEMINI", "model": qa_ai_runtime.get("model"), "context_fingerprint": fingerprint, "source_generated_at_local": report.get("generated_at_local")},
        )
        return render_template_string(
            HOME_PAGE, days=DAYS_BACK, season_days=SEASON_DAYS_BACK,
            data=data, error=None, css=BASE_CSS, logo=LOGO_B64, brand_wordmark=BRAND_WORDMARK_B64, favicon=FAVICON_B64,
            notes=[], chat_answer=None, chat_error=None, feelings=[], latest_feeling=None,
            app_version=APP_VERSION, clock_preview=get_clock_preview(), is_preview=False, report_mode=True, report_meta=qa_report, download_mode=False,
            latest_report_meta=get_latest_report_meta(), chat_context_meta=None, qa_mode=True, qa_meta=qa_report.get("qa_meta"),
            qa_audit_markdown=qa_audit, qa_audit_filename=f"the_lab_qa_replay_audit_{get_rome_now().strftime('%Y%m%d_%H%M')}.md",
        )
    except (ValueError, RuntimeError, AIUsageLimitError) as exc:
        return redirect(url_for("home", notice="QA REPLAY FAILED", detail=str(exc)))
    except requests.HTTPError as exc:
        return redirect(url_for("home", notice="QA REPLAY FAILED", detail=f"Gemini service error: {exc}"))
    except Exception as exc:
        return redirect(url_for("home", notice="QA REPLAY FAILED", detail=f"Unexpected QA error: {exc}"))


