@app.route("/analyze", methods=["POST"])
def analyze():
    if not require_login():
        return redirect(url_for("login"))

    error = None
    data = None
    chat_context_meta = None
    try:
        user = current_user(touch=False)
        if not user:
            return redirect(url_for("login"))
        qa_requested = str(request.form.get("qa_mode") or "").strip().upper() == "LIVE"
        if qa_requested and str(user.get("role") or "").lower() != "admin":
            abort(403)
        qa_ai_runtime = _v4831_admin_qa_ai_runtime(user["id"]) if qa_requested else None

        # QA Live is intentionally read-only with respect to Training Direction: it
        # uses the currently saved plan and never starts a new declared block. The
        # normal production Snapshot keeps the existing preflight save behavior.
        if qa_requested:
            strategy_plan = get_active_training_strategy_plan(user["id"])
            if not strategy_plan:
                raise ValueError("Save a Training Direction before running Live QA.")
        else:
            submitted_distribution = str(request.form.get("distribution_target") or "").strip().upper()
            submitted_goal = str(request.form.get("primary_goal") or "").strip().upper()
            if submitted_distribution or submitted_goal:
                strategy_plan, strategy_changed = save_training_strategy_plan(submitted_distribution, submitted_goal, user_id=user["id"])
                if strategy_changed:
                    audit_event(
                        "TRAINING_STRATEGY_UPDATED", actor_user_id=user["id"], target_user_id=user["id"],
                        details={"distribution_target": strategy_plan.get("distribution_target"), "primary_goal": strategy_plan.get("primary_goal"), "new_block": True, "source": "snapshot_preflight"},
                    )
            else:
                strategy_plan = get_active_training_strategy_plan(user["id"])
                if not strategy_plan:
                    raise ValueError("Choose a Training Direction and primary goal before generating the Snapshot.")

        # External calls start only after the athlete's declared direction is resolved.
        recent_activities, season_activities, wellness, season_wellness, history_activities = fetch_intervals_data()
        form_thresholds = personal_form_thresholds(season_wellness)
        form_median = personal_form_median(season_wellness)
        fatigue_thresholds = personal_fatigue_thresholds(season_wellness)
        metrics = compute_metrics(wellness, form_thresholds, fatigue_thresholds, baseline_wellness=season_wellness)
        planning_context = build_planning_context()
        metabolic_context = build_metabolic_context(recent_activities, season_wellness, planning_context)
        metrics = apply_health_override_to_metrics(metrics, planning_context)
        season_stats = compute_season_stats(season_activities)
        training_rhythm = build_training_rhythm(season_activities)
        energy_bank = compute_energy_bank(
            metrics["form_zone"], metrics["fatigue_zone"], metrics.get("latest_sleep_hours"),
            recent_activities=recent_activities, personal_baselines=metrics.get("personal_baselines"), now=get_rome_now(),
            sleep_quality=metrics.get("sleep_quality"), training_rhythm=training_rhythm, wellness=season_wellness
        )
        energy_bank = apply_health_override_to_energy(energy_bank, planning_context)
        recent_trend = compute_recent_trend(wellness, n=5, form_thresholds=form_thresholds, form_median=form_median)
        trend_arrows = compute_trend_arrows(wellness)
        health_rings = compute_health_rings(metrics)
        weight_for_power = ((metabolic_context.get("weight") or {}).get("kg") if isinstance(metabolic_context, dict) else None)
        best_watts, best_watts_debug, power_model, current_power_payload = get_power_intelligence(weight_kg=weight_for_power)
        performance_breakthrough = build_performance_breakthrough(recent_activities, now=get_rome_now(), window_days=7)
        ftp_anchor = build_ftp_anchor_context(history_activities, now=get_rome_now(), user_id=user["id"])
        vo2_trend = build_vo2max_trend(season_wellness, current_power_payload=current_power_payload, current_power_day=get_rome_now().date(), history_user_id=user["id"])
        recent_calories = sum(a.get("calories") or 0 for a in recent_activities)
        avg_daily_calories = round(recent_calories / DAYS_BACK) if DAYS_BACK else 0
        notes = load_notes()
        training_definitions = build_training_definitions(notes)
        feelings = load_feelings()
        daily_logs_full = load_daily_logs(240)
        undefined_training_intent = _v4829_undefined_training_intent(daily_logs_full, training_definitions, now=get_rome_now())
        feeling_trend_live = compute_feeling_trend(daily_logs_full)
        coach_clock = build_coach_clock(season_activities, planning_context=planning_context, training_rhythm=training_rhythm)
        subjective_activity_context = build_subjective_activity_context(daily_logs_full, season_activities)
        week_memory = build_week_memory(recent_activities)
        previous_training_blocks = build_previous_training_blocks(recent_activities, 3)
        heat_pattern = build_heat_response_pattern(season_activities, season_wellness)
        aerobic_efficiency = build_aerobic_efficiency(season_activities)
        training_state = build_training_state(season_activities, season_wellness, planning_context, metrics, feeling_trend_live)
        training_direction = build_training_direction(season_activities, planning_context=planning_context, plan=strategy_plan)
        physiological_state = build_physiological_state(metrics, training_state, aerobic_efficiency, metabolic_context, heat_pattern, feeling_trend_live)
        advanced_physiology = build_advanced_physiology_metrics(
            season_activities, season_wellness, metrics, training_state, vo2_trend, feeling_trend_live, planning_context
        )
        science_context = build_science_snapshot_context(
            training_state=training_state, physiological_state=physiological_state, adaptive_sleep=metrics.get("adaptive_sleep"),
            aerobic_efficiency=aerobic_efficiency, metabolic_context=metabolic_context, heat_pattern=heat_pattern, planning_context=planning_context,
        )
        data_text = build_data_text(recent_activities, wellness, season_stats, notes, feelings, best_watts, vo2_trend, performance_breakthrough)
        data_text += "\n\n" + coach_clock_text(coach_clock)
        data_text += "\n\n" + week_memory_text(week_memory)
        data_text += "\n\n" + previous_training_blocks_text(previous_training_blocks)
        data_text += "\n\n" + heat_response_pattern_text(heat_pattern)
        data_text += "\n\n" + training_state_text(training_state)
        data_text += "\n\n" + training_direction_text(training_direction)
        data_text += "\n\n" + physiological_state_text(physiological_state)
        data_text += "\n\n" + adaptive_sleep_text(metrics.get("adaptive_sleep"))
        data_text += "\n\n" + aerobic_efficiency_text(aerobic_efficiency)
        data_text += "\n\n" + power_model_text(power_model)
        data_text += "\n\n" + ftp_anchor_text(ftp_anchor)
        data_text += "\n\n" + _v4829_hard_spacing_context_text(recent_activities, coach_clock)
        data_text += "\n\n" + advanced_physiology_text(advanced_physiology)
        data_text += "\n\n" + planning_context_text(planning_context)
        data_text += "\n\n" + subjective_context_text(feeling_trend_live, daily_logs_full, subjective_activity_context)
        snapshot_question = extract_snapshot_daily_question(daily_logs_full)
        analysis_args = {
            "data_text": data_text, "metrics": metrics, "coach_clock": coach_clock, "week_memory": week_memory,
            "planning_context": planning_context, "feeling_trend": feeling_trend_live, "metabolic_context": metabolic_context,
            "snapshot_question": snapshot_question, "science_context": science_context,
            "subjective_activity_context": subjective_activity_context, "training_definitions": training_definitions,
            "ftp_anchor": ftp_anchor, "recent_activities": recent_activities,
            "undefined_training_intent": undefined_training_intent, "power_model": power_model,
            "athlete_context_override": _runtime_athlete_context(),
        }
        replay_bundle = _v4831_build_replay_bundle(analysis_args)
        analysis = ask_ai_analysis(
            **analysis_args,
            ai_runtime_override=qa_ai_runtime,
            usage_kind=("QA_LIVE_SNAPSHOT" if qa_requested else "SNAPSHOT"),
        )
        nutrition_plan = build_nutrition_plan(analysis.get("next_sessions"), metabolic_context)
        data = {
            **metrics, **season_stats, **analysis, **energy_bank,
            "coach_clock": coach_clock,
            "training_rhythm": training_rhythm,
            "subjective_activity_context": subjective_activity_context,
            "week_memory": week_memory,
            "previous_training_blocks": previous_training_blocks,
            "heat_pattern": heat_pattern,
            "training_state": training_state,
            "training_direction": training_direction,
            "physiological_state": physiological_state,
            "adaptive_sleep": metrics.get("adaptive_sleep"),
            "aerobic_efficiency": aerobic_efficiency,
            "power_model": power_model,
            "advanced_physiology": advanced_physiology,
            "planning_context": planning_context,
            "feeling_trend": feeling_trend_live,
            "avg_daily_calories": avg_daily_calories,
            "recent_trend": recent_trend,
            "trend_arrows": trend_arrows,
            "health_rings": health_rings,
            "best_watts": best_watts,
            "best_watts_debug": best_watts_debug,
            "performance_breakthrough": performance_breakthrough,
            "ftp_anchor": ftp_anchor,
            "training_definitions": training_definitions,
            "undefined_training_intent": undefined_training_intent,
            "vo2_trend": vo2_trend,
            "metabolic_context": metabolic_context,
            "nutrition_plan": nutrition_plan,
            "nutrition_reference": NUTRITION_REFERENCE,
            "race_carb_reference": RACE_CARB_REFERENCE,
            "training_legend": TRAINING_METRIC_LEGEND,
            "snapshot_question": snapshot_question,
            "science_insights": science_context,
            "science_kb_version": SCIENCE_KB.get("version", 1),
        }
        # V4.8.31 QA Live renders an ephemeral full Snapshot using live Intervals +
        # forced Gemini QA, but it never replaces the production Last Report. Normal
        # production generation persists exactly as before, with one hidden replay
        # context bundle inside the existing report JSON envelope.
        if qa_requested:
            qa_report = _v4831_qa_report(
                data, "LIVE", replay_bundle.get("context_fingerprint"),
                source_report=None, ai_runtime=qa_ai_runtime,
            )
            qa_audit = build_content_audit_markdown(qa_report)
            audit_event(
                "QA_LIVE_SNAPSHOT", actor_user_id=user["id"], target_user_id=user["id"],
                details={"provider": "GEMINI", "model": qa_ai_runtime.get("model"), "context_fingerprint": replay_bundle.get("context_fingerprint")},
            )
            return render_template_string(
                HOME_PAGE, days=DAYS_BACK, season_days=SEASON_DAYS_BACK,
                data=data, error=None, css=BASE_CSS, logo=LOGO_B64, brand_wordmark=BRAND_WORDMARK_B64, favicon=FAVICON_B64,
                notes=[], chat_answer=None, chat_error=None, feelings=[], latest_feeling=None,
                app_version=APP_VERSION, clock_preview=get_clock_preview(), is_preview=False, report_mode=True, report_meta=qa_report, download_mode=False,
                latest_report_meta=get_latest_report_meta(), chat_context_meta=None, qa_mode=True, qa_meta=qa_report.get("qa_meta"),
                qa_audit_markdown=qa_audit, qa_audit_filename=f"the_lab_qa_live_audit_{get_rome_now().strftime('%Y%m%d_%H%M')}.md",
            )

        # V4.8.23: the complete Snapshot is deliberately NOT stored in Flask's
        # client-side cookie session. ``data`` is rendered for this response and the
        # durable per-user copy is persisted by save_latest_report() below.
        try:
            save_latest_report(data, qa_replay_bundle=replay_bundle)
            chat_context_meta = get_latest_report_meta()
        except Exception as report_exc:
            data["report_save_warning"] = f"Latest report could not be stored: {report_exc}"
            chat_context_meta = None
    except ValueError as e:
        error = str(e)
    except AIUsageLimitError as e:
        error = str(e)
    except requests.HTTPError as e:
        error = _safe_external_http_error(e)
    except (json.JSONDecodeError, KeyError) as e:
        error = f"The AI response could not be parsed: {e}"
    except Exception as e:
        error = f"Unexpected error: {e}"

    return render_template_string(
        HOME_PAGE, days=DAYS_BACK, season_days=SEASON_DAYS_BACK,
        data=data, error=error, css=BASE_CSS, logo=LOGO_B64, brand_wordmark=BRAND_WORDMARK_B64, favicon=FAVICON_B64,
        notes=load_notes(), chat_answer=None, chat_error=None,
        feelings=load_feelings(), latest_feeling=get_latest_feeling(),
        app_version=APP_VERSION, clock_preview=get_clock_preview(), is_preview=False, report_mode=False, report_meta=None, download_mode=False,
        latest_report_meta=get_latest_report_meta(), chat_context_meta=chat_context_meta,
    )


@app.route("/coach-chat", methods=["POST"])
def coach_chat():
    if not require_login():
        return jsonify({"ok": False, "error": "Your session has expired. Log in again."}), 401
    payload = request.get_json(silent=True) or {}
    question = str(payload.get("question") or "").strip()
    context_id = str(payload.get("context_id") or "").strip()
    history = payload.get("history") or []
    if not question:
        return jsonify({"ok": False, "error": "Write a question first."}), 400
    if len(question) > 1200:
        return jsonify({"ok": False, "error": "Keep the question under 1,200 characters."}), 400

    report = load_latest_report(include_payload=True)
    if not report or not report.get("data"):
        return jsonify({"ok": False, "error": "No stored Snapshot is available. Generate a Snapshot first."}), 409
    if context_id and str(report.get("generated_at_local") or "") != context_id:
        return jsonify({"ok": False, "error": "A newer Snapshot is available. Reload the dashboard before continuing this chat."}), 409

    try:
        answer = ask_ai_coach_chat(question, report.get("data"), history=history, report_meta=report)
        return jsonify({"ok": True, "answer": answer, "context_id": report.get("generated_at_local")})
    except AIUsageLimitError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 429
    except requests.HTTPError as exc:
        return jsonify({"ok": False, "error": f"AI Coach service error: {exc}"}), 502
    except (json.JSONDecodeError, KeyError, ValueError) as exc:
        return jsonify({"ok": False, "error": f"AI Coach response error: {exc}"}), 502
    except Exception as exc:
        return jsonify({"ok": False, "error": f"Unexpected AI Coach error: {exc}"}), 500


@app.route("/coach-chat/save-memory", methods=["POST"])
def coach_chat_save_memory():
    if not require_login():
        return jsonify({"ok": False, "error": "Your session has expired. Log in again."}), 401
    payload = request.get_json(silent=True) or {}
    text = str(payload.get("text") or "").strip()
    if not text:
        return jsonify({"ok": False, "error": "There is no answer to save."}), 400
    text = text[:3500]
    memory_text = "AI Coach chat · " + text
    if memory_text_exists(memory_text):
        return jsonify({"ok": True, "duplicate": True})
    add_memory_item(memory_text, category="COACH")
    return jsonify({"ok": True, "duplicate": False})


